// The toolbar is three groups, each an ordered list you arrange in Customise Toolbar:
//   left (one capsule), address (inside the address bar, at its right end), right (each on its own, Lens always last).
static NSString *const kToolbarLayout = @"toolbarLayout";
// key, name, SF Symbol, which groups it may live in (L, A, R), its home group when added, a line about it
static NSArray<NSArray *> *ToolbarCatalog(void) {
    static NSArray *c;
    if (!c) c = @[
        @[@"back", @"Back", @"chevron.left", @"LAR", @"L", @"The page before"],
        @[@"forward", @"Forward", @"chevron.right", @"LAR", @"L", @"The page after"],
        @[@"reload", @"Reload", @"arrow.clockwise", @"LAR", @"L", @"Stops a page while it loads"],
        @[@"home", @"Home", @"house", @"LAR", @"L", @"Your new-tab page"],
        @[@"newtab", @"New Tab", @"plus", @"LAR", @"L", @"Same as ⌘T"],
        @[@"install", @"Install App", @"arrow.down.app", @"LAR", @"A", @"Appears on sites you can install"],
        @[@"star", @"Bookmark", @"star", @"LAR", @"A", @"Save or edit this page"],
        @[@"pip", @"Picture in Picture", @"pip.enter", @"LAR", @"A", @"Appears while a video plays"],
        @[@"reader", @"Reader", @"doc.plaintext", @"LAR", @"A", @"Just the article"],
        @[@"share", @"Share", @"square.and.arrow.up", @"LAR", @"A", @"Send the page somewhere"],
        @[@"find", @"Find", @"magnifyingglass", @"LAR", @"A", @"Find on the page"],
        @[@"shield", @"Blocking", @"checkmark.shield", @"LAR", @"R", @"With the count of what it stopped"],
        @[@"downloads", @"Downloads", @"tray.and.arrow.down", @"LAR", @"R", @"While something downloads"],
        @[@"split", @"Split View", @"rectangle.split.2x1", @"LAR", @"R", @"Two pages side by side"],
        @[@"tabs", @"Tabs", @"square.on.square", @"LAR", @"R", @"Brings your tabs out"],
        @[@"history", @"History", @"clock.arrow.circlepath", @"LAR", @"R", @"Where you've been"],
        @[@"bookmarks", @"Bookmarks", @"book", @"LAR", @"R", @"All your bookmarks"],
        @[@"private", @"Private Window", @"eye.slash", @"LAR", @"R", @"Nothing is kept"],
        @[@"extensions", @"Extensions", @"puzzlepiece.extension", @"R", @"R", @"All your extensions, in a panel"],
    ];
    return c;
}
static NSArray *ToolbarItem(NSString *k) { for (NSArray *i in ToolbarCatalog()) if ([i[0] isEqualToString:k]) return i; return nil; }
static NSDictionary *ToolbarLayoutDefault(void) {
    return @{@"left": @[@"back", @"forward", @"reload"], @"address": @[@"install", @"pip", @"star"], @"right": @[@"shield", @"downloads", @"extensions"]};
}
// The stored arrangement, cleaned: known keys only, each once, and only in a group it may live in.
static NSDictionary *ToolbarSanitize(NSDictionary *d) {
    if (![d isKindOfClass:NSDictionary.class]) return ToolbarLayoutDefault();
    NSMutableSet *seen = [NSMutableSet set]; NSMutableDictionary *out = [NSMutableDictionary dictionary];
    NSDictionary *zc = @{@"left": @"L", @"address": @"A", @"right": @"R"};
    for (NSString *z in @[@"left", @"address", @"right"]) {
        NSMutableArray *a = [NSMutableArray array];
        for (id k in [d[z] isKindOfClass:NSArray.class] ? d[z] : @[]) {
            NSArray *it = [k isKindOfClass:NSString.class] ? ToolbarItem(k) : nil;
            if (!it || [seen containsObject:k] || ![it[3] containsString:zc[z]]) continue;
            [seen addObject:k]; [a addObject:k];
        }
        out[z] = a;
    }
    return out;
}
static NSDictionary *ToolbarLayout(void) { id d = [Defaults() objectForKey:kToolbarLayout]; return d ? ToolbarSanitize(d) : ToolbarLayoutDefault(); }
static NSString *ToolbarZoneOf(NSString *k) { NSDictionary *L = ToolbarLayout(); for (NSString *z in @[@"left", @"address", @"right"]) if ([L[z] containsObject:k]) return z; return nil; }
static NSArray<NSString *> *OptInButtons(void) { return @[@"dlalways"]; }
static BOOL ToolbarShows(NSString *key) {
    if ([key isEqualToString:@"dlalways"]) return [[Defaults() arrayForKey:kShowExtra] containsObject:key];
    if ([key isEqualToString:@"sidebar"]) return NO;
    return ToolbarZoneOf(key) != nil;
}
static void SetToolbarShows(NSString *key, BOOL on) {
    if ([key isEqualToString:@"dlalways"]) {
        NSMutableArray *a = [[Defaults() arrayForKey:kShowExtra] ?: @[] mutableCopy];
        [a removeObject:key]; if (on) [a addObject:key];
        [Defaults() setObject:a forKey:kShowExtra]; return;
    }
    NSArray *it = ToolbarItem(key); if (!it) return;
    NSMutableDictionary *L = [NSMutableDictionary dictionary];
    for (NSString *z in @[@"left", @"address", @"right"]) { NSMutableArray *a = [ToolbarLayout()[z] mutableCopy]; [a removeObject:key]; L[z] = a; }
    if (on) { NSString *home = @{@"L": @"left", @"A": @"address", @"R": @"right"}[it[4]]; [L[home] addObject:key]; }
    [Defaults() setObject:L forKey:kToolbarLayout];
}
static BOOL ExtensionPinned(NSString *ident) {
    return [[Defaults() arrayForKey:kExtPinned] containsObject:ident];
}

// Debug log next to the source when it exists (~/Documents/Iris/iris.log).
// Developer files live beside Iris.app (in Documents); they're touched only on this background queue,
// so a macOS folder-access prompt can never freeze the browser itself.
static dispatch_queue_t DevQueue(void) {
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("iris.dev", DISPATCH_QUEUE_SERIAL); });
    return q;
}
static NSString *gWebAppTag = @"";   // "[App name] " in the log lines of an installed app
static void DLog(NSString *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    NSString *s = [[NSString alloc] initWithFormat:fmt arguments:ap];
    va_end(ap);
    NSString *line = [NSString stringWithFormat:@"%@  %@%@\n", [NSDate.date descriptionWithLocale:nil], [NSBundle.mainBundle.bundleIdentifier isEqualToString:@"com.y.iris.dev"] ? @"[dev] " : gWebAppTag, s];
    dispatch_async(DevQueue(), ^{
        NSString *path = [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/Iris/iris.log"];
        if (![NSFileManager.defaultManager fileExistsAtPath:path.stringByDeletingLastPathComponent]) return;
        NSFileHandle *h = [NSFileHandle fileHandleForWritingAtPath:path];
        if (!h) { [NSFileManager.defaultManager createFileAtPath:path contents:nil attributes:nil]; h = [NSFileHandle fileHandleForWritingAtPath:path]; }
        [h seekToEndOfFile]; [h writeData:[line dataUsingEncoding:NSUTF8StringEncoding]]; [h closeFile];
    });
}

#pragma mark - Look

static NSColor *Hex(uint32_t h) {
    return [NSColor colorWithSRGBRed:((h >> 16) & 255) / 255.0 green:((h >> 8) & 255) / 255.0 blue:(h & 255) / 255.0 alpha:1];
}
static NSColor *HexA(uint32_t h, CGFloat a) { return [Hex(h) colorWithAlphaComponent:a]; }

// Themes: Graphite (dark grey), Carbon (near black, like the icon), Light, or follow macOS.
// Accents never include yellow.
static NSColor *vBg, *vPill, *vPillFocus, *vHover, *vActive, *vLine, *vText, *vDim, *vFaint, *vAccent, *vContentBg;
static NSColor *vCard, *vNav, *vPanel, *vToast, *vLinkBg, *vSep, *vBorder, *vCloseHover, *vBadgeText;
static NSColor *vEmber;   // the one highlight colour: your accent, or a quiet grey with Silver
static NSArray<NSArray *> *Accents(void) {
    return @[@[@"Silver", @0xdcdce2, @0x2c2c30], @[@"Crimson", @0xff3b55, @0xd70f35], @[@"Ember", @0xff6a3d, @0xe0461c],
             @[@"Blue", @0x5aa2ff, @0x1f6fe0], @[@"Violet", @0xb08cff, @0x7b4ee0], @[@"Green", @0x4fd18b, @0x14995a], @[@"Pink", @0xff7ab8, @0xe0408a]];
}
// Light or dark is decided once, when the palette is built, and everything reads that answer: asking macOS again
// while drawing could get a different reply mid-switch (Follow macOS at sunset), leaving dark capsules with dark text.
static int gThemeLight = -1;
static BOOL ThemeIsLightNow(void) {
    NSInteger t = [Defaults() integerForKey:kTheme];
    if (t == 3) return YES;
    if (t != 0) return NO;
    // Follow macOS: ask the system setting itself (fresh from disk), not the app's appearance, which lags a switch
    // and still says "dark" for a moment after leaving Carbon or Graphite
    CFPreferencesAppSynchronize(kCFPreferencesAnyApplication);
    CFStringRef s = (CFStringRef)CFPreferencesCopyAppValue(CFSTR("AppleInterfaceStyle"), kCFPreferencesAnyApplication);
    BOOL dark = s && CFGetTypeID(s) == CFStringGetTypeID() && CFStringCompare(s, CFSTR("Dark"), kCFCompareCaseInsensitive) == kCFCompareEqualTo;
    if (s) CFRelease(s);
    return !dark;
}
static BOOL ThemeIsLight(void) { if (gThemeLight < 0) gThemeLight = ThemeIsLightNow(); return gThemeLight == 1; }
static NSAppearance *ThemeAppearance(void) { return [NSAppearance appearanceNamed:ThemeIsLight() ? NSAppearanceNameAqua : NSAppearanceNameDarkAqua]; }
static void InitPalette(void) {
    NSInteger t = [Defaults() integerForKey:kTheme];
    gThemeLight = ThemeIsLightNow() ? 1 : 0;
    BOOL light = gThemeLight == 1, carbon = (t == 2);
    if (light) {
        vBg = Hex(0xe9e9ec); vPill = Hex(0xffffff); vPillFocus = Hex(0xffffff); vHover = Hex(0xdcdce1);
        vActive = Hex(0xd2d2d8); vLine = Hex(0xc4c4cb); vText = Hex(0x1b1b1e); vDim = Hex(0x55555c);
        vFaint = Hex(0x8b8b92); vContentBg = Hex(0xffffff);
        vCard = Hex(0xffffff); vNav = Hex(0xe2e2e6); vPanel = Hex(0xeeeef1); vToast = Hex(0x2a2a2e); vLinkBg = HexA(0xffffff, 0.97);
        vSep = HexA(0x000000, 0.07); vBorder = HexA(0x000000, 0.08); vCloseHover = Hex(0xc9c9d0); vBadgeText = Hex(0xffffff);
    } else if (carbon) {
        vBg = Hex(0x0d0d0f); vPill = Hex(0x1a1a1d); vPillFocus = Hex(0x141416); vHover = Hex(0x1c1c20);
        vActive = Hex(0x232327); vLine = Hex(0x2b2b30); vText = Hex(0xededf0); vDim = Hex(0x9d9da4);
        vFaint = Hex(0x66666d); vContentBg = Hex(0x0f0f11);
        vCard = Hex(0x18181b); vNav = Hex(0x0f0f11); vPanel = Hex(0x121214); vToast = Hex(0x232327); vLinkBg = HexA(0x161619, 0.96);
        vSep = HexA(0xffffff, 0.05); vBorder = HexA(0xffffff, 0.05); vCloseHover = Hex(0x34343a); vBadgeText = Hex(0x0d0d0f);
    } else {
        vBg = Hex(0x1c1c1e); vPill = Hex(0x2a2a2d); vPillFocus = Hex(0x232326); vHover = Hex(0x2c2c30);
        vActive = Hex(0x333338); vLine = Hex(0x3a3a3f); vText = Hex(0xececee); vDim = Hex(0xa3a3a9);
        vFaint = Hex(0x6e6e75); vContentBg = Hex(0x1b1b1d);
        vCard = Hex(0x262629); vNav = Hex(0x1a1a1c); vPanel = Hex(0x1f1f22); vToast = Hex(0x2f2f33); vLinkBg = HexA(0x232326, 0.96);
        vSep = HexA(0xffffff, 0.06); vBorder = HexA(0xffffff, 0.06); vCloseHover = Hex(0x45454b); vBadgeText = Hex(0x1c1c1e);
    }
    NSArray *a = Accents()[(NSUInteger)MAX(0, MIN((NSInteger)Accents().count - 1, [Defaults() integerForKey:kAccent]))];
    vAccent = Hex((uint32_t)[a[light ? 2 : 1] unsignedIntValue]);
    vEmber = [Defaults() integerForKey:kAccent] == 0 ? [vText colorWithAlphaComponent:0.55] : vAccent;   // Silver: no colour at all
}

// Your accent where something is chosen, on, or current. With Silver (no accent) the active tab keeps its profile's colour.
// iris://source?u=<address>: Iris's code viewer for a page or any file it loads
static NSString *SourceViewerURL(NSString *u, NSString *ident) {
    NSMutableCharacterSet *ok = NSCharacterSet.URLQueryAllowedCharacterSet.mutableCopy; [ok removeCharactersInString:@"&=+?#"];
    NSString *s = [@"iris://source?u=" stringByAppendingString:[u stringByAddingPercentEncodingWithAllowedCharacters:ok] ?: @""];
    return ident.length ? [s stringByAppendingFormat:@"&id=%@", ident] : s;
}

static BOOL AccentChosen(void) { return [Defaults() integerForKey:kAccent] != 0; }
// Where the tabs live: along the bottom edge (0), or down the left (1) or right (2) side, turned vertical.
static NSString *const kShelfSide = @"shelfSide";
static NSInteger ShelfSide(void) { NSInteger s = [Defaults() integerForKey:kShelfSide]; return s >= 0 && s <= 2 ? s : 0; }
static BOOL ShelfVertical(void) { return ShelfSide() != 0; }
static CGFloat ShelfMidY(CGFloat H) { return round((48 + H) / 2); }   // the middle of the page area, below the toolbar
// YES when Iris itself handles http(s) links; then "Open in Default Browser" would just reopen here, so it's hidden.
static BOOL IrisIsDefaultBrowser(void) {
    static BOOL cached; static CFAbsoluteTime at;
    CFAbsoluteTime now = CFAbsoluteTimeGetCurrent();
    if (at == 0 || now - at > 10) {
        NSURL *app = [NSWorkspace.sharedWorkspace URLForApplicationToOpenURL:[NSURL URLWithString:@"https://example.com"]];
        cached = app && [app.URLByStandardizingPath.path isEqualToString:NSBundle.mainBundle.bundleURL.URLByStandardizingPath.path];
        at = now;
    }
    return cached;
}

static void IrisEventLog(NSString *kind, NSString *detail);   // crashes/events.log (v6c_crash)
static NSFont *UIFont(CGFloat s, NSFontWeight w) { return [NSFont systemFontOfSize:s weight:w] ?: [NSFont systemFontOfSize:s] ?: [NSFont userFontOfSize:s]; }   // never nil: a nil font in drawing attributes is a crash
// Headings: San Francisco at display sizes (the system face, tuned for large text), not a serif:
// crisp and neutral, like the rest of macOS. Very large sizes go a step lighter so they don't shout.
static NSFont *TitleFont(CGFloat s, BOOL bold) {
    return [NSFont systemFontOfSize:s weight:!bold ? NSFontWeightRegular : s >= 36 ? NSFontWeightMedium : NSFontWeightSemibold];
}
static NSImage *Symbol(NSString *name, CGFloat pt, NSFontWeight w) {
    NSImage *im = [NSImage imageWithSystemSymbolName:name accessibilityDescription:nil];
    if (!im) return nil;
    return [im imageWithSymbolConfiguration:[NSImageSymbolConfiguration configurationWithPointSize:pt weight:w]];
}
static NSImage *Tinted(NSImage *im, NSColor *c) {
    if (!im) return nil;
    return [NSImage imageWithSize:im.size flipped:NO drawingHandler:^BOOL(NSRect r) {
        [im drawInRect:r]; [c set]; NSRectFillUsingOperation(r, NSCompositingOperationSourceAtop); return YES;
    }];
}
// Iris's look: quiet and exact. Soft macOS corners, hairline edges, no glow; colour only where it means something.
static void RoundRect(NSRect r, CGFloat radius, NSColor *fill) {
    [fill setFill];
    [[NSBezierPath bezierPathWithRoundedRect:r xRadius:radius yRadius:radius] fill];
}
static void ShardStroke(NSRect r, CGFloat c, NSColor *color, CGFloat w) {
    NSBezierPath *p = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(r, w / 2, w / 2) xRadius:c yRadius:c]; p.lineWidth = w; [color setStroke]; [p stroke];
}
// Aperture: Iris's own colours (the loading line), the same whatever accent is chosen. Kept for the moments
// that are Iris's: progress, where you are, a new build waiting. Everything else stays in your accent.
static NSColor *ApTeal(void)   { return ThemeIsLight() ? Hex(0x22b3a0) : Hex(0x7fe3d1); }
static NSColor *ApBlue(void)   { return ThemeIsLight() ? Hex(0x4a78ee) : Hex(0x86a3f7); }
static NSColor *ApViolet(void) { return ThemeIsLight() ? Hex(0x8c63e6) : Hex(0xb796f5); }
static NSGradient *ApertureGradient(CGFloat alpha) {
    return [[NSGradient alloc] initWithColors:@[[ApTeal() colorWithAlphaComponent:alpha], [ApBlue() colorWithAlphaComponent:alpha], [ApViolet() colorWithAlphaComponent:alpha]]];
}
static NSColor *ApertureAt(CGFloat t) {   // 0 teal … 0.5 blue … 1 violet
    t = MAX(0, MIN(1, t));
    return t < 0.5 ? [ApTeal() blendedColorWithFraction:t * 2 ofColor:ApBlue()] : [ApBlue() blendedColorWithFraction:(t - 0.5) * 2 ofColor:ApViolet()];
}
// A rounded outline drawn in the Aperture gradient (the same footprint as ShardStroke).
static void ApertureStroke(NSRect r, CGFloat c, CGFloat w) {
    NSBezierPath *ring = [NSBezierPath bezierPathWithRoundedRect:r xRadius:c yRadius:c];
    [ring appendBezierPath:[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(r, w, w) xRadius:MAX(0, c - w) yRadius:MAX(0, c - w)]];
    ring.windingRule = NSWindingRuleEvenOdd;
    [ApertureGradient(1) drawInBezierPath:ring angle:-35];
}
// A symbol filled with the Aperture gradient instead of one colour.
static NSImage *ApertureTinted(NSImage *im) {
    if (!im) return nil;
    return [NSImage imageWithSize:im.size flipped:NO drawingHandler:^BOOL(NSRect r) {
        [ApertureGradient(1) drawInRect:r angle:-45];
        [im drawInRect:r fromRect:NSZeroRect operation:NSCompositingOperationDestinationIn fraction:1];
        return YES;
    }];
}
static CGFloat gSlowMo = 1;   // dev: stretch Iris's own animations to check them ("slowmo 8" in control.txt)
// Monolith: the page is one slab; the controls float over it as dark glass.
static NSColor *MGlass(void) { return ThemeIsLight() ? HexA(0xffffff, 0.92) : HexA(0x0f1013, 0.9); }
static NSColor *MGlassEdge(void) { return ThemeIsLight() ? HexA(0x000000, 0.09) : HexA(0xffffff, 0.08); }
static NSColor *MPanel(void) { return ThemeIsLight() ? HexA(0xf6f6f4, 0.98) : HexA(0x111215, 0.97); }
static NSColor *MCard(void) { return ThemeIsLight() ? Hex(0xffffff) : Hex(0x1a1c20); }
static NSColor *MChip(void) { return ThemeIsLight() ? HexA(0x000000, 0.05) : HexA(0xffffff, 0.06); }
static void Blend(NSRect r) { NSRectFillUsingOperation(r, NSCompositingOperationSourceOver); }   // NSRectFill copies alpha straight through, punching see-through slits
static NSFont *MMono(CGFloat s, NSFontWeight w) { return [NSFont monospacedSystemFontOfSize:s weight:w] ?: UIFont(s, w); }
static void MShadowed(void (^draw)(void)) {
    NSShadow *sh = [NSShadow new]; sh.shadowColor = [NSColor colorWithWhite:0 alpha:ThemeIsLight() ? 0.12 : 0.3];
    sh.shadowBlurRadius = 14; sh.shadowOffset = NSMakeSize(0, -4);
    [NSGraphicsContext saveGraphicsState]; [sh set]; draw(); [NSGraphicsContext restoreGraphicsState];
}
static void FacetView(NSView *v, CGFloat c, NSColor *edge) {
    v.wantsLayer = YES;
    CALayer *L = v.layer; L.mask = nil; L.cornerRadius = c; L.masksToBounds = YES;
    if (@available(macOS 11.0, *)) L.cornerCurve = kCACornerCurveContinuous;
    for (CALayer *s in L.sublayers.copy) if ([s.name isEqualToString:@"facetEdge"]) [s removeFromSuperlayer];
    L.borderWidth = edge ? 1 : 0; L.borderColor = edge.CGColor;
}
// Condensed system type for big display text (SF Pro's narrow widths), falling back to regular widths.
static void DrawImage(NSImage *im, NSRect r) {
    [im drawInRect:r fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1 respectFlipped:YES hints:nil];
}
// Fill r with the image at its own proportions, centred; the overflow is cropped by the caller's clip (like CSS object-fit: cover).
static void DrawImageFill(NSImage *im, NSRect r) {
    NSSize s = im.size; if (s.width <= 0 || s.height <= 0) return;
    CGFloat k = MAX(NSWidth(r) / s.width, NSHeight(r) / s.height);
    NSRect d = NSMakeRect(NSMidX(r) - s.width * k / 2, NSMidY(r) - s.height * k / 2, s.width * k, s.height * k);
    [im drawInRect:d fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1 respectFlipped:YES hints:@{NSImageHintInterpolation: @(NSImageInterpolationHigh)}];
}
static NSRect CenterIn(NSSize s, NSRect r) {
    return NSMakeRect(round(NSMidX(r) - s.width / 2), round(NSMidY(r) - s.height / 2), s.width, s.height);
}
static void Clip(NSView *v) { @try { [v setValue:@YES forKey:@"clipsToBounds"]; } @catch (NSException *e) {} }
static NSString *Trim(NSString *s) { return [s stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; }

static NSString *HostOf(NSURL *u) {
    NSString *h = u.host.lowercaseString ?: @"";
    return [h hasPrefix:@"www."] ? [h substringFromIndex:4] : h;
}
static NSDictionary *gWebApp;       // running as an installed web app (see the web-app code)
static NSDictionary *gProfileApp;   // running as a profile's own app, a separate user: {id, name, color, mainApp}
// Iris Dev: the copy new builds go to first (com.y.iris.dev). It keeps its own data, so testing never touches yours.
static BOOL IrisIsDev(void) { static int dev = -1; if (dev < 0) dev = [NSBundle.mainBundle.bundleIdentifier isEqualToString:@"com.y.iris.dev"]; return dev == 1; }
// Where this Iris keeps its data. Iris: Application Support/Iris. Iris Dev: Iris Dev. A profile's app: Iris/Profiles/<id>,
// a person of its own. An installed site: the folder of the Iris (or profile) that installed it, for its extensions and lists.
static NSString *SupportDir(void) {
    NSString *base = NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory, NSUserDomainMask, YES).firstObject, *d;
    NSString *root = [gWebApp[@"root"] isKindOfClass:NSString.class] ? gWebApp[@"root"] : nil;
    if (root.length) d = root;
    else if ([gProfileApp[@"id"] length]) d = [[[base stringByAppendingPathComponent:@"Iris"] stringByAppendingPathComponent:@"Profiles"] stringByAppendingPathComponent:gProfileApp[@"id"]];
    else d = [base stringByAppendingPathComponent:IrisIsDev() ? @"Iris Dev" : @"Iris"];
    [NSFileManager.defaultManager createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil];
    return d;
}
static NSString *SupportFile(NSString *name) { return [SupportDir() stringByAppendingPathComponent:name]; }

#pragma mark - Search engines

static NSArray<NSArray<NSString *> *> *Engines(void) {
    NSArray *base = @[@[@"DuckDuckGo", @"https://duckduckgo.com/?q=%@"],
             @[@"Google", @"https://www.google.com/search?q=%@"],
             @[@"Brave Search", @"https://search.brave.com/search?q=%@"],
             @[@"Kagi", @"https://kagi.com/search?q=%@"],
             @[@"Startpage", @"https://www.startpage.com/do/search?q=%@"],
             @[@"Ecosia", @"https://www.ecosia.org/search?q=%@"],
             @[@"Bing", @"https://www.bing.com/search?q=%@"],
             @[@"Perplexity", @"https://www.perplexity.ai/search?q=%@"]];
    NSArray *c = [Defaults() arrayForKey:kCustomEngine];
    if (c.count == 2 && [c[1] containsString:@"%@"]) base = [base arrayByAddingObject:c];
    return base;
}
static NSArray<NSString *> *Engine(void) {
    NSInteger i = [Defaults() integerForKey:kSearch];
    NSArray *e = Engines();
    return e[(NSUInteger)MAX(0, MIN((NSInteger)e.count - 1, i))];
}
static NSURL *SearchURL(NSString *q) {
    NSString *enc = [q stringByAddingPercentEncodingWithAllowedCharacters:NSCharacterSet.URLQueryAllowedCharacterSet];
    enc = [enc stringByReplacingOccurrencesOfString:@"&" withString:@"%26"];
    enc = [enc stringByReplacingOccurrencesOfString:@"+" withString:@"%2B"];
    return [NSURL URLWithString:[NSString stringWithFormat:Engine()[1], enc]];
}

// What the address bar does with typed text: a URL if it looks like one, otherwise a search.
static NSURL *URLFromInput(NSString *s) {
    s = Trim(s);
    if (!s.length) return nil;
    if ([s rangeOfString:@" "].location == NSNotFound) {
        NSRegularExpression *scheme = [NSRegularExpression regularExpressionWithPattern:@"^[a-zA-Z][a-zA-Z0-9+.-]*:" options:0 error:nil];
        if ([scheme firstMatchInString:s options:0 range:NSMakeRange(0, s.length)] && ![s hasPrefix:@"localhost:"]) {
            NSURL *u = [NSURL URLWithString:s];
            if (u.scheme && ([u.scheme isEqualToString:@"http"] || [u.scheme isEqualToString:@"https"] || [u.scheme isEqualToString:@"file"] || [u.scheme isEqualToString:@"about"] || [u.scheme isEqualToString:@"iris"] || [u.scheme isEqualToString:@"chrome-extension"] || [u.scheme isEqualToString:@"view-source"])) return u;
        }
        NSRegularExpression *hostish = [NSRegularExpression regularExpressionWithPattern:
            @"^(localhost|[^./\\s]+(\\.[^./\\s]+)*\\.[a-zA-Z]{2,}|\\d{1,3}(\\.\\d{1,3}){3})(:\\d+)?(/.*)?$" options:0 error:nil];
        if ([hostish firstMatchInString:s options:0 range:NSMakeRange(0, s.length)]) {
            NSURL *u = [NSURL URLWithString:[(([s hasPrefix:@"localhost"] || [s rangeOfString:@"127.0.0.1"].location == 0) ? @"http://" : @"https://") stringByAppendingString:s]];
            if (u) return u;
        }
    }
    return SearchURL(s);
}

// Tracking tags that ride along on links (utm_*, fbclid, gclid...). Removed before a page loads.
static NSURL *StripTracking(NSURL *u) {
    NSURLComponents *c = [NSURLComponents componentsWithURL:u resolvingAgainstBaseURL:NO];
    if (!c.queryItems.count) return nil;
    static NSRegularExpression *rx;
    if (!rx) rx = [NSRegularExpression regularExpressionWithPattern:
        @"^(utm_[a-z_]+|gclid|gclsrc|dclid|gbraid|wbraid|fbclid|msclkid|mc_cid|mc_eid|igshid|igsh|yclid|_hsenc|_hsmi|ref_src|oly_anon_id|oly_enc_id|vero_id|_openstat|twclid|ttclid|li_fat_id|mkt_tok|srsltid)$"
        options:NSRegularExpressionCaseInsensitive error:nil];
    NSMutableArray *keep = [NSMutableArray array]; BOOL hit = NO;
    for (NSURLQueryItem *q in c.queryItems) {
        if ([rx firstMatchInString:q.name options:0 range:NSMakeRange(0, q.name.length)]) hit = YES; else [keep addObject:q];
    }
    if (!hit) return nil;
    c.queryItems = keep.count ? keep : nil;
    return c.URL;
}

