        if ([t isEqualToString:@"main_frame"]) { [wk addObject:@"document"]; *top = YES; }
        else if ([t isEqualToString:@"sub_frame"]) { [wk addObject:@"document"]; *child = YES; }
        else if (m[t]) [wk addObject:m[t]];
