    if (!allowAll) base[@"resource-type"] = [wkTypes.allObjects sortedArrayUsingSelector:@selector(compare:)];
    if ([c[@"domainType"] isEqual:@"firstParty"]) base[@"load-type"] = @[@"first-party"];
