    NSSet *ids = [a isKindOfClass:NSDictionary.class] && [a[@"ids"] isKindOfClass:NSArray.class] ? [NSSet setWithArray:a[@"ids"]] : nil;
    if ([op isEqualToString:@"scripting.getRegisteredContentScripts"]) {
