        if (gExtDebug) DLog(@"ext %@ console: %@", e.name, t.length > 400 ? [t substringToIndex:400] : t);
        reply(NSNull.null, nil); return;
    }
    WKContentWorld *world = m.world;
    RememberFrame(m.webView, m.frameInfo);
    BOOL fromPage = world == WKContentWorld.pageWorld;
    NSString *proto = m.frameInfo.securityOrigin.protocol;
    // who may call: the extension's own pages, its content world, and its externally_connectable sites
    if (fromPage && ![proto isEqualToString:@"chrome-extension"]) {
        if (![op isEqualToString:@"runtime.sendMessageExternal"]) { reply(nil, @"not allowed"); return; }
    } else if (fromPage && ![m.frameInfo.securityOrigin.host isEqualToString:e.ident]) { reply(nil, @"not allowed"); return; }
    else if (!fromPage && world != e.world) { reply(nil, @"not allowed"); return; }

    id (^arg)(NSUInteger) = ^id(NSUInteger i) { id v = i < args.count ? args[i] : nil; return v == NSNull.null ? nil : v; };
    void (^ok)(id) = ^(id v) { reply(v ?: NSNull.null, nil); };
    void (^fail)(NSString *) = ^(NSString *why) { reply(@{@"__error": why ?: @"error"}, nil); };

    if ([op isEqualToString:@"runtime.sendMessage"] || [op isEqualToString:@"runtime.sendMessageExternal"]) {
        BOOL ext = [op hasSuffix:@"External"];
        if (m.webView == e.background) { ok(nil); return; }   // background → itself isn't delivered (popup listeners not tracked yet)
        NSMutableDictionary *sender = [[self senderFor:m ext:e] mutableCopy];
        if (ext) [sender removeObjectForKey:@"id"];   // like Chrome: messages from web pages carry no extension id
        [self toBackground:e body:@"return await __irisOnMessage(msg, sender, external)" args:@{@"msg": arg(0) ?: NSNull.null, @"sender": sender, @"external": @(ext)}
                      done:^(id r, NSError *err) {
            if (ext || gExtDebug) DLog(@"ext msg%@ from %@: %@ → %@ %@", ext ? @" (external)" : @"", m.frameInfo.securityOrigin.host, [self brief:arg(0)], [self brief:r], err.localizedDescription ?: @"");
            if (err) fail(err.localizedDescription); else ok(r); }];
    }
    else if ([op isEqualToString:@"runtime.connect"]) {
        FPort *p = [FPort new]; p.ident = arg(0);
        p.aView = m.webView; p.aWorld = world; p.aFrame = m.frameInfo;
        p.bView = e.background; p.bWorld = WKContentWorld.pageWorld;
        if (!p.ident || !e.background) { ok(@NO); return; }
        _ports[p.ident] = p;
        [self toBackground:e body:@"return __irisOnConnect(id, name, sender, false)" args:@{@"id": p.ident, @"name": arg(1) ?: @"", @"sender": [self senderFor:m ext:e]}
                      done:^(id r, NSError *err) { ok(@(err == nil)); }];
    }
    else if ([op isEqualToString:@"port.post"] || [op isEqualToString:@"port.disconnect"]) {
        FPort *p = _ports[arg(0) ?: @""]; if (!p) { ok(@NO); return; }
        BOOL fromA = m.webView == p.aView && world == p.aWorld;
        WKWebView *v = fromA ? p.bView : p.aView; WKContentWorld *w = fromA ? p.bWorld : p.aWorld;
        WKFrameInfo *f = fromA ? nil : p.aFrame;
        BOOL post = [op isEqualToString:@"port.post"];
        if (gExtDebug) DLog(@"ext port %@ %@ %@: %@", p.ident, fromA ? @"→bg" : @"→page", post ? @"msg" : @"disconnect", [self brief:arg(1)]);
        if (!post) [_ports removeObjectForKey:p.ident];
        [self call:@"return __irisPortEvent(id, kind, data)" args:@{@"id": p.ident, @"kind": post ? @"message" : @"disconnect", @"data": arg(1) ?: NSNull.null}
              view:v world:w frame:f done:^(id r, NSError *err) { if (err && f) [self call:@"return __irisPortEvent(id, kind, data)" args:@{@"id": p.ident, @"kind": post ? @"message" : @"disconnect", @"data": arg(1) ?: NSNull.null} view:v world:w frame:nil done:nil]; }];
        ok(@YES);
    }
    else if ([op hasPrefix:@"storage."]) [self storageOp:op ext:e args:args ok:ok];
    else if ([op isEqualToString:@"tabs.query"]) {
        NSDictionary *q = arg(0) ?: @{};
        NSMutableArray *out = [NSMutableArray array];
        BOOL thisWin = [q[@"currentWindow"] boolValue] || [q[@"lastFocusedWindow"] boolValue];
        for (VTab *t in AllTabs(NO)) {
            if (thisWin && t.owner != NormalWin()) continue;
            if ([q[@"windowId"] isKindOfClass:NSNumber.class] && [q[@"windowId"] integerValue] > 0 && WinID(t.owner) != [q[@"windowId"] integerValue]) continue;
            if ([q[@"active"] isKindOfClass:NSNumber.class] && [q[@"active"] boolValue] != (t == t.owner.current)) continue;
            if (q[@"url"]) { NSString *pat = [q[@"url"] isKindOfClass:NSString.class] ? q[@"url"] : nil; if (pat && ![pat isEqualToString:@"<all_urls>"] && ![t.url ?: @"" hasPrefix:[pat stringByReplacingOccurrencesOfString:@"*" withString:@""]]) continue; }
            [out addObject:TabInfo(t)];
        }
        ok(out);
    }
    else if ([op isEqualToString:@"tabs.get"]) { NSDictionary *i = TabInfo(TabForID([arg(0) integerValue])); if (i) ok(i); else fail(@"No tab with id"); }
    else if ([op isEqualToString:@"tabs.getCurrent"]) ok(TabInfo(TabForView(m.webView)));
    else if ([op isEqualToString:@"tabs.create"]) {
        NSDictionary *p = arg(0) ?: @{};
        NSString *u = p[@"url"]; if ([u isKindOfClass:NSString.class] && ![u containsString:@":"]) u = [NSString stringWithFormat:@"chrome-extension://%@/%@", e.ident, [u hasPrefix:@"/"] ? [u substringFromIndex:1] : u];
        VWindow *w = NormalWin(); NSArray *before = w.tabs.copy;
        [w newTab:[NSURL URLWithString:u ?: @""] select:p[@"active"] ? [p[@"active"] boolValue] : YES];
        VTab *made = nil; for (VTab *t in w.tabs) if (![before containsObject:t]) made = t;
        ok(TabInfo(made ?: w.current));
    }
    else if ([op isEqualToString:@"tabs.update"]) {
        BOOL hasId = args.count >= 2;
        VTab *t = hasId ? TabForID([arg(0) integerValue]) : NormalWin().current;
        NSDictionary *p = (hasId ? arg(1) : arg(0)) ?: @{};
        if (!t) { fail(@"No tab with id"); return; }
        if ([p[@"url"] isKindOfClass:NSString.class]) { if (!t.web) [t.owner selectTab:t]; [t.web open:p[@"url"] record:YES]; }
        if ([p[@"active"] boolValue]) [t.owner selectTab:t];
        ok(TabInfo(t));
    }
    else if ([op isEqualToString:@"tabs.remove"]) {
        id ids = arg(0); for (NSNumber *n in [ids isKindOfClass:NSArray.class] ? ids : @[ids ?: @0]) { VTab *t = TabForID(n.integerValue); if (t) [t.owner closeTab:t]; }
        ok(nil);
    }
    else if ([op isEqualToString:@"tabs.reload"]) { VTab *t = arg(0) ? TabForID([arg(0) integerValue]) : NormalWin().current; [t.web reload]; ok(nil); }
    else if ([op isEqualToString:@"tabs.sendMessage"]) {
        VTab *t = TabForID([arg(0) integerValue]);
        if (!t.web.web) { fail(@"Could not establish connection. Receiving end does not exist."); return; }
        NSMutableDictionary *sender = [@{@"id": e.ident} mutableCopy];
        if (m.frameInfo.request.URL) sender[@"url"] = m.frameInfo.request.URL.absoluteString;
        // options.frameId: one frame of the tab (one that has talked to the extension), otherwise the page
        NSDictionary *opts = [arg(2) isKindOfClass:NSDictionary.class] ? arg(2) : nil;
        WKFrameInfo *fi = nil;
        if ([opts[@"frameId"] isKindOfClass:NSNumber.class] && [opts[@"frameId"] longLongValue] != 0) { fi = [gFrames objectForKey:t.web.web][opts[@"frameId"]]; if (!fi) { fail(@"Could not establish connection. Receiving end does not exist."); return; } }
        [self call:@"return await __irisOnMessage(msg, sender, false)" args:@{@"msg": arg(1) ?: NSNull.null, @"sender": sender} view:t.web.web world:e.world frame:fi
              done:^(id r, NSError *err) { if (err) fail(@"Could not establish connection. Receiving end does not exist."); else ok(r); }];
    }
    else if ([op isEqualToString:@"scripting.executeScript"] || [op isEqualToString:@"scripting.insertCSS"] || [op isEqualToString:@"scripting.removeCSS"]) [self scripting:op ext:e details:arg(0) ok:ok fail:fail];
    else if (([op hasPrefix:@"scripting."] && [op hasSuffix:@"ContentScripts"]) || [op hasPrefix:@"userScripts."]) [self registeredOp:op ext:e arg:arg(0) ok:ok fail:fail];
    else if ([op hasPrefix:@"dnr."]) [FDNR.shared op:op ext:e.ident args:args reply:^(id r, NSString *err) { if (err) fail(err); else ok(r); }];
    else if ([op hasPrefix:@"contextMenus."]) [self menuOp:op ext:e args:args ok:ok fail:fail];
    else if ([op isEqualToString:@"action.openPopup"]) { [self openPopup:e from:nil]; ok(nil); }
    else if ([op isEqualToString:@"runtime.openOptionsPage"]) {
        [self openOptions:e];
        ok(nil);
    }
    else if ([op isEqualToString:@"runtime.reload"]) { [e.background reload]; ok(nil); }
    else if ([op isEqualToString:@"net.fetch"]) [self fetch:arg(0) ok:ok];
    else { DLog(@"ext unsupported op %@", op); fail([@"Iris doesn't support " stringByAppendingString:op]); }
}

- (NSString *)brief:(id)o {
    if (!o) return @"nil";
    if ([o isKindOfClass:NSDictionary.class]) return [NSString stringWithFormat:@"{type:%@}", o[@"type"] ?: @"?"];
    return [o isKindOfClass:NSString.class] ? @"<string>" : NSStringFromClass([o class]);
    NSData *d = [NSJSONSerialization isValidJSONObject:o] ? [NSJSONSerialization dataWithJSONObject:o options:0 error:nil] : nil;
    NSString *t = d ? [[NSString alloc] initWithData:d encoding:NSUTF8StringEncoding] : [o description];
    return t.length > 400 ? [[t substringToIndex:400] stringByAppendingString:@"…"] : t;
}

- (void)storageOp:(NSString *)op ext:(FExt *)e args:(NSArray *)args ok:(void (^)(id))ok {
    NSString *areaName = args.count ? args[0] : @"local";
    NSMutableDictionary *area = e.store[areaName]; if (!area) { ok(@{}); return; }
    id keys = args.count > 1 ? args[1] : nil;
    if ([op isEqualToString:@"storage.get"]) {
        if (!keys || keys == NSNull.null) { ok(area); return; }
        NSMutableDictionary *out = [NSMutableDictionary dictionary];
        if ([keys isKindOfClass:NSString.class]) { if (area[keys]) out[keys] = area[keys]; }
        else if ([keys isKindOfClass:NSArray.class]) { for (NSString *k in keys) if (area[k]) out[k] = area[k]; }
        else if ([keys isKindOfClass:NSDictionary.class]) { for (NSString *k in keys) out[k] = area[k] ?: keys[k]; }
        ok(out); return;
    }
    NSMutableDictionary *changes = [NSMutableDictionary dictionary];
    if ([op isEqualToString:@"storage.set"] && [keys isKindOfClass:NSDictionary.class]) {
        for (NSString *k in keys) { changes[k] = @{@"oldValue": area[k] ?: NSNull.null, @"newValue": keys[k]}; area[k] = keys[k]; }
    } else if ([op isEqualToString:@"storage.remove"]) {
        for (NSString *k in [keys isKindOfClass:NSArray.class] ? keys : (keys ? @[keys] : @[])) if (area[k]) { changes[k] = @{@"oldValue": area[k]}; [area removeObjectForKey:k]; }
    } else if ([op isEqualToString:@"storage.clear"]) {
        for (NSString *k in area) changes[k] = @{@"oldValue": area[k]};
        [area removeAllObjects];
    }
    ok(nil);
    if (!changes.count) return;
    if ([areaName isEqualToString:@"local"] || [areaName isEqualToString:@"sync"]) {
        NSData *d = [NSJSONSerialization dataWithJSONObject:area options:0 error:nil];
        [d writeToFile:[self storePath:e area:areaName] atomically:YES];
    }
    // tell every part of the extension (onChanged): background, its pages, its content scripts
    NSDictionary *a = @{@"c": changes, @"a": areaName};
    NSString *body = @"return globalThis.__irisStorageChanged ? __irisStorageChanged(c, a) : false";
    if (e.background) [self call:body args:a view:e.background world:WKContentWorld.pageWorld frame:nil done:nil];
    for (VTab *t in AllTabs(NO)) if (t.web.web) {
        [self call:body args:a view:t.web.web world:e.world frame:nil done:nil];
        if ([t.url hasPrefix:@"chrome-extension://"]) [self call:body args:a view:t.web.web world:WKContentWorld.pageWorld frame:nil done:nil];
    }
    WKWebView *pop = (WKWebView *)_popover.contentViewController.view;
    if (_popover.shown && [pop isKindOfClass:WKWebView.class]) [self call:body args:a view:pop world:WKContentWorld.pageWorld frame:nil done:nil];
}

- (void)scripting:(NSString *)op ext:(FExt *)e details:(NSDictionary *)d ok:(void (^)(id))ok fail:(void (^)(NSString *))fail {
    VTab *t = TabForID([d[@"target"][@"tabId"] integerValue]);
    WKWebView *v = t.web.web;
    if (!v) { fail(@"No tab with id"); return; }
    WKContentWorld *w = [d[@"world"] isEqual:@"MAIN"] ? WKContentWorld.pageWorld : e.world;
    NSArray *frames = TargetFrames(v, [d[@"target"] isKindOfClass:NSDictionary.class] ? d[@"target"] : @{});
    if (!frames.count) { fail(@"No frame with id"); return; }
    NSMutableString *code = [NSMutableString string];
    NSDictionary *jsArgs;
    BOOL css = [op isEqualToString:@"scripting.insertCSS"] || [op isEqualToString:@"scripting.removeCSS"];
    if (css) {
        NSMutableString *text = [NSMutableString stringWithString:[d[@"css"] isKindOfClass:NSString.class] ? d[@"css"] : @""];
        for (NSString *f in [d[@"files"] isKindOfClass:NSArray.class] ? d[@"files"] : @[]) [text appendString:[NSString stringWithContentsOfFile:[e.dir stringByAppendingPathComponent:f] encoding:NSUTF8StringEncoding error:nil] ?: @""];
        // each inserted sheet is labelled with a hash of its text, so the same text can be removed again
        NSData *bytes = [text dataUsingEncoding:NSUTF8StringEncoding]; unsigned char h[CC_SHA256_DIGEST_LENGTH]; CC_SHA256(bytes.bytes, (CC_LONG)bytes.length, h);
        NSMutableString *key = [NSMutableString stringWithString:e.ident]; for (int i = 0; i < 8; i++) [key appendFormat:@"%02x", h[i]];
        if ([op isEqualToString:@"scripting.removeCSS"])
            [code appendString:@"for (const s of document.querySelectorAll('style[data-iris-css]')) if (s.dataset.irisCss === key) { s.remove(); break; } return null;"];
        else [code appendString:@"const s = document.createElement('style'); s.dataset.irisCss = key; s.textContent = css; (document.head || document.documentElement).appendChild(s); return null;"];
        jsArgs = @{@"css": text, @"key": key};
        w = WKContentWorld.pageWorld;   // a style is part of the page whichever world adds it
    } else {
        if ([d[@"func"] isKindOfClass:NSString.class]) [code appendFormat:@"return await (%@)(...args);", d[@"func"]];
        else {
            for (NSString *f in [d[@"files"] isKindOfClass:NSArray.class] ? d[@"files"] : @[]) {
                NSString *t2 = [NSString stringWithContentsOfFile:[e.dir stringByAppendingPathComponent:f] encoding:NSUTF8StringEncoding error:nil];
                if (t2) [code appendFormat:@"%@\n;", t2];
            }
            // run as the body of an injected function: WebKit injects it like a user script, so the page's CSP doesn't apply
            [code appendString:@"\nreturn null;"];
        }
        jsArgs = @{@"args": [d[@"args"] isKindOfClass:NSArray.class] ? d[@"args"] : @[]};
    }
    NSString *shim = w == e.world ? [[self shimFor:@"content" ext:e] stringByAppendingString:@";true"] : nil;
    NSMutableArray *results = [NSMutableArray array];
    __block NSUInteger pending = frames.count;
    for (NSArray *fr in frames) {
        WKFrameInfo *fi = fr[1] == NSNull.null ? nil : fr[1];
        NSNumber *fid = fr[0];
        void (^finished)(id) = ^(id r) {
            [results addObject:@{@"frameId": fid, @"result": r ?: NSNull.null, @"documentId": fid.longLongValue ? fid.stringValue : @"main"}];
            if (--pending == 0) ok(css ? nil : results);
        };
        void (^run)(void) = ^{
            [v callAsyncJavaScript:code arguments:jsArgs inFrame:fi inContentWorld:w completionHandler:^(id r, NSError *err) {
                if (err && !css) DLog(@"executeScript error: %@", err.userInfo[@"WKJavaScriptExceptionMessage"] ?: err.localizedDescription);
                finished(r);
            }];
        };
        if (!shim) { run(); continue; }
        // the extension's own world must have chrome.* before its code runs (a page loaded before the extension, or one
        // its content scripts don't match, has a bare world): give it the API first, as Chrome always does
        [v evaluateJavaScript:@"!!globalThis.__irisExtLoaded" inFrame:fi inContentWorld:w completionHandler:^(id has, NSError *err) {
            if ([has boolValue]) { run(); return; }
            [v evaluateJavaScript:shim inFrame:fi inContentWorld:w completionHandler:^(id r2, NSError *e2) { run(); }];
        }];
    }
}

- (void)fetch:(NSDictionary *)r ok:(void (^)(id))ok {
    NSURL *u = [NSURL URLWithString:r[@"url"] ?: @""];
    if (!u) { ok(@{@"error": @"bad URL"}); return; }
    NSMutableURLRequest *q = [NSMutableURLRequest requestWithURL:u];
    q.HTTPMethod = r[@"method"] ?: @"GET";
    NSDictionary *hs = [r[@"headers"] isKindOfClass:NSDictionary.class] ? r[@"headers"] : @{};
    for (NSString *k in hs) [q setValue:hs[k] forHTTPHeaderField:k];
    if ([r[@"body"] isKindOfClass:NSString.class]) q.HTTPBody = [[NSData alloc] initWithBase64EncodedString:r[@"body"] options:0];
    q.HTTPShouldHandleCookies = ![r[@"credentials"] isEqual:@"omit"];
    [[NSURLSession.sharedSession dataTaskWithRequest:q completionHandler:^(NSData *d, NSURLResponse *resp, NSError *err) {
        NSHTTPURLResponse *h = [resp isKindOfClass:NSHTTPURLResponse.class] ? (NSHTTPURLResponse *)resp : nil;
        NSDictionary *out = err ? @{@"error": err.localizedDescription} :
            @{@"status": @(h.statusCode ?: 200), @"statusText": [NSHTTPURLResponse localizedStringForStatusCode:h.statusCode], @"headers": h.allHeaderFields ?: @{},
              @"body": [d base64EncodedStringWithOptions:0] ?: @"", @"url": resp.URL.absoluteString ?: u.absoluteString};
        dispatch_async(dispatch_get_main_queue(), ^{ ok(out); });
    }] resume];
}

#pragma mark chrome-extension:// files

- (void)webView:(WKWebView *)w startURLSchemeTask:(id<WKURLSchemeTask>)task {
    NSURL *u = task.request.URL;
    FExt *e = _exts[u.host.lowercaseString ?: @""];
    NSData *data = nil; NSString *mime = @"text/html";
    if (e) {
        NSString *path = u.path.length ? u.path : @"/";
        if ([path isEqualToString:@"/__iris_background.html"]) data = [self backgroundHTML:e];
        else {
            NSString *file = [[e.dir stringByAppendingPathComponent:path] stringByStandardizingPath];
            if ([file hasPrefix:e.dir]) { data = [NSData dataWithContentsOfFile:file]; mime = MIMEFor(file.pathExtension); }
        }
    }
    NSDictionary *headers = @{@"Content-Type": mime, @"Access-Control-Allow-Origin": @"*", @"Cache-Control": @"no-cache"};
    NSHTTPURLResponse *resp = [[NSHTTPURLResponse alloc] initWithURL:u statusCode:data ? 200 : 404 HTTPVersion:@"HTTP/1.1" headerFields:headers];
    @try {
        [task didReceiveResponse:resp];
        [task didReceiveData:data ?: [NSData data]];
        [task didFinish];
    } @catch (NSException *x) {}
}
- (void)webView:(WKWebView *)w stopURLSchemeTask:(id<WKURLSchemeTask>)task {}

#pragma mark Names and icons for the toolbar, address bar and sidebar

- (NSImage *)iconFor:(FExt *)e {
    if (!e) return nil;
    NSDictionary *action = e.manifest[@"action"] ?: e.manifest[@"browser_action"];
    id icons = action[@"default_icon"] ?: e.manifest[@"icons"];
    NSString *path = [icons isKindOfClass:NSString.class] ? icons : nil;
    if ([icons isKindOfClass:NSDictionary.class]) for (NSString *size in @[@"32", @"48", @"38", @"64", @"128", @"16"]) if (icons[size]) { path = icons[size]; break; }
    if (!path) return nil;
    NSImage *im = [[NSImage alloc] initWithContentsOfFile:[e.dir stringByAppendingPathComponent:path]];
    im.size = NSMakeSize(18, 18);
    return im;
}
- (NSString *)nameForID:(NSString *)ident { return _exts[ident.lowercaseString].name; }
- (NSImage *)iconForID:(NSString *)ident { return [self iconFor:_exts[ident.lowercaseString]]; }

#pragma mark Managing extensions (Settings ▸ Extensions)

- (NSArray<NSDictionary *> *)allExtensionInfo {
    NSMutableArray *out = [NSMutableArray array];
    for (NSDictionary *src in @[_exts, _disabled]) for (FExt *e in src.allValues)
        [out addObject:@{@"ident": e.ident, @"name": e.name ?: e.ident, @"version": e.manifest[@"version"] ?: @"", @"dir": e.dir,
                         @"enabled": @(src == _exts), @"icon": [self iconFor:e] ?: [NSImage imageWithSystemSymbolName:@"puzzlepiece.extension" accessibilityDescription:nil]}];
    return [out sortedArrayUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) { return [a[@"name"] compare:b[@"name"]]; }];
}
- (void)setExtension:(NSString *)ident enabled:(BOOL)on {
    NSMutableArray *off = [[Defaults() arrayForKey:kExtDisabled] ?: @[] mutableCopy];
    if (on) [off removeObject:ident]; else if (![off containsObject:ident]) [off addObject:ident];
    [Defaults() setObject:off forKey:kExtDisabled];
}
- (void)removeExtension:(NSString *)ident {
    FExt *e = _exts[ident] ?: _disabled[ident]; if (!e) return;
    [NSFileManager.defaultManager trashItemAtURL:[NSURL fileURLWithPath:e.dir] resultingItemURL:nil error:nil];
    [_disabled removeObjectForKey:ident];
}

// Install from a Chrome Web Store link (or a bare extension ID): download the CRX, keep its official ID
// (the public key goes into manifest.json, so sites that talk to the extension still recognise it), unpack.
- (void)installFromWebStore:(NSString *)input done:(void (^)(NSString *name, NSString *error))done {
    NSRegularExpression *rx = [NSRegularExpression regularExpressionWithPattern:@"[a-p]{32}" options:0 error:nil];
    NSTextCheckingResult *m = [rx firstMatchInString:input ?: @"" options:0 range:NSMakeRange(0, input.length)];
    if (!m) { done(nil, @"That doesn't look like a Chrome Web Store link."); return; }
    NSString *ident = [input substringWithRange:m.range];
    NSURL *u = [NSURL URLWithString:[NSString stringWithFormat:@"https://clients2.google.com/service/update2/crx?response=redirect&prodversion=140.0.0.0&acceptformat=crx2,crx3&x=id%%3D%@%%26installsource%%3Dondemand%%26uc", ident]];
    [[NSURLSession.sharedSession dataTaskWithURL:u completionHandler:^(NSData *crx, NSURLResponse *r, NSError *err) {
        NSString *problem = nil, *name = nil;
        NSData *zip = nil, *key = nil;
        const uint8_t *b = crx.bytes;
        if (!crx || crx.length < 16 || memcmp(b, "Cr24", 4) != 0) problem = err.localizedDescription ?: @"The Web Store didn't send an extension.";
        else {
            uint32_t ver = OSReadLittleInt32(b, 4);
            if (ver == 2) {
                uint32_t kl = OSReadLittleInt32(b, 8), sl = OSReadLittleInt32(b, 12);
                if (16 + kl + sl <= crx.length) { key = [crx subdataWithRange:NSMakeRange(16, kl)]; zip = [crx subdataWithRange:NSMakeRange(16 + kl + sl, crx.length - 16 - kl - sl)]; }
            } else {
                uint32_t hl = OSReadLittleInt32(b, 8);
                if (12 + hl <= crx.length) {
                    zip = [crx subdataWithRange:NSMakeRange(12 + hl, crx.length - 12 - hl)];
                    // CRX3 header is protobuf: fields 2/3 hold {1: public key, 2: signature}; pick the key whose ID matches
                    const uint8_t *h = b + 12; size_t n = hl, i = 0;
                    uint64_t (^varint)(size_t *) = ^uint64_t(size_t *p) { uint64_t v = 0; int s = 0; while (*p < n) { uint8_t c = h[(*p)++]; v |= (uint64_t)(c & 127) << s; s += 7; if (!(c & 128)) break; } return v; };
                    while (i < n && !key) {
                        uint64_t tag = varint(&i); uint64_t f = tag >> 3, wt = tag & 7;
                        if (wt != 2) { if (wt == 0) varint(&i); else break; continue; }
                        uint64_t len = varint(&i); size_t end = i + (size_t)len; if (end > n) break;
                        if (f == 2 || f == 3) {
                            size_t j = i;
                            while (j < end) {
                                size_t jj = j; uint64_t t2 = 0; int s2 = 0; while (jj < end) { uint8_t c = h[jj++]; t2 |= (uint64_t)(c & 127) << s2; s2 += 7; if (!(c & 128)) break; }
                                uint64_t l2 = 0; s2 = 0; while (jj < end) { uint8_t c = h[jj++]; l2 |= (uint64_t)(c & 127) << s2; s2 += 7; if (!(c & 128)) break; }
                                if ((t2 >> 3) == 1 && jj + l2 <= end) {
                                    NSData *cand = [NSData dataWithBytes:h + jj length:(NSUInteger)l2];
                                    if ([ExtIDFromKey([cand base64EncodedStringWithOptions:0]) isEqualToString:ident]) key = cand;
                                }
                                j = jj + (size_t)l2;
                            }
                        }
                        i = end;
                    }
                }
            }
            if (!zip.length) problem = @"The extension file was damaged.";
        }
        if (!problem) {
            NSString *tmp = [NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"%@.zip", ident]];
            [zip writeToFile:tmp atomically:YES];
            NSString *dest = [ExtRoot() stringByAppendingPathComponent:ident];
            [NSFileManager.defaultManager removeItemAtPath:dest error:nil];
            NSTask *t = [NSTask launchedTaskWithLaunchPath:@"/usr/bin/ditto" arguments:@[@"-x", @"-k", tmp, dest]];
            [t waitUntilExit];
            [NSFileManager.defaultManager removeItemAtPath:tmp error:nil];
            [NSFileManager.defaultManager removeItemAtPath:[dest stringByAppendingPathComponent:@"_metadata"] error:nil];
            NSMutableDictionary *mf = JSONFile([dest stringByAppendingPathComponent:@"manifest.json"]);
            if (![mf isKindOfClass:NSDictionary.class]) problem = @"The extension has no manifest.";
            else {
                if (key) mf[@"key"] = [key base64EncodedStringWithOptions:0];
                [[NSJSONSerialization dataWithJSONObject:mf options:NSJSONWritingPrettyPrinted error:nil] writeToFile:[dest stringByAppendingPathComponent:@"manifest.json"] atomically:YES];
                name = mf[@"name"];
                if ([name hasPrefix:@"__MSG_"]) {
                    NSString *loc = mf[@"default_locale"] ?: @"en";
                    NSDictionary *msgs = JSONFile([NSString stringWithFormat:@"%@/_locales/%@/messages.json", dest, loc]);
                    NSString *k = [name substringWithRange:NSMakeRange(6, name.length - 8)];
                    for (NSString *mk in msgs) if ([mk caseInsensitiveCompare:k] == NSOrderedSame) name = msgs[mk][@"message"];
                }
            }
        }
        dispatch_async(dispatch_get_main_queue(), ^{ done(name, problem); });
    }] resume];
}

#pragma mark Test harness hooks

- (void)evalIn:(NSString *)where code:(NSString *)code {
    FExt *e = self.extensions.firstObject;
    if ([code hasPrefix:@"@"]) {   // "@<extension id> code": a particular extension
        NSRange sp = [code rangeOfString:@" "];
        if (sp.location != NSNotFound) { FExt *x = _exts[[code substringWithRange:NSMakeRange(1, sp.location - 1)]]; if (x) e = x; code = [code substringFromIndex:sp.location + 1]; }
    }
    WKWebView *v = [where isEqualToString:@"bg"] ? e.background : (WKWebView *)_popover.contentViewController.view;
    if (![v isKindOfClass:WKWebView.class]) { CtlOut([where stringByAppendingString:@" not open"]); return; }
    [v callAsyncJavaScript:[NSString stringWithFormat:@"const r = await (%@); return typeof r === 'object' ? JSON.stringify(r) : String(r);", code]
                 arguments:@{} inFrame:nil inContentWorld:WKContentWorld.pageWorld completionHandler:^(id r, NSError *err) {
        NSString *out = err ? [@"ERR " stringByAppendingString:(err.userInfo[@"WKJavaScriptExceptionMessage"] ?: err.localizedDescription)] : [r description];
        CtlOut([NSString stringWithFormat:@"%@js %@", where, out.length > 3000 ? [out substringToIndex:3000] : out]);
    }];
}

#pragma mark Popup (the toolbar button's page)

- (BOOL)openOptions:(FExt *)e {
    id ui = e.manifest[@"options_ui"];
    NSString *opt = [ui isKindOfClass:NSDictionary.class] && [ui[@"page"] isKindOfClass:NSString.class] ? ui[@"page"] : [e.manifest[@"options_page"] isKindOfClass:NSString.class] ? e.manifest[@"options_page"] : nil;
    if (!opt) return NO;
    NSString *url = [NSString stringWithFormat:@"chrome-extension://%@/%@", e.ident, [opt hasPrefix:@"/"] ? [opt substringFromIndex:1] : opt];
    VWindow *w = NormalWin();
    for (VTab *t in w.tabs) if ([t.url hasPrefix:url]) { [w selectTab:t]; return YES; }   // already open: switch to it
    [w newTab:[NSURL URLWithString:url] select:YES];
    return YES;
}
- (BOOL)openOptionsForID:(NSString *)ident { FExt *e = _exts[ident ?: @""]; return e ? [self openOptions:e] : NO; }
- (BOOL)hasOptionsForID:(NSString *)ident {
    FExt *e = _exts[ident ?: @""]; id ui = e.manifest[@"options_ui"];
    return ([ui isKindOfClass:NSDictionary.class] && ui[@"page"]) || [e.manifest[@"options_page"] isKindOfClass:NSString.class];
}

// Popups take the size of their content (Chrome: between 25×25 and 800×600). The page is measured at its natural
// size: the root laid out at max-content, so an element that fills the width doesn't fill the old window instead.
static NSString *const kPopupMeasureJS = @"(()=>{const d=document.documentElement,b=document.body;if(!b)return null;"
    "const sw=d.style.width,sh=d.style.height,bw=b.style.width,bh=b.style.height;"
    "d.style.width='max-content';d.style.height='max-content';b.style.height='auto';"
    "const r=d.getBoundingClientRect();let w=Math.ceil(r.width),h=Math.ceil(Math.max(r.height,b.scrollHeight));"
    "d.style.width=sw;d.style.height=sh;b.style.width=bw;b.style.height=bh;return[w,h]})()";
- (void)fitPopup:(WKWebView *)v {
    if (!_popover || _popover.contentViewController.view != v) return;
    [v evaluateJavaScript:kPopupMeasureJS completionHandler:^(id r, NSError *err) {
        if (![r isKindOfClass:NSArray.class] || [r count] != 2 || self->_popover.contentViewController.view != v) return;
        CGFloat w = MIN(800, MAX(25, [r[0] doubleValue])), h = MIN(600, MAX(25, [r[1] doubleValue]));
        if (fabs(w - self->_popover.contentSize.width) > 1 || fabs(h - self->_popover.contentSize.height) > 1) self->_popover.contentSize = NSMakeSize(w, h);
    }];
}
- (void)webView:(WKWebView *)v didFinishNavigation:(WKNavigation *)n {
    [self fitPopup:v];
    // pages that build themselves after loading settle a moment later
    for (NSNumber *ms in @[@150, @500, @1200]) dispatch_after(dispatch_time(DISPATCH_TIME_NOW, ms.longLongValue * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ [self fitPopup:v]; });
}

- (void)openPopup:(FExt *)e from:(NSView *)anchor {
    if (!e) e = self.extensions.firstObject;
    NSDictionary *action = e.manifest[@"action"] ?: e.manifest[@"browser_action"];
    NSString *page = [action[@"default_popup"] isKindOfClass:NSString.class] ? action[@"default_popup"] : nil;
    if (!page) {   // like Chrome: tell the extension it was clicked; if it doesn't listen, open its options
        VTab *cur = NormalWin().current;
        [self toBackground:e body:@"return globalThis.__irisActionClicked ? __irisActionClicked(tab) : false" args:@{@"tab": TabInfo(cur) ?: @{}} done:^(id r, NSError *err) {
            if ([r boolValue]) return;
            if (![self openOptions:e]) [gWin showToast:[NSString stringWithFormat:@"%@ has no popup or options", e.name]];
        }];
        return;
    }
    [_popover close];
    WKWebView *v = [[WKWebView alloc] initWithFrame:NSMakeRect(0, 0, 380, 600) configuration:IrisConfig()];
    if (@available(macOS 13.3, *)) v.inspectable = YES;
    @try { [v setValue:@NO forKey:@"drawsBackground"]; } @catch (NSException *x) {}
    v.navigationDelegate = self;   // sized to its content once it has loaded, as Chrome does
    [v loadRequest:[NSURLRequest requestWithURL:[NSURL URLWithString:[NSString stringWithFormat:@"chrome-extension://%@/%@", e.ident, page]]]];
    NSViewController *vc = [NSViewController new]; vc.view = v;
    _popover = [NSPopover new];
    _popover.contentViewController = vc;
    _popover.contentSize = NSMakeSize(380, 600);
    _popover.behavior = NSPopoverBehaviorTransient;
    _popover.appearance = ThemeAppearance();
    NSView *at = anchor ?: [gWin.toolbar extensionButtonFor:e.ident] ?: gWin.toolbar.menuBtn;
    [_popover showRelativeToRect:at.bounds ofView:at preferredEdge:NSRectEdgeMaxY];
}

@end
#pragma mark - Shield: the layers beyond WebKit's lists

// WebKit's content rules (built from the lists above) do the bulk of the blocking. Four more layers bring Iris level
// with uBlock Origin:
//   3  page scripts   uBlock's own scriptlets (+js rules): its source is downloaded from uBlock's repository (GPL-3,
//                     never bundled into Iris), and uBlock's own code builds the injection scripts, in JavaScriptCore,
//                     exactly as uBlock does for itself. They run at document start in every frame.
//   4  procedural     :has-text, :upward, :remove, :style, :matches-css, :xpath… and "example.*" sites, in Iris's
//                     own engine (pages/shield-procedural.js), re-applied as the page changes
//   5  stand-ins      $redirect rules: the request is blocked and uBlock's harmless stand-in script is planted in the
//                     page in its place, so sites that expect it (googletag, analytics…) keep working
//   1  live gate      every connection WebKit makes goes through Iris (a local proxy, macOS 14+), which follows the
//                     site's DNS aliases and stops first-party trackers in disguise (CNAME cloaking)

static NSString *const kShieldGate = @"shieldGate";

static NSString *ShieldSrcRoot(void) { return [ListDir() stringByAppendingPathComponent:@"ubo-src"]; }
static NSString *ShieldSrcRef(void) {
    return Trim([NSString stringWithContentsOfFile:[ShieldSrcRoot() stringByAppendingPathComponent:@"current"] encoding:NSUTF8StringEncoding error:nil] ?: @"");
}
static NSString *ShieldSrcDir(void) {
    NSString *ref = ShieldSrcRef();
    NSString *d = ref.length ? [ShieldSrcRoot() stringByAppendingPathComponent:ref] : nil;
    return d && [NSFileManager.defaultManager fileExistsAtPath:[d stringByAppendingPathComponent:@"js/resources/scriptlets.js"]] ? d : nil;
}
static NSString *ShieldCacheFile(void) {
    NSString *d = SupportFile(@"shield");
    [NSFileManager.defaultManager createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil];
    return [d stringByAppendingPathComponent:@"shield.json"];
}
static NSData *ShieldGet(NSString *url) {   // on a background queue only
    __block NSData *out = nil;
    dispatch_semaphore_t s = dispatch_semaphore_create(0);
    NSMutableURLRequest *r = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:url] cachePolicy:NSURLRequestReloadIgnoringLocalCacheData timeoutInterval:30];
    [r setValue:@"Iris" forHTTPHeaderField:@"User-Agent"];
    [[NSURLSession.sharedSession dataTaskWithRequest:r completionHandler:^(NSData *d, NSURLResponse *resp, NSError *e) {
        if (d && [(NSHTTPURLResponse *)resp statusCode] == 200) out = d;
        dispatch_semaphore_signal(s);
    }] resume];
    dispatch_semaphore_wait(s, dispatch_time(DISPATCH_TIME_NOW, 40 * NSEC_PER_SEC));
    return out;
}
static NSString *ShieldNormPath(NSString *from, NSString *rel) {
    NSMutableArray *parts = [[from componentsSeparatedByString:@"/"] mutableCopy]; [parts removeLastObject];
    for (NSString *p in [rel componentsSeparatedByString:@"/"]) { if (!p.length || [p isEqualToString:@"."]) continue; if ([p isEqualToString:@".."]) { if (parts.count) [parts removeLastObject]; } else [parts addObject:p]; }
    return [parts componentsJoinedByString:@"/"];
}

// uBlock's scriptlet sources and stand-in scripts, from its latest release, once a week (Iris itself only: the others read Iris's copy)
static void ShieldFetchSources(BOOL force, void (^done)(void)) {
    if (ListsAreIris() && ShieldSrcDir()) { if (done) done(); return; }   // Iris keeps them fresh; the others only fetch if Iris hasn't yet
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        NSFileManager *fm = NSFileManager.defaultManager;
        NSString *root = ShieldSrcRoot(), *cur = ShieldSrcRef(), *curFile = [root stringByAppendingPathComponent:@"current"];
        NSDate *at = [[fm attributesOfItemAtPath:curFile error:nil] fileModificationDate];
        if (!force && ShieldSrcDir() && at && -at.timeIntervalSinceNow < 6 * 86400) { if (done) done(); return; }
        NSString *ref = @"master";
        NSData *rel = ShieldGet(@"https://api.github.com/repos/gorhill/uBlock/releases/latest");
        id j = rel ? [NSJSONSerialization JSONObjectWithData:rel options:0 error:nil] : nil;
        if ([j isKindOfClass:NSDictionary.class] && [j[@"tag_name"] isKindOfClass:NSString.class] && [j[@"tag_name"] length]) ref = j[@"tag_name"];
        if ([ref isEqualToString:cur] && ShieldSrcDir()) { [fm setAttributes:@{NSFileModificationDate: NSDate.date} ofItemAtPath:curFile error:nil]; if (done) done(); return; }
        NSString *dir = [root stringByAppendingPathComponent:[ref stringByAppendingString:@".building"]];
        [fm removeItemAtPath:dir error:nil];
        NSString *base = [NSString stringWithFormat:@"https://raw.githubusercontent.com/gorhill/uBlock/%@/src/", ref];
        BOOL ok = YES;
        NSMutableArray *queue = [@[@"js/resources/scriptlets.js", @"js/make-scriptlets.js", @"js/arglist-parser.js", @"js/redirect-resources.js",
                                   @"js/scriptlet.template.js", @"js/scriptlet-begin.template.js", @"js/scriptlet-end.template.js"] mutableCopy];
        NSMutableSet *seen = [NSMutableSet set];
        NSRegularExpression *imp = [NSRegularExpression regularExpressionWithPattern:@"import\\s+(?:[^'\";]*?\\s+from\\s+)?['\"](\\.{1,2}/[^'\"]+)['\"]" options:0 error:nil];
        while (queue.count) {
            NSString *p = queue.lastObject; [queue removeLastObject];
            if ([seen containsObject:p]) continue;
            [seen addObject:p];
            NSData *d = ShieldGet([base stringByAppendingString:p]);
            if (!d) { ok = NO; DLog(@"shield: couldn't fetch %@ (%@)", p, ref); break; }
            NSString *dest = [dir stringByAppendingPathComponent:p];
            [fm createDirectoryAtPath:dest.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil];
            [d writeToFile:dest atomically:YES];
            if ([p hasSuffix:@".template.js"]) continue;
            NSString *src = [[NSString alloc] initWithData:d encoding:NSUTF8StringEncoding] ?: @"";
            for (NSTextCheckingResult *m in [imp matchesInString:src options:0 range:NSMakeRange(0, src.length)]) {
                NSString *q = ShieldNormPath(p, [src substringWithRange:[m rangeAtIndex:1]]);
                if ([q hasPrefix:@"js/"] && ![seen containsObject:q]) [queue addObject:q];
            }
        }
        if (ok) {   // the stand-in scripts uBlock serves in place of blocked ones
            NSString *rr = [NSString stringWithContentsOfFile:[dir stringByAppendingPathComponent:@"js/redirect-resources.js"] encoding:NSUTF8StringEncoding error:nil] ?: @"";
            NSRegularExpression *names = [NSRegularExpression regularExpressionWithPattern:@"\\[\\s*'([A-Za-z0-9_.-]+\\.js)'\\s*," options:0 error:nil];
            [fm createDirectoryAtPath:[dir stringByAppendingPathComponent:@"war"] withIntermediateDirectories:YES attributes:nil error:nil];
            for (NSTextCheckingResult *m in [names matchesInString:rr options:0 range:NSMakeRange(0, rr.length)]) {
                NSString *n = [rr substringWithRange:[m rangeAtIndex:1]];
                NSData *d = ShieldGet([NSString stringWithFormat:@"%@web_accessible_resources/%@", base, n]);
                if (d) [d writeToFile:[[dir stringByAppendingPathComponent:@"war"] stringByAppendingPathComponent:n] atomically:YES];
            }
            NSString *final = [root stringByAppendingPathComponent:ref];
            [fm removeItemAtPath:final error:nil];
            [fm moveItemAtPath:dir toPath:final error:nil];
            [ref writeToFile:curFile atomically:YES encoding:NSUTF8StringEncoding error:nil];
            for (NSString *x in [fm contentsOfDirectoryAtPath:root error:nil]) if (![x isEqualToString:ref] && ![x isEqualToString:@"current"]) [fm removeItemAtPath:[root stringByAppendingPathComponent:x] error:nil];
            DLog(@"shield: uBlock Origin %@ sources ready (%lu files)", ref, (unsigned long)seen.count);
        } else [fm removeItemAtPath:dir error:nil];
        if (done) done();
    });
}

#pragma mark Building the layers from one parse

static NSString *ShieldPage(NSString *name) {
    return [NSString stringWithContentsOfFile:[[NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:@"pages"] stringByAppendingPathComponent:name] encoding:NSUTF8StringEncoding error:nil];
}
static NSString *ShieldHostOfFilter(NSString *rx) {   // "^[a-z][a-z0-9.+-]*://([^/?#]*\.)?ads\.example\.com…" → ads.example.com
    NSString *pre = @"^[a-z][a-z0-9.+-]*://([^/?#]*\\.)?";
    if (![rx hasPrefix:pre]) return nil;
    NSMutableString *h = [NSMutableString string];
    for (NSUInteger i = pre.length; i < rx.length; i++) {
        unichar c = [rx characterAtIndex:i];
        if (c == '\\' && i + 1 < rx.length && [rx characterAtIndex:i + 1] == '.') { [h appendString:@"."]; i++; continue; }
        if (isalnum(c) || c == '-' || c == '_') { [h appendFormat:@"%C", c]; continue; }
        break;
    }
    return h.length > 3 && [h containsString:@"."] ? h.lowercaseString : nil;
}
static BOOL gShieldBuilding;
static void ShieldLoad(NSDictionary *cache);
static void ShieldRulesParsed(FLRules *R, NSString *fp) {
    NSString *src = ShieldSrcDir(), *ref = ShieldSrcRef();
    NSMutableDictionary *cache = [@{@"fp": fp ?: @"", @"ref": ref ?: @""} mutableCopy];
    NSDate *t0 = NSDate.date;
    NSDictionary *aliases = nil;
    // 3: uBlock's scriptlets, built by uBlock's own code
    if (src) @autoreleasepool {
        NSString *driver = ShieldPage(@"shield-driver.js");
        NSMutableDictionary *files = [NSMutableDictionary dictionary];
        NSString *js = [src stringByAppendingPathComponent:@"js"];
        NSDirectoryEnumerator *en = [NSFileManager.defaultManager enumeratorAtPath:js];
        for (NSString *rel in en) {
            if (![rel hasSuffix:@".js"] || [rel hasSuffix:@".template.js"]) continue;
            NSString *t = [NSString stringWithContentsOfFile:[js stringByAppendingPathComponent:rel] encoding:NSUTF8StringEncoding error:nil];
            if (t) files[rel] = t;
        }
        JSContext *ctx = [JSContext new];
        __block NSString *jsErr = nil;
        ctx.exceptionHandler = ^(JSContext *c, JSValue *e) { jsErr = e.toString; };
        ctx[@"__files"] = files;
        ctx[@"__filters"] = R.scriptlets;
        ctx[@"__templates"] = @{@"begin": [NSString stringWithContentsOfFile:[js stringByAppendingPathComponent:@"scriptlet-begin.template.js"] encoding:NSUTF8StringEncoding error:nil] ?: @"",
                                @"core": [NSString stringWithContentsOfFile:[js stringByAppendingPathComponent:@"scriptlet.template.js"] encoding:NSUTF8StringEncoding error:nil] ?: @"",
                                @"end": [NSString stringWithContentsOfFile:[js stringByAppendingPathComponent:@"scriptlet-end.template.js"] encoding:NSUTF8StringEncoding error:nil] ?: @""};
        ctx[@"__secret"] = [[NSUUID.UUID.UUIDString stringByReplacingOccurrencesOfString:@"-" withString:@""] lowercaseString];
        if (driver) [ctx evaluateScript:driver];
        NSString *json = driver && !jsErr ? [ctx[@"__irisBuild"] callWithArguments:@[]].toString : nil;
        NSDictionary *out = json ? [NSJSONSerialization JSONObjectWithData:[json dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil] : nil;
        if ([out isKindOfClass:NSDictionary.class]) {
            cache[@"main"] = out[@"worlds"][@"MAIN"][@"code"] ?: @"";
            cache[@"isolated"] = out[@"worlds"][@"ISOLATED"][@"code"] ?: @"";
            cache[@"scriptletCount"] = out[@"compiled"] ?: @0;
        } else DLog(@"shield: page scripts not built (%@)", jsErr ?: @"no result");
        NSString *rj = [ctx[@"__irisRedirects"] callWithArguments:@[]].toString;
        aliases = rj ? [NSJSONSerialization JSONObjectWithData:[rj dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil] : nil;
    } else DLog(@"shield: uBlock's sources aren't here yet; page scripts come with the next list update");
    // 5: stand-ins for $redirect rules, where uBlock has a script for them
    NSMutableDictionary *canon = [NSMutableDictionary dictionary], *stubs = [NSMutableDictionary dictionary];
    if ([aliases isKindOfClass:NSDictionary.class]) for (NSString *name in aliases) {
        canon[name.lowercaseString] = name;
        for (NSString *a in aliases[name]) if ([a isKindOfClass:NSString.class]) canon[a.lowercaseString] = name;
        NSString *noExt = [name.lowercaseString stringByDeletingPathExtension]; if (!canon[noExt]) canon[noExt] = name;
    }
    canon[@"noopjs"] = canon[@"noopjs"] ?: @"noop.js";
    NSMutableArray *redirects = [NSMutableArray array];
    for (NSDictionary *r in R.redirects) {
        NSString *name = canon[r[@"res"]];
        if (!name) continue;
        if (!stubs[name]) {
            NSString *code = src ? [NSString stringWithContentsOfFile:[[src stringByAppendingPathComponent:@"war"] stringByAppendingPathComponent:name] encoding:NSUTF8StringEncoding error:nil] : nil;
            if (!code) continue;
            stubs[name] = code;
        }
        NSDictionary *t = r[@"trigger"];
        NSMutableDictionary *e = [@{@"rx": t[@"url-filter"] ?: @".*", @"res": name} mutableCopy];
        if (t[@"if-domain"]) e[@"inc"] = t[@"if-domain"];
        if (t[@"unless-domain"]) e[@"exc"] = t[@"unless-domain"];
        NSString *h = ShieldHostOfFilter(e[@"rx"]); if (h) e[@"host"] = h;
        [redirects addObject:e];
    }
    cache[@"redirects"] = redirects; cache[@"stubs"] = stubs;
    // 4: procedural hiding, site → selectors
    NSMutableDictionary *T = [NSMutableDictionary dictionary];
    void (^put)(NSString *, NSString *, BOOL) = ^(NSString *k, NSString *sel, BOOL exc) { NSMutableArray *a = T[k]; if (!a) T[k] = a = [NSMutableArray array]; [a addObject:@[sel, @(exc)]]; };
    for (NSArray *p in R.procedural) {
        NSString *doms = p[0], *sel = p[1]; BOOL exc = [p[2] boolValue];
        BOOL any = NO;
        for (NSString *raw in [doms componentsSeparatedByString:@","]) {
            NSString *d = Trim(raw).lowercaseString; if (!d.length) continue;
            if ([d hasPrefix:@"~"]) put([d substringFromIndex:1], sel, YES); else { put(d, sel, exc); any = YES; }
        }
        if (!any && exc) put(@"*", sel, YES);
    }
    cache[@"procedural"] = T;
    cache[@"proceduralCount"] = @(R.procedural.count);
    // 1: whole tracker hosts, for the live gate's disguise check
    cache[@"hosts"] = R.hosts.allObjects ?: @[];
    NSData *d = [NSJSONSerialization dataWithJSONObject:cache options:0 error:nil];
    [d writeToFile:ShieldCacheFile() atomically:YES];
    DLog(@"shield: %@ page scripts, %lu procedural, %lu stand-ins, %lu gate hosts built in %.1fs", cache[@"scriptletCount"] ?: @0, (unsigned long)R.procedural.count,
         (unsigned long)redirects.count, (unsigned long)R.hosts.count, -t0.timeIntervalSinceNow);
    dispatch_async(dispatch_get_main_queue(), ^{ ShieldLoad(cache); });
}

#pragma mark Loading and installing

static NSString *gShieldFP, *gShieldRef, *gShieldMain, *gShieldIsolated, *gShieldProcedural;
static NSUInteger gShieldScriptletCount, gShieldProceduralCount;
static NSArray *gShieldRedirectsAny; static NSDictionary<NSString *, NSArray *> *gShieldRedirectsByHost; static NSDictionary *gShieldStubs;
static NSSet<NSString *> *gGateHosts;
static NSMapTable<WKUserContentController *, NSMutableArray *> *gShieldScripts;
static NSMapTable<WKUserContentController *, NSNumber *> *gShieldUCCs;
static void GateStart(void);
static void ShieldChanged(void);

static void ShieldLoad(NSDictionary *cache) {
    gShieldFP = cache[@"fp"]; gShieldRef = cache[@"ref"];
    gShieldMain = [cache[@"main"] length] ? cache[@"main"] : nil;
    gShieldIsolated = [cache[@"isolated"] length] ? cache[@"isolated"] : nil;
    gShieldScriptletCount = [cache[@"scriptletCount"] unsignedIntegerValue];
    gShieldProceduralCount = [cache[@"proceduralCount"] unsignedIntegerValue];
    NSString *engine = ShieldPage(@"shield-procedural.js");
    NSData *pj = [cache[@"procedural"] count] ? [NSJSONSerialization dataWithJSONObject:cache[@"procedural"] options:0 error:nil] : nil;
    gShieldProcedural = engine && pj ? [NSString stringWithFormat:@"%@(%@);", engine, [[NSString alloc] initWithData:pj encoding:NSUTF8StringEncoding]] : nil;
    NSMutableArray *any = [NSMutableArray array]; NSMutableDictionary *byHost = [NSMutableDictionary dictionary];
    for (NSDictionary *r in cache[@"redirects"] ?: @[]) {
        NSString *h = r[@"host"];
        if (h) { NSMutableArray *a = byHost[h]; if (!a) byHost[h] = a = [NSMutableArray array]; [a addObject:r]; } else [any addObject:r];
    }
    gShieldRedirectsAny = any; gShieldRedirectsByHost = byHost; gShieldStubs = cache[@"stubs"];
    gGateHosts = [NSSet setWithArray:cache[@"hosts"] ?: @[]];
    ShieldChanged();
    GateStart();
}
static void ShieldEnsure(NSString *fp, NSString *dir) {
    if (([gShieldFP isEqualToString:fp] && [gShieldRef isEqualToString:ShieldSrcRef()]) || gShieldBuilding) return;
    static BOOL fetching;
    if (!ShieldSrcDir() && !fetching) {   // no uBlock sources yet: build what we can now, again once they arrive
        fetching = YES;
        ShieldFetchSources(NO, ^{ dispatch_async(dispatch_get_main_queue(), ^{ fetching = NO; if (ShieldSrcDir()) ShieldEnsure(fp, dir); }); });
    }
    NSData *d = [NSData dataWithContentsOfFile:ShieldCacheFile()];
    NSDictionary *cache = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : nil;
    if ([cache isKindOfClass:NSDictionary.class] && [cache[@"fp"] isEqual:fp] && [cache[@"ref"] isEqual:ShieldSrcRef()]) { ShieldLoad(cache); return; }
    gShieldBuilding = YES;
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        FLRules *R = FLParse(dir);
        ShieldRulesParsed(R, fp);
        dispatch_async(dispatch_get_main_queue(), ^{ gShieldBuilding = NO; });
    });
}

// The scripts go into every page's controller at document start, in every frame; sites you've switched blocking off for are left out.
static void ShieldApply(WKUserContentController *u, BOOL priv) {
    if (!gShieldScripts) gShieldScripts = [NSMapTable weakToStrongObjectsMapTable];
    NSMutableArray *mine = [gShieldScripts objectForKey:u];
    if (!mine) { mine = [NSMutableArray array]; [gShieldScripts setObject:mine forKey:u]; }
    if (mine.count) {
        NSMutableArray *keep = [NSMutableArray array];
        for (WKUserScript *us in u.userScripts) if (![mine containsObject:us]) [keep addObject:us];
        [u removeAllUserScripts];
        for (WKUserScript *us in keep) [u addUserScript:us];
        [mine removeAllObjects];
    }
    if (!gBlockOn) return;
    NSMutableArray *exc = [NSMutableArray array];
    for (NSString *site in SiteArray(priv, kAllowlist) ?: @[]) if ([site isKindOfClass:NSString.class] && site.length) {
        NSString *h = [site.lowercaseString hasPrefix:@"www."] ? [site.lowercaseString substringFromIndex:4] : site.lowercaseString;
        [exc addObject:[NSString stringWithFormat:@"*://*.%@/*", h]];
    }
    WKContentWorld *iso = [WKContentWorld worldWithName:@"iris-shield"];
    BOOL hide = ![Defaults() objectForKey:kHideElements] || [Defaults() boolForKey:kHideElements];
    NSArray *parts = @[@[gShieldMain ?: @"", WKContentWorld.pageWorld], @[gShieldIsolated ?: @"", iso], @[hide ? gShieldProcedural ?: @"" : @"", iso]];
    for (NSArray *p in parts) {
        NSString *code = p[0]; if (!code.length) continue;
        WKUserScript *us = MatchedScript(code, WKUserScriptInjectionTimeAtDocumentStart, NO, @[@"*://*/*"], exc, p[1])
                        ?: [[WKUserScript alloc] initWithSource:code injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:NO inContentWorld:p[1]];
        [u addUserScript:us]; [mine addObject:us];
    }
}
static void ShieldInstall(WKUserContentController *ucc, BOOL priv) {
    if (!gShieldUCCs) gShieldUCCs = [NSMapTable weakToStrongObjectsMapTable];
    [gShieldUCCs setObject:@(priv) forKey:ucc];
    if (gShieldFP) ShieldApply(ucc, priv);
}
static void ShieldChanged(void) {
    for (WKUserContentController *u in gShieldUCCs.keyEnumerator.allObjects) ShieldApply(u, [[gShieldUCCs objectForKey:u] boolValue]);
}

#pragma mark 5: stand-ins

static BOOL ShieldDomainHit(NSString *host, NSArray *list) {
    for (NSString *w in list) {
        NSString *d = [w hasPrefix:@"*"] ? [w substringFromIndex:1] : w;
        if ([host isEqualToString:d] || [host hasSuffix:[@"." stringByAppendingString:d]]) return YES;
    }
    return NO;
}
static char kStandInKey;
static void ShieldBlocked(VPage *p, NSURL *u) {
    if (!u.host || (!gShieldRedirectsAny.count && !gShieldRedirectsByHost.count)) return;
    NSString *uh = u.host.lowercaseString, *url = u.absoluteString;
    NSMutableArray *cands = [NSMutableArray arrayWithArray:gShieldRedirectsAny ?: @[]];
    NSString *h = uh;
    while (h.length) {
        NSArray *a = gShieldRedirectsByHost[h]; if (a) [cands addObjectsFromArray:a];
        NSRange dot = [h rangeOfString:@"."]; if (dot.location == NSNotFound) break;
        h = [h substringFromIndex:dot.location + 1];
    }
    if (!cands.count) return;
    WKWebView *web = p.web;
    NSString *page = web.URL.host.lowercaseString ?: @"";
    static NSMutableDictionary<NSString *, NSRegularExpression *> *rxCache; if (!rxCache) rxCache = [NSMutableDictionary dictionary];
    for (NSDictionary *r in cands) {
        if (r[@"inc"] && !ShieldDomainHit(page, r[@"inc"])) continue;
        if (r[@"exc"] && ShieldDomainHit(page, r[@"exc"])) continue;
        NSRegularExpression *re = rxCache[r[@"rx"]];
        if (!re) { re = [NSRegularExpression regularExpressionWithPattern:r[@"rx"] options:NSRegularExpressionCaseInsensitive error:nil]; if (!re) continue; rxCache[r[@"rx"]] = re; }
        if (![re firstMatchInString:url options:0 range:NSMakeRange(0, url.length)]) continue;
        // once per page and stand-in
        NSMutableDictionary *done = objc_getAssociatedObject(p, &kStandInKey);
        NSString *pageURL = web.URL.absoluteString ?: @"";
        if (!done || ![done[@"page"] isEqual:pageURL]) { done = [@{@"page": pageURL, @"set": [NSMutableSet set]} mutableCopy]; objc_setAssociatedObject(p, &kStandInKey, done, OBJC_ASSOCIATION_RETAIN_NONATOMIC); }
        if ([done[@"set"] containsObject:r[@"res"]]) return;
        [done[@"set"] addObject:r[@"res"]];
        NSString *code = gShieldStubs[r[@"res"]]; if (!code.length) return;
        [web evaluateJavaScript:code inFrame:nil inContentWorld:WKContentWorld.pageWorld completionHandler:nil];
        return;
    }
}

#pragma mark 1: the live gate

static NSString *ShieldStats(void) {
    return [NSString stringWithFormat:@"%lu page scripts · %lu procedural rules · %lu stand-ins", (unsigned long)gShieldScriptletCount, (unsigned long)gShieldProceduralCount,
            (unsigned long)(gShieldRedirectsAny.count + [[gShieldRedirectsByHost.allValues valueForKeyPath:@"@sum.@count"] unsignedIntegerValue])];
}
static id gGate;                     // nw_listener_t
static uint16_t gGatePort;
static NSHashTable<WKWebsiteDataStore *> *gGateStores;
static NSCache *gCnameCache;
static volatile long gGateUncloaked, gGateConnections;
static volatile BOOL gGateBlocking = YES;

static void GateApplyStore(WKWebsiteDataStore *ds) {
    SEL set = NSSelectorFromString(@"setProxyConfigurations:");
    if (![ds respondsToSelector:set]) return;
    id (*mk)(id, id) = (id (*)(id, id))dlsym(RTLD_DEFAULT, "nw_proxy_config_create_http_connect");
    NSArray *cfg = @[];
    if (gGatePort && mk) {
        nw_endpoint_t ep = nw_endpoint_create_host("127.0.0.1", [NSString stringWithFormat:@"%u", gGatePort].UTF8String);
        id pc = mk(ep, nil);
        if (pc) cfg = @[pc];
    }
    ((void (*)(id, SEL, id))objc_msgSend)(ds, set, cfg);
}
static void ShieldAdoptStore(WKWebsiteDataStore *ds) {
    if (!ds) return;
    if (!gGateStores) gGateStores = [NSHashTable weakObjectsHashTable];
    if ([gGateStores containsObject:ds]) return;
    [gGateStores addObject:ds];
    if (gGatePort) GateApplyStore(ds);
}
static void GateApplyAll(void) { for (WKWebsiteDataStore *ds in gGateStores.allObjects) GateApplyStore(ds); }

static BOOL GateHostListed(NSString *h) {
    NSSet *set = gGateHosts;
    while (h.length) {
        if ([set containsObject:h]) return YES;
        NSRange d = [h rangeOfString:@"."]; if (d.location == NSNotFound) break;
        h = [h substringFromIndex:d.location + 1];
    }
    return NO;
}
typedef struct { char target[1025]; BOOL got; } IrisCname;
static void IrisCnameReply(DNSServiceRef sd, DNSServiceFlags flags, uint32_t ifi, DNSServiceErrorType err, const char *name, uint16_t type, uint16_t cls, uint16_t len, const void *rdata, uint32_t ttl, void *ctx) {
    IrisCname *c = ctx;
    if (err != kDNSServiceErr_NoError || type != kDNSServiceType_CNAME || !rdata) return;
    const unsigned char *p = rdata, *end = p + len; char out[1025]; size_t o = 0;
    while (p < end && *p) {
        unsigned n = *p++; if (n > 63 || p + n > end || o + n + 2 >= sizeof out) break;
        if (o) out[o++] = '.';
        memcpy(out + o, p, n); o += n; p += n;
    }
    out[o] = 0;
    if (o) { strlcpy(c->target, out, sizeof c->target); c->got = YES; }
}
static NSString *IrisCnameOf(NSString *host) {
    DNSServiceRef sd = NULL; IrisCname c = {{0}, NO};
    if (DNSServiceQueryRecord(&sd, kDNSServiceFlagsReturnIntermediates, 0, host.UTF8String, kDNSServiceType_CNAME, kDNSServiceClass_IN, IrisCnameReply, &c) != kDNSServiceErr_NoError) return nil;
    int fd = DNSServiceRefSockFD(sd);
    fd_set set; FD_ZERO(&set); FD_SET(fd, &set);
    struct timeval tv = {0, 250000};
    if (fd >= 0 && select(fd + 1, &set, NULL, NULL, &tv) > 0) DNSServiceProcessResult(sd);
    DNSServiceRefDeallocate(sd);
    return c.got ? [@(c.target) lowercaseString] : nil;
}
// A first-party name that is really an alias of a tracker (metrics.site.com → site.tracker.net): blocked like the tracker
static NSString *GateCloakedVia(NSString *host) {
    if (!gCnameCache) gCnameCache = [NSCache new];
    NSString *h = host;
    for (int i = 0; i < 5; i++) {
        id cached = [gCnameCache objectForKey:h];
        NSString *t = [cached isKindOfClass:NSString.class] ? cached : nil;
        if (!cached) { t = IrisCnameOf(h); [gCnameCache setObject:t ?: NSNull.null forKey:h]; }
        if (!t.length || [t isEqualToString:h]) return nil;
        if (GateHostListed(t)) return t;
        h = t;
    }
    return nil;
}

@interface IrisGateLink : NSObject
@property (strong) nw_connection_t a, b;
@property int closed;
@end
@implementation IrisGateLink
- (void)halfDone { if (++self.closed >= 2) [self cancel]; }
- (void)cancel { if (self.a) nw_connection_cancel(self.a); if (self.b) nw_connection_cancel(self.b); self.a = nil; self.b = nil; }
@end

static void GateSendAndClose(nw_connection_t c, NSString *s) {
    NSData *d = [s dataUsingEncoding:NSASCIIStringEncoding];
    dispatch_data_t dd = dispatch_data_create(d.bytes, d.length, nil, DISPATCH_DATA_DESTRUCTOR_DEFAULT);
    nw_connection_send(c, dd, NW_CONNECTION_FINAL_MESSAGE_CONTEXT, true, ^(nw_error_t e) { nw_connection_cancel(c); });
}
static void GatePump(nw_connection_t from, nw_connection_t to, IrisGateLink *link) {
    nw_connection_receive(from, 1, 256 * 1024, ^(dispatch_data_t content, nw_content_context_t ctx, bool complete, nw_error_t err) {
        if (err && !content) { [link cancel]; return; }
        void (^after)(void) = ^{
            if (complete) { nw_connection_send(to, NULL, NW_CONNECTION_FINAL_MESSAGE_CONTEXT, true, ^(nw_error_t e) {}); [link halfDone]; return; }
            if (err) { [link cancel]; return; }
            GatePump(from, to, link);
        };
        if (content) nw_connection_send(to, content, NW_CONNECTION_DEFAULT_MESSAGE_CONTEXT, false, ^(nw_error_t e) { if (e) { [link cancel]; return; } after(); });
        else after();
    });
}
static BOOL GateIsIP(NSString *h) { return [h rangeOfCharacterFromSet:[[NSCharacterSet characterSetWithCharactersInString:@"0123456789."] invertedSet]].location == NSNotFound || [h containsString:@":"]; }
static void GateOpen(nw_connection_t client, NSString *host, NSString *port, NSData *rest, dispatch_queue_t q) {
    nw_endpoint_t ep = nw_endpoint_create_host(host.UTF8String, port.UTF8String);
    nw_parameters_t params = nw_parameters_create_secure_tcp(NW_PARAMETERS_DISABLE_PROTOCOL, NW_PARAMETERS_DEFAULT_CONFIGURATION);
    nw_connection_t out = nw_connection_create(ep, params);
    __block BOOL ready = NO, failed = NO, decided = NO, block = NO, went = NO;
    __block NSString *via = nil;
    void (^go)(void) = ^{
        if (went || !decided || !(ready || failed)) return;
        went = YES;
        if (block) { nw_connection_cancel(out); GateSendAndClose(client, @"HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"); return; }
        if (failed) { nw_connection_cancel(out); GateSendAndClose(client, @"HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"); return; }
        IrisGateLink *link = [IrisGateLink new]; link.a = client; link.b = out;
        NSData *ok = [@"HTTP/1.1 200 Connection established\r\n\r\n" dataUsingEncoding:NSASCIIStringEncoding];
        nw_connection_send(client, dispatch_data_create(ok.bytes, ok.length, nil, DISPATCH_DATA_DESTRUCTOR_DEFAULT), NW_CONNECTION_DEFAULT_MESSAGE_CONTEXT, false, ^(nw_error_t e) {
            if (e) { [link cancel]; return; }
            void (^pump)(void) = ^{ GatePump(client, out, link); GatePump(out, client, link); };
            if (rest.length) nw_connection_send(out, dispatch_data_create(rest.bytes, rest.length, nil, DISPATCH_DATA_DESTRUCTOR_DEFAULT), NW_CONNECTION_DEFAULT_MESSAGE_CONTEXT, false, ^(nw_error_t e2) { if (e2) [link cancel]; else pump(); });
            else pump();
        });
    };
    nw_connection_set_queue(out, q);
    nw_connection_set_state_changed_handler(out, ^(nw_connection_state_t st, nw_error_t e) {
        if (st == nw_connection_state_ready && !ready) { ready = YES; go(); }
        else if ((st == nw_connection_state_failed || st == nw_connection_state_waiting) && !ready && !failed) { failed = YES; go(); }
    });
    nw_connection_start(out);
    if (!gGateBlocking || GateIsIP(host) || [host isEqualToString:@"localhost"] || !gGateHosts.count) { decided = YES; return; }
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        NSString *v = GateCloakedVia(host.lowercaseString);
        dispatch_async(q, ^{
            decided = YES; block = v != nil; via = v;
            if (block) { __sync_fetch_and_add(&gGateUncloaked, 1); DLog(@"gate: %@ is %@ in disguise, blocked", host, v); }
            go();
        });
    });
}
static void GateReadHead(nw_connection_t c, NSMutableData *buf, dispatch_queue_t q) {
    nw_connection_receive(c, 1, 16384, ^(dispatch_data_t content, nw_content_context_t ctx, bool complete, nw_error_t err) {
        if (content) dispatch_data_apply(content, ^bool(dispatch_data_t r, size_t off, const void *bytes, size_t size) { [buf appendBytes:bytes length:size]; return true; });
        NSRange end = [buf rangeOfData:[NSData dataWithBytes:"\r\n\r\n" length:4] options:0 range:NSMakeRange(0, buf.length)];
        if (end.location == NSNotFound) {
            if (err || complete || buf.length > 65536) { nw_connection_cancel(c); return; }
            GateReadHead(c, buf, q); return;
        }
        NSString *head = [[NSString alloc] initWithData:[buf subdataWithRange:NSMakeRange(0, end.location)] encoding:NSISOLatin1StringEncoding] ?: @"";
        NSData *rest = [buf subdataWithRange:NSMakeRange(NSMaxRange(end), buf.length - NSMaxRange(end))];
        NSArray *first = [[head componentsSeparatedByString:@"\r\n"].firstObject componentsSeparatedByString:@" "];
        if (first.count < 2 || ![first[0] isEqualToString:@"CONNECT"]) { GateSendAndClose(c, @"HTTP/1.1 405 Method Not Allowed\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"); return; }
        NSString *hp = first[1], *host = hp, *port = @"443";
        if ([hp hasPrefix:@"["]) { NSRange rb = [hp rangeOfString:@"]"]; if (rb.location != NSNotFound) { host = [hp substringWithRange:NSMakeRange(1, rb.location - 1)]; if (rb.location + 2 < hp.length) port = [hp substringFromIndex:rb.location + 2]; } }
        else { NSRange colon = [hp rangeOfString:@":" options:NSBackwardsSearch]; if (colon.location != NSNotFound) { host = [hp substringToIndex:colon.location]; port = [hp substringFromIndex:colon.location + 1]; } }
        GateOpen(c, host, port, rest, q);
    });
}
static void GateAccept(nw_connection_t c) {
    dispatch_queue_t q = dispatch_queue_create_with_target("iris.gate.conn", DISPATCH_QUEUE_SERIAL, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0));
    nw_connection_set_queue(c, q);
    nw_connection_start(c);
    __sync_fetch_and_add(&gGateConnections, 1);
    GateReadHead(c, [NSMutableData data], q);
}
static void GateStart(void) {
    if (@available(macOS 14.0, *)) {} else return;
    if (gGate || ![Defaults() boolForKey:kShieldGate]) return;
    if (!dlsym(RTLD_DEFAULT, "nw_proxy_config_create_http_connect") || ![WKWebsiteDataStore instancesRespondToSelector:NSSelectorFromString(@"setProxyConfigurations:")]) { DLog(@"gate: this macOS can't route WebKit through Iris"); return; }
    nw_parameters_t p = nw_parameters_create_secure_tcp(NW_PARAMETERS_DISABLE_PROTOCOL, NW_PARAMETERS_DEFAULT_CONFIGURATION);
    nw_parameters_set_local_endpoint(p, nw_endpoint_create_host("127.0.0.1", "0"));
    nw_listener_t l = nw_listener_create(p);
    if (!l) { DLog(@"gate: couldn't open"); return; }
    gGate = l;
    nw_listener_set_queue(l, dispatch_queue_create("iris.gate", DISPATCH_QUEUE_SERIAL));
    nw_listener_set_new_connection_handler(l, ^(nw_connection_t c) { GateAccept(c); });
    nw_listener_set_state_changed_handler(l, ^(nw_listener_state_t st, nw_error_t e) {
        if (st == nw_listener_state_ready) {
            uint16_t port = nw_listener_get_port(l);
            dispatch_async(dispatch_get_main_queue(), ^{ gGatePort = port; ShieldAdoptStore(WKWebsiteDataStore.defaultDataStore); GateApplyAll(); DLog(@"gate: live on port %u", port); });
        } else if (st == nw_listener_state_failed || st == nw_listener_state_cancelled) {
            dispatch_async(dispatch_get_main_queue(), ^{ if (gGate == (id)l) { gGate = nil; gGatePort = 0; GateApplyAll(); DLog(@"gate: closed"); } });
        }
    });
    nw_listener_start(l);
}
static void GateStop(void) {
    nw_listener_t l = gGate; gGate = nil; gGatePort = 0;
    GateApplyAll();
    if (l) nw_listener_cancel(l);
}

#pragma mark - Iris's own pages (iris://history, iris://bookmarks)

// Built-in pages are plain HTML files (Resources/pages, or pages/ beside Iris.app while developing),
// served on the iris: scheme with the current theme's colours filled in. They talk to Iris through
// irisInternal, which answers only main frames whose origin is iris: — websites, extensions and
// frames embedded in other pages can't reach it.

static NSString *CSSColor(NSColor *c) {
    NSColor *s = [c colorUsingColorSpace:NSColorSpace.sRGBColorSpace] ?: c;
    return [NSString stringWithFormat:@"rgba(%d,%d,%d,%.3f)", (int)lround(s.redComponent * 255), (int)lround(s.greenComponent * 255), (int)lround(s.blueComponent * 255), s.alphaComponent];
}

// Iris's own pages share the window's colours and its shape language: struck shards, the spark, compressed headings.
static NSString *ThemeCSS(void) {
    NSString *vars = [NSString stringWithFormat:@":root{color-scheme:%@;--bg:%@;--card:%@;--pill:%@;--text:%@;--dim:%@;--faint:%@;--line:%@;--hover:%@;--active:%@;--accent:%@;--border:%@;--toast:%@;--onaccent:%@;--ember:%@;--pick:%@;--onpick:%@}",
            ThemeIsLight() ? @"light" : @"dark", CSSColor(vContentBg), CSSColor(vCard), CSSColor(vPill), CSSColor(vText), CSSColor(vDim), CSSColor(vFaint),
            CSSColor(vSep), CSSColor(vHover), CSSColor(vActive), CSSColor(vAccent), CSSColor(vBorder), CSSColor(vToast), CSSColor(vBadgeText), CSSColor(vEmber),
            CSSColor(AccentChosen() ? vAccent : vText), AccentChosen() ? @"#fff" : CSSColor(vContentBg)];
    // Aperture's colours (the loading line) for the section marker, whatever accent is chosen
    vars = [vars stringByAppendingString:ThemeIsLight() ? @":root{--ap-t:#22b3a0;--ap-b:#4a78ee;--ap-v:#8c63e6;--ap-glow:.14}" : @":root{--ap-t:#7fe3d1;--ap-b:#86a3f7;--ap-v:#b796f5;--ap-glow:.22}"];
    return [vars stringByAppendingString:@" .btn,.search input,.field input,.field select,.acts a,.bar button,.bar a,.selbar{border-radius:8px!important}"
        ".list,.menu,dialog,.pop{border-radius:12px!important}"
        ".search input:focus,.field input:focus,.field select:focus{box-shadow:0 0 0 3px color-mix(in srgb,var(--pick) 18%,transparent)!important;border-color:color-mix(in srgb,var(--pick) 60%,transparent)!important}"
        ".btn.primary,.acts a.primary{background:var(--pick)!important;color:var(--onpick)!important;border-color:transparent!important}"
        ".btn.danger{background:var(--text)!important;color:var(--bg)!important;border-color:transparent!important}"
        ".sw:checked{background:var(--pick)!important}.sws button.on{border-color:var(--pick)!important}"   // your accent: switches that are on, the chosen swatch
        "nav a.on{position:relative}"                                                                 // the section you're in: an Aperture bar
        "nav a.on::before{content:'';position:absolute;left:0;top:7px;bottom:7px;width:3px;border-radius:3px;background:linear-gradient(180deg,var(--ap-t),var(--ap-b) 50%,var(--ap-v));box-shadow:0 0 8px color-mix(in srgb,var(--ap-b) 60%,transparent)}"
        "input[type=checkbox],input[type=radio],input[type=range],progress{accent-color:var(--pick)}"
        "::selection{background:color-mix(in srgb,var(--pick) 30%,transparent)}"
        ".menu button:hover{background:var(--active)!important;color:var(--text)!important}"
        "mark{background:color-mix(in srgb,var(--text) 18%,transparent)!important;color:inherit!important}"
        "h1{font-family:-apple-system,BlinkMacSystemFont,system-ui,sans-serif;font-weight:650;letter-spacing:-.022em}"
        "h2{letter-spacing:.02em}"
        ".prog{background:linear-gradient(90deg,var(--ap-t),var(--ap-b),var(--ap-v))!important}.search svg{z-index:2}"];
}

static NSString *InternalPagePath(NSString *name) {
    if (![[NSCharacterSet characterSetWithCharactersInString:@"abcdefghijklmnopqrstuvwxyz-"] isSupersetOfSet:[NSCharacterSet characterSetWithCharactersInString:name]]) return nil;
    NSString *file = [name stringByAppendingPathExtension:@"html"];
    NSString *res = [[NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:@"pages"] stringByAppendingPathComponent:file];
    return [NSFileManager.defaultManager fileExistsAtPath:res] ? res : nil;
}


#pragma mark Bookmarks: validation and imports from other browsers

// A tree sent by the bookmark manager is rebuilt from scratch: only names, URLs and folders survive.
static NSMutableDictionary *CleanNode(id n, int depth) {
    if (depth > 40 || ![n isKindOfClass:NSDictionary.class]) return nil;
    NSString *name = [n[@"name"] isKindOfClass:NSString.class] ? n[@"name"] : @"";
    if (name.length > 1000) name = [name substringToIndex:1000];
    if ([n[@"children"] isKindOfClass:NSArray.class]) {
        NSMutableArray *kids = [NSMutableArray array];
        for (id c in n[@"children"]) { NSMutableDictionary *k = CleanNode(c, depth + 1); if (k) [kids addObject:k]; }
        return [NSMutableDictionary dictionaryWithDictionary:@{@"name": name.length ? name : @"Folder", @"children": kids}];
    }
    NSString *url = [n[@"url"] isKindOfClass:NSString.class] ? Trim(n[@"url"]) : nil;
    NSURL *u = url.length && url.length < 8192 ? [NSURL URLWithString:url] : nil;
    if (!u.scheme.length) return nil;
    return [NSMutableDictionary dictionaryWithDictionary:@{@"name": name, @"url": url}];
}

static NSString *AppSupport(NSString *rel) { return [[NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support"] stringByAppendingPathComponent:rel]; }

// Chromium-family browsers keep bookmarks in the same JSON format.
static NSArray<NSArray<NSString *> *> *ChromiumSources(void) {
    return @[@[@"chrome", @"Google Chrome", @"Google/Chrome"], @[@"helium", @"Helium", @"net.imput.helium"], @[@"brave", @"Brave", @"BraveSoftware/Brave-Browser"],
             @[@"edge", @"Microsoft Edge", @"Microsoft Edge"], @[@"vivaldi", @"Vivaldi", @"Vivaldi"], @[@"arc", @"Arc", @"Arc/User Data"], @[@"chromium", @"Chromium", @"Chromium"]];
}
static NSString *ChromiumBookmarksFile(NSString *rel) {
    for (NSString *p in @[@"Default", @"Profile 1", @"Profile 2", @"Profile 3"]) {
        NSString *f = [[AppSupport(rel) stringByAppendingPathComponent:p] stringByAppendingPathComponent:@"Bookmarks"];
        if ([NSFileManager.defaultManager fileExistsAtPath:f]) return f;
    }
    return nil;
}
static NSString *GeckoPlaces(NSString *rel) {
    NSString *dir = [AppSupport(rel) stringByAppendingPathComponent:@"Profiles"];
    NSString *best = nil; NSDate *bestDate = nil;
    for (NSString *p in [NSFileManager.defaultManager contentsOfDirectoryAtPath:dir error:nil] ?: @[]) {
        NSString *f = [[dir stringByAppendingPathComponent:p] stringByAppendingPathComponent:@"places.sqlite"];
        NSDate *d = [NSFileManager.defaultManager attributesOfItemAtPath:f error:nil].fileModificationDate;
        if (d && (!bestDate || [d compare:bestDate] == NSOrderedDescending)) { best = f; bestDate = d; }
    }
    return best;
}
static NSArray<NSDictionary *> *ImportSources(void) {
    NSMutableArray *out = [NSMutableArray array];
    for (NSArray *s in ChromiumSources()) if (ChromiumBookmarksFile(s[2])) [out addObject:@{@"id": s[0], @"name": s[1]}];
    if (GeckoPlaces(@"Firefox")) [out addObject:@{@"id": @"firefox", @"name": @"Firefox"}];
    if (GeckoPlaces(@"zen")) [out addObject:@{@"id": @"zen", @"name": @"Zen"}];
    [out addObject:@{@"id": @"safari", @"name": @"Safari"}];
    return out;
}

static NSMutableDictionary *SafariNode(NSDictionary *n) {
    NSString *type = n[@"WebBookmarkType"];
    if ([type isEqualToString:@"WebBookmarkTypeList"]) {
        NSString *title = n[@"Title"] ?: @"Folder";
        if ([title isEqualToString:@"com.apple.ReadingList"]) return nil;
        if ([title isEqualToString:@"BookmarksBar"]) title = @"Favourites";
        if ([title isEqualToString:@"BookmarksMenu"]) title = @"Bookmarks Menu";
        NSMutableArray *kids = [NSMutableArray array];
        for (NSDictionary *c in n[@"Children"]) { NSMutableDictionary *k = SafariNode(c); if (k) [kids addObject:k]; }
        return [NSMutableDictionary dictionaryWithDictionary:@{@"name": title, @"children": kids}];
    }
    if ([type isEqualToString:@"WebBookmarkTypeLeaf"] && [n[@"URLString"] isKindOfClass:NSString.class])
        return [NSMutableDictionary dictionaryWithDictionary:@{@"name": n[@"URIDictionary"][@"title"] ?: @"", @"url": n[@"URLString"]}];
    return nil;
}

static NSArray *GeckoTree(NSString *places, NSString **err) {
    NSString *tmp = SupportFile(@"import-places.sqlite");
    NSFileManager *fm = NSFileManager.defaultManager;
    for (NSString *sfx in @[@"", @"-wal"]) {
        [fm removeItemAtPath:[tmp stringByAppendingString:sfx] error:nil];
        NSString *src = [places stringByAppendingString:sfx];
        if ([fm fileExistsAtPath:src]) [fm copyItemAtPath:src toPath:[tmp stringByAppendingString:sfx] error:nil];
    }
    sqlite3 *db = NULL;
    NSMutableDictionary<NSNumber *, NSMutableDictionary *> *byId = [NSMutableDictionary dictionary];
    NSMutableArray *rows = [NSMutableArray array];
    if (sqlite3_open_v2(tmp.fileSystemRepresentation, &db, SQLITE_OPEN_READONLY, NULL) == SQLITE_OK) {
        sqlite3_stmt *st = NULL;
        const char *sql = "SELECT b.id, b.parent, b.type, b.title, p.url, b.guid FROM moz_bookmarks b LEFT JOIN moz_places p ON b.fk = p.id ORDER BY b.parent, b.position";
        if (sqlite3_prepare_v2(db, sql, -1, &st, NULL) == SQLITE_OK) {
            while (sqlite3_step(st) == SQLITE_ROW) {
                const char *ti = (const char *)sqlite3_column_text(st, 3), *u = (const char *)sqlite3_column_text(st, 4), *g = (const char *)sqlite3_column_text(st, 5);
                [rows addObject:@{@"id": @(sqlite3_column_int64(st, 0)), @"parent": @(sqlite3_column_int64(st, 1)), @"type": @(sqlite3_column_int(st, 2)),
                                  @"title": ti ? @(ti) : @"", @"url": u ? @(u) : @"", @"guid": g ? @(g) : @""}];
            }
            sqlite3_finalize(st);
        } else if (err) *err = @"Couldn't read the bookmarks database.";
        sqlite3_close(db);
    } else if (err) *err = @"Couldn't open the bookmarks database.";
    for (NSString *sfx in @[@"", @"-wal", @"-shm"]) [fm removeItemAtPath:[tmp stringByAppendingString:sfx] error:nil];
    for (NSDictionary *r in rows) {
        if ([r[@"type"] intValue] == 2) byId[r[@"id"]] = [NSMutableDictionary dictionaryWithDictionary:@{@"name": r[@"title"], @"children": [NSMutableArray array], @"guid": r[@"guid"]}];
        else if ([r[@"type"] intValue] == 1 && [r[@"url"] length] && ![r[@"url"] hasPrefix:@"place:"]) byId[r[@"id"]] = [NSMutableDictionary dictionaryWithDictionary:@{@"name": r[@"title"], @"url": r[@"url"]}];
    }
    for (NSDictionary *r in rows) { NSMutableDictionary *n = byId[r[@"id"]], *p = byId[r[@"parent"]]; if (n && p) [p[@"children"] addObject:n]; }
    NSDictionary *names = @{@"toolbar_____": @"Bookmarks Toolbar", @"menu________": @"Bookmarks Menu", @"unfiled_____": @"Other Bookmarks", @"mobile______": @"Mobile Bookmarks"};
    NSMutableArray *out = [NSMutableArray array];
    for (NSString *g in @[@"toolbar_____", @"menu________", @"unfiled_____", @"mobile______"]) {
        for (NSMutableDictionary *n in byId.allValues) if ([n[@"guid"] isEqualToString:g] && [n[@"children"] count]) {
            n[@"name"] = names[g]; [out addObject:n];
        }
    }
    return out;   // guid keys are dropped by CleanNode on the way back in
}

static NSArray *ImportTree(NSString *source, NSString **err) {
    for (NSArray *s in ChromiumSources()) if ([s[0] isEqualToString:source]) {
        NSData *d = [NSData dataWithContentsOfFile:ChromiumBookmarksFile(s[2]) ?: @""];
        NSDictionary *root = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : nil;
        if (![root isKindOfClass:NSDictionary.class]) { *err = [NSString stringWithFormat:@"Couldn't read %@'s bookmarks.", s[1]]; return nil; }
        NSMutableArray *out = [NSMutableArray array];
        NSDictionary *names = @{@"bookmark_bar": @"Bookmarks Bar", @"other": @"Other Bookmarks", @"synced": @"Mobile Bookmarks"};
        for (NSString *k in @[@"bookmark_bar", @"other", @"synced"]) {
            NSMutableDictionary *n = ConvertChromeNode(root[@"roots"][k] ?: @{});
            if ([n[@"children"] count]) { n[@"name"] = names[k]; [out addObject:n]; }
        }
        return out;
    }
    if ([source isEqualToString:@"firefox"] || [source isEqualToString:@"zen"]) {
        NSString *places = GeckoPlaces([source isEqualToString:@"zen"] ? @"zen" : @"Firefox");
        if (!places) { *err = @"No profile found."; return nil; }
        return GeckoTree(places, err);
    }
    if ([source isEqualToString:@"safari"]) {
        NSString *f = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Safari/Bookmarks.plist"];
        NSDictionary *root = [NSDictionary dictionaryWithContentsOfFile:f];
        if (!root) { *err = @"macOS keeps Safari's bookmarks private. In Safari choose File › Export › Bookmarks…, then use “Import from HTML file…” here."; return nil; }
        NSMutableDictionary *n = SafariNode(root);
        return n[@"children"] ?: @[];
    }
    *err = @"Unknown browser.";
    return nil;
}


static NSMutableDictionary<NSString *, NSDictionary *> *gReader;   // reader articles, by one-time id (in memory only)
static NSMutableDictionary<NSString *, NSDictionary *> *gSource;   // the page as it stands (live DOM), captured for the source viewer, by one-time id

// Fetch what the server sends for an address, as this profile (its cookies, Iris's user agent), without running it.
static void SourceFetch(NSURL *u, WKWebView *from, void (^done)(NSDictionary *)) {
    WKWebsiteDataStore *store = from.configuration.websiteDataStore ?: WKWebsiteDataStore.defaultDataStore;
    NSString *ua = nil; @try { ua = [from valueForKey:@"_userAgent"]; } @catch (NSException *e) {}
    [store.httpCookieStore getAllCookies:^(NSArray<NSHTTPCookie *> *all) {
        NSMutableURLRequest *r = [NSMutableURLRequest requestWithURL:u cachePolicy:NSURLRequestReturnCacheDataElseLoad timeoutInterval:30];
        r.HTTPShouldHandleCookies = NO;
        if (ua.length) [r setValue:ua forHTTPHeaderField:@"User-Agent"];
        [r setValue:@"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8" forHTTPHeaderField:@"Accept"];
        NSString *cookie = CookieHeader(all, u); if (cookie.length) [r setValue:cookie forHTTPHeaderField:@"Cookie"];
        NSURLSessionConfiguration *cfg = NSURLSessionConfiguration.ephemeralSessionConfiguration;
        cfg.HTTPCookieStorage = nil; cfg.HTTPShouldSetCookies = NO; cfg.URLCache = NSURLCache.sharedURLCache;
        NSURLSession *s = [NSURLSession sessionWithConfiguration:cfg];
        CFAbsoluteTime t0 = CFAbsoluteTimeGetCurrent();
        [[s dataTaskWithRequest:r completionHandler:^(NSData *d, NSURLResponse *resp, NSError *e) {
            NSHTTPURLResponse *h = [resp isKindOfClass:NSHTTPURLResponse.class] ? (NSHTTPURLResponse *)resp : nil;
            NSMutableDictionary *out = [NSMutableDictionary dictionary];
            out[@"status"] = @(h.statusCode); out[@"type"] = resp.MIMEType ?: @""; out[@"url"] = resp.URL.absoluteString ?: u.absoluteString;
            out[@"bytes"] = @(d.length); out[@"ms"] = @((int)((CFAbsoluteTimeGetCurrent() - t0) * 1000));
            if (!d) out[@"error"] = e.localizedDescription ?: @"Couldn't load";
            NSString *mime = resp.MIMEType.lowercaseString ?: @"";
            BOOL binary = [mime hasPrefix:@"image/"] || [mime hasPrefix:@"video/"] || [mime hasPrefix:@"audio/"] || [mime hasPrefix:@"font/"] || [mime isEqualToString:@"application/octet-stream"] || [mime isEqualToString:@"application/pdf"] || [mime containsString:@"zip"];
            if (d && binary && ![mime containsString:@"svg"]) out[@"binary"] = @YES;
            else if (d) {
                NSData *body = d.length > 12 * 1024 * 1024 ? [d subdataWithRange:NSMakeRange(0, 12 * 1024 * 1024)] : d;
                if (body.length < d.length) out[@"truncated"] = @YES;
                NSStringEncoding enc = NSUTF8StringEncoding;
                if (resp.textEncodingName.length) { CFStringEncoding ce = CFStringConvertIANACharSetNameToEncoding((__bridge CFStringRef)resp.textEncodingName); if (ce != kCFStringEncodingInvalidId) enc = CFStringConvertEncodingToNSStringEncoding(ce); }
                NSString *text = [[NSString alloc] initWithData:body encoding:enc] ?: [[NSString alloc] initWithData:body encoding:NSUTF8StringEncoding] ?: [[NSString alloc] initWithData:body encoding:NSISOLatin1StringEncoding];
                out[@"text"] = text ?: @"";
            }
            [s finishTasksAndInvalidate];
            dispatch_async(dispatch_get_main_queue(), ^{ done(out); });
        }] resume];
    }];
}

@interface VInternal : NSObject <WKURLSchemeHandler, WKScriptMessageHandlerWithReply>
+ (instancetype)shared;
@end

@implementation VInternal

+ (instancetype)shared { static VInternal *v; static dispatch_once_t once; dispatch_once(&once, ^{ v = [VInternal new]; }); return v; }

static void Respond(id<WKURLSchemeTask> task, NSInteger status, NSString *type, NSData *body, NSDictionary *extra) {
    NSMutableDictionary *h = [NSMutableDictionary dictionaryWithDictionary:@{@"Content-Type": type, @"Cache-Control": @"no-store"}];
    [h addEntriesFromDictionary:extra ?: @{}];
    NSHTTPURLResponse *r = [[NSHTTPURLResponse alloc] initWithURL:task.request.URL statusCode:status HTTPVersion:@"HTTP/1.1" headerFields:h];
    @try { [task didReceiveResponse:r]; [task didReceiveData:body ?: [NSData data]]; [task didFinish]; } @catch (NSException *e) {}
}

- (void)webView:(WKWebView *)w startURLSchemeTask:(id<WKURLSchemeTask>)task {
    NSURL *u = task.request.URL;
    NSString *host = u.host.lowercaseString ?: @"";
    if ([host isEqualToString:@"favicon"]) {
        NSString *page = nil;
        for (NSURLQueryItem *q in [NSURLComponents componentsWithURL:u resolvingAgainstBaseURL:NO].queryItems) if ([q.name isEqualToString:@"u"]) page = q.value;
        NSString *k = page ? IconKey(page) : nil;
        NSData *png = k ? [NSData dataWithContentsOfFile:[[IconDir() stringByAppendingPathComponent:k] stringByAppendingPathExtension:@"png"]] : nil;
        Respond(task, png ? 200 : 404, png ? @"image/png" : @"text/plain", png, @{@"Cache-Control": @"max-age=600"});
        return;
    }
    if ([host isEqualToString:@"dlicon"]) {   // the Mac's own icon for a file type, for the download manager
        NSString *ext = [u.lastPathComponent stringByRemovingPercentEncoding] ?: @"";
        static NSCache *cache; if (!cache) cache = [NSCache new];
        NSData *png = [cache objectForKey:ext];
        if (!png) {
            UTType *t = [UTType typeWithFilenameExtension:ext] ?: UTTypeData;
            NSImage *im = [NSWorkspace.sharedWorkspace iconForContentType:t];
            NSImage *sized = [NSImage imageWithSize:NSMakeSize(64, 64) flipped:NO drawingHandler:^BOOL(NSRect r) { [im drawInRect:r]; return YES; }];
            CGImageRef cg = [sized CGImageForProposedRect:NULL context:nil hints:nil];
            png = cg ? [[[NSBitmapImageRep alloc] initWithCGImage:cg] representationUsingType:NSBitmapImageFileTypePNG properties:@{}] : nil;
            if (png) [cache setObject:png forKey:ext];
        }
        Respond(task, png ? 200 : 404, png ? @"image/png" : @"text/plain", png, @{@"Cache-Control": @"max-age=3600"});
        return;
    }
    // pages only open as a whole tab, never framed inside a website
    NSURL *top = task.request.mainDocumentURL;
    if (top && ![top.scheme isEqualToString:@"iris"]) { Respond(task, 403, @"text/plain", nil, nil); return; }
    NSString *path = InternalPagePath(host);
    NSString *html = path ? [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil] : nil;
    if (!html) {
        html = [NSString stringWithFormat:@"<!doctype html><meta charset=utf-8><title>Not found</title><style>/*THEME*/html{background:var(--bg);color:var(--dim);font:15px -apple-system,system-ui;display:grid;place-items:center;height:100%%}</style><p>Iris has no page called “%@”.</p>",
                [[host stringByReplacingOccurrencesOfString:@"<" withString:@""] stringByReplacingOccurrencesOfString:@"&" withString:@""]];
    }
    // scripts run only with this response's nonce: markup that slips into a page (a reader article, a bookmark name) can't run code
    uint8_t rnd[18]; arc4random_buf(rnd, sizeof rnd);
    NSString *nonce = [[NSData dataWithBytes:rnd length:sizeof rnd] base64EncodedStringWithOptions:0];
    html = [html stringByReplacingOccurrencesOfString:@"/*THEME*/" withString:ThemeCSS()];
    html = [html stringByReplacingOccurrencesOfString:@"{{NONCE}}" withString:nonce];
    NSString *img = [host isEqualToString:@"reader"] ? @"iris: data: https: http:" : @"iris: data:";
    Respond(task, path ? 200 : 404, @"text/html; charset=utf-8", [html dataUsingEncoding:NSUTF8StringEncoding],
            @{@"Content-Security-Policy": [NSString stringWithFormat:@"default-src 'none'; img-src %@; media-src https:; style-src 'unsafe-inline'; script-src 'nonce-%@'; %@base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
                                           img, nonce, [host isEqualToString:@"source"] ? @"worker-src blob:; " : @""]});   // the code viewer formats big files off the main thread
}

- (void)webView:(WKWebView *)w stopURLSchemeTask:(id<WKURLSchemeTask>)task {}

// The download manager page (iris://downloads): a list it polls, and the controls it calls.
static NSString *DLCategory(NSString *ext) {
    ext = ext.lowercaseString;
    NSDictionary *m = @{@"video": @[@"mp4", @"mkv", @"mov", @"avi", @"webm", @"m4v", @"flv", @"wmv", @"mpg", @"mpeg", @"ts"],
                        @"audio": @[@"mp3", @"m4a", @"aac", @"flac", @"wav", @"ogg", @"opus", @"aiff", @"wma"],
                        @"archive": @[@"zip", @"rar", @"7z", @"tar", @"gz", @"bz2", @"xz", @"tgz", @"zst", @"lz"],
                        @"doc": @[@"pdf", @"doc", @"docx", @"xls", @"xlsx", @"ppt", @"pptx", @"txt", @"rtf", @"epub", @"pages", @"numbers", @"key", @"csv", @"md", @"odt"],
                        @"program": @[@"dmg", @"pkg", @"app", @"exe", @"msi", @"iso", @"deb", @"rpm", @"apk", @"appimage", @"jar"],
                        @"image": @[@"jpg", @"jpeg", @"png", @"gif", @"webp", @"heic", @"svg", @"bmp", @"tiff", @"avif", @"ico"]};
    for (NSString *k in m) if ([m[k] containsObject:ext]) return k;
    return @"other";
}
static NSDictionary *DLInfo(VDownload *x) {
    NSString *ext = x.name.pathExtension.length ? x.name.pathExtension : @"bin";
    NSMutableDictionary *d = [@{@"id": x.ident ?: @"", @"name": x.name ?: @"", @"url": x.url ?: @"", @"host": HostOf([NSURL URLWithString:x.url ?: @""]) ?: @"",
        @"state": x.state ?: @"failed", @"kind": x.kind ?: @"webkit", @"got": @(x.received), @"total": @(x.total), @"speed": @((int64_t)x.speed), @"peak": @((int64_t)x.peak),
        @"t": @(x.started), @"end": @(x.ended), @"conns": @(x.conns), @"res": @(x.resumable), @"path": x.path ?: @"", @"ext": ext.lowercaseString,
        @"cat": DLCategory(ext), @"exists": @([x.state isEqual:@"done"] && [NSFileManager.defaultManager fileExistsAtPath:x.path ?: @""])} mutableCopy];
    if (x.error) d[@"err"] = x.error;
    if ([x.kind isEqual:@"accel"] && ![x.state isEqual:@"done"] && x.total > 0 && x.segs.count) {
        NSMutableArray *segs = [NSMutableArray array];
        NSArray *live = x.tasks.allKeys ?: @[];
        NSUInteger i = 0;
        for (NSDictionary *g in x.segs.copy) { if (segs.count < 48) [segs addObject:@[g[@"s"] ?: @0, g[@"e"] ?: @0, g[@"g"] ?: @0, @([live containsObject:@(i)])]]; i++; }
        d[@"segs"] = segs;
    }
    return d;
}
// Customise Toolbar (iris://toolbar, shown over the window): the catalog, the arrangement, and changes applied live.
static NSString *SymbolDataURL(NSString *name, CGFloat pt) {
    static NSCache *cache; if (!cache) cache = [NSCache new];
    NSString *key = [NSString stringWithFormat:@"%@@%.1f", name, pt];
    NSString *hit = [cache objectForKey:key]; if (hit) return hit;
    NSImage *im = Tinted(Symbol(name, pt, NSFontWeightMedium), NSColor.whiteColor);
    if (!im) return @"";
    NSInteger W = (NSInteger)ceil(im.size.width * 2), H = (NSInteger)ceil(im.size.height * 2);
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:W pixelsHigh:H bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
    rep.size = im.size;
    [NSGraphicsContext saveGraphicsState];
    NSGraphicsContext.currentContext = [NSGraphicsContext graphicsContextWithBitmapImageRep:rep];
    [im drawInRect:NSMakeRect(0, 0, im.size.width, im.size.height)];
    [NSGraphicsContext restoreGraphicsState];
    NSData *png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    NSString *url = [@"data:image/png;base64," stringByAppendingString:[png base64EncodedStringWithOptions:0]];
    [cache setObject:url forKey:key];
    return url;
}
static NSString *ImageDataURL(NSImage *im, CGFloat side) {
    if (!im) return @"";
    NSImage *sized = [NSImage imageWithSize:NSMakeSize(side, side) flipped:NO drawingHandler:^BOOL(NSRect r) { [im drawInRect:r]; return YES; }];
    CGImageRef cg = [sized CGImageForProposedRect:NULL context:nil hints:nil];
    NSData *png = cg ? [[[NSBitmapImageRep alloc] initWithCGImage:cg] representationUsingType:NSBitmapImageFileTypePNG properties:@{}] : nil;
    return png ? [@"data:image/png;base64," stringByAppendingString:[png base64EncodedStringWithOptions:0]] : @"";
}
static NSDictionary *ToolbarState(void) {
    NSMutableArray *cat = [NSMutableArray array];
    for (NSArray *i in ToolbarCatalog())
        [cat addObject:@{@"k": i[0], @"title": i[1], @"icon": SymbolDataURL(i[2], 15), @"zones": i[3], @"home": i[4], @"desc": i[5]}];
    NSMutableArray *exts = [NSMutableArray array];
    for (id e in FExtHost.shared.extensions) if (ExtensionPinned([e valueForKey:@"ident"]))
        [exts addObject:@{@"name": [e valueForKey:@"name"] ?: @"", @"icon": ImageDataURL([FExtHost.shared iconFor:e], 32)}];
    return @{@"layout": ToolbarLayout(), @"catalog": cat, @"exts": exts, @"width": @([Defaults() integerForKey:kAddrWidth]), @"dlAlways": @(ToolbarShows(@"dlalways")),
             @"lens": SymbolDataURL(@"camera.aperture", 15), @"lock": SymbolDataURL(@"lock.fill", 11), @"isDefault": @([Defaults() objectForKey:kToolbarLayout] == nil)};
}
static void ToolbarOp(NSString *op, NSDictionary *b, VWindow *win, void (^reply)(id, NSString *)) {
    if ([op isEqualToString:@"toolbar.get"]) {
        NSMutableDictionary *st = [ToolbarState() mutableCopy]; st[@"blocked"] = @(win.current.blocked); st[@"puzzle"] = SymbolDataURL(@"puzzlepiece.extension", 15);
        reply(st, nil); return;
    }
    if ([op isEqualToString:@"toolbar.set"]) {
        NSDictionary *L = ToolbarSanitize(b[@"layout"]);
        [Defaults() setObject:L forKey:kToolbarLayout]; RelayoutToolbars();
        reply(L, nil); return;
    }
    if ([op isEqualToString:@"toolbar.width"]) { [Defaults() setInteger:MAX(0, MIN(2, [b[@"v"] integerValue])) forKey:kAddrWidth]; RelayoutToolbars(); reply(@YES, nil); return; }
    if ([op isEqualToString:@"toolbar.dlalways"]) { SetToolbarShows(@"dlalways", [b[@"on"] boolValue]); RelayoutToolbars(); reply(@YES, nil); return; }
    if ([op isEqualToString:@"toolbar.reset"]) {
        for (NSString *k in @[kToolbarLayout, kAddrWidth]) [Defaults() removeObjectForKey:k];
        SetToolbarShows(@"dlalways", NO); RelayoutToolbars(); reply(ToolbarState(), nil); return;
    }
    if ([op isEqualToString:@"toolbar.done"]) { [win closeToolbarCustomiser]; reply(@YES, nil); return; }
    reply(nil, @"unknown op");
}

static void DownloadOp(NSString *op, NSDictionary *b, VWindow *win, void (^reply)(id, NSString *)) {
    VDownloads *D = VDownloads.shared; FAccel *A = FAccel.shared;
    VDownload *x = [b[@"id"] isKindOfClass:NSString.class] ? [D byId:b[@"id"]] : nil;
    if ([op isEqualToString:@"dl.list"]) {
        NSMutableArray *out = [NSMutableArray array]; NSInteger running = 0;
        for (VDownload *it in D.items.copy) { if (!it.ident) it.ident = NSUUID.UUID.UUIDString; [out addObject:DLInfo(it)]; if ([it.state isEqual:@"running"]) running++; }
        int64_t speed = A.currentSpeed;
        for (VDownload *it in D.items.copy) if ([it.kind isEqual:@"webkit"] && [it.state isEqual:@"running"]) speed += (int64_t)it.speed;
        reply(@{@"items": out, @"speed": @(speed), @"running": @(running),
                @"settings": @{@"accel": @([Defaults() boolForKey:kDLAccel]), @"conns": @([Defaults() integerForKey:kDLConns]), @"active": @([Defaults() integerForKey:kDLActive]),
                               @"limit": @([Defaults() integerForKey:kDLLimit]), @"ask": @([Defaults() boolForKey:kAskDownload]), @"folder": win.downloadFolder.path ?: @""}}, nil);
        return;
    }
    if ([op isEqualToString:@"dl.pause"]) { if (x) [A pause:x]; reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.resume"] || [op isEqualToString:@"dl.retry"]) {
        if (x && [x.kind isEqual:@"webkit"] && x.resume && x.view) { [D.items removeObject:x]; [x.view resumeDownloadFromResumeData:x.resume completionHandler:^(WKDownload *d) { d.delegate = (id<WKDownloadDelegate>)x.view.navigationDelegate; }]; }
        else if (x && [x.state isEqual:@"cancelled"]) { [D.items removeObject:x]; [A downloadURL:[NSURL URLWithString:x.url] name:x.name referer:x.referer view:win.current.web.web private:NO]; }
        else if (x) [A resume:x];
        [D save]; reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"dl.cancel"]) { if (x) [A cancel:x]; dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 300 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ [D save]; }); reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.remove"]) {
        if (x) { if ([@[@"running", @"queued"] containsObject:x.state ?: @""]) [A cancel:x]; [D.items removeObject:x]; [D save]; [D changed]; }
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"dl.trash"]) {   // the file goes to the Trash (recoverable), and the entry leaves the list
        if (x.path && [NSFileManager.defaultManager fileExistsAtPath:x.path]) [NSWorkspace.sharedWorkspace recycleURLs:@[[NSURL fileURLWithPath:x.path]] completionHandler:nil];
        if (x) { [D.items removeObject:x]; [D save]; [D changed]; }
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"dl.open"]) { if (x.path) [NSWorkspace.sharedWorkspace openURL:[NSURL fileURLWithPath:x.path]]; reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.reveal"]) {
        NSString *p = [x.state isEqual:@"done"] ? x.path : x.partPath ?: x.path;
        if (p && [NSFileManager.defaultManager fileExistsAtPath:p]) [NSWorkspace.sharedWorkspace activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:p]]];
        else [NSWorkspace.sharedWorkspace openURL:win.downloadFolder];
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"dl.copy"]) { if (x.url) { [NSPasteboard.generalPasteboard clearContents]; [NSPasteboard.generalPasteboard setString:x.url forType:NSPasteboardTypeString]; [win showToast:@"Link copied"]; } reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.add"]) {
        NSURL *u = [b[@"url"] isKindOfClass:NSString.class] ? URLFromInput(Trim(b[@"url"])) : nil;
        if (![@[@"http", @"https"] containsObject:u.scheme.lowercaseString ?: @""]) { reply(@NO, nil); return; }
        [A downloadURL:u name:nil referer:nil view:win.current.web.web ?: nil private:win.isPrivate];
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"dl.pauseAll"]) { [A pauseAll]; reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.resumeAll"]) { [A resumeAll]; reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.openFolder"]) { [NSWorkspace.sharedWorkspace openURL:win.downloadFolder]; reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.chooseFolder"]) { [win showSettingsSection:@"downloads"]; reply(@YES, nil); return; }
    if ([op isEqualToString:@"dl.set"]) {
        NSString *k = b[@"key"]; id v = b[@"value"];
        if ([k isEqual:@"accel"]) [Defaults() setBool:[v boolValue] forKey:kDLAccel];
        else if ([k isEqual:@"ask"]) [Defaults() setBool:[v boolValue] forKey:kAskDownload];
        else if ([k isEqual:@"conns"]) [Defaults() setInteger:MAX(1, MIN(16, [v integerValue])) forKey:kDLConns];
        else if ([k isEqual:@"active"]) [Defaults() setInteger:MAX(1, MIN(8, [v integerValue])) forKey:kDLActive];
        else if ([k isEqual:@"limit"]) [Defaults() setInteger:MAX(0, [v integerValue]) forKey:kDLLimit];
        reply(@YES, nil); return;
    }
    reply(nil, @"unknown");
}

static NSURL *WebURL(id s) {
    NSURL *u = [s isKindOfClass:NSString.class] ? [NSURL URLWithString:s] : nil;
    return [@[@"http", @"https", @"iris", @"file"] containsObject:u.scheme.lowercaseString ?: @""] ? u : nil;
}

- (void)userContentController:(WKUserContentController *)ucc didReceiveScriptMessage:(WKScriptMessage *)m replyHandler:(void (^)(id, NSString *))reply {
    if (!m.frameInfo.isMainFrame || ![m.frameInfo.securityOrigin.protocol isEqualToString:@"iris"] || ![m.body isKindOfClass:NSDictionary.class]) { reply(nil, @"denied"); return; }
    NSDictionary *b = m.body;
    VWindow *win = WinOfWeb(m.webView) ?: gWin;
    NSString *op = [b[@"op"] isKindOfClass:NSString.class] ? b[@"op"] : @"";

    if ([op hasPrefix:@"dl."]) { DownloadOp(op, b, win, reply); return; }
    if ([op hasPrefix:@"settings."]) { SettingsOp(op, b, win, reply); return; }
    if ([op hasPrefix:@"toolbar."]) { ToolbarOp(op, b, win, reply); return; }
    if ([op hasPrefix:@"install."] || [op hasPrefix:@"apps."]) { WebAppOp(op, b, win, reply); return; }
    if ([op isEqualToString:@"history.list"]) {
        NSMutableArray *out = [NSMutableArray array];
        for (NSDictionary *e in [VHistory.shared all]) [out addObject:@{@"u": e[@"u"] ?: @"", @"ti": e[@"ti"] ?: @"", @"t": e[@"t"] ?: @0, @"c": e[@"c"] ?: @1}];
        reply(out, nil); return;
    }
    if ([op isEqualToString:@"history.remove"]) {
        NSArray *urls = [b[@"urls"] isKindOfClass:NSArray.class] ? b[@"urls"] : @[];
        [VHistory.shared removeURLs:urls]; reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"history.removeHost"]) {
        NSString *h = [b[@"host"] isKindOfClass:NSString.class] ? b[@"host"] : nil;
        [VHistory.shared removeHost:h]; reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"history.clear"]) {
        NSString *range = [b[@"range"] isKindOfClass:NSString.class] ? b[@"range"] : @"hour";
        NSDictionary *names = @{@"hour": @"the last hour", @"today": @"today", @"week": @"the last 7 days", @"all": @"all time"};
        NSTimeInterval now = NSDate.date.timeIntervalSince1970;
        NSTimeInterval since = [range isEqualToString:@"hour"] ? now - 3600 : [range isEqualToString:@"today"] ? [NSCalendar.currentCalendar startOfDayForDate:NSDate.date].timeIntervalSince1970
                             : [range isEqualToString:@"week"] ? now - 7 * 86400 : 0;
        NSAlert *a = [NSAlert new];
        a.messageText = [NSString stringWithFormat:@"Clear history from %@?", names[range] ?: @"the last hour"];
        a.informativeText = @"Pages you visited in this period are removed from History and address-bar suggestions. Bookmarks and open tabs stay.";
        a.showsSuppressionButton = YES; a.suppressionButton.title = @"Also remove cookies, site data and cache from this period"; a.suppressionButton.state = NSControlStateValueOff;
        [a addButtonWithTitle:@"Clear"]; [a addButtonWithTitle:@"Cancel"];
        NSWindow *win = m.webView.window ?: gWin.window;
        [a beginSheetModalForWindow:win completionHandler:^(NSModalResponse r) {
            if (r != NSAlertFirstButtonReturn) { reply(@NO, nil); return; }
            if (since <= 0) [VHistory.shared clear]; else [VHistory.shared removeSince:since];
            if (a.suppressionButton.state == NSControlStateValueOn)
                [ProfileStore(gWin && !gWin.isPrivate ? gWin.profile : @"") removeDataOfTypes:WKWebsiteDataStore.allWebsiteDataTypes modifiedSince:[NSDate dateWithTimeIntervalSince1970:since] completionHandler:^{}];
            [gWin showToast:@"History cleared"];
            reply(@YES, nil);
        }];
        return;
    }
    if ([op isEqualToString:@"open"]) {
        NSURL *u = WebURL(b[@"url"]); NSString *how = [b[@"how"] isKindOfClass:NSString.class] ? b[@"how"] : @"here";
        if (!u) { reply(@NO, nil); return; }
        if ([how isEqualToString:@"tab"]) [win newTab:u select:YES];
        else if ([how isEqualToString:@"bg"]) [win newTab:u select:NO];
        else [win openURL:u newTab:NO];
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"copy"]) {
        NSString *s = [b[@"text"] isKindOfClass:NSString.class] ? b[@"text"] : @"";
        [NSPasteboard.generalPasteboard clearContents]; [NSPasteboard.generalPasteboard setString:s forType:NSPasteboardTypeString];
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"reader.get"]) {
        NSString *ident = [b[@"id"] isKindOfClass:NSString.class] ? b[@"id"] : @"";
        reply(gReader[ident] ?: @{}, nil); return;
    }
    if ([op isEqualToString:@"reader.prefs"]) {
        if ([b[@"set"] isKindOfClass:NSDictionary.class]) [Defaults() setObject:b[@"set"] forKey:@"readerPrefs"];
        reply([Defaults() dictionaryForKey:@"readerPrefs"] ?: @{}, nil); return;
    }
    if ([op isEqualToString:@"source.get"]) {   // the live DOM captured when you chose View Source
        NSString *ident = [b[@"id"] isKindOfClass:NSString.class] ? b[@"id"] : @"";
        reply(gSource[ident] ?: @{}, nil); return;
    }
    if ([op isEqualToString:@"source.fetch"]) {   // what the server sent: web addresses only
        NSURL *u = WebURL(b[@"url"]);
        if (![@[@"http", @"https"] containsObject:u.scheme.lowercaseString ?: @""]) { reply(@{@"error": @"Only web addresses have a source to show"}, nil); return; }
        SourceFetch(u, m.webView, ^(NSDictionary *r) { reply(r, nil); }); return;
    }
    if ([op isEqualToString:@"source.save"]) {
        NSString *text = [b[@"text"] isKindOfClass:NSString.class] ? b[@"text"] : @"";
        NSString *name = [b[@"name"] isKindOfClass:NSString.class] && [b[@"name"] length] ? b[@"name"] : @"source.html";
        name = [[name stringByReplacingOccurrencesOfString:@"/" withString:@"-"] stringByReplacingOccurrencesOfString:@":" withString:@"-"];
        [win saveData:[text dataUsingEncoding:NSUTF8StringEncoding] name:name]; reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"toast"]) {
        if ([b[@"text"] isKindOfClass:NSString.class]) [gWin showToast:b[@"text"]];
        reply(@YES, nil); return;
    }

    if ([op isEqualToString:@"bm.tree"]) { reply(@{@"v": @(gBmVersion), @"tree": VBookmarks.shared.bar}, nil); return; }
    if ([op isEqualToString:@"bm.replace"]) {
        if ([b[@"v"] integerValue] != gBmVersion) { reply(@{@"stale": @YES, @"v": @(gBmVersion), @"tree": VBookmarks.shared.bar}, nil); return; }
        if (![b[@"tree"] isKindOfClass:NSArray.class]) { reply(nil, @"bad tree"); return; }
        NSMutableArray *bar = [NSMutableArray array];
        for (id n in b[@"tree"]) { NSMutableDictionary *k = CleanNode(n, 0); if (k) [bar addObject:k]; }
        VBookmarks.shared.bar = bar; [VBookmarks.shared save]; BookmarksChanged();
        reply(@{@"v": @(gBmVersion), @"tree": bar}, nil); return;
    }
    if ([op isEqualToString:@"bm.sources"]) { reply(ImportSources(), nil); return; }
    if ([op isEqualToString:@"bm.import"]) {
        NSString *err = nil;
        NSArray *t = ImportTree([b[@"source"] isKindOfClass:NSString.class] ? b[@"source"] : @"", &err);
        NSMutableArray *clean = [NSMutableArray array];
        for (id n in t ?: @[]) { NSMutableDictionary *k = CleanNode(n, 0); if (k) [clean addObject:k]; }
        reply(t ? @{@"tree": clean} : @{@"error": err ?: @"Nothing to import."}, nil); return;
    }
    if ([op isEqualToString:@"bm.export"]) {
        NSString *html = [b[@"html"] isKindOfClass:NSString.class] ? b[@"html"] : @"";
        NSSavePanel *p = [NSSavePanel savePanel];
        NSDateFormatter *f = [NSDateFormatter new]; f.dateFormat = @"yyyy-MM-dd";
        p.nameFieldStringValue = [NSString stringWithFormat:@"Iris Bookmarks %@.html", [f stringFromDate:NSDate.date]];
        p.directoryURL = gWin.downloadFolder;
        [p beginSheetModalForWindow:m.webView.window ?: gWin.window completionHandler:^(NSModalResponse r) {
            BOOL ok = r == NSModalResponseOK && [[html dataUsingEncoding:NSUTF8StringEncoding] writeToURL:p.URL atomically:YES];
            if (ok) [gWin showToast:[NSString stringWithFormat:@"Saved %@", p.URL.lastPathComponent]];
            reply(@(ok), nil);
        }];
        return;
    }
    if ([op isEqualToString:@"bm.openAll"]) {
        NSArray *urls = [b[@"urls"] isKindOfClass:NSArray.class] ? b[@"urls"] : @[];
        NSUInteger n = 0;
        for (id s in urls) { NSURL *u = WebURL(s); if (!u) continue; [win newTab:u select:n == 0]; if (++n >= 40) break; }
        reply(@(n), nil); return;
    }
    if ([op isEqualToString:@"bm.tabs"]) {
        NSMutableArray *out = [NSMutableArray array];
        for (VTab *t in win.tabs) if (WebURL(t.url) && ![t.url hasPrefix:@"iris:"]) [out addObject:@{@"name": t.title ?: @"", @"url": t.url}];
        reply(out, nil); return;
    }
    reply(nil, @"unknown op");
}

@end

static void IrisInternalInstall(WKWebViewConfiguration *c, WKUserContentController *ucc) {
    if (![c urlSchemeHandlerForURLScheme:@"iris"]) [c setURLSchemeHandler:VInternal.shared forURLScheme:@"iris"];
    static NSHashTable *done;
    if (!done) done = [NSHashTable weakObjectsHashTable];
    if (ucc && ![done containsObject:ucc]) { [done addObject:ucc]; [ucc addScriptMessageHandlerWithReply:VInternal.shared contentWorld:WKContentWorld.pageWorld name:@"irisInternal"]; }
}

static void PageHearsMouse(VWindow *w, BOOL hears);
// The shade behind Customise Toolbar: covers the page (not the bar), closes the editor when clicked.
@interface VCustomiserDim : NSView
@property (weak) VWindow *owner;
@property (strong) NSView *box;
@property NSSize want;   // the editor's size, when the window has room for it
- (void)placeBox;
@end
@implementation VCustomiserDim
- (void)placeBox {
    NSRect b = self.bounds; CGFloat top = 44;
    CGFloat w = MIN(self.want.width ?: 900, NSWidth(b) - 40), h = MIN(self.want.height ?: 640, NSHeight(b) - top - 28);
    BOOL flipped = self.isFlipped;
    CGFloat y = flipped ? top + 6 : NSHeight(b) - top - 6 - h;
    self.box.frame = NSMakeRect(round((NSWidth(b) - w) / 2), y, w, h);
    self.box.subviews.firstObject.frame = self.box.bounds;
}
- (void)resizeSubviewsWithOldSize:(NSSize)s { [self placeBox]; }
- (void)mouseDown:(NSEvent *)e { if (!NSPointInRect([self convertPoint:e.locationInWindow fromView:nil], self.box.frame)) [self.owner closeToolbarCustomiser]; }
- (void)scrollWheel:(NSEvent *)e {}
- (BOOL)mouseDownCanMoveWindow { return NO; }
@end

@implementation VWindow (Internal)
- (void)openInternal:(NSString *)name {
    NSString *prefix = [NSString stringWithFormat:@"iris://%@", name];
    for (VTab *t in self.tabs) if ([t.url hasPrefix:prefix]) { [self selectTab:t]; return; }
    [self newTab:[NSURL URLWithString:prefix] select:YES];
}
// Customise Toolbar: the editor floats over the page, below the bar, so the bar itself is the live preview.
- (void)showToolbarCustomiser:(id)s { [self showOverlay:@"toolbar" size:NSMakeSize(900, 640)]; }
// An iris:// page floating over the window (Customise Toolbar, Install App): the page under it is shaded and quiet.
- (void)showOverlay:(NSString *)page size:(NSSize)size {
    NSView *root = self.window.contentView;
    if (objc_getAssociatedObject(self, &kCustomiserKey)) return;
    [self closePanels];
    VCustomiserDim *dim = [[VCustomiserDim alloc] initWithFrame:root.bounds];
    dim.want = size;
    dim.owner = self; dim.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    dim.wantsLayer = YES; dim.layer.backgroundColor = [NSColor colorWithWhite:0 alpha:ThemeIsLight() ? 0.16 : 0.42].CGColor;
    WKWebViewConfiguration *cfg = [WKWebViewConfiguration new];
    IrisInternalInstall(cfg, cfg.userContentController);
    NSView *box = [[NSView alloc] initWithFrame:NSZeroRect];
    box.wantsLayer = YES; box.layer.cornerRadius = 20; box.layer.masksToBounds = YES;
    box.layer.borderWidth = 1; box.layer.borderColor = (ThemeIsLight() ? HexA(0x000000, 0.1) : HexA(0xffffff, 0.09)).CGColor;
    WKWebView *web = [[WKWebView alloc] initWithFrame:NSZeroRect configuration:cfg];
    [web setValue:@NO forKey:@"drawsBackground"];
    web.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    [box addSubview:web]; [dim addSubview:box]; dim.box = box;
    [dim placeBox];
    [root addSubview:dim positioned:NSWindowAbove relativeTo:nil];
    [root addSubview:self.toolbar positioned:NSWindowAbove relativeTo:nil];   // the bar stays on top, lit: it's the preview
    objc_setAssociatedObject(self, &kCustomiserKey, dim, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    PageHearsMouse(self, NO);   // pages under the shade still get pointer moves (tracking areas ignore what covers them) and would fight over the cursor
    [web loadRequest:[NSURLRequest requestWithURL:[NSURL URLWithString:[@"iris://" stringByAppendingString:page]]]];
    dim.alphaValue = 0; box.layer.transform = CATransform3DMakeTranslation(0, -8, 0);
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext *c) { c.duration = 0.2; dim.animator.alphaValue = 1; }];
    [self.window makeFirstResponder:web];
}
- (void)closeToolbarCustomiser {
    NSView *dim = objc_getAssociatedObject(self, &kCustomiserKey);
    if (!dim) return;
    objc_setAssociatedObject(self, &kCustomiserKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    PageHearsMouse(self, YES);
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext *c) { c.duration = 0.16; dim.animator.alphaValue = 0; } completionHandler:^{ [dim removeFromSuperview]; }];
    [self.window makeFirstResponder:self.current.web.web];
}
- (void)showHistory:(id)s { [self openInternal:@"history"]; }
- (void)showBookmarks:(id)s { [self openInternal:@"bookmarks"]; }
- (void)showDownloadManager:(id)s { [self openInternal:@"downloads"]; }
// iris://settings#<section>: switch to the open settings tab (and its section), or open one
- (void)showSettingsSection:(NSString *)section {
    for (VTab *t in self.tabs) if ([t.url hasPrefix:@"iris://settings"]) {
        [self selectTab:t];
        [t.web.web evaluateJavaScript:[NSString stringWithFormat:@"location.hash='#%@'", section] completionHandler:nil];
        return;
    }
    [self newTab:[NSURL URLWithString:[@"iris://settings#" stringByAppendingString:section]] select:YES];
}
- (void)bookmarkAllTabs:(id)s {
    NSMutableArray *kids = [NSMutableArray array];
    for (VTab *t in self.tabs) if ([t.url hasPrefix:@"http"]) [kids addObject:[NSMutableDictionary dictionaryWithDictionary:@{@"name": t.title ?: @"", @"url": t.url}]];
    if (!kids.count) { [self showToast:@"No web pages open"]; return; }
    NSDateFormatter *f = [NSDateFormatter new]; f.dateStyle = NSDateFormatterMediumStyle; f.timeStyle = NSDateFormatterShortStyle;
    NSString *name = [NSString stringWithFormat:@"Tabs · %@", [f stringFromDate:NSDate.date]];
    [VBookmarks.shared.bar addObject:[NSMutableDictionary dictionaryWithDictionary:@{@"name": name, @"children": kids}]];
    [VBookmarks.shared save]; BookmarksChanged();
    [self showToast:[NSString stringWithFormat:@"Bookmarked %lu tabs in “%@”", (unsigned long)kids.count, name]];
}
@end

#pragma mark - Monolith: window buttons, the tab strip from the bottom edge

// The three window buttons, in a small glass pill at the top-left corner of the page: graphite, never coloured;
// hovering the pill shows what each one does. (The real title bar is hidden so the page reaches the top.)
@interface VLights : NSView
@property BOOL hover;
@end
@implementation VLights
- (BOOL)isFlipped { return YES; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    for (NSTrackingArea *t in self.trackingAreas.copy) [self removeTrackingArea:t];
    [self addTrackingArea:[[NSTrackingArea alloc] initWithRect:NSZeroRect options:NSTrackingMouseEnteredAndExited | NSTrackingActiveAlways | NSTrackingInVisibleRect owner:self userInfo:nil]];
}
- (void)mouseEntered:(NSEvent *)e { self.hover = YES; self.needsDisplay = YES; }
- (void)mouseExited:(NSEvent *)e { self.hover = NO; self.needsDisplay = YES; }
- (NSRect)dot:(NSInteger)i { return NSMakeRect(9 + i * 17, round((NSHeight(self.bounds) - 10) / 2), 10, 10); }
- (void)drawRect:(NSRect)r {
    NSRect b = self.bounds;
    MShadowed(^{ RoundRect(b, NSHeight(b) / 2, MGlass()); });
    ShardStroke(b, NSHeight(b) / 2, MGlassEdge(), 1);
    BOOL key = self.window.isKeyWindow;
    NSArray *glyphs = @[@"xmark", @"minus", @"plus"];
    for (NSInteger i = 0; i < 3; i++) {
        NSRect d = [self dot:i];
        NSColor *c = self.hover ? (ThemeIsLight() ? Hex(0x9a9ca2) : Hex(0x6e7178)) : (key ? (ThemeIsLight() ? Hex(0xb9bbc0) : Hex(0x3a3c42)) : (ThemeIsLight() ? Hex(0xd4d5d8) : Hex(0x2a2c30)));
        [c setFill]; [[NSBezierPath bezierPathWithOvalInRect:d] fill];
        if (self.hover) { NSImage *g = Tinted(Symbol(glyphs[i], 6, NSFontWeightBold), ThemeIsLight() ? Hex(0xffffff) : Hex(0x0a0b0d)); DrawImage(g, CenterIn(g.size, d)); }
    }
}
- (void)mouseDown:(NSEvent *)e {
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    for (NSInteger i = 0; i < 3; i++) if (NSPointInRect(p, NSInsetRect([self dot:i], -4, -6))) {
        if (i == 0) [self.window performClose:nil];
        else if (i == 1) [self.window performMiniaturize:nil];
        else [self.window toggleFullScreen:nil];
        return;
    }
    [self.window performWindowDragWithEvent:e];
}
@end

// A small picture of the page, for the tab strip. Taken while the page is still on screen.
// Tab pictures cost a render of the page, so they're taken only when they'd show something new: never of a window
// you can't see, and not again within 30 seconds of the last one of the same address (a quick switch back and forth
// reuses it). The picture is shrunk once, straight to the card's size, so drawing the strip never scales anything.
static const CGFloat kThumbW = 136, kThumbH = 88;   // the card, in points
static NSImage *ThumbFor(NSImage *src) {
    NSSize s = src.size; if (s.width <= 0 || s.height <= 0) return nil;
    CGFloat scale = NSScreen.mainScreen.backingScaleFactor ?: 2;
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:(NSInteger)(kThumbW * scale) pixelsHigh:(NSInteger)(kThumbH * scale)
                                bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
    if (!rep) return nil;
    rep.size = NSMakeSize(kThumbW, kThumbH);
    [NSGraphicsContext saveGraphicsState];
    NSGraphicsContext *ctx = [NSGraphicsContext graphicsContextWithBitmapImageRep:rep];
    NSGraphicsContext.currentContext = ctx; ctx.imageInterpolation = NSImageInterpolationHigh;
    CGFloat k = MAX(kThumbW / s.width, kThumbH / s.height);   // fill the card, cropping the overflow (top-anchored: the page's top is what you recognise)
    [src drawInRect:NSMakeRect((kThumbW - s.width * k) / 2, kThumbH - s.height * k, s.width * k, s.height * k) fromRect:NSZeroRect operation:NSCompositingOperationCopy fraction:1];
    [NSGraphicsContext restoreGraphicsState];
    NSImage *im = [[NSImage alloc] initWithSize:NSMakeSize(kThumbW, kThumbH)]; [im addRepresentation:rep];
    return im;
}
static void CaptureThumb(VTab *t) {
    WKWebView *wv = t.web.web;
    if (!wv || !wv.window || NSWidth(wv.bounds) < 60 || NSHeight(wv.bounds) < 60) return;
    if (!(wv.window.occlusionState & NSWindowOcclusionStateVisible) || wv.window.isMiniaturized) return;   // nothing new to see
    NSTimeInterval now = NSDate.date.timeIntervalSince1970;
    if (t.thumb && [t.thumbURL isEqualToString:t.url ?: @""] && now - t.thumbAt < 30) return;
    t.thumbAt = now; t.thumbURL = t.url ?: @"";
    WKSnapshotConfiguration *c = [WKSnapshotConfiguration new];
    c.snapshotWidth = @(kThumbW * 2);   // rendered at the size it's shown, not the page's
    c.rect = NSMakeRect(0, 0, NSWidth(wv.bounds), MIN(NSHeight(wv.bounds), NSWidth(wv.bounds) * kThumbH / kThumbW));
    __weak VTab *wt = t;
    [wv takeSnapshotWithConfiguration:c completionHandler:^(NSImage *im, NSError *e) {
        VTab *tt = wt; if (!im || !tt) return;
        tt.thumb = ThumbFor(im) ?: im;
        NSView *sh = tt.owner.shelf;
        if (sh && !sh.hidden) [(NSView *)[sh valueForKey:@"strip"] setNeedsDisplay:YES];   // only the pictures changed: redraw, don't rebuild the strip
    }];
}

static NSString *ShelfTime(VTab *t, BOOL current) {
    if (current) return @"now";
    if (t.hiddenAt <= 0) return @"earlier";
    NSDate *d = [NSDate dateWithTimeIntervalSince1970:t.hiddenAt];
    NSCalendar *cal = NSCalendar.currentCalendar;
    static NSDateFormatter *hm, *day;   // made once: formatters are slow to create, and every card asks on every redraw
    if (!hm) { hm = [NSDateFormatter new]; hm.dateFormat = @"HH:mm"; day = [NSDateFormatter new]; day.dateFormat = @"EEE"; }
    if ([cal isDateInToday:d]) return [hm stringFromDate:d];
    if ([cal isDateInYesterday:d]) return @"yesterday";
    return [day stringFromDate:d].lowercaseString;
}
static NSString *ShelfAgo(VTab *t) {   // how long since you looked: "now", "4m", "2h", "yesterday", "mon"
    if (t.hiddenAt <= 0) return nil;
    double s = NSDate.date.timeIntervalSince1970 - t.hiddenAt;
    if (s < 60) return @"now";
    if (s < 3600) return [NSString stringWithFormat:@"%.0fm", floor(s / 60)];
    if (s < 86400) return [NSString stringWithFormat:@"%.0fh", floor(s / 3600)];
    return ShelfTime(t, NO);
}
static NSString *ShelfMeta(VTab *t, BOOL current) {
    if (current) return @"this tab";
    if (t.audible && !t.muted) return @"playing";
    if (!t.web && !t.isHome) return @"asleep";
    if (t.isHome) return @"new tab";
    return HostOf([NSURL URLWithString:t.url ?: @""]) ?: @"";
}
static NSString *ShelfBadge(VTab *t) {   // "(3) Inbox" → 3
    NSString *ti = t.title ?: @"";
    if (![ti hasPrefix:@"("]) return nil;
    NSRange close = [ti rangeOfString:@")"]; if (close.location == NSNotFound || close.location < 2 || close.location > 6) return nil;
    NSString *n = [ti substringWithRange:NSMakeRange(1, close.location - 1)];
    return [n rangeOfCharacterFromSet:NSCharacterSet.decimalDigitCharacterSet.invertedSet].location == NSNotFound ? n : nil;
}
static void ShelfIcon(VTab *t, NSRect r, CGFloat radius) {
    RoundRect(r, radius, ThemeIsLight() ? Hex(0xe4e4e8) : Hex(0x2a2c31));
    if (t.favicon) { CGFloat s = MIN(NSWidth(r), NSHeight(r)) * 0.62; DrawImage(t.favicon, NSMakeRect(NSMidX(r) - s / 2, NSMidY(r) - s / 2, s, s)); return; }
    NSString *ti = t.title.length ? t.title : HostOf([NSURL URLWithString:t.url ?: @""]);
    NSString *l = ti.length ? [[ti substringToIndex:1] uppercaseString] : @"•";
    NSDictionary *a = @{NSFontAttributeName: UIFont(NSHeight(r) * 0.45, NSFontWeightSemibold), NSForegroundColorAttributeName: vText};
    NSSize sz = [l sizeWithAttributes:a];
    [l drawAtPoint:NSMakePoint(NSMidX(r) - sz.width / 2, NSMidY(r) - sz.height / 2) withAttributes:a];
}

@class VTabShelf;
@interface VTabShelf : NSView <NSTextFieldDelegate>
@property (weak) VWindow *owner;
@property BOOL shown, sticky;
@property (strong) NSTextField *search;
@property (strong) NSScrollView *scroll;
@property (strong) NSView *strip, *pinnedView;
@property (strong) NSButton *addBtn;
@property (strong) NSArray<VTab *> *items, *pinned;
- (void)scrollToCurrent;
@property CGFloat wantHeight;   // just tall enough for what's in it
@property CGFloat wantWidth;    // just wide enough for every tab's card (searching doesn't shrink it)
- (instancetype)initWithOwner:(VWindow *)w;
- (void)reload;
- (void)scrollToNewest;
@end

// Your tabs in the order you keep them: pinned first, then the rest; new tabs arrive at the right end, and you drag
// a card to move it. How recently you looked at a tab shows in how bright its card is, not where it sits, so
// every tab stays where your hand remembers it.
@interface VShelfStrip : NSView
@property (weak) VTabShelf *shelf;
@property NSInteger hover;
@property NSInteger btnHover;   // over a card's close (1) or pin (2) button
@property CGFloat glideTo; @property BOOL gliding;   // a mouse wheel's scroll, gliding to where it's headed
@property NSInteger kbd;             // the card the arrow keys are on (-1: none)
@property NSInteger pressIndex; @property NSPoint pressAt; @property BOOL dragging;   // a card being dragged to a new place
- (NSRect)card:(NSInteger)i;
- (void)redrawCard:(NSInteger)i;
@property NSInteger pinnedCount;   // the first cards are your pinned tabs, set apart from the timeline
@end
static const CGFloat kCardW = 136, kCardH = 88, kCardGap = 12, kCardTop = 30;
@implementation VShelfStrip
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }   // one click works even while another app is in front
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    for (NSTrackingArea *t in self.trackingAreas.copy) [self removeTrackingArea:t];
    [self addTrackingArea:[[NSTrackingArea alloc] initWithRect:NSZeroRect options:NSTrackingMouseMoved | NSTrackingMouseEnteredAndExited | NSTrackingActiveAlways | NSTrackingInVisibleRect owner:self userInfo:nil]];
}
static const CGFloat kRowPitch = 88 + 26 + 10;   // vertical: a card, its line underneath, a gap
- (NSRect)card:(NSInteger)i {
    CGFloat extra = self.pinnedCount > 0 && i >= self.pinnedCount ? 22 : 0;
    if (ShelfVertical()) return NSMakeRect(round((NSWidth(self.bounds) - kCardW) / 2), (self.pinnedCount > 0 ? kCardTop : 8) + i * kRowPitch + extra, kCardW, kCardH);
    return NSMakeRect(6 + i * (kCardW + kCardGap) + extra, kCardTop, kCardW, kCardH);
}
// Close and pin: 28 pt discs inside the card's corner, and each answers a little beyond its edge (a 36 pt target).
- (NSRect)closeRect:(NSInteger)i { NSRect c = [self card:i]; return NSMakeRect(NSMaxX(c) - 34, NSMinY(c) + 6, 28, 28); }
- (NSRect)pinRect:(NSInteger)i { NSRect c = [self card:i]; return NSMakeRect(NSMaxX(c) - 66, NSMinY(c) + 6, 28, 28); }
- (NSInteger)buttonAt:(NSPoint)p card:(NSInteger)i {
    if (i < 0 || i >= (NSInteger)self.shelf.items.count) return 0;
    NSRect cr = [self closeRect:i], pr = [self pinRect:i];
    if (NSPointInRect(p, NSMakeRect(NSMinX(cr) - 2, NSMinY(cr) - 5, NSWidth(cr) + 7, NSHeight(cr) + 9))) return 1;   // up to the card's edge
    if (NSPointInRect(p, NSMakeRect(NSMinX(pr) - 4, NSMinY(pr) - 5, NSWidth(pr) + 6, NSHeight(pr) + 9))) return 2;
    return 0;
}
- (NSInteger)indexAt:(NSPoint)p {   // items.count = the New tab card at the end
    for (NSInteger i = 0; i <= (NSInteger)self.shelf.items.count; i++) { NSRect c = [self card:i]; c.size.height += 26; if (NSPointInRect(p, NSInsetRect(c, -4, -4))) return i; }
    return -1;
}
- (void)mouseMoved:(NSEvent *)e {
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    NSInteger h = [self indexAt:p], b = [self buttonAt:p card:h];
    if (h != self.hover || b != self.btnHover) { [self redrawCard:self.hover]; self.hover = h; self.btnHover = b; [self redrawCard:h]; }
}
- (void)redrawCard:(NSInteger)i {   // a card, its ring and its label: the rest of the strip stays as it is
    if (i < 0) return;
    NSRect c = [self card:i];
    [self setNeedsDisplayInRect:NSMakeRect(NSMinX(c) - 6, NSMinY(c) - 6, NSWidth(c) + 12, NSHeight(c) + 34)];
}
- (void)mouseExited:(NSEvent *)e { [self redrawCard:self.hover]; self.hover = -1; self.btnHover = 0; }
- (void)drawRect:(NSRect)dirty {
    NSArray<VTab *> *items = self.shelf.items;
    VWindow *w = self.shelf.owner;
    NSColor *accent = PickColor(w.isPrivate, w.profile);
    {   // the last card opens a new tab
        NSRect c = [self card:(NSInteger)items.count]; BOOL hov = self.hover == (NSInteger)items.count;
        RoundRect(c, 12, hov ? (ThemeIsLight() ? HexA(0x000000, 0.08) : Hex(0x24262b)) : (ThemeIsLight() ? HexA(0x000000, 0.04) : Hex(0x1a1c20)));
        ShardStroke(c, 12, hov ? [vText colorWithAlphaComponent:0.3] : MGlassEdge(), 1);
        NSImage *plus = Tinted(Symbol(@"plus", 11, NSFontWeightSemibold), vText);
        NSDictionary *a = @{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium), NSForegroundColorAttributeName: vText};
        NSSize sz = [@"New tab" sizeWithAttributes:a]; CGFloat w = plus.size.width + 6 + sz.width, x = round(NSMidX(c) - w / 2);
        DrawImage(plus, NSMakeRect(x, round(NSMidY(c) - plus.size.height / 2), plus.size.width, plus.size.height));
        [@"New tab" drawAtPoint:NSMakePoint(x + plus.size.width + 6, round(NSMidY(c) - sz.height / 2)) withAttributes:a];
    }
    if (!items.count) return;
    NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.lineBreakMode = NSLineBreakByTruncatingTail;
    // recency as brightness: the tab you looked at most recently is full strength, the longest-unvisited ~40% dimmer
    NSMutableArray<VTab *> *byRecent = [NSMutableArray array];
    for (VTab *t in items) if (!t.pinned && t != w.current && t.openedFresh <= 0) [byRecent addObject:t];
    [byRecent sortUsingComparator:^NSComparisonResult(VTab *x, VTab *y) { return x.hiddenAt > y.hiddenAt ? NSOrderedAscending : x.hiddenAt < y.hiddenAt ? NSOrderedDescending : NSOrderedSame; }];
    for (NSInteger i = 0; i < (NSInteger)items.count; i++) {
        NSRect c = [self card:i];
        if (!NSIntersectsRect(NSInsetRect(c, -10, -10), dirty) && !NSIntersectsRect(NSMakeRect(NSMinX(c), NSMaxY(c), kCardW, 30), dirty)) continue;
        VTab *t = items[(NSUInteger)i];
        BOOL cur = t == w.current, hov = i == self.hover, kb = i == self.kbd, asleep = !t.web && !t.isHome;
        NSUInteger rank = [byRecent indexOfObjectIdenticalTo:t];
        CGFloat fade = rank == NSNotFound || byRecent.count < 2 ? 1 : 1 - 0.4 * (CGFloat)rank / (CGFloat)(byRecent.count - 1);
        CGFloat alpha = (hov || kb) ? 1 : MIN(fade, asleep ? 0.6 : 1);
        [NSGraphicsContext saveGraphicsState];
        NSBezierPath *clip = [NSBezierPath bezierPathWithRoundedRect:c xRadius:12 yRadius:12];
        [clip addClip];
        if (t.thumb) { if (NSEqualSizes(t.thumb.size, c.size)) [t.thumb drawInRect:c fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1 respectFlipped:YES hints:nil]; else DrawImageFill(t.thumb, c); }
        else { [(ThemeIsLight() ? Hex(0xececef) : Hex(0x1e2025)) setFill]; NSRectFillUsingOperation(c, NSCompositingOperationSourceOver); ShelfIcon(t, NSMakeRect(NSMidX(c) - 16, NSMinY(c) + 14, 32, 32), 9); }
        // the name on the card itself: site icon and title over a soft shade at the bottom
        NSGradient *shade = [[NSGradient alloc] initWithStartingColor:[NSColor colorWithWhite:0 alpha:0] endingColor:[NSColor colorWithWhite:0 alpha:0.78]];
        [shade drawInRect:NSMakeRect(NSMinX(c), NSMaxY(c) - 38, NSWidth(c), 38) angle:90];
        CGFloat tx = NSMinX(c) + 9;
        if (t.favicon) { DrawImage(t.favicon, NSMakeRect(tx, NSMaxY(c) - 22, 14, 14)); tx += 20; }
        NSString *title = t.isHome ? @"New Tab" : (t.title.length ? t.title : t.url ?: @"");
        [title drawInRect:NSMakeRect(tx, NSMaxY(c) - 23, NSMaxX(c) - tx - 8, 16) withAttributes:@{NSFontAttributeName: UIFont(11.5, NSFontWeightMedium), NSForegroundColorAttributeName: NSColor.whiteColor, NSParagraphStyleAttributeName: ps}];
        if (alpha < 1) { [[vBg colorWithAlphaComponent:1 - alpha] setFill]; NSRectFillUsingOperation(c, NSCompositingOperationSourceOver); }
        [NSGraphicsContext restoreGraphicsState];
        if (cur && !w.isPrivate) ApertureStroke(NSInsetRect(c, -3, -3), 14, 1.75);
        else if (cur) ShardStroke(NSInsetRect(c, -3, -3), 14, accent, 1.5);
        else if (kb) ShardStroke(NSInsetRect(c, -3, -3), 14, [accent colorWithAlphaComponent:0.7], 1.5);
        else if (hov) ShardStroke(NSInsetRect(c, -3, -3), 14, [vText colorWithAlphaComponent:0.35], 1);
        else ShardStroke(c, 12, MGlassEdge(), 1);
        // top-left badges: its ⌘-number, pinned, playing
        CGFloat bx = NSMinX(c) + 7;
        if (i < 9 || i == (NSInteger)items.count - 1) {
            NSInteger n = i < 8 ? i + 1 : (i == (NSInteger)items.count - 1 ? 9 : 0);
            if (n > 0 && !(i == 8 && i != (NSInteger)items.count - 1)) {
                NSString *k = [NSString stringWithFormat:@"⌘%ld", (long)n];
                NSDictionary *ka = @{NSFontAttributeName: MMono(10, NSFontWeightMedium), NSForegroundColorAttributeName: [NSColor colorWithWhite:1 alpha:0.9]};
                NSSize ks = [k sizeWithAttributes:ka];
                NSRect kr = NSMakeRect(bx, NSMinY(c) + 7, ceil(ks.width) + 10, 20);
                RoundRect(kr, 10, HexA(0x0a0b0d, 0.72));
                [k drawAtPoint:NSMakePoint(NSMinX(kr) + 5, NSMinY(kr) + round((20 - ks.height) / 2)) withAttributes:ka];
                bx = NSMaxX(kr) + 4;
            }
        }
        if (t.pinned) {
            NSRect pb = NSMakeRect(bx, NSMinY(c) + 7, 20, 20);
            [HexA(0x0a0b0d, 0.8) setFill]; [[NSBezierPath bezierPathWithOvalInRect:pb] fill];
            NSImage *pn = Tinted(Symbol(@"pin.fill", 8.5, NSFontWeightSemibold), Hex(0xe7e8eb)); DrawImage(pn, CenterIn(pn.size, pb));
            bx += 24;
        }
        if (t.audible && !t.muted) {   // playing: three small bars
            NSRect bg = NSMakeRect(bx, NSMinY(c) + 7, 26, 20);
            RoundRect(bg, 10, HexA(0x0a0b0d, 0.8));
            CGFloat hs[3] = {6, 11, 8};
            for (int k = 0; k < 3; k++) RoundRect(NSMakeRect(NSMinX(bg) + 8 + k * 4, NSMaxY(bg) - 5 - hs[k], 2, hs[k]), 1, accent);
        }
        if (hov && !self.dragging) {
            NSRect cr = [self closeRect:i], pr = [self pinRect:i];
            NSArray *btns = @[@[[NSValue valueWithRect:cr], @"xmark", @10.5, @1], @[[NSValue valueWithRect:pr], t.pinned ? @"pin.slash" : @"pin", @11.5, @2]];
            for (NSArray *b in btns) {
                NSRect r = [b[0] rectValue]; BOOL on = self.btnHover == [b[3] integerValue];
                NSBezierPath *disc = [NSBezierPath bezierPathWithOvalInRect:r];
                [HexA(0x0a0b0d, on ? 0.92 : 0.72) setFill]; [disc fill];   // dark glass, firmer under the pointer
                [[NSColor colorWithWhite:1 alpha:on ? 0.28 : 0.14] setStroke]; NSBezierPath *rim = [NSBezierPath bezierPathWithOvalInRect:NSInsetRect(r, 0.5, 0.5)]; rim.lineWidth = 1; [rim stroke];
                NSImage *ic = Tinted(Symbol(b[1], [b[2] doubleValue], NSFontWeightSemibold), on ? NSColor.whiteColor : Hex(0xd6d8dc));
                DrawImage(ic, CenterIn(ic.size, r));
            }
        }
        // under the card, one quiet line: where it is and how long since you looked
        BOOL fresh = t.openedFresh > 0 && !cur;
        NSString *where = ShelfMeta(t, cur), *ago = cur || fresh ? nil : ShelfAgo(t);
        NSString *meta = fresh ? @"new · not opened yet" : t.pinned && !cur ? (ago ? [@"pinned · " stringByAppendingString:ago] : @"pinned") : ago && ![where isEqualToString:@"playing"] ? [NSString stringWithFormat:@"%@ · %@", where, ago] : where;
        [meta drawInRect:NSMakeRect(NSMinX(c) + 1, NSMaxY(c) + 7, kCardW - 2, 14) withAttributes:@{NSFontAttributeName: MMono(10.5, NSFontWeightRegular), NSForegroundColorAttributeName: fresh ? vEmber : cur ? vDim : vFaint, NSParagraphStyleAttributeName: ps}];
    }
    if (self.pinnedCount > 0) {   // the pinned group: labelled, and a hairline before the rest
        [@"PINNED" drawAtPoint:NSMakePoint(NSMinX([self card:0]), kCardTop - 22) withAttributes:@{NSFontAttributeName: MMono(10, NSFontWeightMedium), NSForegroundColorAttributeName: vFaint, NSKernAttributeName: @1.2}];
        if (self.pinnedCount < (NSInteger)items.count) {
            NSRect nx = [self card:self.pinnedCount];
            [[vText colorWithAlphaComponent:0.1] setFill];
            Blend(ShelfVertical() ? NSMakeRect(NSMinX(nx), NSMinY(nx) - 21, kCardW, 1) : NSMakeRect(NSMinX(nx) - 17, kCardTop, 1, kCardH + 22));
        }
    }
}
// Press, then either let go (open, close or pin) or drag the card along to put it somewhere else.
- (void)mouseDown:(NSEvent *)e {
    self.pressAt = [self convertPoint:e.locationInWindow fromView:nil];
    self.pressIndex = [self indexAt:self.pressAt]; self.dragging = NO;
}
- (void)mouseDragged:(NSEvent *)e {
    NSInteger from = self.pressIndex; NSArray<VTab *> *items = self.shelf.items;
    if (from < 0 || from >= (NSInteger)items.count || self.shelf.search.stringValue.length) return;   // not while searching: only matches show
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    BOOL v = ShelfVertical();   // along the strip: across when it's at the bottom, down when it's at a side
    CGFloat at = v ? p.y : p.x, was = v ? self.pressAt.y : self.pressAt.x;
    if (!self.dragging && fabs(at - was) < 6) return;
    self.dragging = YES;
    VTab *t = items[(NSUInteger)from];
    // the slot under the pointer, within the card's own group (pinned stay with pinned)
    NSInteger lo = t.pinned ? 0 : self.pinnedCount, hi = t.pinned ? self.pinnedCount - 1 : (NSInteger)items.count - 1, to = from;
    CGFloat (^start)(NSRect) = ^CGFloat(NSRect c) { return v ? NSMinY(c) : NSMinX(c); };
    CGFloat (^end)(NSRect) = ^CGFloat(NSRect c) { return v ? NSMinY(c) + kRowPitch - 10 : NSMaxX(c); };
    CGFloat half = (v ? 10 : kCardGap) / 2;
    for (NSInteger k = lo; k <= hi; k++) { NSRect c = [self card:k]; if (at >= start(c) - half && at < end(c) + half) { to = k; break; } }
    if (at < start([self card:lo])) to = lo;
    if (at > end([self card:hi])) to = hi;
    if (to == from) return;
    VWindow *w = self.shelf.owner;
    NSUInteger dest = [w.tabs indexOfObjectIdenticalTo:items[(NSUInteger)to]];
    if (dest == NSNotFound) return;
    [w moveTab:t to:(NSInteger)dest];
    [self.shelf reload];
    self.pressIndex = to; self.hover = to;
    [self autoscroll:e];
}
- (void)mouseUp:(NSEvent *)e {
    NSInteger i = self.pressIndex; self.pressIndex = -1;
    if (self.dragging) { self.dragging = NO; self.needsDisplay = YES; return; }
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    if (i < 0 || [self indexAt:p] != i) return;
    VWindow *w = self.shelf.owner;
    if (i == (NSInteger)self.shelf.items.count) { [w showShelf:NO]; [w newTab:nil select:YES]; [NSApp activateIgnoringOtherApps:YES]; [w.window makeKeyAndOrderFront:nil]; return; }
    VTab *t = self.shelf.items[(NSUInteger)i];
    NSInteger b = [self buttonAt:p card:i];
    if (b == 1) { self.btnHover = 0; [w closeTab:t]; [self.shelf reload]; return; }
    if (b == 2) { self.btnHover = 0; [w togglePin:t]; [self.shelf reload]; return; }
    [w showShelf:NO];
    [w selectTab:t];
    [NSApp activateIgnoringOtherApps:YES]; [w.window makeKeyAndOrderFront:nil];
}
- (void)otherMouseDown:(NSEvent *)e {   // middle click closes
    NSInteger i = [self indexAt:[self convertPoint:e.locationInWindow fromView:nil]];
    if (i >= 0 && i < (NSInteger)self.shelf.items.count) { [self.shelf.owner closeTab:self.shelf.items[(NSUInteger)i]]; [self.shelf reload]; }
}
- (void)rightMouseDown:(NSEvent *)e {
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    NSInteger i = [self indexAt:p];
    if (i >= 0 && i < (NSInteger)self.shelf.items.count) [self.shelf.owner tabMenu:self.shelf.items[(NSUInteger)i] at:p inView:self];
}
// One path for every kind of scroll, so nothing fights over the position: sideways or up-and-down both run along
// the timeline. A trackpad follows your fingers exactly, momentum included (macOS sends the glide as events);
// a mouse wheel's notches become a short eased glide instead of jumps.
- (void)scrollWheel:(NSEvent *)e {
    NSScrollView *sv = self.enclosingScrollView; NSClipView *cv = sv.contentView; if (!cv) return;
    CGFloat dx = e.scrollingDeltaX, dy = e.scrollingDeltaY;
    BOOL v = ShelfVertical();
    CGFloat d = v ? (fabs(dy) >= fabs(dx) ? dy : dx) : (fabs(dx) >= fabs(dy) ? dx : dy);
    if (d == 0) return;
    CGFloat maxO = v ? MAX(0, NSHeight(self.frame) - NSHeight(cv.bounds)) : MAX(0, NSWidth(self.frame) - NSWidth(cv.bounds));
    CGFloat cur = v ? cv.bounds.origin.y : cv.bounds.origin.x;
    if (e.hasPreciseScrollingDeltas) {
        if (self.gliding) { self.gliding = NO; [cv.layer removeAllAnimations]; }
        CGFloat o = round(MAX(0, MIN(maxO, cur - d)));
        [cv setBoundsOrigin:v ? NSMakePoint(cv.bounds.origin.x, o) : NSMakePoint(o, cv.bounds.origin.y)]; [sv reflectScrolledClipView:cv];
        return;
    }
    CGFloat from = self.gliding ? self.glideTo : cur;
    CGFloat to = round(MAX(0, MIN(maxO, from - d * 26)));
    self.glideTo = to; self.gliding = YES;
    __weak VShelfStrip *ws = self;
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext *c) {
        c.duration = 0.24; c.timingFunction = [CAMediaTimingFunction functionWithControlPoints:0.2 :0.7 :0.3 :1];
        [cv.animator setBoundsOrigin:v ? NSMakePoint(cv.bounds.origin.x, to) : NSMakePoint(to, cv.bounds.origin.y)];
    } completionHandler:^{
        VShelfStrip *me = ws; if (!me) return;
        [sv reflectScrolledClipView:cv];
        if (me.glideTo == to) me.gliding = NO;
    }];
}
@end

// Pinned tabs: always there, so they sit apart from the timeline as square tiles.
@interface VShelfPinned : NSView
@property (weak) VTabShelf *shelf;
@property NSInteger hover;
@end
@implementation VShelfPinned
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }   // one click works even while another app is in front
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (NSInteger)cols { return self.shelf.pinned.count > 6 ? 3 : 2; }
- (NSRect)tile:(NSInteger)i {
    NSInteger cols = [self cols], rows = ((NSInteger)self.shelf.pinned.count + cols - 1) / cols;
    CGFloat h = 26 + MIN(rows, 3) * 66 - 8, top = round((NSHeight(self.bounds) - h) / 2) + 26;
    return NSMakeRect((i % cols) * 66, top + (i / cols) * 66, 58, 58);
}
+ (CGFloat)widthFor:(NSUInteger)n { return n == 0 ? 0 : (n > 6 ? 3 : 2) * 66 - 8; }
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    for (NSTrackingArea *t in self.trackingAreas.copy) [self removeTrackingArea:t];
    [self addTrackingArea:[[NSTrackingArea alloc] initWithRect:NSZeroRect options:NSTrackingMouseMoved | NSTrackingMouseEnteredAndExited | NSTrackingActiveAlways | NSTrackingInVisibleRect owner:self userInfo:nil]];
}
- (NSInteger)indexAt:(NSPoint)p { for (NSInteger i = 0; i < (NSInteger)self.shelf.pinned.count; i++) if (NSPointInRect(p, [self tile:i])) return i; return -1; }
- (void)mouseMoved:(NSEvent *)e { NSInteger h = [self indexAt:[self convertPoint:e.locationInWindow fromView:nil]]; if (h != self.hover) { self.hover = h; self.needsDisplay = YES; } }
- (void)mouseExited:(NSEvent *)e { self.hover = -1; self.needsDisplay = YES; }
- (void)drawRect:(NSRect)dirty {
    NSArray<VTab *> *ps = self.shelf.pinned; if (!ps.count) return;
    VWindow *w = self.shelf.owner;
    NSRect first = [self tile:0];
    [@"PINNED" drawAtPoint:NSMakePoint(0, NSMinY(first) - 24) withAttributes:@{NSFontAttributeName: MMono(10, NSFontWeightMedium), NSForegroundColorAttributeName: vFaint, NSKernAttributeName: @1.2}];
    for (NSInteger i = 0; i < (NSInteger)ps.count && i < [self cols] * 3; i++) {
        VTab *t = ps[(NSUInteger)i]; NSRect r = [self tile:i];
        RoundRect(r, 14, MCard());
        if (t == w.current) { if (w.isPrivate) ShardStroke(NSInsetRect(r, -3, -3), 16, vText, 1.5); else ApertureStroke(NSInsetRect(r, -3, -3), 16, 1.75); }
        else if (i == self.hover) ShardStroke(NSInsetRect(r, -3, -3), 16, [vText colorWithAlphaComponent:0.35], 1);
        ShelfIcon(t, NSMakeRect(NSMidX(r) - 14, NSMidY(r) - 14, 28, 28), 9);
        NSString *b = ShelfBadge(t);
        if (b) {
            NSDictionary *a = @{NSFontAttributeName: MMono(9.5, NSFontWeightSemibold), NSForegroundColorAttributeName: vBg};
            NSSize sz = [b sizeWithAttributes:a];
            NSRect br = NSMakeRect(NSMaxX(r) - 6 - MAX(16, sz.width + 8), NSMinY(r) + 6, MAX(16, sz.width + 8), 16);
            RoundRect(br, 8, vText);
            [b drawAtPoint:NSMakePoint(NSMidX(br) - sz.width / 2, NSMinY(br) + (16 - sz.height) / 2) withAttributes:a];
        }
        if (t.audible && !t.muted) { NSImage *sp = Tinted(Symbol(@"speaker.wave.2.fill", 8, NSFontWeightBold), vDim); DrawImage(sp, NSMakeRect(NSMinX(r) + 6, NSMaxY(r) - 6 - sp.size.height, sp.size.width, sp.size.height)); }
    }
}
- (void)mouseDown:(NSEvent *)e {
    NSInteger i = [self indexAt:[self convertPoint:e.locationInWindow fromView:nil]]; if (i < 0) return;
    VWindow *w = self.shelf.owner; VTab *t = self.shelf.pinned[(NSUInteger)i];
    [w showShelf:NO]; [w selectTab:t];
    [NSApp activateIgnoringOtherApps:YES]; [w.window makeKeyAndOrderFront:nil];
}
- (void)rightMouseDown:(NSEvent *)e {
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    NSInteger i = [self indexAt:p];
    if (i >= 0) [self.shelf.owner tabMenu:self.shelf.pinned[(NSUInteger)i] at:p inView:self];
}
@end

@interface VShelfButton : NSButton
@end
@implementation VShelfButton
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (void)drawRect:(NSRect)r {
    RoundRect(self.bounds, NSHeight(self.bounds) / 2, self.isHighlighted ? [vText colorWithAlphaComponent:0.16] : (ThemeIsLight() ? HexA(0x000000, 0.07) : Hex(0x24262b)));
    NSImage *plus = Tinted(Symbol(@"plus", 10, NSFontWeightSemibold), vText);
    NSDictionary *a = @{NSFontAttributeName: UIFont(12, NSFontWeightMedium), NSForegroundColorAttributeName: vText};
    NSSize sz = [self.title sizeWithAttributes:a];
    CGFloat w = plus.size.width + 6 + sz.width, x = round((NSWidth(self.bounds) - w) / 2);
    DrawImage(plus, NSMakeRect(x, round((NSHeight(self.bounds) - plus.size.height) / 2), plus.size.width, plus.size.height));
    [self.title drawAtPoint:NSMakePoint(x + plus.size.width + 6, round((NSHeight(self.bounds) - sz.height) / 2)) withAttributes:a];
}
@end

@implementation VTabShelf
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }   // one click works even while another app is in front
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (instancetype)initWithOwner:(VWindow *)w {
    if (!(self = [super initWithFrame:NSMakeRect(0, 0, 900, 300)])) return nil;
    self.owner = w; self.hidden = YES;
    self.wantsLayer = YES;
    NSTextField *f = [[NSTextField alloc] initWithFrame:NSZeroRect];
    f.bezeled = NO; f.bordered = NO; f.drawsBackground = NO; f.focusRingType = NSFocusRingTypeNone;
    f.font = UIFont(12.5, NSFontWeightRegular); f.textColor = vText; f.delegate = self;
    f.placeholderAttributedString = [[NSAttributedString alloc] initWithString:@"Find a tab" attributes:@{NSFontAttributeName: UIFont(12.5, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint}];
    f.cell.usesSingleLineMode = YES; f.cell.scrollable = YES;
    self.search = f; [self addSubview:f];
    VShelfButton *nb = [[VShelfButton alloc] initWithFrame:NSZeroRect];
    nb.bordered = NO; nb.title = @"New tab"; nb.target = self; nb.action = @selector(newTab:);
    self.addBtn = nb; [self addSubview:nb];
    VShelfPinned *pv = [[VShelfPinned alloc] initWithFrame:NSZeroRect]; pv.shelf = self; pv.hover = -1;
    self.pinnedView = pv; [self addSubview:pv];
    VShelfStrip *st = [[VShelfStrip alloc] initWithFrame:NSZeroRect]; st.shelf = self; st.hover = -1; st.kbd = -1; st.pressIndex = -1;
    self.strip = st;
    NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSZeroRect];
    sv.drawsBackground = NO; sv.hasHorizontalScroller = YES; sv.hasVerticalScroller = NO; sv.autohidesScrollers = YES;
    sv.scrollerStyle = NSScrollerStyleOverlay; sv.borderType = NSNoBorder; sv.horizontalScrollElasticity = NSScrollElasticityNone;
    sv.wantsLayer = YES;   // scrolled by moving layers, with the cards drawn in tiles, not redrawn whole every frame
    sv.documentView = st;
    self.scroll = sv; [self addSubview:sv];
    return self;
}
- (void)newTab:(id)s { [self.owner showShelf:NO]; [self.owner newTab:nil select:YES]; }
- (void)scrollWheel:(NSEvent *)e { [self.strip scrollWheel:e]; }   // scrolling anywhere on the strip moves the tabs, never the page behind
- (void)controlTextDidChange:(NSNotification *)n { self.sticky = YES; [self reload]; }
- (BOOL)control:(NSControl *)c textView:(NSTextView *)tv doCommandBySelector:(SEL)sel {
    VShelfStrip *st = (VShelfStrip *)self.strip;
    BOOL typing = self.search.stringValue.length > 0;
    BOOL vert = ShelfVertical();
    if (vert && (sel == @selector(moveUp:) || sel == @selector(moveDown:))) sel = sel == @selector(moveUp:) ? @selector(moveLeft:) : @selector(moveRight:);   // down the side: up and down walk them
    if ((sel == @selector(moveLeft:) || sel == @selector(moveRight:)) && (!typing || st.kbd >= 0 || vert)) {   // arrows walk the cards
        NSInteger n = (NSInteger)self.items.count; if (!n) return YES;
        NSInteger k = st.kbd < 0 ? [self.items indexOfObjectIdenticalTo:self.owner.current] : st.kbd;
        if (k == NSNotFound || k < 0) k = 0;
        k = MAX(0, MIN(n - 1, k + (sel == @selector(moveRight:) ? 1 : -1)));
        [st redrawCard:st.kbd]; st.kbd = k; [st redrawCard:k];
        [st scrollRectToVisible:NSInsetRect([st card:k], -20, 0)];
        return YES;
    }
    if (sel == @selector(insertNewline:)) {   // Return opens the card the arrows are on, or the first match
        VTab *t = st.kbd >= 0 && st.kbd < (NSInteger)self.items.count ? self.items[(NSUInteger)st.kbd] : (typing ? self.items.firstObject : nil);
        if (t) { [self.owner showShelf:NO]; [self.owner selectTab:t]; }
        return YES;
    }
    if (sel == @selector(cancelOperation:)) { [self.owner showShelf:NO]; return YES; }
    return NO;
}
- (void)reload {
    VWindow *w = self.owner;
    NSString *q = self.search.stringValue.lowercaseString ?: @"";
    NSMutableArray *pins = [NSMutableArray array], *rest = [NSMutableArray array];
    for (VTab *t in w.tabs) {
        if (q.length && ![(t.title ?: @"").lowercaseString containsString:q] && ![(t.url ?: @"").lowercaseString containsString:q]) continue;
        [(t.pinned ? pins : rest) addObject:t];
    }
    NSMutableArray *items = [NSMutableArray arrayWithArray:pins]; [items addObjectsFromArray:rest];   // the order you keep them in
    self.items = items; self.pinned = pins;
    ((VShelfStrip *)self.strip).pinnedCount = (NSInteger)pins.count;
    VShelfStrip *st = (VShelfStrip *)self.strip; if (st.kbd >= (NSInteger)items.count) st.kbd = -1;
    CGFloat want = 54 + 150 + 8;
    BOOL anyPin = NO; for (VTab *t in w.tabs) if (t.pinned) { anyPin = YES; break; }
    CGFloat wantW = 16 + 12 + (w.tabs.count + 1) * (kCardW + kCardGap) + (anyPin ? 22 : 0) + 16;
    if (ShelfVertical()) {   // a column: header, every card stacked, the count at the foot
        wantW = kCardW + 48;
        want = 84 + (anyPin ? kCardTop + 22 : 8) + (w.tabs.count + 1) * kRowPitch + 34;
    }
    if (fabs(want - self.wantHeight) > 0.5 || fabs(wantW - self.wantWidth) > 0.5) {
        self.wantHeight = want; self.wantWidth = wantW;
        if (self.shown) self.frame = [self.owner shelfFrame];
    }
    [self layoutShelf];
    self.needsDisplay = YES; self.strip.needsDisplay = YES; self.pinnedView.needsDisplay = YES;
}
- (void)layoutShelf {
    CGFloat W = NSWidth(self.bounds), H = NSHeight(self.bounds);
    BOOL vert = ShelfVertical();
    self.scroll.hasHorizontalScroller = !vert; self.scroll.hasVerticalScroller = vert;
    self.scroll.verticalScrollElasticity = NSScrollElasticityNone;
    if (vert) {
        self.search.frame = NSMakeRect(28, 51, W - 56, 17);
        self.addBtn.hidden = YES; self.pinnedView.hidden = YES;
        self.scroll.frame = NSMakeRect(0, 84, W, MAX(40, H - 84 - 34));
        CGFloat docH = MAX(NSHeight(self.scroll.contentView.bounds), (self.pinned.count ? kCardTop + 22 : 8) + (self.items.count + 1) * kRowPitch);
        [self.strip setFrameSize:NSMakeSize(NSWidth(self.scroll.contentView.bounds), docH)];
        return;
    }
    CGFloat sx = 260;
    self.search.frame = NSMakeRect(84 + 12, 19, 214, 17);
    self.addBtn.hidden = YES;   // New tab is the last card in the strip
    CGFloat pw = 0;   // pinned tabs are full cards at the start of the strip now
    self.pinnedView.hidden = pw == 0;
    self.pinnedView.frame = NSMakeRect(22, 54, pw, H - 62);
    sx = pw > 0 ? 22 + pw + 41 : 16;
    self.scroll.frame = NSMakeRect(sx, 54, W - sx - 16, H - 62);   // H follows wantHeight
    CGFloat docW = MAX(NSWidth(self.scroll.contentView.bounds), 12 + (self.items.count + 1) * (kCardW + kCardGap) + (self.pinned.count ? 22 : 0));
    [self.strip setFrameSize:NSMakeSize(docW, NSHeight(self.scroll.contentView.bounds))];
}
- (void)setFrameSize:(NSSize)s { [super setFrameSize:s]; [self layoutShelf]; }
- (void)scrollToCurrent {   // the tab you're on, in view
    VShelfStrip *st = (VShelfStrip *)self.strip;
    NSUInteger i = [self.items indexOfObjectIdenticalTo:self.owner.current];
    if (i == NSNotFound) { [self scrollToNewest]; return; }
    NSClipView *cv = self.scroll.contentView; NSRect c = [st card:(NSInteger)i];
    if (ShelfVertical()) {
        CGFloat y = MAX(0, MIN(NSHeight(st.frame) - NSHeight(cv.bounds), NSMidY(c) - NSHeight(cv.bounds) / 2));
        [cv scrollToPoint:NSMakePoint(0, round(y))]; [self.scroll reflectScrolledClipView:cv]; return;
    }
    CGFloat x = MAX(0, MIN(NSWidth(st.frame) - NSWidth(cv.bounds), NSMidX(c) - NSWidth(cv.bounds) / 2));
    [cv scrollToPoint:NSMakePoint(round(x), 0)]; [self.scroll reflectScrolledClipView:cv];
}
- (void)scrollToNewest {
    NSClipView *cv = self.scroll.contentView;
    if (ShelfVertical()) { [cv scrollToPoint:NSMakePoint(0, MAX(0, NSHeight(self.strip.frame) - NSHeight(cv.bounds)))]; [self.scroll reflectScrolledClipView:cv]; return; }
    [cv scrollToPoint:NSMakePoint(MAX(0, NSWidth(self.strip.frame) - NSWidth(cv.bounds)), 0)];
    [self.scroll reflectScrolledClipView:cv];
}
- (void)drawRect:(NSRect)dirty {
    NSRect b = NSInsetRect(self.bounds, 0.5, 0.5);
    NSInteger side = ShelfSide();
    if (side) {   // a column out of the side edge: rounded only on the inner corners
        NSRect body = side == 1 ? NSMakeRect(NSMinX(b) - 40, NSMinY(b), NSWidth(b) + 40, NSHeight(b)) : NSMakeRect(NSMinX(b), NSMinY(b), NSWidth(b) + 40, NSHeight(b));
        RoundRect(body, 22, ThemeIsLight() ? Hex(0xf6f6f4) : Hex(0x111215));
        [@"TABS" drawAtPoint:NSMakePoint(24, 21) withAttributes:@{NSFontAttributeName: MMono(11, NSFontWeightMedium), NSForegroundColorAttributeName: vDim, NSKernAttributeName: @1.3}];
        RoundRect(NSMakeRect(16, 44, NSWidth(self.bounds) - 32, 30), 15, ThemeIsLight() ? HexA(0x000000, 0.05) : Hex(0x1a1c20));
        NSUInteger sleeping = 0; for (VTab *t in self.owner.tabs) if (!t.web && !t.isHome) sleeping++;
        NSString *cnt = [NSString stringWithFormat:@"%@%lu open%@", self.pinned.count ? [NSString stringWithFormat:@"%lu pinned · ", (unsigned long)self.pinned.count] : @"", (unsigned long)(self.items.count - self.pinned.count), sleeping ? [NSString stringWithFormat:@" · %lu asleep", (unsigned long)sleeping] : @""];
        NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.lineBreakMode = NSLineBreakByTruncatingTail; ps.alignment = NSTextAlignmentCenter;
        [cnt drawInRect:NSMakeRect(16, NSHeight(self.bounds) - 25, NSWidth(self.bounds) - 32, 14) withAttributes:@{NSFontAttributeName: MMono(10.5, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint, NSParagraphStyleAttributeName: ps}];
        [[vText colorWithAlphaComponent:0.07] setFill]; Blend(NSMakeRect(16, NSHeight(self.bounds) - 34, NSWidth(self.bounds) - 32, 1));
        return;
    }
    RoundRect(NSMakeRect(NSMinX(b), NSMinY(b), NSWidth(b), NSHeight(b) + 40), 22, ThemeIsLight() ? Hex(0xf6f6f4) : Hex(0x111215));   // rounded on top only: it rises out of the edge   // solid: the page never shows through ShardStroke(b, 22, ThemeIsLight() ? HexA(0x000000, 0.1) : HexA(0xffffff, 0.1), 1);
    [@"TABS" drawAtPoint:NSMakePoint(24, 21) withAttributes:@{NSFontAttributeName: MMono(11, NSFontWeightMedium), NSForegroundColorAttributeName: vDim, NSKernAttributeName: @1.3}];
    NSRect sr = NSMakeRect(84, 13, 240, 30);
    RoundRect(sr, 15, ThemeIsLight() ? HexA(0x000000, 0.05) : Hex(0x1a1c20));
    NSUInteger asleep = 0; for (VTab *t in self.owner.tabs) if (!t.web && !t.isHome) asleep++;
    NSString *count = [NSString stringWithFormat:@"%@%lu open%@", self.pinned.count ? [NSString stringWithFormat:@"%lu pinned · ", (unsigned long)self.pinned.count] : @"", (unsigned long)(self.items.count - self.pinned.count), asleep ? [NSString stringWithFormat:@" · %lu asleep", (unsigned long)asleep] : @""];
    NSDictionary *a = @{NSFontAttributeName: MMono(11, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint};
    NSSize sz = [count sizeWithAttributes:a];
    [count drawAtPoint:NSMakePoint(NSWidth(self.bounds) - 24 - sz.width, 21) withAttributes:a];
    if (!self.pinnedView.hidden) { [[vText colorWithAlphaComponent:0.08] setFill]; Blend(NSMakeRect(NSMaxX(self.pinnedView.frame) + 20, 72, 1, NSHeight(self.bounds) - 108)); }
}
@end

// The hint at the bottom edge of the page: hover or click it and the tabs come up.
@interface VShelfHandle : NSView
@property BOOL hover;
@property CGFloat swipe;   // a two-finger swipe up on it, adding up
@property CFTimeInterval flashStart;   // a tab just opened in the background: the hint lights up and a spark runs to the right,
@property (strong) NSTimer *flashTimer; // where the new tab now sits in the strip
@property (readonly) BOOL flashing;
@property CGFloat lift, liftTarget;     // 0…1: how far it leans up toward the cursor as it comes near
@property (strong) NSTimer *liftTimer;
- (void)flashNewTab;
- (void)setApproach:(CGFloat)target;
- (NSRect)edgeRect;
@end
@implementation VShelfHandle
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }   // one click works even while another app is in front
- (BOOL)mouseDownCanMoveWindow { return NO; }
// The view is taller than the bar so the bar has room to rise; only the bottom strip (plus however far it has risen)
// takes the pointer, so the page above stays clickable.
- (CGFloat)hitDepth { return 24; }   // fixed: a hit area that grew with the lean flipped the cursor back and forth
// The 24 pt band along whichever window edge it sits on: that's where it takes the pointer.
- (NSRect)edgeRect {
    NSRect b = self.bounds; NSInteger s = ShelfSide();
    return s == 0 ? NSMakeRect(0, NSHeight(b) - 24, NSWidth(b), 24) : s == 1 ? NSMakeRect(0, 0, 24, NSHeight(b)) : NSMakeRect(NSWidth(b) - 24, 0, 24, NSHeight(b));
}
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    for (NSTrackingArea *t in self.trackingAreas.copy) [self removeTrackingArea:t];
    [self addTrackingArea:[[NSTrackingArea alloc] initWithRect:self.edgeRect options:NSTrackingMouseEnteredAndExited | NSTrackingActiveAlways owner:self userInfo:nil]];
}
// No cursor of its own: the page underneath sets the cursor on every move, so a second opinion here made it flicker.
- (NSView *)hitTest:(NSPoint)p {
    NSPoint q = [self convertPoint:p fromView:self.superview];
    return NSPointInRect(q, self.edgeRect) ? [super hitTest:p] : nil;
}
// Eased toward the target at 60 fps, so it glides rather than tracking every jitter of the mouse; stops when settled.
- (void)setApproach:(CGFloat)target {
    target = MAX(0, MIN(1, target));
    if (fabs(target - self.liftTarget) < 0.005 && fabs(self.lift - target) < 0.005) return;
    self.liftTarget = target;
    if (self.liftTimer) return;
    __weak VShelfHandle *ws = self;
    self.liftTimer = [NSTimer timerWithTimeInterval:1.0 / 60 repeats:YES block:^(NSTimer *t) {
        VShelfHandle *me = ws; if (!me) { [t invalidate]; return; }
        CGFloat d = me.liftTarget - me.lift;
        me.lift = fabs(d) < 0.004 ? me.liftTarget : me.lift + d * 0.42;
        me.needsDisplay = YES;
        if (me.lift == me.liftTarget) { [t invalidate]; me.liftTimer = nil; }
    }];
    [NSRunLoop.mainRunLoop addTimer:self.liftTimer forMode:NSRunLoopCommonModes];
}
- (void)mouseEntered:(NSEvent *)e { self.hover = YES; self.needsDisplay = YES; }   // opening on hover is ShelfTrack's call (it waits for intent)
- (void)scrollWheel:(NSEvent *)e {   // swipe up on the bar: the tabs come up and stay
    CGFloat dy = e.scrollingDeltaY, dx = e.scrollingDeltaX; NSInteger side = ShelfSide();
    BOOL up = side == 0 ? (e.isDirectionInvertedFromDevice ? dy < 0 : dy > 0) : fabs(dx) > fabs(dy);   // at a side: a sideways swipe
    if (e.phase == NSEventPhaseBegan) self.swipe = 0;
    if (up) self.swipe += side == 0 ? fabs(dy) : fabs(dx);
    if (self.swipe > 18) { self.swipe = 0; VWindow *w = WinFor(self); [w showShelf:YES]; VTabShelf *s = (VTabShelf *)w.shelf; s.sticky = YES; [w.window makeFirstResponder:s.search]; }
}
- (void)mouseExited:(NSEvent *)e { self.hover = NO; self.needsDisplay = YES; }
static const CFTimeInterval kFlashLen = 1.35;
- (BOOL)flashing { return self.flashTimer != nil; }
- (void)flashNewTab {
    self.flashStart = CACurrentMediaTime();
    if (self.hidden) { self.hidden = NO; }
    if (!self.flashTimer) {
        __weak VShelfHandle *ws = self;
        self.flashTimer = [NSTimer timerWithTimeInterval:1.0 / 60 repeats:YES block:^(NSTimer *t) {
            VShelfHandle *me = ws; if (!me) { [t invalidate]; return; }
            me.needsDisplay = YES;
            if (CACurrentMediaTime() - me.flashStart > kFlashLen) { [t invalidate]; me.flashTimer = nil; [WinFor(me) layout]; }
        }];
        [NSRunLoop.mainRunLoop addTimer:self.flashTimer forMode:NSRunLoopCommonModes];
    }
    self.needsDisplay = YES;
}
// A map of your tabs, one dot each, in strip order; the one you're on is a longer bar in your accent, playing tabs
// are a little brighter. A glance says how many there are and where you are, without opening anything.
- (void)drawRect:(NSRect)r {
    CGFloat e = 0, run = 0;
    if (self.flashTimer) {
        CGFloat t = MIN(1, (CACurrentMediaTime() - self.flashStart) / kFlashLen);
        e = t < 0.16 ? 1 - pow(1 - t / 0.16, 3) : pow(1 - (t - 0.16) / 0.84, 2);   // quick rise, long soft fade
        run = 1 - pow(1 - MIN(1, t / 0.7), 3);
    }
    VWindow *w = WinFor(self);
    NSArray<VTab *> *tabs = w.tabs ?: @[];
    NSInteger n = MIN(40, (NSInteger)tabs.count);
    // Drawn as if along the bottom edge (length across, depth up from the edge); at a side the drawing is turned
    // so the same map runs down the left or right edge, leaning inward.
    NSInteger side = ShelfSide();
    CGFloat len = side ? NSHeight(self.bounds) : NSWidth(self.bounds), H = side ? NSWidth(self.bounds) : NSHeight(self.bounds);
    if (side) {
        NSAffineTransform *tf = [NSAffineTransform transform];
        NSAffineTransformStruct m = {0, 1, side == 1 ? -1 : 1, 0, side == 1 ? H : 0, 0};
        tf.transformStruct = m; [tf concat];
    }
    CGFloat dot = 5, curW = 16, gap = n > 1 ? MIN(4, (len - 20 - curW - (n - 1) * dot) / (n - 1)) : 0;
    if (gap < 1.5) { gap = 1.5; dot = MAX(2, (len - 20 - curW - (n - 1) * gap) / MAX(1, n - 1)); }
    CGFloat total = n ? curW + (n - 1) * (dot + gap) : 56;
    CGFloat L = self.lift, ease = L * L * (3 - 2 * L);   // smoothstep: barely moves far away, leans in near
    CGFloat x = round(len / 2 - total / 2), y = H - 7 - 12 * ease;
    NSRect group = NSMakeRect(x - 7, y - 5, total + 14, dot + 10);
    if (n == 1) group = NSMakeRect(round(len / 2 - 27), y - 5, 54, 14);   // one tab: the backing fits the 40 pt bar
    // as it leans up, its backing grows out of the window's edge to meet it (a tab being drawn up, no gap under it)
    CGFloat back = MAX(ease, self.hover ? 1 : 0);
    if (back > 0.02) {
        NSRect tab = NSMakeRect(NSMinX(group), NSMinY(group), NSWidth(group), H - NSMinY(group) + NSHeight(group));
        RoundRect(tab, NSHeight(group) / 2, [vText colorWithAlphaComponent:(ThemeIsLight() ? 0.06 : 0.085) * back]);
    }
    if (e > 0.001) for (int k = 3; k >= 1; k--)   // a soft halo in your highlight colour when a tab opens behind
        RoundRect(NSInsetRect(group, -2.2 * k, -1.6 * k), NSHeight(group) / 2 + 2.2 * k, [vEmber colorWithAlphaComponent:0.075 * e]);

    if (!n) { RoundRect(NSMakeRect(x, y, 56, dot), 2.5, [Hex(0x787a80) colorWithAlphaComponent:0.5]); return; }
    // one tab: there's no position to show, so just a quiet bar (a lone bright pill read as a spike at the window's edge)
    if (n == 1 && e <= 0.001) {
        CGFloat bw = 40, bx = round(len / 2 - bw / 2);
        RoundRect(NSMakeRect(bx, y + 0.5, bw, 4), 2, [Hex(0x8a8c93) colorWithAlphaComponent:self.hover ? 0.8 : 0.45 + 0.35 * ease]);
        return;
    }
    NSColor *pick = PickColor(w.isPrivate, w.profile);
    for (NSInteger i = 0; i < n; i++) {
        VTab *t = tabs[(NSUInteger)i]; BOOL cur = t == w.current;
        CGFloat wd = cur ? curW : dot;
        NSColor *c = cur ? pick : [Hex(0x8a8c93) colorWithAlphaComponent:(t.audible && !t.muted) ? 0.95 : (self.hover ? 0.8 : 0.55 + 0.25 * ease)];
        if (e > 0.001 && i == n - 1 && !cur) c = [c blendedColorWithFraction:e ofColor:vEmber] ?: c;   // the new one, at the right end
        NSRect pr = NSMakeRect(x, y, wd, dot);
        if (cur && !w.isPrivate) [ApertureGradient(1) drawInBezierPath:[NSBezierPath bezierPathWithRoundedRect:pr xRadius:dot / 2 yRadius:dot / 2] angle:0];
        else RoundRect(pr, dot / 2, c);
        x += wd + gap;
    }
    if (e > 0.001) {   // the spark heads right, where the new tab is
        CGFloat sx = NSMidX(group) + (NSWidth(group) / 2 - 10) * run;
        RoundRect(NSMakeRect(sx - 7, y, 14, dot), dot / 2, [NSColor.whiteColor colorWithAlphaComponent:0.55 * e]);
    }
}
- (void)mouseDown:(NSEvent *)e { VWindow *w = WinFor(self); [w showShelf:YES]; VTabShelf *s = (VTabShelf *)w.shelf; s.sticky = YES; [w.window makeFirstResponder:s.search]; }
@end

// Hovering the bottom edge of a Iris window brings its tabs up, even while another app is in front
// (as long as nothing covers that edge); moving well away puts them back. Esc closes them.
// The hover zone: a band around the tab map at the middle of the bottom edge (360 × 24 pt), not the whole edge,
// so reaching for a link low on the page doesn't bring the tabs up.
static BOOL ShelfZone(NSView *root, NSPoint p) {
    CGFloat H = NSHeight(root.bounds), W = NSWidth(root.bounds); NSInteger side = ShelfSide();
    if (side == 1) return fabs(p.y - ShelfMidY(H)) <= 180 && p.x >= -1 && p.x <= 24;
    if (side == 2) return fabs(p.y - ShelfMidY(H)) <= 180 && p.x >= W - 24 && p.x <= W + 1;
    return fabs(p.x - W / 2) <= 180 && p.y >= H - 24 && p.y <= H + 1;
}
// How far the pointer is from the tab map: along the edge beyond its ends, and in from the edge.
static CGFloat ShelfDistance(NSView *root, NSPoint p) {
    CGFloat H = NSHeight(root.bounds), W = NSWidth(root.bounds); NSInteger side = ShelfSide();
    if (side == 1) return hypot(MAX(0, fabs(p.y - ShelfMidY(H)) - 130), MAX(0, p.x));
    if (side == 2) return hypot(MAX(0, fabs(p.y - ShelfMidY(H)) - 130), MAX(0, W - p.x));
    return hypot(MAX(0, fabs(p.x - W / 2) - 130), MAX(0, H - p.y));
}
// Intent, not passing through: the tabs open once the pointer has been in the zone for 30 ms moving slowly.
// A fast pass (travel toward the Dock or across the page) keeps restarting the clock and leaves before it runs out.
static NSInteger gShelfGen; static BOOL gShelfIn; static CFTimeInterval gShelfSince, gShelfLastT; static NSPoint gShelfLastP;

// While the pointer is over the tab strip or the tab map, the page underneath stops hearing mouse moves: otherwise it
// keeps setting its own cursor (a hand, a text beam) for whatever lies hidden behind the widget.
static __weak VWindow *gMuted;
static void PageHearsMouse(VWindow *w, BOOL hears) {
    if (!w) return;
    if (hears && (objc_getAssociatedObject(w, &kCustomiserKey) || [w panelOpen] || gMuted == w || PrivateWindowLocked(w))) hears = NO;   // something of Iris's is over the page   // Customise Toolbar is open: the pages under it stay out of the pointer's way
    NSMutableArray<WKWebView *> *webs = [NSMutableArray array];
    for (VTab *t in w.tabs) if (t.web.web) [webs addObject:t.web.web];
    SEL a = NSSelectorFromString(@"_setIgnoresMouseMoveEvents:"), b = NSSelectorFromString(@"_setIgnoresNonWheelEvents:");
    for (WKWebView *v in webs) {
        if ([v respondsToSelector:a]) ((void (*)(id, SEL, BOOL))objc_msgSend)(v, a, !hears);
        else if ([v respondsToSelector:b]) ((void (*)(id, SEL, BOOL))objc_msgSend)(v, b, !hears);
    }
    if (!hears) [NSCursor.arrowCursor set];
}
static void ShelfMuteFor(VWindow *w) {   // w: the window whose widget is under the pointer, or nil
    VWindow *cur = gMuted;
    if (cur == w) { if (w) [NSCursor.arrowCursor set]; return; }
    gMuted = w;   // first, so un-muting the old window isn't refused because it still looks muted
    if (cur) PageHearsMouse(cur, YES);
    if (w) PageHearsMouse(w, NO);
}
static void ShelfTrack(NSPoint screen) {
    // this runs on every mouse move anywhere on the Mac: plain arithmetic first, and the window server is only asked
    // "which window is on top here?" when the pointer is actually near an Iris window's bottom edge
    BOOL near = NO;
    for (VWindow *w in gWindows) {
        NSWindow *win = w.window; if (!win.isVisible || win.isMiniaturized) continue;
        NSRect f = win.frame;
        NSInteger side = ShelfSide();
        BOOL inX = screen.x > NSMinX(f) && screen.x < NSMaxX(f), inY = screen.y > NSMinY(f) && screen.y < NSMaxY(f);
        BOOL band = side == 0 ? (inX && screen.y >= NSMinY(f) - 1 && screen.y <= NSMinY(f) + 105)
                  : side == 1 ? (inY && screen.x >= NSMinX(f) - 1 && screen.x <= NSMinX(f) + 105)
                              : (inY && screen.x <= NSMaxX(f) + 1 && screen.x >= NSMaxX(f) - 105);
        if (((VTabShelf *)w.shelf).shown || band) { near = YES; break; }
    }
    static BOOL leaning;
    if (!near) {
        ShelfMuteFor(nil);
        if (gShelfIn) { gShelfIn = NO; gShelfGen++; }
        if (leaning) { leaning = NO; for (VWindow *w in gWindows) [(VShelfHandle *)w.shelfHandle setApproach:0]; }
        return;
    }
    VWindow *hit = nil, *over = nil;
    static NSInteger lastTop; static CFTimeInterval lastAsk; static NSPoint lastAt;
    CFTimeInterval nowT = CACurrentMediaTime();
    if (nowT - lastAsk > 0.12 || hypot(screen.x - lastAt.x, screen.y - lastAt.y) > 60) {   // the window server is only asked now and then
        lastTop = [NSWindow windowNumberAtPoint:screen belowWindowWithWindowNumber:0]; lastAsk = nowT; lastAt = screen;
    }
    NSInteger topNumber = lastTop;
    for (VWindow *w in gWindows.copy) {
        NSWindow *win = w.window; VTabShelf *s = (VTabShelf *)w.shelf;
        if (!s || !win.isVisible || win.isMiniaturized) continue;
        NSView *root = win.contentView;
        NSPoint p = [root convertPoint:[win convertPointFromScreen:screen] fromView:nil];
        CGFloat H = NSHeight(root.bounds), W = NSWidth(root.bounds); (void)H; (void)W;
        if (!s.shown) {
            BOOL ok = topNumber == win.windowNumber && ![Defaults() boolForKey:kShelfNoHover] && ![[w valueForKey:@"pageFull"] boolValue];
            if (!hit && ok && ShelfZone(root, p)) hit = w;
            // the closer the pointer comes (within 100 pt of the tab map), the further the map leans up to meet it
            CGFloat a = ok ? MAX(0, 1 - ShelfDistance(root, p) / 100) : 0;
            [(VShelfHandle *)w.shelfHandle setApproach:a]; if (a > 0) leaning = YES;
        } else if (!s.sticky && !NSPointInRect(p, NSInsetRect(s.frame, -30, -40))) [w showShelf:NO];
        if (!over && topNumber == win.windowNumber) {   // the pointer is on Iris's own widget, not the page
            NSView *hd = w.shelfHandle;
            NSRect handleHit = [hd convertRect:[(VShelfHandle *)hd edgeRect] toView:root];
            if ((s.shown && NSPointInRect(p, s.frame)) || (!hd.hidden && !s.shown && NSPointInRect(p, handleHit))) over = w;
        }
    }
    ShelfMuteFor(over);
    if (!hit) { if (gShelfIn) { gShelfIn = NO; gShelfGen++; } return; }
    CFTimeInterval now = CACurrentMediaTime();
    double speed = gShelfIn ? hypot(screen.x - gShelfLastP.x, screen.y - gShelfLastP.y) / MAX(0.001, now - gShelfLastT) : 1e9;
    if (!gShelfIn || speed > 450) gShelfSince = now;   // still travelling: the clock starts once it slows down
    gShelfIn = YES; gShelfLastP = screen; gShelfLastT = now;
    NSInteger gen = ++gShelfGen;
    __weak VWindow *ww = hit;
    double wait = MAX(0.02, gShelfSince + 0.03 - now);
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(wait * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        VWindow *x = ww; if (!x || gen != gShelfGen || ((VTabShelf *)x.shelf).shown) return;
        NSView *rt = x.window.contentView;
        NSPoint q = [rt convertPoint:[x.window convertPointFromScreen:NSEvent.mouseLocation] fromView:nil];
        if (ShelfZone(rt, q) && CACurrentMediaTime() - gShelfSince >= 0.02) [x showShelf:YES];
    });
}
static void InstallShelfMonitor(void) {
    static id mon, outside;
    if (mon) return;
    outside = [NSEvent addGlobalMonitorForEventsMatchingMask:NSEventMaskMouseMoved handler:^(NSEvent *e) { ShelfTrack(NSEvent.mouseLocation); }];
    mon = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskMouseMoved | NSEventMaskKeyDown | NSEventMaskLeftMouseDown handler:^NSEvent *(NSEvent *e) {
        if (e.type == NSEventTypeMouseMoved) { ShelfTrack(NSEvent.mouseLocation); return e; }
        id c = e.window.windowController;
        if (![c isKindOfClass:VWindow.class]) return e;
        VWindow *w = c; VTabShelf *s = (VTabShelf *)w.shelf;
        if (!s) return e;
        if (e.type == NSEventTypeKeyDown) {
            if (e.keyCode == 53 && w.lensPanel && [[w.lensPanel valueForKey:@"shown"] boolValue]) { [w closePanels]; return nil; }
            if (e.keyCode == 53 && [w panelOpen]) { [w closePanels]; return e; }   // the address field gets its Esc too
            if (s.shown && e.keyCode == 53) { [w showShelf:NO]; return nil; }
            return e;
        }
        NSView *root = w.window.contentView;
        NSPoint p = [root convertPoint:e.locationInWindow fromView:nil];
        if (s.shown && !NSPointInRect(p, s.frame)) [w showShelf:NO];
        if ([w panelOpen] && ![w point:p inPanelOrBar:root]) [w closePanels];
        return e;
    }];
}

@implementation VWindow (Shelf)
- (NSRect)shelfFrame {
    NSView *root = self.window.contentView;
    CGFloat W = NSWidth(root.bounds), H = NSHeight(root.bounds);
    VTabShelf *s = (VTabShelf *)self.shelf;
    NSInteger side = ShelfSide();
    if (side) {   // a column out of the side edge, centred on the page area, as tall as its cards need (then it scrolls)
        CGFloat w = s.wantWidth ?: kCardW + 48, avail = H - 64 - 16;
        CGFloat h = MIN(avail, MAX(300, s.wantHeight ?: avail));
        CGFloat y = MAX(64, MIN(H - 16 - h, round(ShelfMidY(H) - h / 2)));
        return side == 1 ? NSMakeRect(0, y, w, h) : NSMakeRect(W - w, y, w, h);
    }
    CGFloat h = s.wantHeight ?: 274;
    // centred over the tab map it rises from, as wide as its cards need (never narrower than its header, never wider
    // than the window; past that the cards scroll)
    CGFloat w = MIN(W - 28, MAX(560, s.wantWidth ?: W - 28));
    return NSMakeRect(round((W - w) / 2), H - h - 6, w, h + 6);   // sits on the window's bottom edge: nothing of the page shows under it
}
// Where it waits while hidden: just past its place, toward the edge it comes out of.
- (NSRect)shelfRestFrame {
    NSRect f = [self shelfFrame]; NSInteger side = ShelfSide();
    return side == 1 ? NSOffsetRect(f, -16, 0) : side == 2 ? NSOffsetRect(f, 16, 0) : NSOffsetRect(f, 0, 14);
}
- (void)showShelf:(BOOL)on {
    if (gWebApp && on) return;   // an installed app has no tabs to show
    if (on && PrivateWindowLocked(self)) return;   // a locked private window shows nothing, its tabs included
    VTabShelf *s = (VTabShelf *)self.shelf;
    if (!s || s.shown == on) return;
    if (on && [[self valueForKey:@"pageFull"] boolValue]) return;
    s.shown = on;
    NSRect f = [self shelfFrame];
    if (on) {
        if (s.superview) [s.superview addSubview:s positioned:NSWindowAbove relativeTo:nil];
        s.search.stringValue = @"";
        CaptureThumb(self.current);
        [s reload]; f = [self shelfFrame];
        [CATransaction begin]; [CATransaction setDisableActions:YES];   // start from just below its place, not wherever it last was
        s.frame = [self shelfRestFrame]; s.alphaValue = 0; s.hidden = NO;
        ((VShelfStrip *)s.strip).kbd = -1;
        [s layoutShelf]; [s scrollToCurrent]; [s displayIfNeeded];
        [CATransaction commit];
        self.shelfHandle.hidden = YES;
        dispatch_async(dispatch_get_main_queue(), ^{   // next turn: the start position is on screen before it moves
            if (!s.shown) return;
            [NSAnimationContext runAnimationGroup:^(NSAnimationContext *ctx) {
                ctx.duration = 0.18; ctx.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionEaseOut];
                s.animator.frame = f; s.animator.alphaValue = 1;
            }];
        });
    } else {
        s.sticky = NO;
        if (s.search.currentEditor) [self.window makeFirstResponder:self.current.web.web ?: self.window.contentView];
        __weak VWindow *ws = self;
        [NSAnimationContext runAnimationGroup:^(NSAnimationContext *ctx) {
            ctx.duration = 0.14;
            s.animator.frame = [self shelfRestFrame]; s.animator.alphaValue = 0;
        } completionHandler:^{
            if (!s.shown) { s.hidden = YES; ws.shelfHandle.hidden = [[ws valueForKey:@"pageFull"] boolValue] || [Defaults() boolForKey:kShelfNoHint]; }
        }];
    }
}
- (void)toggleShelfButton:(id)s { [self toggleShelf]; }
- (void)toggleShelf {
    VTabShelf *s = (VTabShelf *)self.shelf;
    if (s.shown) { [self showShelf:NO]; return; }
    [self showShelf:YES]; s.sticky = YES;
    [self.window makeFirstResponder:s.search];
}
@end


// The loading line: a hairline along the bottom of the top band, from one edge of the window to the other, right
// where the page begins. It grows with the page's real progress (and creeps on its own while a page goes quiet,
// so it never sits still), brightest at its tip, with a glint running along it; done, it reaches the far edge and fades.
@interface VLoadLine : NSView
@property (strong) CALayer *fill, *halfL, *halfR;
@property (strong) CAGradientLayer *flowL, *flowR, *core, *aperture;
@property double real, shown;
@property CFTimeInterval started;
@property BOOL active;
@property (strong) NSTimer *tick;
- (void)loading:(BOOL)on progress:(double)p;
@end
// Aperture: a load opens from the middle of the page's top edge outward, like an iris widening, while Iris's
// teal, blue and violet flow out from the centre; a soft bright core breathes at the middle so a stalled load still
// looks alive. When the page arrives it opens to both edges, blooms once and fades.
@implementation VLoadLine
static const CGFloat kFlowPeriod = 260;
- (instancetype)initWithFrame:(NSRect)r {
    if (!(self = [super initWithFrame:r])) return nil;
    self.wantsLayer = YES; self.layer.masksToBounds = NO;
    self.fill = [CALayer layer];
    self.halfL = [CALayer layer]; self.halfL.masksToBounds = YES;
    self.halfR = [CALayer layer]; self.halfR.masksToBounds = YES;
    self.flowL = [CAGradientLayer layer]; self.flowL.startPoint = CGPointMake(0, 0.5); self.flowL.endPoint = CGPointMake(1, 0.5);
    self.flowR = [CAGradientLayer layer]; self.flowR.startPoint = CGPointMake(0, 0.5); self.flowR.endPoint = CGPointMake(1, 0.5);
    self.core = [CAGradientLayer layer]; self.core.startPoint = CGPointMake(0, 0.5); self.core.endPoint = CGPointMake(1, 0.5);
    self.aperture = [CAGradientLayer layer]; self.aperture.startPoint = CGPointMake(0, 0.5); self.aperture.endPoint = CGPointMake(1, 0.5);
    self.aperture.colors = @[(id)[NSColor colorWithWhite:0 alpha:0].CGColor, (id)NSColor.blackColor.CGColor, (id)NSColor.blackColor.CGColor, (id)[NSColor colorWithWhite:0 alpha:0].CGColor];
    self.aperture.locations = @[@0, @0.14, @0.86, @1];
    [self.halfL addSublayer:self.flowL]; [self.halfR addSublayer:self.flowR];
    [self.fill addSublayer:self.halfL]; [self.fill addSublayer:self.halfR]; [self.fill addSublayer:self.core];
    self.fill.mask = self.aperture;
    [self.layer addSublayer:self.fill];
    self.fill.hidden = YES;
    return self;
}
- (NSView *)hitTest:(NSPoint)p { return nil; }   // never in the way of a click
// colours repeat every kFlowPeriod points, so sliding a flow by exactly one period loops without a seam
- (NSArray *)cycle:(NSUInteger)n reversed:(BOOL)rev {
    BOOL light = ThemeIsLight();
    NSColor *teal = light ? Hex(0x22b3a0) : Hex(0x7fe3d1), *blue = light ? Hex(0x4a78ee) : Hex(0x86a3f7), *violet = light ? Hex(0x8c63e6) : Hex(0xb796f5);
    NSArray *one = @[(id)blue.CGColor, (id)violet.CGColor, (id)blue.CGColor, (id)teal.CGColor];
    NSMutableArray *c = [NSMutableArray array];
    for (NSUInteger i = 0; i < n; i++) [c addObjectsFromArray:one];
    [c addObject:(id)blue.CGColor];
    return rev ? c.reverseObjectEnumerator.allObjects : c;
}
- (void)paint {
    CGFloat W = NSWidth(self.bounds), H = NSHeight(self.bounds), half = round(W / 2);
    NSUInteger n = (NSUInteger)ceil((half + kFlowPeriod) / kFlowPeriod) + 1;
    CGFloat span = n * kFlowPeriod;
    [CATransaction begin]; [CATransaction setDisableActions:YES];
    self.fill.frame = CGRectMake(0, 0, W, H);
    self.halfL.frame = CGRectMake(0, 0, half, H); self.halfR.frame = CGRectMake(half, 0, W - half, H);
    // the right half flows rightward from the centre, the left half (mirrored) leftward
    self.flowR.frame = CGRectMake(-kFlowPeriod, 0, span, H); self.flowR.colors = [self cycle:n reversed:NO];
    self.flowL.frame = CGRectMake(half + kFlowPeriod - span, 0, span, H); self.flowL.colors = [self cycle:n reversed:YES];
    self.core.frame = CGRectMake(half - 60, 0, 120, H);
    self.core.colors = @[(id)[NSColor colorWithWhite:1 alpha:0].CGColor, (id)[NSColor colorWithWhite:1 alpha:ThemeIsLight() ? 0.55 : 0.75].CGColor, (id)[NSColor colorWithWhite:1 alpha:0].CGColor];
    [CATransaction commit];
    NSColor *glow = ThemeIsLight() ? Hex(0x4a78ee) : Hex(0x86a3f7);
    self.layer.shadowColor = glow.CGColor; self.layer.shadowOffset = CGSizeZero;
    self.layer.shadowRadius = 4; self.layer.shadowOpacity = ThemeIsLight() ? 0.45 : 0.85;   // the glow follows the line's own shape
}
- (void)place:(double)f duration:(CFTimeInterval)d {
    CGFloat W = NSWidth(self.bounds), H = NSHeight(self.bounds), w = round(W * f);
    [CATransaction begin]; [CATransaction setAnimationDuration:d];
    [CATransaction setAnimationTimingFunction:[CAMediaTimingFunction functionWithControlPoints:0.25 :0.8 :0.3 :1]];
    if (d == 0) [CATransaction setDisableActions:YES];
    self.aperture.frame = CGRectMake(round((W - w) / 2), 0, w, H);   // opens from the middle out
    [CATransaction commit];
}
- (void)startMotion {
    CABasicAnimation *r = [CABasicAnimation animationWithKeyPath:@"position.x"];
    r.byValue = @(kFlowPeriod); r.duration = 2.6; r.repeatCount = HUGE_VALF; r.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionLinear];
    [self.flowR addAnimation:r forKey:@"flow"];
    CABasicAnimation *l = [r copy]; l.byValue = @(-kFlowPeriod);
    [self.flowL addAnimation:l forKey:@"flow"];
    CABasicAnimation *b = [CABasicAnimation animationWithKeyPath:@"opacity"];
    b.fromValue = @0.35; b.toValue = @1; b.duration = 0.9; b.autoreverses = YES; b.repeatCount = HUGE_VALF;
    b.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionEaseInEaseOut];
    [self.core addAnimation:b forKey:@"breathe"];
}
- (void)stopMotion { [self.flowR removeAllAnimations]; [self.flowL removeAllAnimations]; [self.core removeAllAnimations]; }
- (void)advance {
    double t = CACurrentMediaTime() - self.started;
    double creep = 0.85 * (1 - exp(-t / 4.0));   // a page that's gone quiet still shows life, never past 85%
    double target = MAX(MAX(0.04, self.real), creep);
    if (target > self.shown + 0.002) { self.shown = target; [self place:self.shown duration:0.45]; }
}
- (void)loading:(BOOL)on progress:(double)p {
    self.real = MAX(0, MIN(1, p));
    if (on && !self.active) {   // a fresh load opens from nothing at the centre
        self.active = YES; self.started = CACurrentMediaTime(); self.shown = 0;
        [self paint];
        [self.fill removeAllAnimations];
        [CATransaction begin]; [CATransaction setDisableActions:YES]; self.fill.opacity = 1; self.fill.hidden = NO; [CATransaction commit];
        [self place:0 duration:0];
        [self startMotion];
        __weak VLoadLine *ws = self;
        self.tick = [NSTimer timerWithTimeInterval:0.25 repeats:YES block:^(NSTimer *tm) { [ws advance]; }];
        [NSRunLoop.mainRunLoop addTimer:self.tick forMode:NSRunLoopCommonModes];
    }
    if (on) { [self advance]; return; }
    if (!self.active) return;
    self.active = NO; [self.tick invalidate]; self.tick = nil;
    // arrived: open to both edges, a brief bloom, then fade
    [CATransaction begin];
    [CATransaction setCompletionBlock:^{
        if (self.active) return;
        CABasicAnimation *bloom = [CABasicAnimation animationWithKeyPath:@"shadowRadius"];
        bloom.fromValue = @4; bloom.toValue = @9; bloom.duration = 0.18; bloom.autoreverses = YES;
        [self.layer addAnimation:bloom forKey:@"bloom"];
        [CATransaction begin]; [CATransaction setAnimationDuration:0.42];
        [CATransaction setCompletionBlock:^{ if (!self.active) { self.fill.hidden = YES; [self stopMotion]; } }];
        self.fill.opacity = 0;
        [CATransaction commit];
    }];
    [self place:1 duration:0.24];
    [CATransaction commit];
}
- (void)setFrameSize:(NSSize)s { [super setFrameSize:s]; if (self.active) { [self paint]; [self place:self.shown duration:0]; [self startMotion]; } }
@end

#pragma mark - Monolith panels: Lens, and the address popup

// One small vocabulary for both panels: each item is a rect, a look and (optionally) what clicking it does.
typedef NS_ENUM(NSInteger, VPKind) { VPLabel, VPRow, VPToggle, VPChip, VPTile, VPGrid, VPStat, VPPill, VPText, VPSep, VPHeader, VPAvatar };
@interface VPItem : NSObject
@property VPKind kind;
@property NSRect r;
@property (copy) NSString *title, *meta, *symbol;
@property (strong) NSImage *icon;
@property BOOL on;
@property (copy) void (^act)(NSEvent *e, NSRect r);
@property (copy) NSMenu *(^menu)(void);   // right-click: what you can do with this item
@property (strong) NSMutableDictionary *node;   // a bookmark (or folder) you can drag to rearrange
@property (weak) NSMutableArray *list;          // the list it sits in
@end
@implementation VPItem
@end

@interface VPanel : NSView
@property (weak) VWindow *owner;
@property (strong) NSMutableArray<VPItem *> *items;
@property NSInteger hover;
@property BOOL shown;
@property CGFloat irisX;
@property NSInteger dragItem, dropItem, dropMode;   // dragging a bookmark: which, onto which, and 0 before / 1 after / 2 into a folder
@property NSPoint dragAt;   // where the button that opened it sits, across the panel: it opens from there like an iris (<0: just fades in)
- (void)build;   // subclasses: fill the items and set the height
- (VPItem *)add:(VPKind)k rect:(NSRect)r title:(NSString *)t;
- (void)present:(NSRect)frame;
- (void)dismiss;
@end

static void PanelShadow(NSView *v) {
    CGPathRef p = CGPathCreateWithRoundedRect(CGRectMake(0, 0, NSWidth(v.frame), NSHeight(v.frame)), 18, 18, NULL);
    v.layer.shadowPath = p; CGPathRelease(p);
}
static NSColor *PanelAccent(VWindow *w) { return PickColor(w.isPrivate, w.profile); }
static NSImage *PanelLetter(NSString *s, CGFloat size) {
    NSString *l = s.length ? [[s substringToIndex:[s rangeOfComposedCharacterSequenceAtIndex:0].length] uppercaseString] : @"•";
    return [NSImage imageWithSize:NSMakeSize(size, size) flipped:NO drawingHandler:^BOOL(NSRect r) {
        NSDictionary *a = @{NSFontAttributeName: UIFont(size * 0.5, NSFontWeightSemibold), NSForegroundColorAttributeName: vText};
        NSSize sz = [l sizeWithAttributes:a];
        [l drawAtPoint:NSMakePoint((size - sz.width) / 2, (size - sz.height) / 2) withAttributes:a];
        return YES;
    }];
}

@implementation VPanel
- (BOOL)isFlipped { return YES; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (void)scrollWheel:(NSEvent *)e {}   // the page behind a panel stays put
- (instancetype)initWithFrame:(NSRect)r {
    if (!(self = [super initWithFrame:r])) return nil;
    self.items = [NSMutableArray array]; self.hover = -1; self.hidden = YES; self.irisX = -1; self.dragItem = -1; self.dropItem = -1;
    self.wantsLayer = YES;
    self.layer.shadowColor = NSColor.blackColor.CGColor; self.layer.shadowOpacity = ThemeIsLight() ? 0.14 : 0.45;
    self.layer.shadowRadius = 30; self.layer.shadowOffset = CGSizeMake(0, -14);
    return self;
}
- (VPItem *)add:(VPKind)k rect:(NSRect)r title:(NSString *)t {
    VPItem *i = [VPItem new]; i.kind = k; i.r = r; i.title = t ?: @"";
    [self.items addObject:i]; return i;
}
- (void)build {}
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    for (NSTrackingArea *t in self.trackingAreas.copy) [self removeTrackingArea:t];
    [self addTrackingArea:[[NSTrackingArea alloc] initWithRect:NSZeroRect options:NSTrackingMouseMoved | NSTrackingMouseEnteredAndExited | NSTrackingActiveInKeyWindow | NSTrackingInVisibleRect owner:self userInfo:nil]];
}
- (NSInteger)itemAt:(NSPoint)p {
    for (NSInteger i = (NSInteger)self.items.count - 1; i >= 0; i--) { VPItem *it = self.items[(NSUInteger)i]; if (it.act && NSPointInRect(p, it.r)) return i; }
    return -1;
}
- (void)mouseMoved:(NSEvent *)e { NSInteger h = [self itemAt:[self convertPoint:e.locationInWindow fromView:nil]]; if (h != self.hover) { self.hover = h; self.needsDisplay = YES; } }
- (void)mouseExited:(NSEvent *)e { self.hover = -1; self.needsDisplay = YES; }
- (void)rightMouseDown:(NSEvent *)e {
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    for (NSInteger i = (NSInteger)self.items.count - 1; i >= 0; i--) {
        VPItem *it = self.items[(NSUInteger)i];
        if (!it.menu || !NSPointInRect(p, it.r)) continue;
        NSMenu *m = it.menu(); if (m) PopMenu(m, p, self);
        return;
    }
}
- (void)mouseDown:(NSEvent *)e {
    NSPoint start = [self convertPoint:e.locationInWindow fromView:nil];
    NSInteger i = [self itemAt:start];
    if (i < 0) return;
    VPItem *it = self.items[(NSUInteger)i];
    if (!it.node) { it.act(e, [self convertRect:it.r toView:nil]); return; }
    // a bookmark: a click opens it; a drag rearranges (between others, or into a folder)
    BOOL dragging = NO; self.dropItem = -1;
    while (YES) {
        NSEvent *n = [self.window nextEventMatchingMask:NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp];
        NSPoint q = [self convertPoint:n.locationInWindow fromView:nil];
        if (n.type == NSEventTypeLeftMouseUp) {
            if (!dragging) { it.act(e, [self convertRect:it.r toView:nil]); return; }
            [self dropDragged]; return;
        }
        if (!dragging && hypot(q.x - start.x, q.y - start.y) > 4) { dragging = YES; self.dragItem = i; [NSCursor.closedHandCursor push]; }
        if (dragging) { self.dragAt = q; [self findDropFor:q]; self.needsDisplay = YES; }
    }
}
- (void)findDropFor:(NSPoint)q {
    VPItem *src = self.items[(NSUInteger)self.dragItem];
    self.dropItem = -1;
    // right on an item: a folder's middle takes it in; otherwise before or after, by which half you're over
    for (NSInteger j = 0; j < (NSInteger)self.items.count; j++) {
        VPItem *t = self.items[(NSUInteger)j];
        if (!t.node || j == self.dragItem || !NSPointInRect(q, NSInsetRect(t.r, -4, -4))) continue;
        BOOL folder = [t.node[@"children"] isKindOfClass:NSArray.class];
        CGFloat f = (q.x - NSMinX(t.r)) / MAX(1, NSWidth(t.r));
        if (folder && f > 0.22 && f < 0.78 && !BMContains(src.node, t.node)) { self.dropItem = j; self.dropMode = 2; return; }
        self.dropItem = j; self.dropMode = f < 0.5 ? 0 : 1; return;
    }
    // in the gaps (or past the last one in a row): the nearest item, before or after it in reading order
    CGFloat best = 60; NSInteger bj = -1;
    for (NSInteger j = 0; j < (NSInteger)self.items.count; j++) {
        VPItem *t = self.items[(NSUInteger)j];
        if (!t.node || j == self.dragItem) continue;
        CGFloat dx = MAX(0, MAX(NSMinX(t.r) - q.x, q.x - NSMaxX(t.r))), dy = MAX(0, MAX(NSMinY(t.r) - q.y, q.y - NSMaxY(t.r)));
        CGFloat d = hypot(dx, dy * 1.5);
        if (d < best) { best = d; bj = j; }
    }
    if (bj < 0) return;
    NSRect r = self.items[(NSUInteger)bj].r;
    self.dropItem = bj;
    self.dropMode = q.y < NSMinY(r) ? 0 : q.y > NSMaxY(r) ? 1 : (q.x < NSMidX(r) ? 0 : 1);
}
- (void)dropDragged {
    [NSCursor pop];
    VPItem *src = self.dragItem >= 0 && self.dragItem < (NSInteger)self.items.count ? self.items[(NSUInteger)self.dragItem] : nil;
    VPItem *dst = self.dropItem >= 0 ? self.items[(NSUInteger)self.dropItem] : nil;
    self.dragItem = -1; self.dropItem = -1;
    if (src && dst) {
        if (self.dropMode == 2) BMPlace(src.node, BMChildren(dst.node), NSNotFound);
        else if (dst.list) { NSUInteger at = [dst.list indexOfObjectIdenticalTo:dst.node]; if (at != NSNotFound) BMPlace(src.node, dst.list, at + (self.dropMode == 1 ? 1 : 0)); }
        BookmarksChanged();
    }
    if ([self respondsToSelector:@selector(rebuildKeepingWidth)]) [self performSelector:@selector(rebuildKeepingWidth)]; else { [self build]; }
    self.needsDisplay = YES;
}
- (void)present:(NSRect)frame {
    self.shown = YES;
    PageHearsMouse(self.owner, NO);   // the page under a panel keeps getting pointer moves (tracking areas ignore what covers them): it mustn't set the cursor
    if (self.superview) [self.superview addSubview:self positioned:NSWindowAbove relativeTo:nil];
    [CATransaction begin]; [CATransaction setDisableActions:YES];
    self.frame = NSOffsetRect(frame, 0, -6); self.alphaValue = 0; self.hidden = NO;
    PanelShadow(self); [self displayIfNeeded];
    [CATransaction commit];
    dispatch_async(dispatch_get_main_queue(), ^{
        if (!self.shown) return;
        if (self.irisX >= 0 && self.layer) [self irisOpen:frame.size];
        [NSAnimationContext runAnimationGroup:^(NSAnimationContext *ctx) {
            ctx.duration = 0.14 * gSlowMo; ctx.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionEaseOut];
            self.animator.frame = frame; self.animator.alphaValue = 1;
        }];
    });
}
// Opening like an aperture: a circle widens from the button's side of the panel until it uncovers all of it,
// then the panel's shadow settles in underneath (a mask would have clipped it while the circle grew).
- (void)irisOpen:(NSSize)size {
    CGFloat W = size.width, H = size.height, cx = MAX(0, MIN(W, self.irisX));
    BOOL down = NO; for (CALayer *l = self.layer; l; l = l.superlayer) down ^= l.geometryFlipped;   // which way is up for the layer
    CGFloat cy = down ? 0 : H, R = hypot(MAX(cx, W - cx), H) + 6;
    CAShapeLayer *m = [CAShapeLayer layer]; m.frame = CGRectMake(0, 0, W, H);
    CGPathRef from = CGPathCreateWithEllipseInRect(CGRectMake(cx - 10, cy - 10, 20, 20), NULL);
    CGPathRef to = CGPathCreateWithEllipseInRect(CGRectMake(cx - R, cy - R, 2 * R, 2 * R), NULL);
    m.path = to; self.layer.mask = m;
    float shadow = self.layer.shadowOpacity;
    [CATransaction begin];
    [CATransaction setCompletionBlock:^{
        if (self.layer.mask != m) return;
        self.layer.mask = nil;
        CABasicAnimation *s = [CABasicAnimation animationWithKeyPath:@"shadowOpacity"]; s.fromValue = @0; s.toValue = @(shadow); s.duration = 0.16 * gSlowMo;
        [self.layer addAnimation:s forKey:@"shadowIn"];
    }];
    CABasicAnimation *a = [CABasicAnimation animationWithKeyPath:@"path"];
    a.fromValue = (__bridge id)from; a.toValue = (__bridge id)to; a.duration = 0.3 * gSlowMo;
    a.timingFunction = [CAMediaTimingFunction functionWithControlPoints:0.22 :0.9 :0.25 :1];
    [m addAnimation:a forKey:@"iris"];
    [CATransaction commit];
    CGPathRelease(from); CGPathRelease(to);
}
- (void)dismiss {
    if (!self.shown) return;
    if (self.layer.mask) self.layer.mask = nil;
    self.shown = NO; self.hover = -1;
    PageHearsMouse(self.owner, YES);
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext *ctx) { ctx.duration = 0.1; self.animator.alphaValue = 0; }
                       completionHandler:^{ if (!self.shown) self.hidden = YES; }];
}
// While a bookmark is dragged: its place dims, an Aperture marker shows where it lands (a line between, a ring around a
// folder it would go into), and a chip with its name follows the pointer.
- (void)drawDragOverlay {
    if (self.dragItem < 0 || self.dragItem >= (NSInteger)self.items.count) return;
    VPItem *src = self.items[(NSUInteger)self.dragItem];
    RoundRect(src.r, 11, [(ThemeIsLight() ? Hex(0xf7f7f5) : Hex(0x121316)) colorWithAlphaComponent:0.7]);
    if (self.dropItem >= 0) {
        NSRect t = self.items[(NSUInteger)self.dropItem].r;
        if (self.dropMode == 2) ApertureStroke(NSInsetRect(t, -2, -2), 13, 2);
        else {
            CGFloat lx = self.dropMode == 0 ? NSMinX(t) - 4 : NSMaxX(t) + 2;
            NSRect line = NSMakeRect(round(lx), NSMinY(t) + 4, 3, NSHeight(t) - 8);
            [NSGraphicsContext saveGraphicsState];
            NSShadow *g = [NSShadow new]; g.shadowBlurRadius = 8; g.shadowOffset = NSZeroSize; g.shadowColor = [ApBlue() colorWithAlphaComponent:0.7]; [g set];
            [ApertureGradient(1) drawInBezierPath:[NSBezierPath bezierPathWithRoundedRect:line xRadius:1.5 yRadius:1.5] angle:90];
            [NSGraphicsContext restoreGraphicsState];
        }
    }
    NSString *title = src.title ?: @"";
    if (title.length > 32) title = [[title substringToIndex:31] stringByAppendingString:@"…"];
    NSDictionary *a = @{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium), NSForegroundColorAttributeName: vText};
    CGFloat w = ceil([title sizeWithAttributes:a].width) + (src.icon || src.symbol ? 44 : 24);
    NSRect chip = NSMakeRect(self.dragAt.x + 14, self.dragAt.y + (self.isFlipped ? 10 : -40), w, 30);
    [NSGraphicsContext saveGraphicsState];
    NSShadow *sh = [NSShadow new]; sh.shadowBlurRadius = 16; sh.shadowOffset = NSMakeSize(0, -6); sh.shadowColor = [NSColor colorWithWhite:0 alpha:0.4]; [sh set];
    RoundRect(chip, 15, ThemeIsLight() ? Hex(0xffffff) : Hex(0x24262c));
    [NSGraphicsContext restoreGraphicsState];
    ApertureStroke(chip, 15, 1);
    CGFloat tx = NSMinX(chip) + 12;
    NSImage *ic = src.icon ?: (src.symbol ? Tinted(Symbol(src.symbol, 12, NSFontWeightMedium), vDim) : nil);
    if (ic) { DrawImage(ic, NSMakeRect(tx, NSMidY(chip) - 8, 16, 16)); tx += 22; }
    [title drawAtPoint:NSMakePoint(tx, NSMidY(chip) - 8) withAttributes:a];
}
- (void)drawRect:(NSRect)dirty {
    NSRect b = NSInsetRect(self.bounds, 0.5, 0.5);
    RoundRect(b, 18, ThemeIsLight() ? Hex(0xf7f7f5) : Hex(0x121316));
    ShardStroke(b, 18, ThemeIsLight() ? HexA(0x000000, 0.1) : HexA(0xffffff, 0.09), 1);
    NSColor *accent = PanelAccent(self.owner);
    NSColor *card = ThemeIsLight() ? HexA(0x000000, 0.045) : Hex(0x18191d), *cardHover = ThemeIsLight() ? HexA(0x000000, 0.08) : Hex(0x212328);
    NSMutableParagraphStyle *tr = [NSMutableParagraphStyle new]; tr.lineBreakMode = NSLineBreakByTruncatingTail;
    NSMutableParagraphStyle *ctr = [NSMutableParagraphStyle new]; ctr.lineBreakMode = NSLineBreakByTruncatingTail; ctr.alignment = NSTextAlignmentCenter;
    for (NSInteger i = 0; i < (NSInteger)self.items.count; i++) {
        VPItem *it = self.items[(NSUInteger)i]; NSRect r = it.r; BOOL hov = i == self.hover;
        switch (it.kind) {
            case VPLabel: {
                [it.title drawAtPoint:NSMakePoint(NSMinX(r), NSMinY(r)) withAttributes:@{NSFontAttributeName: MMono(10.5, NSFontWeightMedium), NSForegroundColorAttributeName: vFaint, NSKernAttributeName: @1.2}];
                if (it.meta.length) {
                    NSDictionary *a = @{NSFontAttributeName: MMono(10.5, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint};
                    NSSize sz = [it.meta sizeWithAttributes:a];
                    [it.meta drawAtPoint:NSMakePoint(NSMaxX(r) - sz.width, NSMinY(r)) withAttributes:a];
                }
                break;
            }
            case VPRow: {
                if (hov || it.on) RoundRect(r, 11, hov ? cardHover : card);
                NSRect ic = NSMakeRect(NSMinX(r) + 8, NSMidY(r) - 13, 26, 26);
                RoundRect(ic, 8, ThemeIsLight() ? HexA(0x000000, 0.06) : Hex(0x22242a));
                if (it.icon) DrawImage(it.icon, NSInsetRect(ic, 5, 5));
                else if (it.symbol) { NSImage *s = Tinted(Symbol(it.symbol, 12, NSFontWeightMedium), vDim); DrawImage(s, CenterIn(s.size, ic)); }
                else { NSImage *l = PanelLetter(it.title, 26); DrawImage(l, ic); }
                NSDictionary *ma = @{NSFontAttributeName: MMono(11, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint};
                CGFloat mw = it.meta.length ? ceil([it.meta sizeWithAttributes:ma].width) + 12 : 0;
                [it.title drawInRect:NSMakeRect(NSMaxX(ic) + 12, NSMidY(r) - 9, NSWidth(r) - 58 - mw, 18) withAttributes:@{NSFontAttributeName: UIFont(13.5, NSFontWeightRegular), NSForegroundColorAttributeName: vText, NSParagraphStyleAttributeName: tr}];
                if (mw) [it.meta drawAtPoint:NSMakePoint(NSMaxX(r) - mw - 2, NSMidY(r) - 7) withAttributes:ma];
                break;
            }
            case VPToggle: {
                [it.title drawAtPoint:NSMakePoint(NSMinX(r), NSMidY(r) - 9) withAttributes:@{NSFontAttributeName: UIFont(13.5, NSFontWeightRegular), NSForegroundColorAttributeName: vText}];
                if (it.meta.length) {
                    NSDictionary *a = @{NSFontAttributeName: MMono(11, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint};
                    NSSize sz = [it.meta sizeWithAttributes:a];
                    [it.meta drawAtPoint:NSMakePoint(NSMaxX(r) - 46 - sz.width, NSMidY(r) - 7) withAttributes:a];
                }
                NSRect tk = NSMakeRect(NSMaxX(r) - 34, NSMidY(r) - 10, 34, 20);
                RoundRect(tk, 10, it.on ? accent : (ThemeIsLight() ? HexA(0x000000, 0.14) : Hex(0x2a2c31)));
                [(it.on ? NSColor.whiteColor : (ThemeIsLight() ? NSColor.whiteColor : Hex(0x8e9199))) setFill];
                [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(it.on ? NSMaxX(tk) - 18 : NSMinX(tk) + 2, NSMinY(tk) + 2, 16, 16)] fill];
                if (i + 1 < (NSInteger)self.items.count && self.items[(NSUInteger)i + 1].kind == VPToggle) { [[vText colorWithAlphaComponent:0.05] setFill]; Blend(NSMakeRect(NSMinX(r), NSMaxY(r) - 0.5, NSWidth(r), 1)); }
                break;
            }
            case VPChip: {
                RoundRect(r, NSHeight(r) / 2, it.on ? (ThemeIsLight() ? HexA(0x000000, 0.1) : Hex(0x2a2c31)) : (hov ? card : NSColor.clearColor));
                ShardStroke(r, NSHeight(r) / 2, it.on ? [vText colorWithAlphaComponent:0.16] : MGlassEdge(), 1);
                CGFloat x = NSMinX(r) + 12;
                if (it.symbol) { NSImage *s = Tinted(Symbol(it.symbol, 11, NSFontWeightMedium), it.on ? vText : vDim); DrawImage(s, NSMakeRect(x, NSMidY(r) - s.size.height / 2, s.size.width, s.size.height)); x += s.size.width + 6; }
                NSDictionary *a = @{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium), NSForegroundColorAttributeName: it.on ? vText : vDim};
                [it.title drawAtPoint:NSMakePoint(x, NSMidY(r) - 8) withAttributes:a];
                if (it.meta.length) [it.meta drawAtPoint:NSMakePoint(x + [it.title sizeWithAttributes:a].width + 6, NSMidY(r) - 7) withAttributes:@{NSFontAttributeName: MMono(11, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint}];
                break;
            }
            case VPTile: {
                CGFloat k = MIN(1, NSHeight(r) / 78), is = round(30 * k);   // smaller tiles when there are more bookmarks: everything scales together
                RoundRect(r, round(14 * k), hov ? cardHover : card);
                NSRect ic = NSMakeRect(round(NSMidX(r) - is / 2), NSMinY(r) + round(12 * k), is, is);
                RoundRect(ic, round(9 * k), ThemeIsLight() ? HexA(0x000000, 0.07) : Hex(0x26282d));
                if (it.icon) DrawImage(it.icon, NSInsetRect(ic, round(6 * k), round(6 * k))); else DrawImage(PanelLetter(it.title, is), ic);
                [it.title drawInRect:NSMakeRect(NSMinX(r) + 5, NSMaxY(r) - round(26 * k) - 1, NSWidth(r) - 10, 16) withAttributes:@{NSFontAttributeName: UIFont(MAX(10.5, 11.5 * k), NSFontWeightRegular), NSForegroundColorAttributeName: vDim, NSParagraphStyleAttributeName: ctr}];
                break;
            }
            case VPGrid: {
                RoundRect(r, 12, hov ? cardHover : card);
                NSImage *s = Tinted(Symbol(it.symbol ?: @"circle", 15, NSFontWeightRegular), it.on ? accent : vText);
                DrawImage(s, NSMakeRect(NSMidX(r) - s.size.width / 2, NSMinY(r) + 13, s.size.width, s.size.height));
                [it.title drawInRect:NSMakeRect(NSMinX(r) + 4, NSMaxY(r) - 22, NSWidth(r) - 8, 15) withAttributes:@{NSFontAttributeName: UIFont(11.5, NSFontWeightMedium), NSForegroundColorAttributeName: vDim, NSParagraphStyleAttributeName: ctr}];
                break;
            }
            case VPStat: {
                RoundRect(r, 11, card);
                [it.title drawAtPoint:NSMakePoint(NSMinX(r) + 12, NSMinY(r) + 9) withAttributes:@{NSFontAttributeName: MMono(20, NSFontWeightMedium), NSForegroundColorAttributeName: vText}];
                [it.meta drawInRect:NSMakeRect(NSMinX(r) + 12, NSMaxY(r) - 22, NSWidth(r) - 20, 15) withAttributes:@{NSFontAttributeName: UIFont(11.5, NSFontWeightRegular), NSForegroundColorAttributeName: vDim, NSParagraphStyleAttributeName: tr}];
                break;
            }
            case VPPill: {
                RoundRect(r, NSHeight(r) / 2, hov ? cardHover : (ThemeIsLight() ? HexA(0x000000, 0.06) : Hex(0x22242a)));
                NSDictionary *a = @{NSFontAttributeName: UIFont(12, NSFontWeightMedium), NSForegroundColorAttributeName: it.on ? vText : vDim};
                NSSize sz = [it.title sizeWithAttributes:a];
                CGFloat w = sz.width; NSImage *s = it.symbol ? Tinted(Symbol(it.symbol, 11, NSFontWeightMedium), it.on ? accent : vDim) : nil;
                if (s) w += s.size.width + 6;
                CGFloat x = round(NSMidX(r) - w / 2);
                if (s) { DrawImage(s, NSMakeRect(x, NSMidY(r) - s.size.height / 2, s.size.width, s.size.height)); x += s.size.width + 6; }
                [it.title drawAtPoint:NSMakePoint(x, NSMidY(r) - sz.height / 2) withAttributes:a];
                break;
            }
            case VPText: {
                [it.title drawInRect:r withAttributes:@{NSFontAttributeName: MMono(11, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint, NSParagraphStyleAttributeName: ctr}];
                break;
            }
            case VPSep: { [[vText colorWithAlphaComponent:0.06] setFill]; NSRectFillUsingOperation(r, NSCompositingOperationSourceOver); break; }
            case VPHeader: {
                NSRect ic = NSMakeRect(NSMinX(r), NSMidY(r) - 19, 38, 38);
                if (it.on && it.icon) DrawImage(it.icon, ic);   // a profile's avatar fills its own circle
                else {
                    RoundRect(ic, 10, ThemeIsLight() ? HexA(0x000000, 0.06) : Hex(0x1f2126));
                    if (it.icon) DrawImage(it.icon, NSInsetRect(ic, 10, 10)); else DrawImage(PanelLetter(it.title, 38), ic);
                }
                [it.title drawInRect:NSMakeRect(NSMaxX(ic) + 12, NSMinY(r) + 1, NSWidth(r) - 50, 18) withAttributes:@{NSFontAttributeName: UIFont(14, NSFontWeightSemibold), NSForegroundColorAttributeName: vText, NSParagraphStyleAttributeName: tr}];
                [it.meta drawInRect:NSMakeRect(NSMaxX(ic) + 12, NSMinY(r) + 22, NSWidth(r) - 50, 16) withAttributes:@{NSFontAttributeName: MMono(11.5, NSFontWeightRegular), NSForegroundColorAttributeName: vDim, NSParagraphStyleAttributeName: tr}];
                break;
            }
            case VPAvatar: {
                RoundRect(r, NSHeight(r) / 2, hov ? cardHover : card);
                ShardStroke(r, NSHeight(r) / 2, MGlassEdge(), 1);
                if (it.icon) DrawImage(it.icon, NSMakeRect(NSMinX(r) + 4, NSMidY(r) - 11, 22, 22));
                [it.title drawInRect:NSMakeRect(NSMinX(r) + 32, NSMidY(r) - 8, NSWidth(r) - 40, 16) withAttributes:@{NSFontAttributeName: UIFont(12, NSFontWeightMedium), NSForegroundColorAttributeName: vText, NSParagraphStyleAttributeName: tr}];
                break;
            }
        }
    }
    [self drawDragOverlay];
}
@end

#pragma mark Lens

// Lens: everything about the page you're on, in one place. Replaces the ⋯ menu, the shield and the site menu.
@interface VLensPanel : VPanel
@property NSInteger cookies;
@property NSInteger mode;   // 0 Lens (the browser), 1 this site (the lock), 2 blocking (the shield)
@end
@implementation VLensPanel
static NSMenuItem *Carry(id obj) { NSMenuItem *m = [NSMenuItem new]; m.representedObject = obj; return m; }
static CGFloat ChipWidth(NSString *t, NSString *meta) {
    return ceil([t sizeWithAttributes:@{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium)}].width + (meta.length ? [meta sizeWithAttributes:@{NSFontAttributeName: MMono(11, NSFontWeightRegular)}].width + 6 : 0)) + 26;
}
- (void)build {
    [self.items removeAllObjects];
    VWindow *w = self.owner; VTab *t = w.current; __weak VWindow *ww = w; __weak VLensPanel *ws = self;
    CGFloat W = self.mode == 0 ? 384 : 340, P = 16, x = P, cw = W - 2 * P, y = P;
    NSURL *u = [NSURL URLWithString:t.url ?: @""];
    BOOL web = [u.scheme hasPrefix:@"http"] && !t.isHome;
    NSString *host = web ? HostOf(u) : @"";
    NSString *site = [host hasPrefix:@"www."] ? [host substringFromIndex:4] : host;

    if (self.mode == 3) {   // ---- the puzzle: your extensions ----
        NSArray *exts = FExtHost.shared.extensions;
        VPItem *h = [self add:VPHeader rect:NSMakeRect(x, y, cw, 40) title:@"Extensions"];
        h.icon = Tinted(Symbol(@"puzzlepiece.extension", 16, NSFontWeightMedium), vText);
        h.meta = w.isPrivate ? @"They don't run in private windows" : [NSString stringWithFormat:@"%lu installed · pin one to keep it beside this button", (unsigned long)exts.count];
        y += 40 + 14;
        for (id e in exts) {
            NSString *ident = [e valueForKey:@"ident"];
            BOOL pinned = ExtensionPinned(ident), opts = [FExtHost.shared hasOptionsForID:ident];
            NSString *name = [e valueForKey:@"name"] ?: @"Extension";
            NSRange cut = [name rangeOfString:@" - "]; if (cut.location == NSNotFound) cut = [name rangeOfString:@": "];
            VPItem *row = [self add:VPRow rect:NSMakeRect(x - 8, y, cw - (opts ? 104 : 64), 36) title:cut.location != NSNotFound ? [name substringToIndex:cut.location] : name];
            row.icon = [FExtHost.shared iconFor:e];
            if (!w.isPrivate) row.act = ^(NSEvent *ev, NSRect r) { [ws.owner closePanels]; [FExtHost.shared openPopup:e from:ww.toolbar.extMenuBtn]; };
            if (opts) { VPItem *o = [self add:VPPill rect:NSMakeRect(x + cw - 100, y + 5, 32, 26) title:@""]; o.symbol = @"gearshape";
                        o.act = ^(NSEvent *ev, NSRect r) { [ws.owner closePanels]; [FExtHost.shared openOptionsForID:ident]; }; }
            VPItem *pin = [self add:VPPill rect:NSMakeRect(x + cw - 64, y + 5, 64, 26) title:pinned ? @"Pinned" : @"Pin"]; pin.on = pinned; pin.symbol = pinned ? @"pin.fill" : @"pin";
            pin.act = ^(NSEvent *ev, NSRect r) {
                NSMutableArray *p = [[Defaults() arrayForKey:kExtPinned] ?: @[] mutableCopy];
                if ([p containsObject:ident]) [p removeObject:ident]; else [p addObject:ident];
                [Defaults() setObject:p forKey:kExtPinned];
                for (VWindow *o in gWindows) { [o.toolbar layoutBar]; [o refreshChrome]; }
                [ws rebuild];
            };
            y += 38;
        }
        y += 10;
        CGFloat half = (cw - 8) / 2;
        VPItem *mg = [self add:VPPill rect:NSMakeRect(x, y, half, 30) title:@"Manage"]; mg.symbol = @"slider.horizontal.3";
        mg.act = ^(NSEvent *ev, NSRect r) { [ws.owner closePanels]; [ww showSettingsSection:@"extensions"]; };
        VPItem *more = [self add:VPPill rect:NSMakeRect(x + half + 8, y, half, 30) title:@"Get more"]; more.symbol = @"bag";
        more.act = ^(NSEvent *ev, NSRect r) { [ws.owner closePanels]; [ww newTab:[NSURL URLWithString:@"https://chromewebstore.google.com/"] select:YES]; };
        y += 30 + P;
        [self setFrameSize:NSMakeSize(W, y)]; self.needsDisplay = YES; return;
    }
    if (self.mode == 1) {   // ---- the lock: this site ----
        VPItem *h = [self add:VPHeader rect:NSMakeRect(x, y, cw, 40) title:web ? host : (t.isHome ? @"New Tab" : t.title ?: @"Iris")];
        h.icon = t.favicon;
        h.meta = !web ? @"Iris page" : [u.scheme isEqualToString:@"https"] ? @"Secure connection · WebKit" : @"Not secure · this page isn't encrypted";
        y += 40 + 14;
        if (web) {
            CGFloat sw = floor((cw - 8) / 2);
            VPItem *s1 = [self add:VPStat rect:NSMakeRect(x, y, sw, 62) title:self.cookies >= 0 ? [NSString stringWithFormat:@"%ld", (long)self.cookies] : @"–"]; s1.meta = @"Cookies";
            VPItem *s2 = [self add:VPStat rect:NSMakeRect(x + sw + 8, y, cw - sw - 8, 62) title:[NSString stringWithFormat:@"%d%%", (int)round((t.web.zoom ?: 1) * 100)]]; s2.meta = @"Zoom";
            y += 62 + 16;
            BOOL js = [Defaults() boolForKey:kScripts] && ![SiteArray(self.owner.isPrivate, kJSOff) containsObject:host];
            VPItem *jv = [self add:VPToggle rect:NSMakeRect(x, y, cw, 40) title:@"JavaScript"]; jv.on = js;
            jv.act = ^(NSEvent *e, NSRect r) { [ww toggleSiteScripts:Carry(host)]; [ws rebuild]; };
            y += 48;
            [self add:VPLabel rect:NSMakeRect(x, y, cw, 14) title:@"PERMISSIONS"]; y += 20;
            NSDictionary *perms = SiteDict(self.owner.isPrivate, kSitePerms)[host];
            CGFloat cx = x;
            for (NSString *k in @[@"location", @"camera", @"microphone"]) {
                NSInteger v = [perms[k] integerValue];
                NSString *state = v == 1 ? @"Allow" : v == 2 ? @"Block" : @"Ask";
                NSString *t1 = k.capitalizedString;
                CGFloat chipW = ChipWidth(t1, state);
                if (cx + chipW > x + cw) { cx = x; y += 36; }   // wrap onto a second row
                VPItem *c = [self add:VPChip rect:NSMakeRect(cx, y, chipW, 30) title:t1]; c.meta = state;
                c.act = ^(NSEvent *e, NSRect r) { [ww setSitePermission:Carry(@[host, k, @((v + 1) % 3)])]; [ws rebuild]; };
                cx += NSWidth(c.r) + 6;
            }
            y += 30 + 18;
            CGFloat bw = floor((cw - 8) / 2);
            VPItem *cl = [self add:VPPill rect:NSMakeRect(x, y, bw, 30) title:@"Clear site data…"];
            cl.act = ^(NSEvent *e, NSRect r) { [ws.owner closePanels]; [ww clearSiteData:Carry(host)]; };
            VPItem *cp = [self add:VPPill rect:NSMakeRect(x + bw + 8, y, cw - bw - 8, 30) title:@"Copy link"]; cp.symbol = @"link";
            cp.act = ^(NSEvent *e, NSRect r) { NSPasteboard *pb = NSPasteboard.generalPasteboard; [pb clearContents]; [pb setString:t.url forType:NSPasteboardTypeString]; [ww showToast:@"Link copied"]; [ws.owner closePanels]; };
            y += 30;
        } else {
            [self add:VPText rect:NSMakeRect(x, y, cw, 16) title:@"Nothing to set for this page"]; y += 16;
        }
        y += P;
        [self setFrameSize:NSMakeSize(W, y)]; self.needsDisplay = YES; return;
    }

    if (self.mode == 2) {   // ---- the shield: blocking ----
        BOOL global = [Defaults() boolForKey:kBlock], allowed = [SiteArray(self.owner.isPrivate, kAllowlist) containsObject:host];
        VPItem *h = [self add:VPHeader rect:NSMakeRect(x, y, cw, 40) title:!global ? @"Blocking is off" : (web && allowed) ? [@"Allowed on " stringByAppendingString:host] : @"Blocking ads and trackers"];
        h.icon = Tinted(Symbol(global && !(web && allowed) ? @"checkmark.shield" : @"shield.slash", 16, NSFontWeightMedium), vText);
        h.meta = [@"Filter lists · " stringByAppendingString:VBlocker.shared.status ?: @""];
        y += 40 + 14;
        CGFloat sw = floor((cw - 8) / 2);
        VPItem *s1 = [self add:VPStat rect:NSMakeRect(x, y, sw, 62) title:[NSString stringWithFormat:@"%ld", (long)t.blocked]]; s1.meta = @"On this page";
        VPItem *s2 = [self add:VPStat rect:NSMakeRect(x + sw + 8, y, cw - sw - 8, 62) title:gRuleCount >= 1000 ? [NSString stringWithFormat:@"%.0fk", gRuleCount / 1000.0] : [NSString stringWithFormat:@"%lu", (unsigned long)gRuleCount]]; s2.meta = @"Rules in the lists";
        y += 62 + 16;
        if (web) {
            VPItem *bs = [self add:VPToggle rect:NSMakeRect(x, y, cw, 40) title:[@"Block on " stringByAppendingString:site]]; bs.on = global && !allowed;
            bs.act = ^(NSEvent *e, NSRect r) { if (!global) [ww toggleBlockingGlobal:nil]; else [ww toggleBlockingSite:Carry(host)]; [ws rebuild]; };
            y += 40;
        }
        VPItem *ga = [self add:VPToggle rect:NSMakeRect(x, y, cw, 40) title:@"Block everywhere"]; ga.on = global;
        ga.act = ^(NSEvent *e, NSRect r) { [ww toggleBlockingGlobal:nil]; [ws rebuild]; };
        y += 48;
        if (web) {
            NSUInteger hidden = [SiteDict(self.owner.isPrivate, @"cosmeticFilters")[site] count];
            VPItem *be = [self add:VPPill rect:NSMakeRect(x, y, cw, 30) title:@"Block an element on this page…"]; be.symbol = @"hand.point.up.left";
            be.act = ^(NSEvent *e, NSRect r) { [ws.owner closePanels]; [ww blockElement:nil]; };
            y += 36;
            if (hidden) {
                CGFloat bw = floor((cw - 8) / 2);
                VPItem *un = [self add:VPPill rect:NSMakeRect(x, y, bw, 30) title:@"Undo last"];
                un.act = ^(NSEvent *e, NSRect r) { [ww undoLastElement:Carry(site)]; [ws rebuild]; };
                VPItem *sa = [self add:VPPill rect:NSMakeRect(x + bw + 8, y, cw - bw - 8, 30) title:[NSString stringWithFormat:@"Show %lu hidden", (unsigned long)hidden]];
                sa.act = ^(NSEvent *e, NSRect r) { [ww resetElements:Carry(site)]; [ws rebuild]; };
                y += 36;
            }
        }
        VPItem *up = [self add:VPPill rect:NSMakeRect(x, y, cw, 30) title:@"Update filter lists now"]; up.symbol = @"arrow.clockwise";
        up.act = ^(NSEvent *e, NSRect r) { [ww updateListsNow:nil]; [ws.owner closePanels]; };
        y += 30 + P;
        [self setFrameSize:NSMakeSize(W, y)]; self.needsDisplay = YES; return;
    }

    // ---- Lens: the browser (the page's own settings live behind the lock and the shield) ----
    // the top of Lens is you: the profile this window belongs to, and a way to change it
    void (^profiles)(NSEvent *, NSRect) = ^(NSEvent *e, NSRect r) {
        NSView *root = ww.window.contentView;
        NSRect rr = [root convertRect:r fromView:nil];
        PopMenu([ww profilesMenu], NSMakePoint(NSMinX(rr), NSMaxY(rr) + 4), root);
    };
    VPItem *h = [self add:VPHeader rect:NSMakeRect(x, y, w.isPrivate ? cw : cw - 140, 40) title:w.isPrivate ? @"Private window" : ProfileName(w.profile)];
    if (w.isPrivate) { h.icon = Tinted(Symbol(@"eye.slash", 16, NSFontWeightMedium), vText); h.meta = @"Nothing is kept when it closes"; }
    else if (IrisIsDev()) {   // the testing copy says so, plainly, wherever you'd look for whose browser this is
        h.title = @"Iris Dev"; h.icon = NSApp.applicationIconImage; h.on = YES;
        h.meta = [NSString stringWithFormat:@"Testing copy · %@ profile · its own tabs and sign-ins", ProfileName(w.profile)];
        VPItem *ch = [self add:VPPill rect:NSMakeRect(W - P - 132, y + 6, 132, 28) title:@"Change profile"]; ch.symbol = @"person.2";
        ch.act = profiles;
    }
    else {
        h.icon = ProfileAvatar(w.profile, ProfileName(w.profile), 38); h.on = YES; h.meta = @"Profile";
        VPItem *ch = [self add:VPPill rect:NSMakeRect(W - P - 132, y + 6, 132, 28) title:@"Change profile"]; ch.symbol = @"person.2";
        ch.act = profiles;
    }
    y += 40 + 16;

    if (t.web) {
        [self add:VPLabel rect:NSMakeRect(x, y + 9, 60, 14) title:@"ZOOM"];
        CGFloat zx = x + cw - 170;
        VPItem *zo = [self add:VPPill rect:NSMakeRect(zx, y, 44, 30) title:@"−"]; zo.act = ^(NSEvent *e, NSRect r) { [ww zoomOut:nil]; [ws rebuild]; };
        VPItem *zr = [self add:VPPill rect:NSMakeRect(zx + 50, y, 70, 30) title:[NSString stringWithFormat:@"%d%%", (int)round(t.web.zoom * 100)]]; zr.on = YES; zr.act = ^(NSEvent *e, NSRect r) { [ww zoomReset:nil]; [ws rebuild]; };
        VPItem *zi = [self add:VPPill rect:NSMakeRect(zx + 126, y, 44, 30) title:@"+"]; zi.act = ^(NSEvent *e, NSRect r) { [ww zoomIn:nil]; [ws rebuild]; };
        y += 30 + 16;
    }

    CGFloat gw = floor((cw - 16) / 3);
    NSArray *grid = @[@[@"Find", @"magnifyingglass", @"showFind:"], @[@"Split", @"rectangle.split.2x1", @"toggleSplit:"], @[@"Share", @"square.and.arrow.up", @"sharePage:"],
                      @[@"Bookmarks", @"book", @"showBookmarks:"], @[@"History", @"clock", @"showHistory:"], @[@"Downloads", @"arrow.down.circle", @"showDownloadManager:"],
                      @[@"New window", @"macwindow.badge.plus", @"newWindow:"], @[@"Private", @"eye.slash", @"newPrivateWindow:"], @[@"Settings", @"gearshape", @"showSettings:"]];
    for (NSUInteger i = 0; i < grid.count; i++) {
        NSArray *g = grid[i];
        VPItem *it = [self add:VPGrid rect:NSMakeRect(x + (i % 3) * (gw + 8), y + (i / 3) * 66, gw, 58) title:g[0]];
        it.symbol = g[1];
        SEL sel = NSSelectorFromString(g[2]);
        it.act = ^(NSEvent *e, NSRect r) {
            [ws.owner closePanels];
            id target = [ww respondsToSelector:sel] ? ww : gApp;
            if ([target respondsToSelector:sel]) [NSApp sendAction:sel to:target from:ww.toolbar.menuBtn];
        };
    }
    y += 3 * 66 + 6;
    if (web) {
        BOOL other = !IrisIsDefaultBrowser() && !IrisIsDev();   // Iris Dev is never your browser
        CGFloat bw = other ? floor((cw - 8) / 2) : cw;
        VPItem *src = [self add:VPPill rect:NSMakeRect(x, y, bw, 28) title:@"View source"]; src.act = ^(NSEvent *e, NSRect r) { [ws.owner closePanels]; [ww viewSource:nil]; };
        if (other) {
            VPItem *ext = [self add:VPPill rect:NSMakeRect(x + bw + 8, y, bw, 28) title:@"Open in default browser"];
            ext.act = ^(NSEvent *e, NSRect r) { [ws.owner closePanels]; [NSWorkspace.sharedWorkspace openURL:u]; };
        }
        y += 28 + 12;
    }
    [self add:VPText rect:NSMakeRect(x, y, cw, 14) title:@"⌘. opens Lens"];
    y += 14 + P;
    [self setFrameSize:NSMakeSize(W, y)];
    self.needsDisplay = YES;
}
- (void)rebuild {
    [self build];
    PanelShadow(self);
}
- (void)countCookies {
    VWindow *w = self.owner; NSString *host = HostOf([NSURL URLWithString:w.current.url ?: @""]);
    self.cookies = -1;
    if (!host.length) return;
    WKWebsiteDataStore *ds = w.isPrivate ? w.privateStore : ProfileStore(w.profile);
    __weak VLensPanel *ws = self;
    NSString *bare = [host hasPrefix:@"www."] ? [host substringFromIndex:4] : host;
    [ds.httpCookieStore getAllCookies:^(NSArray<NSHTTPCookie *> *all) {
        NSInteger n = 0;
        for (NSHTTPCookie *c in all) { NSString *d = [c.domain hasPrefix:@"."] ? [c.domain substringFromIndex:1] : c.domain; if ([bare hasSuffix:d] || [d hasSuffix:bare]) n++; }
        dispatch_async(dispatch_get_main_queue(), ^{ ws.cookies = n; if (ws.shown) [ws rebuild]; });
    }];
}
@end

#pragma mark Address popup

// Click the address: it's selected, ready to type over, and your bookmarks open underneath it —
// folders as chips (the one you open shows in place), loose bookmarks as tiles, then your other open tabs.
@interface VAddressPanel : VPanel
@property (strong) NSMutableArray *path;   // the folder you've opened, as a chain of folder dictionaries
@end
@implementation VAddressPanel
// Right-click menus for what the address popup shows. Actions that change the bookmarks close the popup first,
// so it never shows something that's gone.
- (void)menuOpenHere:(NSMenuItem *)m { [self open:m.representedObject event:nil]; }
- (void)menuEdit:(NSMenuItem *)m { VWindow *w = self.owner; [w closePanels]; [w editBookmark:m]; }
- (void)menuDelete:(NSMenuItem *)m { VWindow *w = self.owner; [w closePanels]; [w deleteBookmark:m]; }
- (void)menuSwitch:(NSMenuItem *)m { VWindow *w = self.owner; [w closePanels]; [w selectTab:m.representedObject]; }
- (void)menuCloseTab:(NSMenuItem *)m { VWindow *w = self.owner; [w closeTab:m.representedObject]; [self rebuildKeepingWidth]; }
- (void)menuSplitTab:(NSMenuItem *)m { VWindow *w = self.owner; [w closePanels]; [w menuSplit:m]; }
- (NSMenu *)menuForBookmark:(NSDictionary *)n {
    VWindow *w = self.owner; NSMenu *c = [[NSMenu alloc] initWithTitle:@""];
    NSMenuItem *(^add)(NSString *, SEL, id, id) = ^NSMenuItem *(NSString *t, SEL a, id target, id obj) { NSMenuItem *it = [c addItemWithTitle:t action:a keyEquivalent:@""]; it.target = target; it.representedObject = obj; return it; };
    NSString *name = [n[@"name"] length] ? n[@"name"] : HostOf([NSURL URLWithString:n[@"url"] ?: @""]);
    [c addItem:[[NSMenuItem alloc] initWithTitle:name ?: @"Bookmark" action:nil keyEquivalent:@""]];
    if (n[@"url"]) {
        add(@"Open", @selector(menuOpenHere:), self, n[@"url"]);
        add(@"Open in New Tab", @selector(openBookmarkInNewTab:), w, n[@"url"]);
        add(@"Open in Background Tab", @selector(openBookmarkInBackground:), w, n[@"url"]);
        add(@"Open in Split View", @selector(splitLink:), w, n[@"url"]);
        [c addItem:NSMenuItem.separatorItem];
        add(@"Copy Link", @selector(copyText:), w, n[@"url"]);
        add(@"Edit…", @selector(menuEdit:), self, n);
    } else {
        NSMutableArray *urls = [NSMutableArray array]; for (NSDictionary *x in n[@"children"]) if (x[@"url"]) [urls addObject:x[@"url"]];
        add([NSString stringWithFormat:@"Open All in Tabs (%lu)", (unsigned long)urls.count], @selector(openAllBookmarks:), w, urls).enabled = urls.count > 0;
        [c addItem:NSMenuItem.separatorItem];
        add(@"Rename…", @selector(menuEdit:), self, n);
    }
    add(@"Delete", @selector(menuDelete:), self, n);
    return c;
}
- (NSMenu *)menuForTab:(VTab *)o {
    VWindow *w = self.owner; NSMenu *c = [[NSMenu alloc] initWithTitle:@""];
    NSMenuItem *(^add)(NSString *, SEL, id, id) = ^NSMenuItem *(NSString *t, SEL a, id target, id obj) { NSMenuItem *it = [c addItemWithTitle:t action:a keyEquivalent:@""]; it.target = target; it.representedObject = obj; return it; };
    add(@"Switch to Tab", @selector(menuSwitch:), self, o);
    add(@"Split View with Current Tab", @selector(menuSplitTab:), self, o);
    if (o.url && !o.isHome) add(@"Copy Link", @selector(copyText:), w, o.url);
    if (o.web && (o.audible || o.muted)) add(o.muted ? @"Unmute Tab" : @"Mute Tab", @selector(menuMute:), w, o);
    [c addItem:NSMenuItem.separatorItem];
    add(@"Close Tab", @selector(menuCloseTab:), self, o);
    return c;
}
- (void)open:(NSString *)url event:(NSEvent *)e {
    VWindow *w = self.owner;
    NSURL *u = [NSURL URLWithString:url]; if (!u) return;
    BOOL nt = (e.modifierFlags & NSEventModifierFlagCommand) != 0;
    [w closePanels];
    [w.window makeFirstResponder:w.current.web.web ?: w.window.contentView];
    [w openURL:u newTab:nt];
}
- (void)build {
    [self.items removeAllObjects];
    VWindow *w = self.owner; VTab *t = w.current; __weak VWindow *ww = w; __weak VAddressPanel *ws = self;
    if (!self.path) self.path = [NSMutableArray array];
    CGFloat W = MAX(560, NSWidth(self.frame) > 0 ? NSWidth(self.frame) : 640), P = 16, x = P, cw = W - 2 * P, y = 12;
    NSURL *u = [NSURL URLWithString:t.url ?: @""];
    BOOL web = !t.isHome && [u.scheme hasPrefix:@"http"];

    if (web) {   // the page you're on: save, copy or share it
        BOOL saved = [VBookmarks.shared find:t.url] != nil;
        VPItem *row = [self add:VPRow rect:NSMakeRect(x - 6, y, cw - 260, 40) title:t.title.length ? t.title : HostOf(u)];
        row.icon = t.favicon; row.meta = nil;
        CGFloat bx = x + cw - 252;
        VPItem *sv = [self add:VPPill rect:NSMakeRect(bx, y + 6, 84, 28) title:saved ? @"Saved" : @"Save"]; sv.symbol = saved ? @"star.fill" : @"star"; sv.on = saved;
        sv.act = ^(NSEvent *e, NSRect r) { [ww toggleBookmark:nil]; [ws rebuildKeepingWidth]; };
        VPItem *cp = [self add:VPPill rect:NSMakeRect(bx + 90, y + 6, 92, 28) title:@"Copy link"]; cp.symbol = @"link";
        cp.act = ^(NSEvent *e, NSRect r) { NSPasteboard *pb = NSPasteboard.generalPasteboard; [pb clearContents]; [pb setString:t.url forType:NSPasteboardTypeString]; [ww showToast:@"Link copied"]; [ws.owner closePanels]; };
        VPItem *sh = [self add:VPPill rect:NSMakeRect(bx + 188, y + 6, 64, 28) title:@"Share"];
        sh.act = ^(NSEvent *e, NSRect r) { [ws.owner closePanels]; [ww sharePage:nil]; };
        y += 40 + 10;
        [self add:VPSep rect:NSMakeRect(0, y, W, 1) title:@""]; y += 14;
    }

    VPItem *bl = [self add:VPLabel rect:NSMakeRect(x, y, cw - 70, 14) title:@"BOOKMARKS"]; (void)bl;
    VPItem *mg = [self add:VPPill rect:NSMakeRect(x + cw - 72, y - 6, 72, 26) title:@"Manage"];
    mg.act = ^(NSEvent *e, NSRect r) { [ws.owner closePanels]; [ww showBookmarks:nil]; };
    y += 24;

    NSArray *bar = VBookmarks.shared.bar ?: @[];
    NSMutableArray *folders = [NSMutableArray array], *links = [NSMutableArray array];
    for (NSDictionary *b in bar) [([b[@"children"] isKindOfClass:NSArray.class] ? folders : links) addObject:b];
    if (!bar.count) { [self add:VPText rect:NSMakeRect(x, y + 4, cw, 16) title:@"No bookmarks yet · ⌘D saves the page you're on"]; y += 30; }

    // folder chips; the open one is filled in
    NSDictionary *openTop = self.path.firstObject;
    CGFloat cx = x;
    for (NSDictionary *f in folders) {
        NSString *name = [f[@"name"] length] ? f[@"name"] : @"Folder";
        NSString *count = [NSString stringWithFormat:@"%lu", (unsigned long)[f[@"children"] count]];
        CGFloat wid = ceil([name sizeWithAttributes:@{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium)}].width + [count sizeWithAttributes:@{NSFontAttributeName: MMono(11, NSFontWeightRegular)}].width) + 50;
        if (cx + wid > x + cw) { cx = x; y += 36; }
        VPItem *c = [self add:VPChip rect:NSMakeRect(cx, y, wid, 30) title:name]; c.symbol = @"folder"; c.meta = count; c.on = openTop == f;
        c.menu = ^NSMenu *{ return [ws menuForBookmark:f]; };
        c.node = (NSMutableDictionary *)f; c.list = VBookmarks.shared.bar;
        c.act = ^(NSEvent *e, NSRect r) { if (ws.path.firstObject == f) [ws.path removeAllObjects]; else { [ws.path removeAllObjects]; [ws.path addObject:f]; } [ws rebuildKeepingWidth]; };
        cx += wid + 6;
    }
    if (folders.count) y += 30 + 12;

    if (self.path.count) {   // the open folder, in place
        NSDictionary *cur = self.path.lastObject;
        NSArray *kids = cur[@"children"];
        if (self.path.count > 1) {
            VPItem *bk = [self add:VPPill rect:NSMakeRect(x, y, 90, 26) title:@"Back"]; bk.symbol = @"chevron.left";
            bk.act = ^(NSEvent *e, NSRect r) { [ws.path removeLastObject]; [ws rebuildKeepingWidth]; };
            [self add:VPLabel rect:NSMakeRect(x + 100, y + 6, cw - 100, 14) title:[cur[@"name"] uppercaseString] ?: @""];
            y += 34;
        }
        CGFloat colW = floor((cw - 8) / 2);
        NSUInteger i = 0;
        for (NSDictionary *b in kids) {
            BOOL isFolder = [b[@"children"] isKindOfClass:NSArray.class];
            NSString *name = [b[@"name"] length] ? b[@"name"] : (HostOf([NSURL URLWithString:b[@"url"] ?: @""]) ?: @"");
            VPItem *row = [self add:VPRow rect:NSMakeRect(x - 6 + (i % 2) * (colW + 8), y + (i / 2) * 40, colW + 6, 38) title:name];
            row.menu = ^NSMenu *{ return [ws menuForBookmark:b]; };
            row.node = (NSMutableDictionary *)b; row.list = BMChildren((NSMutableDictionary *)cur);
            if (isFolder) { row.symbol = @"folder"; row.meta = [NSString stringWithFormat:@"%lu", (unsigned long)[b[@"children"] count]];
                row.act = ^(NSEvent *e, NSRect r) { [ws.path addObject:b]; [ws rebuildKeepingWidth]; }; }
            else { row.icon = [VFavicons.shared iconForURL:b[@"url"]]; row.meta = HostOf([NSURL URLWithString:b[@"url"] ?: @""]);
                NSString *url = b[@"url"]; row.act = ^(NSEvent *e, NSRect r) { [ws open:url event:e]; }; }
            i++;
            if (i >= 16) break;
        }
        if (!kids.count) { [self add:VPText rect:NSMakeRect(x, y + 4, cw, 16) title:@"This folder is empty"]; y += 30; }
        else y += ((MIN(kids.count, 16) + 1) / 2) * 40 + 10;
    }

    if (links.count) {   // loose bookmarks as tiles: every one shows. More of them, smaller tiles, two rows; past what fits, a third row
        const CGFloat gap = 8, minW = 66;
        NSUInteger n = links.count;
        NSInteger cols = MAX(4, (NSInteger)floor((cw + gap) / 102));
        if ((NSInteger)n > cols * 2) cols = MIN((NSInteger)ceil(n / 2.0), MAX(4, (NSInteger)floor((cw + gap) / (minW + gap))));
        CGFloat tw = floor((cw - (cols - 1) * gap) / cols);
        CGFloat th = round(MAX(60, MIN(78, 78 * tw / 96))), step = th + 8;
        NSUInteger i = 0;
        for (NSDictionary *b in links) {
            NSString *name = [b[@"name"] length] ? b[@"name"] : (HostOf([NSURL URLWithString:b[@"url"] ?: @""]) ?: @"");
            VPItem *tile = [self add:VPTile rect:NSMakeRect(x + (i % cols) * (tw + gap), y + (i / cols) * step, tw, th) title:name];
            tile.icon = [VFavicons.shared iconForURL:b[@"url"]];
            NSString *url = b[@"url"]; tile.act = ^(NSEvent *e, NSRect r) { [ws open:url event:e]; };
            tile.menu = ^NSMenu *{ return [ws menuForBookmark:b]; };
            tile.node = (NSMutableDictionary *)b; tile.list = VBookmarks.shared.bar;
            i++;
        }
        y += ((n + cols - 1) / cols) * step + 6;
    }

    // your other open tabs, the most recent first
    NSMutableArray *others = [NSMutableArray array];
    for (VTab *o in w.tabs) if (o != t) [others addObject:o];
    [others sortUsingComparator:^NSComparisonResult(VTab *a, VTab *b) { return a.hiddenAt > b.hiddenAt ? NSOrderedAscending : a.hiddenAt < b.hiddenAt ? NSOrderedDescending : NSOrderedSame; }];
    if (others.count) {
        [self add:VPSep rect:NSMakeRect(0, y + 4, W, 1) title:@""]; y += 18;
        [self add:VPLabel rect:NSMakeRect(x, y, cw, 14) title:@"OPEN TABS"]; y += 20;
        NSUInteger n = 0;
        for (VTab *o in others) {
            VPItem *row = [self add:VPRow rect:NSMakeRect(x - 6, y, cw + 12, 36) title:o.isHome ? @"New Tab" : (o.title.length ? o.title : o.url ?: @"")];
            row.icon = o.favicon; row.meta = o.audible && !o.muted ? @"playing" : (!o.web && !o.isHome ? @"asleep" : HostOf([NSURL URLWithString:o.url ?: @""]));
            row.act = ^(NSEvent *e, NSRect r) { [ws.owner closePanels]; [ww selectTab:o]; };
            row.menu = ^NSMenu *{ return [ws menuForTab:o]; };
            y += 38;
            if (++n >= 4) break;
        }
    }
    y += 6;
    [self add:VPSep rect:NSMakeRect(0, y, W, 1) title:@""];
    [self add:VPText rect:NSMakeRect(x, y + 12, cw, 14) title:@"type to go or search  ·  ⌘D bookmark  ·  esc close"];
    y += 12 + 14 + 12;
    [self setFrameSize:NSMakeSize(W, y)];
    self.needsDisplay = YES;
}
- (void)rebuildKeepingWidth {
    [self build];
    PanelShadow(self);
}
@end

#pragma mark Opening and closing them

@implementation VWindow (Panels)
- (VLensPanel *)lens {
    if (!self.lensPanel) { VLensPanel *p = [[VLensPanel alloc] initWithFrame:NSMakeRect(0, 0, 384, 400)]; p.owner = self; self.lensPanel = p; [self.window.contentView addSubview:p]; }
    return (VLensPanel *)self.lensPanel;
}
- (VAddressPanel *)addressPopup {
    if (!self.addressPanel) { VAddressPanel *p = [[VAddressPanel alloc] initWithFrame:NSMakeRect(0, 0, 640, 300)]; p.owner = self; self.addressPanel = p; [self.window.contentView addSubview:p]; }
    return (VAddressPanel *)self.addressPanel;
}
- (void)openLensMode:(NSInteger)mode under:(NSRect)anchorInBar {
    VLensPanel *p = [self lens];
    if (p.shown && p.mode == mode) { [p dismiss]; return; }
    [(VPanel *)self.addressPanel dismiss];
    [self showShelf:NO];
    p.mode = mode; p.cookies = -1; [p build];
    if (mode != 2) [p countCookies];
    NSView *root = self.window.contentView; VToolbar *tb = self.toolbar;
    NSRect lr = [root convertRect:anchorInBar fromView:tb];
    CGFloat W = NSWidth(p.frame), H = NSHeight(p.frame);
    CGFloat px = MAX(8, MIN(NSWidth(root.bounds) - W - 8, round(NSMidX(lr) - W / 2)));
    NSRect f = NSMakeRect(px, NSMaxY([root convertRect:tb.pill fromView:tb]) + 8, W, H);
    if (p.shown) { p.frame = f; PanelShadow(p); p.needsDisplay = YES; return; }
    p.irisX = NSMidX(lr) - px;   // it opens from the button you pressed
    [p present:f];
}
- (void)toggleLens:(id)s { [self openLensMode:0 under:self.toolbar.lensRect]; }
- (void)toggleSitePanel:(id)s { [self openLensMode:1 under:self.toolbar.infoBtn.frame]; }
- (void)toggleShieldPanel:(id)s { [self openLensMode:2 under:self.toolbar.shieldBtn.frame]; }
- (void)toggleExtensionsPanel:(id)s { [self openLensMode:3 under:self.toolbar.extMenuBtn.frame]; }
- (void)showAddressPanel {
    VAddressPanel *p = [self addressPopup];
    NSView *root = self.window.contentView; VToolbar *tb = self.toolbar;
    if (!tb.capsule || tb.hidden) return;
    [(VPanel *)self.lensPanel dismiss];
    NSRect pr = [root convertRect:tb.pill fromView:tb];
    CGFloat W = MIN(NSWidth(root.bounds) - 16, MAX(NSWidth(pr) + 120, 640));
    [p setFrameSize:NSMakeSize(W, 10)];
    [p.path removeAllObjects];
    [p build];
    CGFloat px = MAX(8, MIN(NSWidth(root.bounds) - W - 8, round(NSMidX(pr) - W / 2)));
    if (p.shown) { p.frame = NSMakeRect(px, NSMaxY(pr) + 8, W, NSHeight(p.frame)); return; }
    [p present:NSMakeRect(px, NSMaxY(pr) + 8, W, NSHeight(p.frame))];
}
- (void)showBookmarkPopup:(id)s { [self focusAddress]; }   // ⇧⌘B: the address, with your bookmarks under it
- (void)hideAddressPanel { [(VPanel *)self.addressPanel dismiss]; }
- (void)closePanels { [(VPanel *)self.lensPanel dismiss]; [(VPanel *)self.addressPanel dismiss]; }
- (BOOL)panelOpen { return ((VPanel *)self.lensPanel).shown || ((VPanel *)self.addressPanel).shown; }
- (BOOL)point:(NSPoint)p inPanelOrBar:(NSView *)root {
    for (NSView *v in @[self.lensPanel ?: NSNull.null, self.addressPanel ?: NSNull.null]) if ([v isKindOfClass:NSView.class] && !v.hidden && NSPointInRect(p, v.frame)) return YES;
    NSView *hit = [self.toolbar hitTest:[root convertPoint:p toView:self.toolbar.superview]];
    return hit != nil;
}
@end
#pragma mark - Browser window

@interface VRoot : NSView
@end
@implementation VRoot
- (BOOL)isFlipped { return YES; }
- (void)drawRect:(NSRect)r {
    [vBg setFill]; NSRectFill(NSIntersectionRect(r, self.bounds));
    // The band above the page takes the page's own top colour, so page and band read as one surface (Safari's
    // coloured tab bar). The capsules are near-opaque glass, so they stay legible on any colour. The colour runs
    // under the page's rounded top corners too, so they melt into it; a faint shade at the very top keeps the window's edge.
    VWindow *w = WinFor(self);
    NSColor *c = [w.current.headerColor colorUsingColorSpace:NSColorSpace.sRGBColorSpace];
    if (!c || gWebApp) return;
    CGFloat band = NSMinY(w.content.frame) + 12;
    [c setFill]; NSRectFill(NSMakeRect(0, 0, NSWidth(self.bounds), band));
    CGFloat lum = 0.2126 * c.redComponent + 0.7152 * c.greenComponent + 0.0722 * c.blueComponent;
    NSGradient *g = [[NSGradient alloc] initWithStartingColor:[NSColor colorWithWhite:lum > 0.5 ? 0 : 1 alpha:lum > 0.5 ? 0.05 : 0.035] endingColor:[NSColor colorWithWhite:0 alpha:0]];
    [g drawInRect:NSMakeRect(0, 0, NSWidth(self.bounds), 14) angle:90];
}
- (void)resizeSubviewsWithOldSize:(NSSize)s { [WinFor(self) layout]; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
// Leaving the window (say, down through the tab strip) puts the strip away, unless you opened it on purpose.
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    for (NSTrackingArea *t in self.trackingAreas.copy) [self removeTrackingArea:t];
    [self addTrackingArea:[[NSTrackingArea alloc] initWithRect:NSZeroRect options:NSTrackingMouseEnteredAndExited | NSTrackingActiveAlways | NSTrackingInVisibleRect owner:self userInfo:nil]];
}
- (void)mouseExited:(NSEvent *)e {
    VWindow *w = WinFor(self);
    VTabShelf *s = (VTabShelf *)w.shelf;
    if (!s.shown || s.sticky) return;
    __weak NSWindow *win = self.window;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 300 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{   // a moment's grace for an overshoot
        if (!win || NSPointInRect(NSEvent.mouseLocation, win.frame) || s.sticky) return;
        [w showShelf:NO];
    });
}
- (void)mouseDown:(NSEvent *)e {   // the ground around the page moves the window; a double-click zooms it
    VWindow *w = WinFor(self);   // clicking away from the address lets go of it
    if (w.toolbar.field.currentEditor) [self.window makeFirstResponder:w.current.web.web];
    [w closePanels];
    if (e.clickCount == 2) [self.window performZoom:nil]; else [self.window performWindowDragWithEvent:e];
}
@end

// The page frame's struck corners, drawn as two tiny views over the page. (A mask on the page itself would
// make the Mac re-composite the whole page every frame, which costs real speed.)
// the page area never drags the window (only the sidebar's empty space and the title bar do)
@interface VContentView : NSView
@end
@implementation VContentView
- (BOOL)mouseDownCanMoveWindow { return NO; }
@end

@interface VCornerCap : NSView
@property BOOL bottomRight;
@end
@implementation VCornerCap
- (BOOL)isFlipped { return YES; }
- (NSView *)hitTest:(NSPoint)p { return nil; }
- (void)drawRect:(NSRect)dirty {
    CGFloat c = NSWidth(self.bounds);
    NSBezierPath *tri = [NSBezierPath bezierPath], *edge = [NSBezierPath bezierPath];
    if (self.bottomRight) { [tri moveToPoint:NSMakePoint(c, c)]; [tri lineToPoint:NSMakePoint(0, c)]; [tri lineToPoint:NSMakePoint(c, 0)]; }
    else { [tri moveToPoint:NSMakePoint(0, 0)]; [tri lineToPoint:NSMakePoint(c, 0)]; [tri lineToPoint:NSMakePoint(0, c)]; }
    [tri closePath]; [vBg setFill]; [tri fill];
    [edge moveToPoint:NSMakePoint(c, 0)]; [edge lineToPoint:NSMakePoint(0, c)];
    edge.lineWidth = 1; [vBorder setStroke]; [edge stroke];
}
@end

