static const CGFloat kTop = 40, kBook = 30; // kTop: toolbar height in full screen; windowed it's the title bar's

// A short message at the top of the page ("Filter lists updated"): a floating capsule with a mark saying what kind of
// news it is (done, a problem, or just so you know), centred text, a soft shadow. It drops in and lifts away.
@interface VToast : NSView
@property (nonatomic, copy) NSString *message;
@property NSInteger kind;   // 0 note, 1 done, 2 problem
- (void)appear;
- (void)vanish;
@end
@implementation VToast
- (instancetype)init {
    if (!(self = [super initWithFrame:NSMakeRect(0, 0, 200, 34)])) return nil;
    self.wantsLayer = YES; self.alphaValue = 0;
    self.layer.shadowColor = NSColor.blackColor.CGColor; self.layer.shadowOpacity = 0.35; self.layer.shadowRadius = 14; self.layer.shadowOffset = CGSizeMake(0, -5);
    return self;
}
- (BOOL)isFlipped { return YES; }
- (NSView *)hitTest:(NSPoint)p { return nil; }   // never in the way of the page
static NSDictionary *ToastAttrs(void) { return @{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium), NSForegroundColorAttributeName: vText}; }
- (void)setMessage:(NSString *)m {
    _message = [m copy];
    NSString *l = m.lowercaseString;
    BOOL bad = NO; for (NSString *w in @[@"couldn't", @"could not", @"didn't", @"failed", @"can't", @"cannot", @"not allowed", @"blocked", @"error", @"needs "]) if ([l containsString:w]) bad = YES;
    BOOL good = NO; for (NSString *w in @[@"updated", @"saved", @"created", @"deleted", @"renamed", @"installed", @"copied", @"added", @"removed", @"cleared", @"done", @"ready", @"restored", @"imported"]) if ([l containsString:w]) good = YES;
    self.kind = bad ? 2 : good ? 1 : 0;
    self.needsDisplay = YES;
}
- (NSSize)fittingSize { return NSMakeSize(ceil([self.message ?: @"" sizeWithAttributes:ToastAttrs()].width) + 16 + 20 + 8 + 18, 34); }
- (void)setFrameSize:(NSSize)s { [super setFrameSize:s]; CGPathRef p = CGPathCreateWithRoundedRect((CGRect){CGPointZero, s}, s.height / 2, s.height / 2, NULL); self.layer.shadowPath = p; CGPathRelease(p); }
- (void)drawRect:(NSRect)r {
    NSRect b = self.bounds; CGFloat rad = NSHeight(b) / 2;
    BOOL light = ThemeIsLight();
    RoundRect(b, rad, light ? HexA(0xffffff, 0.98) : HexA(0x1f1f23, 0.97));
    ShardStroke(b, rad, light ? HexA(0x000000, 0.10) : HexA(0xffffff, 0.11), 1);
    // a faint lit rim along the top
    NSBezierPath *clip = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, 1, 1) xRadius:rad - 1 yRadius:rad - 1];
    [NSGraphicsContext saveGraphicsState]; [clip addClip];
    [[[NSGradient alloc] initWithStartingColor:[NSColor colorWithWhite:1 alpha:light ? 0.0 : 0.05] endingColor:[NSColor colorWithWhite:1 alpha:0]] drawInRect:NSMakeRect(0, 0, NSWidth(b), NSHeight(b) / 2) angle:90];
    [NSGraphicsContext restoreGraphicsState];
    // the mark: a check in Iris's colours, a warning in red, or a small Aperture dot
    NSRect m = NSMakeRect(9, round((NSHeight(b) - 18) / 2), 18, 18);
    if (self.kind == 2) {
        RoundRect(m, 9, HexA(0xf06a6a, light ? 0.16 : 0.2));
        NSImage *g = Tinted(Symbol(@"exclamationmark", 9.5, NSFontWeightBold), light ? Hex(0xd94848) : Hex(0xf59a9a));
        DrawImage(g, CenterIn(g.size, m));
    } else if (self.kind == 1) {
        NSBezierPath *dot = [NSBezierPath bezierPathWithOvalInRect:m];
        [ApertureGradient(1) drawInBezierPath:dot angle:-35];
        NSImage *g = Tinted(Symbol(@"checkmark", 9, NSFontWeightBold), Hex(0x0b0d16));
        DrawImage(g, CenterIn(g.size, m));
    } else {
        NSRect d = NSInsetRect(m, 5, 5);
        [ApertureGradient(1) drawInBezierPath:[NSBezierPath bezierPathWithOvalInRect:d] angle:-35];
        RoundRect(NSInsetRect(m, 1.5, 1.5), 7.5, [ApBlue() colorWithAlphaComponent:0.12]);
    }
    NSMutableDictionary *a = [ToastAttrs() mutableCopy];
    NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.lineBreakMode = NSLineBreakByTruncatingTail; a[NSParagraphStyleAttributeName] = ps;
    NSSize ts = [self.message ?: @"" sizeWithAttributes:a];
    [self.message drawInRect:NSMakeRect(NSMaxX(m) + 8, round((NSHeight(b) - ts.height) / 2), NSWidth(b) - NSMaxX(m) - 8 - 16, ts.height) withAttributes:a];
}
- (void)appear {
    [self.layer removeAllAnimations];
    self.alphaValue = 1;
    CABasicAnimation *f = [CABasicAnimation animationWithKeyPath:@"opacity"]; f.fromValue = @0; f.toValue = @1; f.duration = 0.18;
    CASpringAnimation *drop = [CASpringAnimation animationWithKeyPath:@"transform"];
    CGFloat above = self.superview.isFlipped ? -1 : 1;   // which way is up for the layer depends on its parent
    drop.fromValue = [NSValue valueWithCATransform3D:CATransform3DMakeTranslation(0, 12 * above, 0)]; drop.toValue = [NSValue valueWithCATransform3D:CATransform3DIdentity];
    drop.damping = 16; drop.stiffness = 260; drop.mass = 1; drop.duration = drop.settlingDuration;
    [self.layer addAnimation:f forKey:@"in-fade"]; [self.layer addAnimation:drop forKey:@"in-drop"];
}
- (void)vanish {
    if (!self.superview) return;
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext *c) {
        c.duration = 0.22; c.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionEaseIn];
        self.animator.alphaValue = 0;
        CABasicAnimation *up = [CABasicAnimation animationWithKeyPath:@"transform"];
        up.toValue = [NSValue valueWithCATransform3D:CATransform3DMakeTranslation(0, 8 * (self.superview.isFlipped ? -1 : 1), 0)]; up.duration = 0.22;
        up.fillMode = kCAFillModeForwards; up.removedOnCompletion = NO;
        [self.layer addAnimation:up forKey:@"out"];
    } completionHandler:^{ if (self.alphaValue < 0.01) { [self.layer removeAllAnimations]; [self removeFromSuperview]; } }];
}
@end

// The browser window. AppKit sets the arrow whenever it rebuilds a window's cursor rects (any view added, removed,
// moved or shown: the link address in the corner, a toast, a button appearing), and the page doesn't send its cursor
// again until the cursor it wants changes. So over a link the hand turned into an arrow a moment after it appeared and
// stayed that way. WebKit's own window did the same thing for its pages: over a page, the page owns the cursor.
@interface VBrowserWindow : NSWindow @end
@implementation VBrowserWindow
static BOOL gCursorGuardOff;   // dev: "cursorguard 0" to see the old behaviour
static BOOL PointIsOverPage(NSWindow *w, NSPoint p) {   // p: window coordinates
    if (gCursorGuardOff) return NO;
    NSView *frame = w.contentView.superview ?: w.contentView;
    for (NSView *v = [frame hitTest:[frame convertPoint:p fromView:nil]]; v; v = v.superview) if ([v isKindOfClass:WKWebView.class]) return YES;
    return NO;
}
- (void)_setCursorForMouseLocation:(NSPoint)p {
    if (PointIsOverPage(self, p)) return;
    struct objc_super sup = {self, NSWindow.class};
    if ([NSWindow instancesRespondToSelector:_cmd]) ((void (*)(struct objc_super *, SEL, NSPoint))objc_msgSendSuper)(&sup, _cmd, p);
}
- (void)resetCursorRects {   // the public path to the same reset: the page's cursor survives it
    NSCursor *had = NSCursor.currentCursor;
    [super resetCursorRects];
    if (had && NSCursor.currentCursor != had && PointIsOverPage(self, self.mouseLocationOutsideOfEventStream)) [had set];
}
@end

@implementation VWindow

// The first window restores the saved session; later ones start empty (or from their saved state).
- (instancetype)init { return [self initPrivate:NO state:[Defaults() dictionaryForKey:kTabsState] ?: @{}]; }

- (instancetype)initPrivate:(BOOL)priv state:(NSDictionary *)state {
    NSWindow *w = [[VBrowserWindow alloc] initWithContentRect:NSMakeRect(0, 0, 1320, 860)
        styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable | NSWindowStyleMaskFullSizeContentView
        backing:NSBackingStoreBuffered defer:NO];
    if (!(self = [super initWithWindow:w])) return nil;
    _isPrivate = priv;
    if (priv) _privateStore = WKWebsiteDataStore.nonPersistentDataStore;
    _profile = @"";   // other profiles are apps of their own: every window here is this app's person
    VWindow *previous = gWin;
    BOOL firstNormal = !priv && ![gWindows filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"isPrivate == NO"]].count;
    if (!gWindows) gWindows = [NSMutableArray array];
    [gWindows addObject:self];
    gWin = self;
    w.titlebarAppearsTransparent = YES; w.titleVisibility = NSWindowTitleHidden;
    w.backgroundColor = vBg; w.minSize = NSMakeSize(640, 420);
    w.appearance = ThemeAppearance();
    w.collectionBehavior = NSWindowCollectionBehaviorFullScreenPrimary;
    w.delegate = self;
    w.title = priv ? @"Iris · Private" : _profile.length ? [@"Iris · " stringByAppendingString:ProfileName(_profile)] : @"Iris";
    // Monolith: no title bar of our own. The page reaches the window's edges; the empty ground around it moves the window.
    w.acceptsMouseMovedEvents = YES;
    if (firstNormal) {
        w.frameAutosaveName = @"IrisMain";
        if (![w setFrameUsingName:@"IrisMain"]) [w center];
    } else if ([state[@"frame"] isKindOfClass:NSString.class] && NSWidth(NSRectFromString(state[@"frame"])) > 300) {
        [w setFrame:NSRectFromString(state[@"frame"]) display:NO];
    } else if (previous.window) {
        [w setFrame:previous.window.frame display:NO];
        NSPoint tl = NSMakePoint(NSMinX(previous.window.frame), NSMaxY(previous.window.frame));
        [w cascadeTopLeftFromPoint:NSMakePoint(tl.x + 26, tl.y - 26)];
    } else [w center];

    self.tabs = [NSMutableArray array];
    self.closed = [NSMutableArray array];

    VRoot *root = [[VRoot alloc] initWithFrame:w.contentView.bounds];
    w.contentView = root;
    self.toolbar = [[VToolbar alloc] initWithFrame:NSMakeRect(0, 0, NSWidth(root.bounds), kTop)];
    self.bookmarksBar = [[VBookmarksBar alloc] initWithFrame:NSZeroRect];
    self.sidebar = [[VSidebar alloc] initWithFrame:NSMakeRect(0, 0, 230, 400)];
    self.sideScroll = [[NSScrollView alloc] initWithFrame:NSZeroRect];
    self.sideScroll.documentView = self.sidebar;
    self.sideScroll.drawsBackground = NO; self.sideScroll.hasVerticalScroller = YES; self.sideScroll.autohidesScrollers = YES;
    self.sideScroll.scrollerStyle = NSScrollerStyleOverlay; self.sideScroll.borderType = NSNoBorder;
    self.content = [[VContentView alloc] initWithFrame:NSZeroRect];
    self.content.wantsLayer = YES;
    self.content.layer.backgroundColor = vContentBg.CGColor;
    // the spark that runs along the top edge of the page while it loads
    CAGradientLayer *ember = [CAGradientLayer layer];
    ember.name = @"ember"; ember.startPoint = CGPointMake(0, 0.5); ember.endPoint = CGPointMake(1, 0.5); ember.zPosition = 900; ember.hidden = YES;
    [self.content.layer addSublayer:ember];
    self.home = [[VHome alloc] initWithFrame:NSZeroRect];
    self.home.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    self.findBar = [[VFindBar alloc] initWithFrame:NSMakeRect(0, 0, 330, 36)];
    self.findBar.hidden = YES;
    self.railDock = [[VRailDock alloc] initWithFrame:NSMakeRect(0, 0, 230, 42)];
    self.capTL = [[VCornerCap alloc] initWithFrame:NSZeroRect]; self.capBR = [[VCornerCap alloc] initWithFrame:NSZeroRect]; self.capBR.bottomRight = YES;
    for (NSView *v in @[self.bookmarksBar, self.sideScroll, self.railDock, self.content, self.capTL, self.capBR]) [root addSubview:v];
    self.suggest = [VSuggest new];
    self.toolbar.capsule = YES;
    [root addSubview:self.toolbar positioned:NSWindowAbove relativeTo:self.content];
    self.lights = [[VLights alloc] initWithFrame:NSMakeRect(12, 7, 62, 22)];
    self.shelfHandle = [[VShelfHandle alloc] initWithFrame:NSZeroRect];
    self.loadLine = [[VLoadLine alloc] initWithFrame:NSZeroRect];
    self.shelf = [[VTabShelf alloc] initWithOwner:self];
    for (NSView *v in @[self.lights, self.shelfHandle, self.shelf]) [root addSubview:v positioned:NSWindowAbove relativeTo:nil];
    InstallShelfMonitor();
    for (NSView *v in @[root, self.toolbar, self.bookmarksBar, self.sidebar, self.sideScroll, self.home, self.findBar, self.content]) Clip(v);

    self.toast = [VToast new];

    self.linkStatus = [NSTextField labelWithString:@""];
    self.linkStatus.font = UIFont(11.5, NSFontWeightRegular); self.linkStatus.textColor = vDim;
    self.linkStatus.wantsLayer = YES; self.linkStatus.layer.backgroundColor = vLinkBg.CGColor;
    self.linkStatus.lineBreakMode = NSLineBreakByTruncatingMiddle;

    [self restoreFrom:state];
    [self layout];
    [NSTimer scheduledTimerWithTimeInterval:60 target:self selector:@selector(sleepIdleTabs) userInfo:nil repeats:YES];
    PrivateWindowOpened(self);
    return self;
}

#pragma mark Pages

#pragma mark Profiles

// The window for a profile: the frontmost one already open, or a new one.
static VWindow *OpenProfileWindow(NSString *pid) {
    if (pid.length && !IrisIsDev() && !gWebApp) { ProfileAppOpen(pid, nil); return nil; }   // another person: their own app
    pid = @"";
    for (VWindow *w in gWindows.reverseObjectEnumerator) if (!w.isPrivate && [w.profile isEqualToString:pid ?: @""]) { [w.window makeKeyAndOrderFront:nil]; return w; }
    VWindow *w = [[VWindow alloc] initPrivate:NO state:@{@"profile": pid ?: @""}];
    [w showWindow:nil]; [w windowDidResize:nil];
    return w;
}
static NSString *CreateProfile(NSString *name) {
    NSString *pid = NSUUID.UUID.UUIDString;
    NSMutableArray *a = [ProfilesStored() mutableCopy];
    NSMutableSet *used = [NSMutableSet set]; for (NSDictionary *p in Profiles()) [used addObject:@(ProfileColorIndex(p[@"id"]))];
    NSInteger color = 0; while (color < (NSInteger)ProfileColors().count - 1 && [used containsObject:@(color)]) color++;   // the first colour not taken
    [a addObject:@{@"id": pid, @"name": name.length ? name : [NSString stringWithFormat:@"Profile %lu", (unsigned long)a.count + 2], @"color": @(color)}];
    ProfilesStore(a);
    for (VWindow *w in gWindows) [w.toolbar layoutBar];
    return pid;
}
- (void)profileMenu:(id)s {
    NSMenu *m = [self profilesMenu];
    NSView *at = [s isKindOfClass:NSView.class] ? s : self.toolbar;
    if (at == (NSView *)self.toolbar.profileBtn) PopMenuRight(m, NSMakePoint(NSWidth(at.bounds), NSHeight(at.bounds) + 6), at);
    else PopMenu(m, NSMakePoint(0, NSHeight(at.bounds) + 4), at);
}
// Every profile (this window's ticked), then New and Manage: the toolbar avatar and the ⋯ menu both show this.
- (NSMenu *)profilesMenu {
    NSMenu *m = [[NSMenu alloc] initWithTitle:@"Profiles"];
    for (NSDictionary *p in Profiles()) {
        NSMenuItem *i = [m addItemWithTitle:p[@"name"] action:@selector(openProfile:) keyEquivalent:@""];
        i.target = self; i.representedObject = p[@"id"]; i.state = [p[@"id"] isEqualToString:self.profile] && !self.isPrivate ? NSControlStateValueOn : NSControlStateValueOff;
        i.image = ProfileAvatar(p[@"id"], p[@"name"], 16);
    }
    [m addItem:NSMenuItem.separatorItem];
    [m addItemWithTitle:@"New Profile…" action:@selector(newProfile:) keyEquivalent:@""].target = self;
    [m addItemWithTitle:@"Manage Profiles…" action:@selector(manageProfiles:) keyEquivalent:@""].target = self;
    return m;
}
- (void)openProfile:(NSMenuItem *)i { OpenProfileWindow(i.representedObject); }
- (void)manageProfiles:(id)s { [self showSettingsSection:@"profiles"]; }
- (void)newProfile:(id)s {
    NSAlert *a = [NSAlert new]; a.messageText = @"New profile";
    a.informativeText = @"For another person, or a part of your life you keep apart. It opens as its own app, with its own extensions, passwords, bookmarks, downloads, history and sign-ins.";
    NSTextField *f = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 260, 24)]; f.placeholderString = @"Name, e.g. Work";
    a.accessoryView = f; [a addButtonWithTitle:@"Create"]; [a addButtonWithTitle:@"Cancel"];
    a.window.initialFirstResponder = f;
    [a beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r != NSAlertFirstButtonReturn) return;
        OpenProfileWindow(CreateProfile(Trim(f.stringValue)));
    }];
}

- (WKWebViewConfiguration *)pageConfig { return self.isPrivate ? PrivateConfig(self.privateStore) : ProfileConfig(self.profile); }

- (VPage *)makePage:(VTab *)t {
    t.owner = self;
    VPage *p = (self.isPrivate || self.profile.length) ? [[VPage alloc] initWithFrame:self.content.bounds web:[[FWebView alloc] initWithFrame:self.content.bounds configuration:[self pageConfig]]]
                                                       : [[VPage alloc] initWithFrame:self.content.bounds];
    p.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    p.tab = t;
    t.web = p; t.isHome = NO;
    ApplyThrottle(p.web, ThrottleHard());
    if (t.savedBack.count) [p.back setArray:t.savedBack];
    t.savedBack = nil;
    return p;
}

- (void)pageChanged:(VPage *)p {
    VTab *t = p.tab; if (!t) return;
    if (p.title.length) t.title = p.title;
    NSString *oldHost = t.url ? HostOf([NSURL URLWithString:t.url]) : nil;
    if (p.url) t.url = p.url;
    t.loading = p.loading; t.progress = p.progress; t.blocked = p.blocked;
    NSURL *u = t.url ? [NSURL URLWithString:t.url] : nil;
    NSString *host = HostOf(u);
    if (u && (!t.favicon || ![oldHost isEqualToString:host])) {
        t.favicon = [VFavicons.shared iconForURL:t.url];
        if (!t.favicon && [u.scheme hasPrefix:@"http"]) {
            __weak VTab *wt = t;
            [VFavicons.shared fetchFor:u href:nil done:^(NSImage *im) { if ([HostOf([NSURL URLWithString:wt.url]) isEqualToString:host]) { wt.favicon = im; [self refreshChrome]; [self.bookmarksBar reload]; } }];
        }
    }
    if (!p.loading) {
        NSNumber *z = SiteDict(self.isPrivate, kZoom)[host] ?: [Defaults() objectForKey:kDefaultZoom];
        if (z && fabs(z.doubleValue - p.zoom) > 0.01) [p setZoomLevel:z.doubleValue];
    }
    // pages report progress many times a second; the toolbar and sidebar redraw at most ~20 times a second
    if (!self.chromePending) { self.chromePending = YES; dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 50 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ self.chromePending = NO; [self refreshChrome]; }); }
    [self scheduleSave];
}

- (void)showLink:(NSString *)u {
    if (!u.length) { [self.linkStatus removeFromSuperview]; return; }
    self.linkStatus.stringValue = [NSString stringWithFormat:@"  %@  ", u];
    [self.linkStatus sizeToFit];
    // bottom-right corner of the page, full address unless it's wider than most of the page
    NSRect cb = self.content.bounds;
    CGFloat w = MIN(NSWidth(self.linkStatus.frame) + 4, NSWidth(cb) - 16);
    CGFloat y = self.content.isFlipped ? NSHeight(cb) - 28 : 8;
    self.linkStatus.frame = NSMakeRect(NSWidth(cb) - w - 8, y, w, 20);
    FacetView(self.linkStatus, 6, vSep);
    if (self.linkStatus.superview != self.content) [self.content addSubview:self.linkStatus];
}

#pragma mark Tabs

- (void)newTab:(NSURL *)u select:(BOOL)sel {
    if (gWebApp && self.tabs.count) {   // an app window holds one page: more of the app is a new window, anything else opens in Iris
        if (!u) u = [NSURL URLWithString:gWebApp[@"start"]];
        if (WebAppInScope(u)) WebAppOpenWindow(u); else OpenInIris(u);
        return;
    }
    VTab *t = [VTab new]; t.owner = self;
    t.isHome = (u == nil);
    [self.tabs addObject:t];   // new tabs arrive at the right end of the strip; they stay where you put them
    if (u) {
        t.url = u.absoluteString; t.title = HostOf(u);
        t.favicon = [VFavicons.shared iconForURL:t.url];
        VPage *p = [self makePage:t];
        [p open:t.url record:NO];
        if (!sel) { t.hiddenAt = t.openedFresh = NSDate.date.timeIntervalSince1970; [self tabOpenedBehind]; }
    }
    if (sel || !self.current) [self selectTab:t];
    else [self refreshChrome];
    if (sel && !u) [self focusAddress];
    [self.sidebar reload];
    [self scheduleSave];
}

- (void)selectTab:(VTab *)t {
    if (!t) return;
    VTab *was = self.current;
    if (was) t.deferred = NO;   // you chose it: it loads
    t.openedFresh = 0;
    if (was != t) [self autoPiPLeaving:was entering:t];   // asked while the old page is still on screen
    if (self.current && self.current != t) { self.current.hiddenAt = NSDate.date.timeIntervalSince1970; CaptureThumb(self.current); }
    self.current = t;
    [FExtHost.shared tab:t event:@"activated"];
    if (self.mediaTab) dispatch_async(dispatch_get_main_queue(), ^{ [self updateNowPlaying]; });
    [self showLink:nil];
    if (t.isHome) {
        [self placePages];
        [self.home reload];
        // a new tab is for typing: the address bar takes focus once the click or key that opened it is done
        dispatch_async(dispatch_get_main_queue(), ^{
            if (self.current == t && t.isHome && (self.window.isKeyWindow || !NSApp.keyWindow)) { self.home.field.stringValue = @""; [self.window makeFirstResponder:self.home.field ?: self.toolbar.field]; }
        });
    } else {
        [self placePages];   // wakes the tab if it was asleep; in split view its partner shows too
        [t.web focus];
    }
    if (!self.findBar.hidden) [self.content addSubview:self.findBar];
    [self.suggest dismiss];
    [self refreshChrome];
    [self.sidebar reload];
    self.window.contentView.needsDisplay = YES;   // the band takes this page's colour
    [self scheduleSave];
}

// Background tabs give their memory back after a while; they reload when you return.
- (void)sleepIdleTabs {
    NSInteger mins = [Defaults() integerForKey:kSleepMins];
    if (mins <= 0) return;
    NSTimeInterval now = NSDate.date.timeIntervalSince1970;
    for (VTab *t in self.tabs.copy) {
        if (t == self.current || !t.web || t.hiddenAt <= 0 || now - t.hiddenAt < mins * 60) continue;
        if ([self.splitPair containsObject:t] && [self.splitPair containsObject:self.current]) continue;
        if (t.audible) continue;   // never silence something you're listening to
        [self sleep:t];
    }
}
- (void)sleep:(VTab *)t {
    t.savedBack = [t.web historyForSleep];
    t.savedState = [t.web sessionState];
    if (t.mediaTime > 0) t.resumeAt = t.mediaTime;   // it wakes where its video was
    [t.web close];
    t.web = nil;
    [self.sidebar reload];
}

- (void)closeTab:(VTab *)t {
    NSUInteger i = [self.tabs indexOfObject:t]; if (i == NSNotFound) return;
    if (gWebApp && self.tabs.count <= 1) { [self.window close]; return; }   // an app window is its page
    if (t.url && !t.isHome) {   // remembered with its back/forward history, so reopening brings all of it back
        NSMutableDictionary *d = [@{@"url": t.url, @"title": t.title ?: @""} mutableCopy];
        id st = t.web ? [t.web sessionState] : t.savedState;
        if ([st isKindOfClass:NSData.class] && [st length] < 400000) d[@"state"] = st;
        double at = t.resumeAt > 0 ? t.resumeAt : t.mediaTime;
        if (at > 0 && t.mediaKey.length) { d[@"mediaTime"] = @(at); d[@"mediaKey"] = t.mediaKey; }
        [self.closed addObject:d];
        if (self.closed.count > 25) [self.closed removeObjectAtIndex:0];
    }
    [FExtHost.shared tab:t event:@"removed"];
    [t.homeBack close]; [t.homeFwd close]; t.homeBack = nil; t.homeFwd = nil;
    VTab *partner = nil;   // closing half of a split leaves the other half in front
    if ([self.splitPair containsObject:t]) { partner = self.splitPair[0] == t ? self.splitPair[1] : self.splitPair[0]; [self endSplit]; }
    [t.web close]; t.web = nil;
    [self.tabs removeObjectAtIndex:i];
    if (t == self.mediaTab) { self.mediaTab = nil; dispatch_async(dispatch_get_main_queue(), ^{ [self updateNowPlaying]; }); }
    if (t == self.current) {
        self.current = nil;
        if (!self.tabs.count) {
            if (gWindows.count > 1) { [self.sidebar reload]; dispatch_async(dispatch_get_main_queue(), ^{ [self.window performClose:nil]; }); return; }
            [self newTab:nil select:YES]; return;
        }
        // back to the tab you were on just before (the one left of it in the strip), so closing a page you opened from
        // another — a sign-in pop-up, a link — returns you where you came from
        VTab *back = nil;
        for (VTab *x in self.tabs) if (!x.openedFresh && x.hiddenAt > 0 && (!back || x.hiddenAt > back.hiddenAt)) back = x;
        [self selectTab:partner && [self.tabs containsObject:partner] ? partner : back ?: self.tabs[MIN(i, self.tabs.count - 1)]];
    } else if (partner) [self placePages];
    [self.sidebar reload];
    [self scheduleSave];
}

- (void)moveTab:(VTab *)t to:(NSInteger)i {
    [self.tabs removeObject:t];
    [self.tabs insertObject:t atIndex:(NSUInteger)MAX(0, MIN((NSInteger)self.tabs.count, i))];
    [self.sidebar reload]; [self scheduleSave];
}

- (void)togglePin:(VTab *)t {
    t.pinned = !t.pinned;
    NSArray *p = [self.tabs filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"pinned == YES"]];
    NSArray *l = [self.tabs filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"pinned == NO"]];
    [self.tabs setArray:[p arrayByAddingObjectsFromArray:l]];
    [self.sidebar reload]; [self scheduleSave];
}

- (void)tabMenu:(VTab *)t at:(NSPoint)p inView:(NSView *)v {
    NSMenu *m = [[NSMenu alloc] initWithTitle:@""];
    NSMenuItem *(^add)(NSString *, SEL) = ^NSMenuItem *(NSString *title, SEL a) {
        NSMenuItem *it = [m addItemWithTitle:title action:a keyEquivalent:@""]; it.target = self; it.representedObject = t; return it;
    };
    if (t.web) add(@"Reload Tab", @selector(menuReload:));
    add(t.pinned ? @"Unpin Tab" : @"Pin Tab", @selector(menuPin:));
    add(@"Duplicate Tab", @selector(menuDuplicate:));
    if (t.url && !t.isHome) {
        add(@"Copy Link", @selector(menuCopyLink:));
        add([VBookmarks.shared find:t.url] ? @"Remove Bookmark" : @"Bookmark Tab", @selector(menuBookmark:));
    }
    if (t.web && (t.audible || t.muted)) add(t.muted ? @"Unmute Tab" : @"Mute Tab", @selector(menuMute:));
    if (t.web && t != self.current) add(@"Put Tab to Sleep", @selector(menuSleep:));
    [m addItem:NSMenuItem.separatorItem];
    add([self.splitPair containsObject:t] ? @"Exit Split View" : t == self.current ? @"New Split View" : @"Split View with Current Tab", @selector(menuSplit:));
    if ([self.splitPair containsObject:t]) add(@"Swap Sides", @selector(swapSplit:));
    add(@"Move Tab to New Window", @selector(menuMoveToWindow:)).enabled = self.tabs.count > 1;
    [m addItem:NSMenuItem.separatorItem];
    add(@"Close Tab", @selector(menuClose:));
    add(@"Close Other Tabs", @selector(menuCloseOthers:));
    add(@"Close Older Tabs", @selector(menuCloseBelow:)).enabled = [self olderThan:t].count > 0;   // left of it in the strip
    [m addItem:NSMenuItem.separatorItem];
    NSMenuItem *ro = add(@"Reopen Closed Tab", @selector(reopenClosed:)); ro.enabled = self.closed.count > 0;
    PopMenu(m, p, v);
}
- (void)menuPin:(NSMenuItem *)i { [self togglePin:i.representedObject]; }
- (void)menuReload:(NSMenuItem *)i { VTab *t = i.representedObject; [t.web reload]; }
- (void)menuBookmark:(NSMenuItem *)i { VTab *t = i.representedObject; [VBookmarks.shared toggle:t.url title:t.title]; [self.bookmarksBar reload]; [self refreshChrome]; }
- (void)saveImageAs:(NSMenuItem *)m { gAskNextDownload = YES; [self.current.web download:m.representedObject]; }
- (void)openBookmarkInBackground:(NSMenuItem *)m { [self newTab:[NSURL URLWithString:m.representedObject] select:NO]; }
- (void)menuMute:(NSMenuItem *)i { VTab *t = i.representedObject; [t.web setMuted:!t.muted]; }
- (void)muteCurrent:(id)s { VTab *t = self.current; if (t.web) { [t.web setMuted:!t.muted]; [self showToast:t.muted ? @"Tab muted" : @"Tab unmuted"]; } }
- (void)pictureInPicture:(id)s { [self.current.web pictureInPicture]; }
- (void)menuDuplicate:(NSMenuItem *)i { VTab *t = i.representedObject; if (t.url && !t.isHome) [self newTab:[NSURL URLWithString:t.url] select:YES]; else [self newTab:nil select:YES]; }
- (void)menuCopyLink:(NSMenuItem *)i { VTab *t = i.representedObject; [self copyString:t.url]; }
- (void)menuSleep:(NSMenuItem *)i { [self sleep:i.representedObject]; }
- (void)menuClose:(NSMenuItem *)i { [self closeTab:i.representedObject]; }
- (void)menuCloseOthers:(NSMenuItem *)i { for (VTab *t in self.tabs.copy) if (t != i.representedObject && !t.pinned) [self closeTab:t]; [self selectTab:i.representedObject]; }
// The strip is a timeline, so "older" means the tabs left of this one: looked at longer ago. Pinned tabs and
// tabs you haven't opened yet are never in it.
- (NSArray<VTab *> *)olderThan:(VTab *)t {
    NSMutableArray *out = [NSMutableArray array];
    for (VTab *x in self.tabs) {
        if (x == t || x == self.current || x.pinned || x.openedFresh > 0) continue;
        if (t == self.current || (t.openedFresh == 0 && x.hiddenAt < t.hiddenAt) || t.openedFresh > 0) [out addObject:x];
    }
    return out;
}
- (void)menuCloseBelow:(NSMenuItem *)i {
    NSArray *older = [self olderThan:i.representedObject];
    for (VTab *t in older) [self closeTab:t];
    if (older.count > 1) [self showToast:[NSString stringWithFormat:@"Closed %lu older tabs · ⇧⌘T brings them back", (unsigned long)older.count]];
}

#pragma mark Session

- (void)scheduleSave {
    [self.saveTimer invalidate];
    self.saveTimer = [NSTimer scheduledTimerWithTimeInterval:0.6 target:self selector:@selector(saveSession) userInfo:nil repeats:NO];
}
- (NSDictionary *)sessionDict {
    NSMutableArray *a = [NSMutableArray array];
    for (VTab *t in self.tabs) {
        NSString *u = t.web.url ?: t.url;
        NSMutableDictionary *d = [@{@"url": t.isHome || !u ? @"" : u, @"title": t.title ?: @"", @"pinned": @(t.pinned)} mutableCopy];
        id state = t.web ? [t.web sessionState] : t.savedState;   // back/forward history and scroll position
        if ([state isKindOfClass:NSData.class] && [state length] < 400000) d[@"state"] = state;
        double at = t.resumeAt > 0 ? t.resumeAt : t.mediaTime;   // where its video was
        if (at > 0 && t.mediaKey.length) { d[@"mediaTime"] = @(at); d[@"mediaKey"] = t.mediaKey; }
        [a addObject:d];
    }
    return @{@"tabs": a, @"current": @(self.current ? (NSInteger)[self.tabs indexOfObject:self.current] : 0), @"frame": NSStringFromRect(self.window.frame), @"profile": self.profile ?: @""};
}
// Every normal window is saved (the first as the main one); private windows never are.
- (void)saveSession {
    if (gQuitting || gWebApp) return;   // an installed app doesn't keep Iris's tabs   // the quit already saved; nothing after it may replace that
    NSMutableArray *normal = [NSMutableArray array];
    for (VWindow *w in gWindows) if (!w.isPrivate) [normal addObject:[w sessionDict]];
    if (!normal.count) { [Defaults() setObject:@{@"tabs": @[], @"current": @0} forKey:kTabsState]; DLog(@"session: no windows left, nothing saved"); return; }
    NSMutableDictionary *main = [normal[0] mutableCopy];
    if (normal.count > 1) main[@"windows"] = [normal subarrayWithRange:NSMakeRange(1, normal.count - 1)];
    [Defaults() setObject:main forKey:kTabsState];
    static NSUInteger lastCount = NSNotFound; NSUInteger n = [main[@"tabs"] count];
    if (n != lastCount) { lastCount = n; DLog(@"session: %lu tabs saved", (unsigned long)n); }
}
- (void)restoreFrom:(NSDictionary *)s {
    BOOL restore = [Defaults() integerForKey:kStartup] == 0 && !self.isPrivate;
    if (!s[@"empty"]) for (NSDictionary *d in s[@"tabs"]) {
        BOOL pinned = [d[@"pinned"] boolValue];
        if (!restore && !pinned) continue;
        VTab *t = [VTab new]; t.owner = self;
        t.url = [d[@"url"] length] ? d[@"url"] : nil;
        t.isHome = t.url == nil; t.title = d[@"title"]; t.pinned = pinned;
        t.savedState = [d[@"state"] isKindOfClass:NSData.class] ? d[@"state"] : nil;
        if (t.url) t.favicon = [VFavicons.shared iconForURL:t.url];
        if ([d[@"mediaKey"] isKindOfClass:NSString.class] && [Defaults() boolForKey:kResumeMedia]) { t.mediaKey = d[@"mediaKey"]; t.mediaTime = t.savedMedia = t.resumeAt = [d[@"mediaTime"] doubleValue]; DLog(@"restoring a video at %.0f s", t.resumeAt); }
        [self.tabs addObject:t];
    }
    if (s[@"empty"]) return;   // a tab is about to be moved in
    if (!self.isPrivate) DLog(@"launch: %lu tabs restored (%lu saved)", (unsigned long)self.tabs.count, (unsigned long)[s[@"tabs"] count]);
    NSInteger cur = [s[@"current"] integerValue];
    if (!self.tabs.count) { [self newTab:nil select:YES]; return; }
    VTab *front = self.tabs[(NSUInteger)MAX(0, MIN((NSInteger)self.tabs.count - 1, cur))];
    if (!front.isHome) { front.launchRestored = [Defaults() boolForKey:kRestorePaused]; front.deferred = [Defaults() boolForKey:kLazyRestore]; front.launchFront = YES; }
    [self selectTab:front];
}

#pragma mark Windows

- (void)windowDidBecomeKey:(NSNotification *)n {
    gWin = self;
    static id mon;   // clicks and keys in a page mark that tab as "yours right now" for the CPU rule
    if (!mon) mon = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskLeftMouseDown | NSEventMaskKeyDown handler:^NSEvent *(NSEvent *e) {
        VWindow *w = WinFor(e.window); VTab *t = w.current;
        if (t && e.window == w.window) t.lastInput = NSDate.date.timeIntervalSince1970;
        return e;
    }];
}
- (void)moveTabToNewWindow:(VTab *)t {
    if (!t || ![self.tabs containsObject:t]) return;
    if (self.tabs.count == 1) { [self showToast:@"This is the only tab in the window"]; return; }
    if ([self.splitPair containsObject:t]) { [self endSplit]; [self placePages]; }
    VWindow *nw = [[VWindow alloc] initPrivate:self.isPrivate state:@{@"empty": @YES, @"profile": self.profile ?: @""}];
    NSUInteger i = [self.tabs indexOfObject:t];
    [self.tabs removeObjectAtIndex:i];
    if (t == self.current) { self.current = nil; [self selectTab:self.tabs[MIN(i, self.tabs.count - 1)]]; }
    [t.web removeFromSuperview];
    t.owner = nil; [nw.tabs addObject:t]; t.owner = nw;
    [nw selectTab:t];
    [nw showWindow:nil]; [nw layout];
    [self.sidebar reload]; [nw.sidebar reload];
    [self scheduleSave];
}
- (void)menuMoveToWindow:(NSMenuItem *)i { [self moveTabToNewWindow:i.representedObject]; }
- (void)moveCurrentToNewWindow:(id)s { [self moveTabToNewWindow:self.current]; }
// Home: this tab goes back to the new tab page (its web page closes, like opening a new tab in place).
// Home is a step in the tab's history, not the end of it: the page you leave is kept (paused), so Back brings it
// straight back, and a page you open from Home goes Back to Home.
static void PausePage(VPage *p) { [p.web evaluateJavaScript:@"document.querySelectorAll('video,audio').forEach(m=>{try{m.pause()}catch(e){}})" completionHandler:nil]; }
- (void)showHomeIn:(VTab *)t keeping:(VPage *)page asForward:(BOOL)fwd {
    if (page) { [page removeFromSuperview]; PausePage(page); }
    if (fwd) { if (t.homeFwd != page) [t.homeFwd close]; t.homeFwd = page; }
    else { if (t.homeBack && t.homeBack != page) [t.homeBack close]; t.homeBack = page; if (!t.homeAhead) { [t.homeFwd close]; t.homeFwd = nil; } }
    t.web = nil; t.isHome = YES; t.homeAnchor = NO; t.homeAhead = NO;
    t.url = nil; t.title = nil; t.favicon = nil; t.savedState = nil; t.loading = NO;
    [self selectTab:t];
    [self scheduleSave];
}
- (void)restorePage:(VPage *)page in:(VTab *)t anchored:(BOOL)anchored {
    t.web = page; t.isHome = NO; t.homeAnchor = anchored; t.homeAhead = NO;
    t.url = page.web.URL.absoluteString ?: t.url; t.title = page.web.title; t.loading = page.web.isLoading;
    [self selectTab:t];
    [self refreshChrome]; [self scheduleSave];
}
- (void)goHome:(id)s {
    VTab *t = self.current; if (!t || t.isHome) { [self focusAddress]; return; }
    t.homeAhead = NO;   // pressing Home starts a new way forward
    [self showHomeIn:t keeping:t.web asForward:NO];
}

#pragma mark Layout and chrome

- (void)layout {
    if (!self.lights) return;   // AppKit can ask for a layout while the window is still being built
    // Layout is never animated: at launch the views would otherwise glide in from wherever they started
    [NSAnimationContext beginGrouping]; NSAnimationContext.currentContext.duration = 0; NSAnimationContext.currentContext.allowsImplicitAnimation = NO;
    [CATransaction begin]; [CATransaction setDisableActions:YES];
    [self layoutNow];
    [CATransaction commit]; [NSAnimationContext endGrouping];
}
- (void)layoutNow {
    NSView *root = self.window.contentView;
    CGFloat W = NSWidth(root.bounds), H = NSHeight(root.bounds);
    BOOL fs = (self.window.styleMask & NSWindowStyleMaskFullScreen) != 0;
    // Monolith: the system title bar stays hidden (its buttons live in our own pill); in full screen macOS owns it
    NSView *titleContainer = [self.window standardWindowButton:NSWindowCloseButton].superview.superview;
    if (titleContainer && !fs && [NSStringFromClass(titleContainer.class) containsString:@"Titlebar"]) titleContainer.hidden = YES;
    self.bookmarksBar.hidden = YES; self.sideScroll.hidden = YES; self.railDock.hidden = YES; self.sideHandle.hidden = YES;
    if (self.toolbar.superview != root) { [self.toolbar removeFromSuperview]; [root addSubview:self.toolbar positioned:NSWindowAbove relativeTo:self.content]; }
    for (NSView *v in @[self.lights, self.shelfHandle, self.shelf, self.loadLine]) if (v.superview != root) [root addSubview:v positioned:NSWindowAbove relativeTo:nil];
    NSView *np = self.nowPlaying;
    if (self.pageFull) {   // a video went full screen: the page gets everything
        self.toolbar.hidden = YES; self.lights.hidden = YES; self.shelfHandle.hidden = YES; np.hidden = YES; self.loadLine.hidden = YES;
        [self showShelf:NO];
        self.content.frame = root.bounds; [self placePages];
        self.content.layer.borderWidth = 0; self.content.layer.cornerRadius = 0; self.capTL.hidden = self.capBR.hidden = YES;
        if (gWebApp) self.appBar.hidden = YES;
        return;
    }
    if (gWebApp) { self.appBar.hidden = NO; [self layoutWebApp]; return; }   // an installed app: its own bar instead of the browser's
    // The capsules float in their own band of the window's ground, so they never cover the page;
    // the page fills everything below it, edge to edge.
    CGFloat top = 36;   // slim band
    self.content.frame = NSMakeRect(0, top, W, H - top);
    self.toolbar.hidden = NO; self.toolbar.capsule = YES;
    self.toolbar.leftInset = fs ? 8 : 84;
    self.toolbar.frame = NSMakeRect(0, 0, W, 56);
    self.toolbar.autoresizingMask = NSViewNotSizable;
    [self.toolbar layoutBar];
    self.lights.hidden = fs;
    self.lights.frame = NSMakeRect(12, 7, 62, 22);
    self.loadLine.hidden = NO; self.loadLine.frame = NSMakeRect(0, top - 2, W, 2);   // right where the page begins, edge to edge
    VTabShelf *sh = (VTabShelf *)self.shelf;
    sh.frame = sh.shown ? [self shelfFrame] : [self shelfRestFrame];   // waiting just past its place, so it always comes out of its edge
    NSInteger side = ShelfSide(); CGFloat midY = ShelfMidY(H);
    self.shelfHandle.frame = side == 1 ? NSMakeRect(0, midY - 130, 32, 260) : side == 2 ? NSMakeRect(W - 32, midY - 130, 32, 260)
                                       : NSMakeRect(round(W / 2 - 130), H - 32, 260, 32);   // room for one dot per tab, and to lean in 12 pt
    self.shelfHandle.hidden = sh.shown || ([Defaults() boolForKey:kShelfNoHint] && !((VShelfHandle *)self.shelfHandle).flashing);
    if (np) {
        [np setValue:@YES forKey:@"floating"];
        np.frame = NSMakeRect(10, H - 10 - 64, 300, 64);
        [np setValue:@YES forKey:@"placeInCorner"];
        [root addSubview:np positioned:NSWindowAbove relativeTo:self.content];
    }
    self.findBar.frame = NSMakeRect(NSWidth(self.content.bounds) - 344, NSHeight(self.content.bounds) - 36 - 10, 330, 36);
    FacetView(self.findBar, 10, vLine);
    [self frameContent];
    [self placePages];
    [self updateEmber];
}

// Theme switch: new colours everywhere, without a relaunch.
static void RedrawTree(NSView *v) { v.needsDisplay = YES; for (NSView *s in v.subviews) RedrawTree(s); }
- (void)frameContent {
    CALayer *L = self.content.layer;
    L.mask = nil; L.cornerRadius = 10; L.masksToBounds = YES;
    L.maskedCorners = kCALayerMinXMaxYCorner | kCALayerMaxXMaxYCorner;   // the top corners; the window's own corners round the bottom
    if (@available(macOS 11.0, *)) L.cornerCurve = kCACornerCurveContinuous;
    L.borderWidth = 0;
    self.capTL.hidden = self.capBR.hidden = YES;
}

// While the page loads: the line along the bottom of the top band (VLoadLine), edge to edge.
- (void)updateEmber {
    VPage *w = self.current.web;
    [(VLoadLine *)self.loadLine loading:w.loading && !self.pageFull progress:w.progress];
}

- (void)applyTheme {
    self.window.appearance = ThemeAppearance();
    self.window.backgroundColor = vBg;
    self.content.layer.backgroundColor = vContentBg.CGColor;
    self.content.layer.borderColor = vBorder.CGColor;
    self.toast.needsDisplay = YES;
    self.linkStatus.layer.backgroundColor = vLinkBg.CGColor; self.linkStatus.textColor = vDim;
    self.toolbar.field.textColor = vText;
    [self frameContent]; FacetView(self.findBar, 10, vLine);
    for (VTab *t in self.tabs) if (t.web) {
        t.web.layer.backgroundColor = vContentBg.CGColor;
        if (@available(macOS 12.0, *)) t.web.web.underPageBackgroundColor = vContentBg;
    }
    RedrawTree(self.window.contentView.superview ?: self.window.contentView);
    [self.bookmarksBar reload]; [self.sidebar reload]; [self layout]; [self refreshChrome];
}

// The title bar's height and the traffic lights are AppKit's (via the compact toolbar style).
- (void)positionLights {}
- (void)windowDidResize:(NSNotification *)n {
    [self closePanels];
    NSView *root = self.window.contentView;
    NSRect want = root.superview.bounds;
    if (!NSEqualRects(root.frame, want) && NSWidth(want) > 0) root.frame = want;
    [self layout];
}
- (void)windowDidEnterFullScreen:(NSNotification *)n { [self layout]; }
- (void)windowDidChangeScreen:(NSNotification *)n { [self layout]; }
- (void)windowDidChangeBackingProperties:(NSNotification *)n { [self layout]; }
- (void)windowDidExitFullScreen:(NSNotification *)n {
    [self layout];
}
- (void)windowWillClose:(NSNotification *)n {
    [self.saveTimer invalidate];
    if (gQuitting) return;   // quitting: the saved tabs stay as they were
    [self.suggest dismiss];
    for (VTab *t in self.tabs) { [FExtHost.shared tab:t event:@"removed"]; [t.web close]; t.web = nil; }
    [self.tabs removeAllObjects];
    PrivateWindowClosed(self);
    [gWindows removeObject:self];
    if (gWin == self) gWin = gWindows.lastObject;
    [self saveSession];
    [gWin.window makeKeyAndOrderFront:nil];
}
// Closing the last window quits, so every page gets to close cleanly first; other windows just close.
- (BOOL)windowShouldClose:(NSWindow *)w {
    if (gWindows.count > 1) return YES;
    [NSApp terminate:nil]; return NO;
}

// The address at rest reads like an instrument: the site in full strength, the rest of the path quietly after it.
- (NSAttributedString *)identityFor:(VTab *)t url:(NSURL *)u extension:(NSString *)extName {
    NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.alignment = NSTextAlignmentLeft; ps.lineBreakMode = NSLineBreakByTruncatingTail;
    NSDictionary *strong = @{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium), NSForegroundColorAttributeName: vText, NSParagraphStyleAttributeName: ps};
    NSDictionary *quiet = @{NSFontAttributeName: UIFont(12.5, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint, NSParagraphStyleAttributeName: ps};
    NSMutableAttributedString *a = [NSMutableAttributedString new];
    if (t.isHome || !u) return a;
    if (extName) { [a appendAttributedString:[[NSAttributedString alloc] initWithString:extName attributes:strong]]; return a; }
    if ([u.scheme isEqualToString:@"iris"]) {
        NSString *orig = nil; for (NSURLQueryItem *q in [NSURLComponents componentsWithURL:u resolvingAgainstBaseURL:NO].queryItems) if ([q.name isEqualToString:@"u"]) orig = q.value;
        NSString *name = u.host.capitalizedString ?: @"Iris";
        [a appendAttributedString:[[NSAttributedString alloc] initWithString:name attributes:strong]];
        NSString *rest = orig ? HostOf([NSURL URLWithString:orig]) : @"Iris";
        if (rest.length) [a appendAttributedString:[[NSAttributedString alloc] initWithString:[@"  ·  " stringByAppendingString:rest] attributes:quiet]];
        return a;
    }
    NSString *host = HostOf(u);
    if (!host.length) { [a appendAttributedString:[[NSAttributedString alloc] initWithString:u.absoluteString attributes:strong]]; return a; }
    [a appendAttributedString:[[NSAttributedString alloc] initWithString:host attributes:strong]];
    NSString *path = u.path ?: @"";
    if (path.length > 1) {
        if (path.length > 48) path = [[path substringToIndex:47] stringByAppendingString:@"…"];
        [a appendAttributedString:[[NSAttributedString alloc] initWithString:path attributes:quiet]];
    }
    return a;
}

- (void)refreshChrome {
    VTab *t = self.current;
    VToolbar *tb = self.toolbar;
    VPage *w = t.web;
    if (!tb.field.currentEditor) {
        tb.editing = NO;
        tb.field.alignment = NSTextAlignmentLeft;
        NSURL *u = t.url ? [NSURL URLWithString:t.url] : nil;
        NSString *extName = [u.scheme isEqualToString:@"chrome-extension"] ? [FExtHost.shared nameForID:u.host] : nil;
        tb.field.attributedStringValue = [self identityFor:t url:u extension:extName];
    }
    tb.backBtn.enabled = t.isHome ? t.homeBack != nil : (w.canGoBack || t.homeAnchor);
    tb.fwdBtn.enabled = t.isHome ? t.homeFwd != nil : (w.canGoForward || t.homeAhead);
    tb.reloadBtn.symbolName = w.loading ? @"xmark" : @"arrow.clockwise";
    tb.reloadBtn.toolTip = w.loading ? @"Stop" : @"Reload (⌘R)";
    NSString *scheme = [NSURL URLWithString:t.url ?: @""].scheme;
    tb.infoBtn.symbolName = t.isHome ? @"magnifyingglass" : [scheme isEqualToString:@"chrome-extension"] ? @"puzzlepiece.extension" : [scheme isEqualToString:@"iris"] ? @"sparkle" : [scheme isEqualToString:@"https"] ? @"lock.fill" : @"exclamationmark.triangle";
    tb.starBtn.hidden = t.isHome || !ToolbarShows(@"star");
    tb.pipBtn.hidden = !ToolbarShows(@"pip") || !(t.web && (t.hasVideo || t.inPiP));
    tb.pipBtn.symbolName = t.inPiP ? @"pip.exit" : @"pip.enter";
    tb.pipBtn.toolTip = t.inPiP ? @"Return video to the page (⌃⌘P)" : @"Picture in Picture (⌃⌘P)";
    tb.pipBtn.active = t.inPiP; tb.pipBtn.needsDisplay = YES;
    [tb placePillButtons];    tb.readerBtn.enabled = [t.url hasPrefix:@"http"] || [t.url hasPrefix:@"iris://reader"];
    tb.readerBtn.active = [t.url hasPrefix:@"iris://reader"];
    tb.shareBtn.enabled = [t.url hasPrefix:@"http"];
    for (VButton *b in @[tb.readerBtn, tb.shareBtn, tb.homeBtn]) b.needsDisplay = YES;
    tb.starBtn.symbolName = [VBookmarks.shared find:t.url] ? @"star.fill" : @"star";
    tb.starBtn.active = [VBookmarks.shared find:t.url] != nil;
    tb.progress = w.loading ? MAX(0.08, t.progress) : 0;
    [self updateEmber];
    tb.blocked = t.blocked;
    [tb placePillButtons];
    if (self.shelf && !self.shelf.hidden) self.shelf.needsDisplay = YES;
    tb.shieldBtn.active = NO;
    tb.shieldBtn.symbolName = [Defaults() boolForKey:kBlock] ? @"checkmark.shield" : @"shield.slash";
    for (VButton *b in @[tb.backBtn, tb.fwdBtn, tb.reloadBtn, tb.infoBtn, tb.starBtn, tb.shieldBtn]) b.needsDisplay = YES;
    tb.needsDisplay = YES;
    self.sidebar.needsDisplay = YES;
    self.shelfHandle.needsDisplay = YES;   // the tab map at the bottom edge
    self.window.title = t.title.length ? t.title : @"Iris";
    if (gWebApp) [self refreshWebAppBar];
    else {   // the install button: install the site, or open the app it already is
        VButton *ib = tb.keyed[@"install"];
        BOOL have = WebAppFor([NSURL URLWithString:t.url ?: @""]) != nil;
        NSString *sym = have ? FirstSymbol(@[@"arrow.up.forward.app", @"arrow.up.forward.square", @"arrow.up.right.square"]) : FirstSymbol(@[@"arrow.down.app", @"plus.app", @"plus.square.on.square", @"square.and.arrow.down"]);
        if (![ib.symbolName isEqualToString:sym]) { ib.symbolName = sym; ib.toolTip = have ? @"Open in its app" : @"Install this site as an app"; ib.needsDisplay = YES; }
    }
}

#pragma mark Address bar

- (void)focusAddress {
    if (gWebApp) return;   // an installed app has no address bar
    if (!self.window.isKeyWindow) [self.window makeKeyAndOrderFront:nil];
    [self.window makeFirstResponder:self.toolbar.field];
}

- (void)go:(NSString *)input {
    NSURL *u = URLFromInput(input);
    if (!u) return;
    [self.suggest dismiss];
    [self openURL:u newTab:NO];
}

- (void)openURL:(NSURL *)u newTab:(BOOL)nt {
    if (!u) return;
    if (nt || !self.current) { [self newTab:u select:!nt || !self.current]; return; }
    VTab *t = self.current;
    if ([Defaults() boolForKey:kStrip] || self.isPrivate) { NSURL *clean = StripTracking(u); if (clean) u = clean; }
    if (!t.web) {
        BOOL fromHome = t.isHome;
        if (fromHome) { [t.homeFwd close]; t.homeFwd = nil; }   // a new way forward from Home replaces the old one
        VPage *p = [self makePage:t];
        t.homeAnchor = fromHome && t.homeBack != nil;
        [self placePages];
        [p open:u.absoluteString record:NO];
    } else {
        [t.web open:u.absoluteString record:YES];
    }
    t.url = u.absoluteString;
    [t.web focus];
    [self refreshChrome];
}

// Commands you can strike from the address bar (type a few letters, or ">" to list them all).
static NSArray<NSDictionary *> *StrikeCommands(void) {
    return @[@{@"title": @"New Tab", @"sel": @"newTabAction:", @"keys": @"⌘T", @"symbol": @"plus.square"},
             @{@"title": @"New Window", @"sel": @"newWindow:", @"keys": @"⌘N", @"symbol": @"macwindow.badge.plus"},
             @{@"title": @"New Private Window", @"sel": @"newPrivateWindow:", @"keys": @"⇧⌘N", @"symbol": @"eye.slash"},
             @{@"title": @"Reopen Closed Tab", @"sel": @"reopenClosed:", @"keys": @"⇧⌘T", @"symbol": @"arrow.uturn.backward"},
             @{@"title": @"History", @"sel": @"showHistory:", @"keys": @"⌘Y", @"symbol": @"clock.arrow.circlepath"},
             @{@"title": @"Bookmarks", @"sel": @"showBookmarks:", @"keys": @"⌥⌘B", @"symbol": @"book"},
             @{@"title": @"Bookmark This Page", @"sel": @"toggleBookmark:", @"keys": @"⌘D", @"symbol": @"star"},
             @{@"title": @"Downloads", @"sel": @"showDownloadManager:", @"keys": @"⌥⌘L", @"symbol": @"arrow.down.circle"},
             @{@"title": @"Settings", @"sel": @"showSettings:", @"keys": @"⌘,", @"symbol": @"gearshape"},
             @{@"title": @"Reader", @"sel": @"toggleReader:", @"keys": @"⌃⌘R", @"symbol": @"doc.plaintext"},
             @{@"title": @"Picture in Picture", @"sel": @"pictureInPicture:", @"keys": @"⌃⌘P", @"symbol": @"pip"},
             @{@"title": @"Mute Tab", @"sel": @"muteCurrent:", @"keys": @"⌃⌘M", @"symbol": @"speaker.slash"},
             @{@"title": @"Find on Page", @"sel": @"showFind:", @"keys": @"⌘F", @"symbol": @"text.magnifyingglass"},
             @{@"title": @"Export as PDF", @"sel": @"exportPDF:", @"keys": @"", @"symbol": @"doc.richtext"},
             @{@"title": @"Share Page", @"sel": @"sharePage:", @"keys": @"", @"symbol": @"square.and.arrow.up"},
             @{@"title": @"Show Tabs", @"sel": @"toggleSidebar:", @"keys": @"⌘S", @"symbol": @"rectangle.stack"},
             @{@"title": @"Split View", @"sel": @"toggleSplit:", @"keys": @"⌃⌘S", @"symbol": @"rectangle.split.2x1"},
             @{@"title": @"Close Other Tabs", @"sel": @"closeOtherTabs:", @"keys": @"⌥⌘W", @"symbol": @"xmark.square"},
             @{@"title": @"Move Tab to New Window", @"sel": @"moveCurrentToNewWindow:", @"keys": @"", @"symbol": @"rectangle.portrait.and.arrow.right"},
             @{@"title": @"Web Inspector", @"sel": @"showInspector:", @"keys": @"⌥⌘I", @"symbol": @"hammer"},
             @{@"title": @"View Page Source", @"sel": @"viewSource:", @"keys": @"⌥⌘U", @"symbol": @"chevron.left.forwardslash.chevron.right"},
             @{@"title": @"Clear Browsing Data", @"sel": @"clearBrowsingData:", @"keys": @"⇧⌘⌫", @"symbol": @"trash"}];
}
static NSArray *MatchCommands(NSString *q, NSUInteger limit) {
    q = Trim(q.lowercaseString);
    BOOL all = [q hasPrefix:@">"];
    if (all) q = Trim([q substringFromIndex:1]);
    NSMutableArray *out = [NSMutableArray array];
    if (!all && q.length < 2) return out;
    NSArray *words = [q componentsSeparatedByCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
    for (NSDictionary *c in StrikeCommands()) {
        NSString *t = [c[@"title"] lowercaseString];
        NSArray *tw = [t componentsSeparatedByString:@" "];
        BOOL ok = YES;
        for (NSString *w in words) {
            if (!w.length) continue;
            BOOL hit = NO; for (NSString *x in tw) if ([x hasPrefix:w]) hit = YES;
            if (!hit) { ok = NO; break; }
        }
        if (ok) { NSMutableDictionary *d = [c mutableCopy]; d[@"kind"] = @"command"; [out addObject:d]; }
        if (out.count >= limit) break;
    }
    return out;
}

- (NSArray *)suggestionsFor:(NSString *)text {
    if ([Trim(text) hasPrefix:@">"]) return MatchCommands(text, 30);
    NSMutableArray *out = [NSMutableArray array];
    NSURL *u = URLFromInput(text);
    BOOL isSearch = u && [u.absoluteString hasPrefix:[[Engine()[1] componentsSeparatedByString:@"%@"] firstObject]];
    NSString *done = self.completion;
    if (done.length) [out addObject:@{@"kind": @"url", @"title": done, @"url": done, @"detail": @"Go to site"}];
    else if (isSearch) [out addObject:@{@"kind": @"search", @"title": text, @"detail": [NSString stringWithFormat:@"Search with %@", Engine()[0]]}];
    else [out addObject:@{@"kind": @"url", @"title": text, @"url": text, @"detail": @"Go to site"}];
    NSMutableSet *seen = [NSMutableSet set];
    NSString *q = text.lowercaseString;
    for (NSDictionary *b in VBookmarks.shared.allURLs) {
        if ([[b[@"name"] lowercaseString] containsString:q] || [[b[@"url"] lowercaseString] containsString:q]) {
            [out addObject:@{@"kind": @"url", @"title": [b[@"name"] length] ? b[@"name"] : b[@"url"], @"url": b[@"url"], @"detail": @"Bookmark"}];
            [seen addObject:b[@"url"]];
            if (out.count >= 3) break;
        }
    }
    for (NSDictionary *e in [[VHistory forProfile:self.profile] match:text limit:8]) {
        if ([seen containsObject:e[@"u"]]) continue;
        NSURL *eu = [NSURL URLWithString:e[@"u"]];
        NSString *bare = [[eu.host ?: @"" stringByAppendingString:eu.path ?: @""] stringByReplacingOccurrencesOfString:@"www." withString:@""];
        [out addObject:@{@"kind": @"url", @"title": [e[@"ti"] length] ? e[@"ti"] : bare, @"url": e[@"u"], @"detail": bare}];
        if (out.count >= 8) break;
    }
    // open tabs: switch instead of opening a duplicate
    NSUInteger tabsAdded = 0;
    for (VTab *t in self.tabs) {
        if (t == self.current || t.isHome || !t.url) continue;
        if ([[t.title lowercaseString] containsString:q] || [[t.url lowercaseString] containsString:q]) {
            [out insertObject:@{@"kind": @"tab", @"title": t.title.length ? t.title : t.url, @"url": t.url, @"detail": @"Switch to tab", @"tab": t} atIndex:MIN(out.count, 1 + tabsAdded)];
            if (++tabsAdded >= 2) break;
        }
    }
    NSArray *cmds = MatchCommands(text, 3);
    if (cmds.count) {   // after tabs, before history
        NSUInteger at = 1; while (at < out.count && [out[at][@"kind"] isEqualToString:@"tab"]) at++;
        [out insertObjects:cmds atIndexes:[NSIndexSet indexSetWithIndexesInRange:NSMakeRange(at, cmds.count)]];
    }
    if (!isSearch && !done.length) [out addObject:@{@"kind": @"search", @"title": text, @"detail": [NSString stringWithFormat:@"Search with %@", Engine()[0]]}];
    for (NSString *s in self.netSuggestions[q] ?: @[]) {
        if ([s.lowercaseString isEqualToString:q] || out.count >= 11) continue;
        [out addObject:@{@"kind": @"search", @"title": s, @"detail": @""}];
    }
    return out;
}

// Search suggestions come from the search engine you chose (and only it), after a short pause in typing.
- (void)fetchSuggestions:(NSString *)text {
    if (![Defaults() boolForKey:kSuggestNet] || text.length < 2 || [text containsString:@"://"]) return;
    NSString *engine = Engine()[0];
    NSString *enc = [text stringByAddingPercentEncodingWithAllowedCharacters:NSCharacterSet.URLQueryAllowedCharacterSet];
    enc = [enc stringByReplacingOccurrencesOfString:@"&" withString:@"%26"];
    NSDictionary *ends = @{@"DuckDuckGo": @"https://duckduckgo.com/ac/?type=list&q=%@", @"Brave Search": @"https://search.brave.com/api/suggest?q=%@",
                           @"Google": @"https://suggestqueries.google.com/complete/search?client=firefox&q=%@", @"Ecosia": @"https://ac.ecosia.org/autocomplete?type=list&q=%@",
                           @"Bing": @"https://api.bing.com/osjson.aspx?query=%@", @"Startpage": @"https://www.startpage.com/osuggestions?q=%@"};
    NSString *fmt = ends[engine]; if (!fmt) return;
    NSString *q = text.lowercaseString;
    if (!self.netSuggestions) self.netSuggestions = [NSMutableDictionary dictionary];
    if (self.netSuggestions[q]) return;
    [NSObject cancelPreviousPerformRequestsWithTarget:self selector:@selector(startSuggestFetch:) object:nil];
    [self performSelector:@selector(startSuggestFetch:) withObject:@[[NSString stringWithFormat:fmt, enc], q] afterDelay:0.12];
}
- (void)startSuggestFetch:(NSArray *)a {
    NSMutableURLRequest *r = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:a[0]] cachePolicy:NSURLRequestReloadIgnoringLocalCacheData timeoutInterval:4];
    r.HTTPShouldHandleCookies = NO;   // suggestions are anonymous
    [[NSURLSession.sharedSession dataTaskWithRequest:r completionHandler:^(NSData *d, NSURLResponse *resp, NSError *e) {
        id j = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : nil;
        NSMutableArray *list = [NSMutableArray array];
        if ([j isKindOfClass:NSArray.class] && [j count] >= 2 && [j[1] isKindOfClass:NSArray.class]) { for (id s in j[1]) if ([s isKindOfClass:NSString.class]) [list addObject:s]; }
        else if ([j isKindOfClass:NSArray.class]) { for (NSDictionary *o in j) if ([o isKindOfClass:NSDictionary.class] && o[@"phrase"]) [list addObject:o[@"phrase"]]; }
        else if ([j isKindOfClass:NSDictionary.class] && [j[@"suggestions"] isKindOfClass:NSArray.class]) { for (id s in j[@"suggestions"]) if ([s isKindOfClass:NSString.class]) [list addObject:s]; }
        if (list.count > 5) [list removeObjectsInRange:NSMakeRange(5, list.count - 5)];
        dispatch_async(dispatch_get_main_queue(), ^{
            self.netSuggestions[a[1]] = list;
            NSTextField *tf = self.typingField ?: self.toolbar.field;
            NSString *typed = Trim(self.completion ? [tf.stringValue substringToIndex:MIN(self.lastTyped, tf.stringValue.length)] : tf.stringValue);
            if (tf.currentEditor && [typed.lowercaseString isEqualToString:a[1]] && self.suggest.isVisible) {
                NSInteger sel = self.suggest.sel;
                [self.suggest showBelow:[self suggestAnchorFor:tf] items:[self suggestionsFor:typed]];
                self.suggest.sel = sel; [self.suggest.contentView setNeedsDisplay:YES];
            }
        });
    }] resume];
}

- (void)useSuggestion:(NSDictionary *)it newTab:(BOOL)nt {
    [self.suggest dismiss];
    if ([it[@"kind"] isEqualToString:@"tab"] && [self.tabs containsObject:it[@"tab"]]) { [self selectTab:it[@"tab"]]; return; }
    if ([it[@"kind"] isEqualToString:@"command"]) {
        [self.window makeFirstResponder:self.current.web ? (NSResponder *)self.current.web : self.window.contentView];
        [self refreshChrome];
        SEL a = NSSelectorFromString(it[@"sel"]);
        if (![NSApp sendAction:a to:nil from:self]) [NSApp sendAction:a to:gApp from:self];
        return;
    }
    NSString *target = it[@"url"] ?: it[@"title"];
    NSURL *u = [it[@"kind"] isEqualToString:@"search"] ? SearchURL(it[@"title"]) : URLFromInput(target);
    if (!u) return;
    if (nt) [self openURL:u newTab:YES]; else [self openURL:u newTab:NO];
}

// Inline completion: typing "you" fills in "youtube.com" with the rest selected.
- (void)autocomplete:(NSTextField *)f {
    NSText *ed = f.currentEditor;
    NSString *typed = f.stringValue;
    self.completion = nil;
    if (typed.length <= self.lastTyped || [typed containsString:@" "] || typed.length < 2) { self.lastTyped = typed.length; return; }
    self.lastTyped = typed.length;
    NSString *q = typed.lowercaseString;
    for (NSDictionary *e in [[VHistory forProfile:self.profile] match:typed limit:6]) {
        NSString *h = HostOf([NSURL URLWithString:e[@"u"]]);
        if ([h hasPrefix:q] && h.length > q.length) {
            self.completion = h;
            f.stringValue = [typed stringByAppendingString:[h substringFromIndex:typed.length]];
            ed.selectedRange = NSMakeRange(typed.length, h.length - typed.length);
            return;
        }
    }
}

- (BOOL)isAddressField:(id)f { return f && (f == self.toolbar.field || f == self.home.field); }
- (NSRect)suggestAnchorFor:(NSTextField *)f {
    if (f == self.home.field && self.home.window) return [self.window convertRectToScreen:[self.home convertRect:self.home.strike toView:nil]];
    VToolbar *tb = self.toolbar;
    return [self.window convertRectToScreen:[tb convertRect:tb.pill toView:nil]];
}
- (void)controlTextDidBeginEditing:(NSNotification *)n { if (n.object == self.home.field) self.home.needsDisplay = YES; }
- (void)controlTextDidChange:(NSNotification *)n {
    NSTextField *f = n.object;
    if (f == self.findBar.field) { [self find:NO restart:YES]; return; }
    if (![self isAddressField:f]) return;
    self.typingField = f;
    [self autocomplete:f];
    NSString *typed = self.completion ? [f.stringValue substringToIndex:MIN(self.lastTyped, f.stringValue.length)] : f.stringValue;
    if (f == self.toolbar.field) { if (Trim(typed).length) [self hideAddressPanel]; else [self showAddressPanel]; }
    if (!Trim(typed).length) { [self.suggest dismiss]; return; }
    [self.suggest showBelow:[self suggestAnchorFor:f] items:[self suggestionsFor:Trim(typed)]];
    [self fetchSuggestions:Trim(typed)];
}

- (void)controlTextDidEndEditing:(NSNotification *)n {
    if (![self isAddressField:n.object]) return;
    if (n.object == self.home.field) self.home.needsDisplay = YES;
    self.lastTyped = 0; self.completion = nil;
    dispatch_async(dispatch_get_main_queue(), ^{ [self.suggest dismiss]; [self hideAddressPanel]; [self refreshChrome]; });
}

- (BOOL)control:(NSControl *)c textView:(NSTextView *)tv doCommandBySelector:(SEL)sel {
    if (c == self.findBar.field) {
        if (sel == @selector(cancelOperation:)) { [self closeFind:nil]; return YES; }
        if (sel == @selector(insertNewline:)) { [self find:(NSApp.currentEvent.modifierFlags & NSEventModifierFlagShift) != 0 restart:NO]; return YES; }
        return NO;
    }
    if (![self isAddressField:c]) return NO;
    NSTextField *af = (NSTextField *)c;
    if (sel == @selector(moveDown:) || sel == @selector(moveUp:)) {
        if (!self.suggest.isVisible) return NO;
        [self.suggest move:sel == @selector(moveDown:) ? 1 : -1];
        return YES;
    }
    if (sel == @selector(insertNewline:) || sel == @selector(insertNewlineIgnoringFieldEditor:)) {
        NSDictionary *it = self.suggest.isVisible && self.suggest.sel > 0 ? self.suggest.selected : nil;
        BOOL nt = (NSApp.currentEvent.modifierFlags & (NSEventModifierFlagCommand | NSEventModifierFlagOption)) != 0;   // ⌘↩ or ⌥↩: new tab
        if (it) { [self useSuggestion:it newTab:nt]; return YES; }
        NSString *target = self.completion ?: af.stringValue;
        if (af == self.home.field) af.stringValue = @"";
        [self.suggest dismiss];
        if (nt) [self openURL:URLFromInput(target) newTab:YES]; else [self go:target];
        return YES;
    }
    if (sel == @selector(cancelOperation:)) {
        [self.suggest dismiss];
        if (self.current.web) [self.current.web focus]; else [self.window makeFirstResponder:nil];
        [self refreshChrome];
        return YES;
    }
    if (sel == @selector(deleteBackward:)) self.lastTyped = NSUIntegerMax;
    return NO;
}

#pragma mark Toolbar and menu actions

- (void)goBack:(id)s {
    VTab *t = self.current;
    if (t.isHome) { if (t.homeBack) { VPage *p = t.homeBack; t.homeBack = nil; [self restorePage:p in:t anchored:NO]; t.homeAhead = YES; [self refreshChrome]; } return; }
    if (!t.web.canGoBack && t.homeAnchor) { [self showHomeIn:t keeping:t.web asForward:YES]; return; }   // back to the Home you came from
    [t.web goBack];
}
- (void)goForward:(id)s {
    VTab *t = self.current;
    if (t.isHome) { if (t.homeFwd) { VPage *p = t.homeFwd; t.homeFwd = nil; [self restorePage:p in:t anchored:YES]; } return; }
    if (!t.web.canGoForward && t.homeAhead) { [self showHomeIn:t keeping:t.web asForward:NO]; return; }   // forward to the Home you went back from
    [t.web goForward];
}
- (void)reloadOrStop:(id)s { VPage *w = self.current.web; if (w.loading) [w stop]; else [w reload]; }
- (void)hardReload:(id)s { [self.current.web hardReload]; }
- (void)printPage:(id)s { [self.current.web print]; }
- (void)stopLoading:(id)s { [self.current.web stop]; }
- (void)toggleSidebar:(id)s { [self toggleShelf]; }   // Monolith: ⌘S brings up the tabs
- (void)toggleBookmarksBar:(id)s { [self showBookmarkPopup:s]; }   // Monolith: bookmarks live under the address now
- (void)newTabAction:(id)s { [self newTab:nil select:YES]; }
- (void)openLocation:(id)s { [self focusAddress]; }
- (void)closeTabAction:(id)s {
    NSWindow *k = NSApp.keyWindow;
    if (k && k != self.window && !k.isSheet) { [k performClose:nil]; return; }   // ⌘W closes Settings and other windows, like everywhere on macOS
    if (self.current) [self closeTab:self.current];
}
- (void)reopenClosed:(id)s {
    NSDictionary *d = [s isKindOfClass:NSMenuItem.class] && [[s representedObject] isKindOfClass:NSDictionary.class] ? [s representedObject] : self.closed.lastObject;
    if (!d) return;
    [self.closed removeObjectIdenticalTo:d];
    VTab *t = [VTab new]; t.owner = self;
    t.url = d[@"url"]; t.title = d[@"title"]; t.savedState = d[@"state"];
    if ([d[@"mediaKey"] isKindOfClass:NSString.class]) { t.mediaKey = d[@"mediaKey"]; t.mediaTime = t.savedMedia = t.resumeAt = [d[@"mediaTime"] doubleValue]; }
    t.favicon = [VFavicons.shared iconForURL:t.url];
    NSUInteger at = self.current ? [self.tabs indexOfObject:self.current] + 1 : self.tabs.count;
    [self.tabs insertObject:t atIndex:MIN(at, self.tabs.count)];
    [self selectTab:t];
}
- (void)nextTab:(id)s { [self cycle:1]; }
- (void)previousTab:(id)s { [self cycle:-1]; }
- (void)cycle:(NSInteger)d {
    if (self.tabs.count < 2) return;
    NSInteger i = (NSInteger)[self.tabs indexOfObject:self.current];
    [self selectTab:self.tabs[(NSUInteger)((i + d + (NSInteger)self.tabs.count) % (NSInteger)self.tabs.count)]];
}
- (void)selectTabNumber:(NSMenuItem *)m {
    NSInteger n = m.tag;
    if (!self.tabs.count) return;
    [self selectTab:n >= 9 ? self.tabs.lastObject : self.tabs[(NSUInteger)MIN(n - 1, (NSInteger)self.tabs.count - 1)]];
}
- (void)pinCurrent:(id)s { if (self.current) [self togglePin:self.current]; }
- (void)duplicateCurrent:(id)s { if (self.current.url && !self.current.isHome) [self newTab:[NSURL URLWithString:self.current.url] select:YES]; }

- (void)toggleBookmark:(id)s {
    VTab *t = self.current; if (!t.url || t.isHome) return;
    [VBookmarks.shared toggle:t.url title:t.title];
    if (t.favicon) [VFavicons.shared remember:t.favicon forURL:t.url];
    [self.bookmarksBar reload]; [self refreshChrome];
    [self showToast:[VBookmarks.shared find:t.url] ? @"Bookmarked" : @"Bookmark removed"];
}
- (void)openBookmarkItem:(NSMenuItem *)m { [self openURL:[NSURL URLWithString:m.representedObject] newTab:(NSApp.currentEvent.modifierFlags & NSEventModifierFlagCommand) != 0]; }
- (void)openBookmarkInNewTab:(NSMenuItem *)m { [self openURL:[NSURL URLWithString:m.representedObject] newTab:YES]; }
- (void)openAllBookmarks:(NSMenuItem *)m { for (NSString *u in m.representedObject) [self newTab:[NSURL URLWithString:u] select:NO]; }
- (void)copyText:(NSMenuItem *)m { [self copyString:m.representedObject]; }
- (void)copyString:(NSString *)s { if (!s) return; [NSPasteboard.generalPasteboard clearContents]; [NSPasteboard.generalPasteboard setString:s forType:NSPasteboardTypeString]; [self showToast:@"Link copied"]; }
static BOOL RemoveNode(NSMutableArray *list, id n) {
    if ([list indexOfObjectIdenticalTo:n] != NSNotFound) { [list removeObjectIdenticalTo:n]; return YES; }
    for (NSMutableDictionary *x in list) if ([x[@"children"] isKindOfClass:NSMutableArray.class] && RemoveNode(x[@"children"], n)) return YES;
    return NO;
}
- (void)editBookmark:(NSMenuItem *)m {
    NSMutableDictionary *n = m.representedObject;
    NSAlert *a = [NSAlert new]; a.messageText = n[@"children"] ? @"Edit folder" : @"Edit bookmark";
    NSView *box = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 320, n[@"children"] ? 26 : 58)];
    NSTextField *name = [[NSTextField alloc] initWithFrame:NSMakeRect(0, n[@"children"] ? 0 : 32, 320, 24)]; name.stringValue = n[@"name"] ?: @""; name.placeholderString = @"Name";
    NSTextField *url = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 320, 24)]; url.stringValue = n[@"url"] ?: @""; url.placeholderString = @"Address";
    [box addSubview:name]; if (!n[@"children"]) [box addSubview:url];
    a.accessoryView = box; [a addButtonWithTitle:@"Save"]; [a addButtonWithTitle:@"Cancel"];
    a.window.initialFirstResponder = name;
    [a beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r != NSAlertFirstButtonReturn) return;
        n[@"name"] = name.stringValue;
        if (!n[@"children"]) { NSURL *u = URLFromInput(url.stringValue); if (u) n[@"url"] = u.absoluteString; }
        [VBookmarks.shared save]; [self.bookmarksBar reload]; [self refreshChrome];
    }];
}
- (void)newBookmarkFolder:(NSMenuItem *)m {
    NSAlert *a = [NSAlert new]; a.messageText = @"New folder";
    NSTextField *f = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 260, 24)]; f.placeholderString = @"Folder name"; a.accessoryView = f;
    [a addButtonWithTitle:@"Create"]; [a addButtonWithTitle:@"Cancel"]; a.window.initialFirstResponder = f;
    [a beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r != NSAlertFirstButtonReturn || !Trim(f.stringValue).length) return;
        NSMutableDictionary *folder = [@{@"name": Trim(f.stringValue), @"children": [NSMutableArray array]} mutableCopy];
        NSMutableDictionary *after = m.representedObject;
        NSUInteger i = after ? [VBookmarks.shared.bar indexOfObjectIdenticalTo:after] : NSNotFound;
        if (i == NSNotFound) [VBookmarks.shared.bar addObject:folder]; else [VBookmarks.shared.bar insertObject:folder atIndex:i + 1];
        [VBookmarks.shared save]; [self.bookmarksBar reload];
    }];
}
- (void)deleteBookmark:(NSMenuItem *)m {
    NSMutableDictionary *n = m.representedObject;
    BMRemove(VBookmarks.shared.bar, n);
    [VBookmarks.shared save]; [self.bookmarksBar reload]; [self refreshChrome];
}

- (void)siteMenu:(id)s {
    VTab *t = self.current;
    if (t.isHome) { [self focusAddress]; return; }
    NSMenu *m = [[NSMenu alloc] initWithTitle:@""];
    NSURL *u = [NSURL URLWithString:t.url ?: @""];
    [m addItemWithTitle:HostOf(u) action:nil keyEquivalent:@""].enabled = NO;
    [m addItemWithTitle:[u.scheme isEqualToString:@"https"] ? @"Connection is secure" : @"Connection is not secure" action:nil keyEquivalent:@""].enabled = NO;
    [m addItemWithTitle:@"Rendered by WebKit (Safari's engine)" action:nil keyEquivalent:@""].enabled = NO;
    NSString *host = HostOf(u);
    [m addItem:NSMenuItem.separatorItem];
    NSMenuItem *js = [m addItemWithTitle:@"JavaScript on This Site" action:@selector(toggleSiteScripts:) keyEquivalent:@""]; js.target = self; js.representedObject = host;
    js.state = [Defaults() boolForKey:kScripts] && ![SiteArray(self.isPrivate, kJSOff) containsObject:host] ? NSControlStateValueOn : NSControlStateValueOff;
    NSDictionary *perms = SiteDict(self.isPrivate, kSitePerms)[host];
    for (NSString *k in @[@"location", @"camera", @"microphone"]) {
        NSInteger v = [perms[k] integerValue];
        NSMenuItem *pi = [m addItemWithTitle:[NSString stringWithFormat:@"%@: %@", k.capitalizedString, v == 1 ? @"Allowed" : v == 2 ? @"Blocked" : @"Ask"] action:nil keyEquivalent:@""];
        NSMenu *sub = [[NSMenu alloc] initWithTitle:k];
        for (NSInteger opt = 0; opt < 3; opt++) {
            NSMenuItem *o = [sub addItemWithTitle:@[@"Ask", @"Allow", @"Block"][(NSUInteger)opt] action:@selector(setSitePermission:) keyEquivalent:@""];
            o.target = self; o.representedObject = @[host, k, @(opt)]; o.state = opt == v ? NSControlStateValueOn : NSControlStateValueOff;
        }
        pi.submenu = sub;
    }
    NSNumber *z = SiteDict(self.isPrivate, kZoom)[host];
    if (z) { NSMenuItem *zi = [m addItemWithTitle:[NSString stringWithFormat:@"Zoom: %d%% (Reset)", (int)round(z.doubleValue * 100)] action:@selector(zoomReset:) keyEquivalent:@""]; zi.target = self; }
    NSMenuItem *cl = [m addItemWithTitle:@"Clear Cookies and Data for This Site…" action:@selector(clearSiteData:) keyEquivalent:@""]; cl.target = self; cl.representedObject = host;
    [m addItem:NSMenuItem.separatorItem];
    NSMenuItem *c = [m addItemWithTitle:@"Copy Link" action:@selector(copyText:) keyEquivalent:@""]; c.target = self; c.representedObject = u.absoluteString;
    VButton *btn = self.toolbar.infoBtn;
    PopMenu(m, NSMakePoint(0, NSHeight(btn.bounds) + 6), btn);
}

- (void)toggleSiteScripts:(NSMenuItem *)m {
    NSString *h = m.representedObject; if (!h.length) return;
    if (![Defaults() boolForKey:kScripts]) { [Defaults() setBool:YES forKey:kScripts]; }
    NSMutableArray *a = [SiteArray(self.isPrivate, kJSOff) ?: @[] mutableCopy];
    if ([a containsObject:h]) [a removeObject:h]; else [a addObject:h];
    SiteSet(self.isPrivate, kJSOff, a);
    [self showToast:[a containsObject:h] ? [NSString stringWithFormat:@"JavaScript off for %@", h] : [NSString stringWithFormat:@"JavaScript on for %@", h]];
    [self.current.web reload];
}
- (void)setSitePermission:(NSMenuItem *)m {
    NSArray *a = m.representedObject;
    NSMutableDictionary *all = [SiteDict(self.isPrivate, kSitePerms) ?: @{} mutableCopy];
    NSMutableDictionary *mine = [all[a[0]] ?: @{} mutableCopy];
    if ([a[2] integerValue] == 0) [mine removeObjectForKey:a[1]]; else mine[a[1]] = a[2];
    if (mine.count) all[a[0]] = mine; else [all removeObjectForKey:a[0]];
    SiteSet(self.isPrivate, kSitePerms, all);
}
- (void)clearSiteData:(NSMenuItem *)m {
    NSString *h = m.representedObject; if (!h.length) return;
    NSAlert *al = [NSAlert new]; al.messageText = [NSString stringWithFormat:@"Clear cookies and data for %@?", h];
    al.informativeText = @"You'll be signed out of this site."; [al addButtonWithTitle:@"Clear"]; [al addButtonWithTitle:@"Cancel"];
    [al beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r != NSAlertFirstButtonReturn) return;
        WKWebsiteDataStore *ds = self.isPrivate ? self.privateStore : ProfileStore(self.profile);
        [ds fetchDataRecordsOfTypes:WKWebsiteDataStore.allWebsiteDataTypes completionHandler:^(NSArray<WKWebsiteDataRecord *> *recs) {
            NSMutableArray *mine = [NSMutableArray array];
            for (WKWebsiteDataRecord *rec in recs) if ([rec.displayName isEqualToString:h] || [h hasSuffix:[@"." stringByAppendingString:rec.displayName]] || [rec.displayName hasSuffix:[@"." stringByAppendingString:h]]) [mine addObject:rec];
            [ds removeDataOfTypes:WKWebsiteDataStore.allWebsiteDataTypes forDataRecords:mine completionHandler:^{ [self showToast:[NSString stringWithFormat:@"Cleared data for %@", h]]; [self.current.web reload]; }];
        }];
    }];
}

- (void)shieldMenu:(id)s {
    VTab *t = self.current;
    NSMenu *m = [[NSMenu alloc] initWithTitle:@""];
    BOOL on = [Defaults() boolForKey:kBlock];
    NSString *head = !on ? @"Blocking is off" : [NSString stringWithFormat:@"Blocking ads, trackers and pop-ups · %lu rules", (unsigned long)gRuleCount];
    (void)t;
    [m addItemWithTitle:head action:nil keyEquivalent:@""].enabled = NO;
    [m addItemWithTitle:[@"Filter lists: " stringByAppendingString:VBlocker.shared.status] action:nil keyEquivalent:@""].enabled = NO;
    [m addItem:NSMenuItem.separatorItem];
    NSString *site = HostOf([NSURL URLWithString:t.url ?: @""]);
    if (on && site.length && !t.isHome) {
        BOOL allowed = [SiteArray(self.isPrivate, kAllowlist) containsObject:site];
        NSMenuItem *si = [m addItemWithTitle:[NSString stringWithFormat:allowed ? @"Turn On Blocking for %@" : @"Turn Off Blocking for %@", site] action:@selector(toggleBlockingSite:) keyEquivalent:@""];
        si.target = self; si.representedObject = site;
    }
    if (site.length && !t.isHome && [t.url hasPrefix:@"http"]) {
        NSMenuItem *be = [m addItemWithTitle:@"Block Element on This Page…" action:@selector(blockElement:) keyEquivalent:@""]; be.target = self;
        NSString *key = [site hasPrefix:@"www."] ? [site substringFromIndex:4] : site;
        NSUInteger n = [SiteDict(self.isPrivate, @"cosmeticFilters")[key] count];
        if (n) {
            NSMenuItem *ul = [m addItemWithTitle:@"Undo Last Blocked Element" action:@selector(undoLastElement:) keyEquivalent:@""]; ul.target = self; ul.representedObject = key;
            NSMenuItem *re = [m addItemWithTitle:[NSString stringWithFormat:@"Show All %lu Hidden Element%@ on %@", (unsigned long)n, n == 1 ? @"" : @"s", key] action:@selector(resetElements:) keyEquivalent:@""]; re.target = self; re.representedObject = key;
        }
        [m addItem:NSMenuItem.separatorItem];
    }
    NSMenuItem *g = [m addItemWithTitle:on ? @"Turn Off Blocking Everywhere" : @"Turn On Blocking" action:@selector(toggleBlockingGlobal:) keyEquivalent:@""]; g.target = self;
    NSMenuItem *u = [m addItemWithTitle:@"Update Filter Lists Now" action:@selector(updateListsNow:) keyEquivalent:@""]; u.target = self;
    [m addItem:NSMenuItem.separatorItem];
    NSMenuItem *st = [m addItemWithTitle:@"Settings…" action:@selector(showSettings:) keyEquivalent:@""]; st.target = gApp;
    VButton *btn = self.toolbar.shieldBtn;
    PopMenu(m, NSMakePoint(0, NSHeight(btn.bounds) + 6), btn);
}

- (void)toggleBlockingGlobal:(id)s {
    BOOL on = ![Defaults() boolForKey:kBlock];
    [Defaults() setBool:on forKey:kBlock];
    IrisSetBlocking(on);
    [self.current.web reload];
    [self refreshChrome];
}
- (void)toggleBlockingSite:(NSMenuItem *)m {
    NSString *site = m.representedObject; if (!site.length) return;
    NSMutableArray *a = [SiteArray(self.isPrivate, kAllowlist) ?: @[] mutableCopy];
    BOOL wasAllowed = [a containsObject:site];
    if (wasAllowed) [a removeObject:site]; else [a addObject:site];
    SiteSet(self.isPrivate, kAllowlist, a);
    [self showToast:wasAllowed ? [NSString stringWithFormat:@"Blocking back on for %@…", site] : [NSString stringWithFormat:@"Blocking off for %@…", site]];
    VPage *w = self.current.web;
    ShieldChanged();
    if (self.isPrivate) { [w reload]; return; }   // switched per page by WebKit: nothing to rebuild, and nothing of it kept
    IrisReloadBlocklistsThen(^{ [w reload]; });
}
- (void)updateListsNow:(id)s {
    [self showToast:@"Updating filter lists…"];
    [VBlocker.shared updateLists:YES done:^{ [self showToast:@"Filter lists updated"]; }];
}

- (void)mainMenu:(id)s {
    NSMenu *m = [[NSMenu alloc] initWithTitle:@""];
    NSMenuItem *(^add)(NSString *, SEL, id) = ^NSMenuItem *(NSString *t, SEL a, id target) { NSMenuItem *i = [m addItemWithTitle:t action:a keyEquivalent:@""]; i.target = target; return i; };
    if (!self.isPrivate) {   // whose window this is, at the top: its avatar and name, opening the list of profiles
        NSMenuItem *pi = [m addItemWithTitle:ProfileName(self.profile) action:nil keyEquivalent:@""];
        pi.image = ProfileAvatar(self.profile, ProfileName(self.profile), 16);
        pi.submenu = [self profilesMenu];
        [m addItem:NSMenuItem.separatorItem];
    }
    add(@"New Tab", @selector(newTabAction:), self);
    add(@"Reopen Closed Tab", @selector(reopenClosed:), self).enabled = self.closed.count > 0;
    [m addItem:NSMenuItem.separatorItem];
    NSMenuItem *hist = [m addItemWithTitle:@"History" action:nil keyEquivalent:@""];
    NSMenu *hm = [[NSMenu alloc] initWithTitle:@"History"];
    for (NSDictionary *e in [[VHistory forProfile:self.profile] recent:20]) {
        NSString *title = [e[@"ti"] length] ? e[@"ti"] : e[@"u"];
        if (title.length > 60) title = [[title substringToIndex:59] stringByAppendingString:@"…"];
        NSMenuItem *i = [hm addItemWithTitle:title action:@selector(openBookmarkItem:) keyEquivalent:@""];
        i.target = self; i.representedObject = e[@"u"];
        NSImage *ic = [VFavicons.shared iconForURL:e[@"u"]]; if (ic) { NSImage *sm = [ic copy]; sm.size = NSMakeSize(16, 16); i.image = sm; }
    }
    if (!hm.numberOfItems) [hm addItemWithTitle:@"Nothing yet" action:nil keyEquivalent:@""].enabled = NO;
    [hm addItem:NSMenuItem.separatorItem];
    NSMenuItem *all = [hm addItemWithTitle:@"Show All History" action:@selector(showHistory:) keyEquivalent:@"y"]; all.target = self;
    NSMenuItem *clr = [hm addItemWithTitle:@"Clear History…" action:@selector(clearBrowsingData:) keyEquivalent:@""]; clr.target = self;
    hist.submenu = hm;
    add(@"Bookmarks", @selector(showBookmarks:), self);
    add(@"Downloads", @selector(showDownloadManager:), self);
    [m addItem:NSMenuItem.separatorItem];
    VPage *w = self.current.web;
    if (w) {
        [m addItemWithTitle:[NSString stringWithFormat:@"Zoom  %d%%", (int)round(w.zoom * 100)] action:nil keyEquivalent:@""].enabled = NO;
        add(@"Zoom In", @selector(zoomIn:), self); add(@"Zoom Out", @selector(zoomOut:), self); add(@"Actual Size", @selector(zoomReset:), self);
        add(@"Find on Page…", @selector(showFind:), self);
        add(@"Save Page to Downloads", @selector(savePage:), self);
        add(@"View Page Source", @selector(viewSource:), self);
        if (!IrisIsDefaultBrowser()) add(@"Open in Default Browser", @selector(openInDefaultBrowser:), self).representedObject = w.url;
        [m addItem:NSMenuItem.separatorItem];
    }
    NSArray *exts = FExtHost.shared.extensions;
    if (exts.count) {
        NSMenuItem *em = [m addItemWithTitle:@"Extensions" action:nil keyEquivalent:@""];
        NSMenu *sub = [[NSMenu alloc] initWithTitle:@"Extensions"];
        for (id e in exts) { NSMenuItem *i = [sub addItemWithTitle:[e valueForKey:@"name"] action:@selector(openExtension:) keyEquivalent:@""]; i.target = self; i.representedObject = e; }
        [sub addItem:NSMenuItem.separatorItem];
        NSMenuItem *f = [sub addItemWithTitle:@"Show Extensions Folder" action:@selector(showExtensions:) keyEquivalent:@""]; f.target = gApp;
        em.submenu = sub;
    } else add(@"Extensions Folder…", @selector(showExtensions:), gApp);
    add(@"Settings…", @selector(showSettings:), gApp);
    VButton *btn = self.toolbar.menuBtn;
    PopMenuRight(m, NSMakePoint(NSWidth(btn.bounds), NSHeight(btn.bounds) + 6), btn);
}

- (void)openExtension:(NSMenuItem *)m { [FExtHost.shared openPopup:m.representedObject from:self.toolbar.menuBtn]; }

// A page that already exists (a popup the site opened) gets its own tab.
// A tab opened without switching to it (⌘-click, middle-click, "Open in Background"): the hint at the bottom edge
// lights up in your highlight colour, or the strip shows the new card if it's already up.
- (void)tabOpenedBehind {
    if ([[self valueForKey:@"pageFull"] boolValue]) return;   // a video filling the window: nothing lights up over it
    VTabShelf *sh = (VTabShelf *)self.shelf;
    if (sh.shown) { [sh reload]; [sh scrollToNewest]; return; }
    [(VShelfHandle *)self.shelfHandle flashNewTab];
}
- (void)newTabWithPage:(VPage *)p url:(NSURL *)u select:(BOOL)sel {
    if (gWebApp && self.tabs.count) {   // a window the page opened (a sign-in popup): its own window, still talking to its opener
        VWindow *w = [[VWindow alloc] initPrivate:NO state:@{@"empty": @YES}];
        NSRect f = self.window.frame; NSSize s = NSMakeSize(MIN(560, NSWidth(f)), MIN(720, NSHeight(f)));
        [w.window setFrame:NSMakeRect(NSMidX(f) - s.width / 2, NSMidY(f) - s.height / 2, s.width, s.height) display:NO];
        [w newTabWithPage:p url:u select:YES];
        [w showWindow:nil]; [w windowDidResize:nil]; [w.window makeKeyAndOrderFront:nil];
        return;
    }
    VTab *t = [VTab new]; t.owner = self;
    t.url = u.absoluteString; t.title = u.host ?: @"New Tab";
    p.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    p.tab = t; t.web = p;
    [self.tabs addObject:t];   // at the right end, like every new tab
    if (sel) [self selectTab:t]; else { t.hiddenAt = t.openedFresh = NSDate.date.timeIntervalSince1970; [self refreshChrome]; [self tabOpenedBehind]; }
    [self.sidebar reload];
    [self scheduleSave];
}

- (void)openLinkInBackground:(NSMenuItem *)m { [self newTab:[NSURL URLWithString:m.representedObject] select:NO]; }
- (void)bookmarkURL:(NSMenuItem *)m {
    NSString *u = m.representedObject; if (!u) return;
    if (![VBookmarks.shared find:u]) [VBookmarks.shared toggle:u title:HostOf([NSURL URLWithString:u])];
    [self.bookmarksBar reload]; [self showToast:@"Bookmarked"];
}
- (void)searchFor:(NSMenuItem *)m { NSURL *u = URLFromInput(m.representedObject); if (u) [self newTab:u select:YES]; }
- (void)openInDefaultBrowser:(NSMenuItem *)m {
    NSString *u = [m isKindOfClass:NSMenuItem.class] ? m.representedObject : nil; u = u ?: self.current.url;
    if (u) [NSWorkspace.sharedWorkspace openURL:[NSURL URLWithString:u]];
}
// View Source opens Iris's code viewer beside the page: what the server sent, and the page as it stands now.
- (void)viewSource:(id)s {
    VTab *t = self.current; NSString *u = t.url;
    if (!u.length || t.isHome || [u hasPrefix:@"iris://source"]) return;
    if (![u hasPrefix:@"http"]) { [self showToast:@"Only web pages have a source to show"]; return; }
    NSString *ident = NSUUID.UUID.UUIDString;
    void (^open)(id) = ^(id dom) {
        if (!gSource) gSource = [NSMutableDictionary dictionary];
        if (gSource.count > 20) [gSource removeAllObjects];
        gSource[ident] = @{@"url": u, @"title": t.title ?: @"", @"dom": [dom isKindOfClass:NSString.class] ? dom : @""};
        [self newTab:[NSURL URLWithString:SourceViewerURL(u, ident)] select:YES];
    };
    if (!t.web.web) { open(nil); return; }
    [t.web.web evaluateJavaScript:@"(()=>{const d=document.doctype;return (d?'<!DOCTYPE '+d.name+(d.publicId?' PUBLIC \"'+d.publicId+'\"':'')+(d.systemId?' \"'+d.systemId+'\"':'')+'>\n':'')+(document.documentElement?document.documentElement.outerHTML:'')})()"
                    inFrame:nil inContentWorld:WKContentWorld.defaultClientWorld completionHandler:^(id r, NSError *e) { open(r); }];
}
- (NSURL *)downloadFolder {
    NSString *d = [Defaults() stringForKey:kDownloadDir];
    return d.length ? [NSURL fileURLWithPath:d] : [NSFileManager.defaultManager URLsForDirectory:NSDownloadsDirectory inDomains:NSUserDomainMask].firstObject;
}
/// Save a file into the download folder (or ask where, if that's the setting), under a name that doesn't clash.
- (void)saveData:(NSData *)data name:(NSString *)name {
    NSString *base = name.length ? name : @"download";
    void (^write)(NSURL *) = ^(NSURL *dest) {
        if ([data writeToURL:dest atomically:YES]) [self showToast:[NSString stringWithFormat:@"Saved %@", dest.lastPathComponent]];
        else [self showToast:@"Couldn't save the file"];
    };
    if ([Defaults() boolForKey:kAskDownload]) {
        NSSavePanel *p = [NSSavePanel savePanel]; p.nameFieldStringValue = base; p.directoryURL = self.downloadFolder;
        [p beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) { if (r == NSModalResponseOK) write(p.URL); }];
        return;
    }
    NSURL *dir = self.downloadFolder;
    NSURL *dest = [dir URLByAppendingPathComponent:base];
    for (int n = 1; [NSFileManager.defaultManager fileExistsAtPath:dest.path]; n++)
        dest = [dir URLByAppendingPathComponent:[NSString stringWithFormat:@"%@ %d%@", base.stringByDeletingPathExtension, n, base.pathExtension.length ? [@"." stringByAppendingString:base.pathExtension] : @""]];
    write(dest);
}
- (void)downloadURL:(NSMenuItem *)m {
    NSURL *u = [NSURL URLWithString:m.representedObject]; if (!u) return;
    if (self.current.web) { [self.current.web download:u.absoluteString]; return; }   // Chromium's downloader keeps your sign-in
    [self showToast:@"Downloading…"];
    [[NSURLSession.sharedSession dataTaskWithURL:u completionHandler:^(NSData *d, NSURLResponse *r, NSError *e) {
        dispatch_async(dispatch_get_main_queue(), ^{
            if (!d || e) { [self showToast:@"Download failed"]; return; }
            [self saveData:d name:r.suggestedFilename ?: u.lastPathComponent];
        });
    }] resume];
}
- (void)savePage:(id)s {
    VPage *w = self.current.web; if (!w) return;
    NSString *title = [[self.current.title ?: @"page" componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"/:\\?%*|\"<>"]] componentsJoinedByString:@"-"];
    [w source:^(NSString *src) {
        if (src.length) [self saveData:[src dataUsingEncoding:NSUTF8StringEncoding] name:[title stringByAppendingPathExtension:@"html"]];
    }];
}

- (void)openDownloads:(id)s {
    [NSWorkspace.sharedWorkspace openURL:self.downloadFolder];
}
- (void)clearBrowsingData:(id)s {
    NSAlert *a = [NSAlert new];
    a.messageText = @"Clear history?";
    a.informativeText = @"This removes your browsing history and address-bar suggestions. Bookmarks and tabs stay.";
    [a addButtonWithTitle:@"Clear"]; [a addButtonWithTitle:@"Cancel"];
    [a beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r != NSAlertFirstButtonReturn) return;
        [[VHistory forProfile:self.profile] clear];
        [self showToast:@"History cleared"];
    }];
}

- (void)setZoom:(CGFloat)z {
    VPage *w = self.current.web; if (!w) return;
    z = MAX(0.3, MIN(3, z));
    [w setZoomLevel:z];
    NSMutableDictionary *d = [SiteDict(self.isPrivate, kZoom) ?: @{} mutableCopy];
    NSString *h = HostOf([NSURL URLWithString:w.url ?: @""]);
    if (fabs(z - 1) < 0.01) [d removeObjectForKey:h]; else if (h.length) d[h] = @(z);
    SiteSet(self.isPrivate, kZoom, d);
    [self showToast:[NSString stringWithFormat:@"Zoom %d%%", (int)round(z * 100)]];
}
- (void)zoomIn:(id)s { [self setZoom:self.current.web.zoom + 0.1]; }
- (void)zoomOut:(id)s { [self setZoom:self.current.web.zoom - 0.1]; }
- (void)zoomReset:(id)s { [self setZoom:1]; }

#pragma mark Find

- (void)showFind:(id)s {
    if (!self.current.web) return;
    if ([self.current.url hasPrefix:@"iris://source"]) {   // the code viewer searches all of the file, not just what's on screen
        [self.current.web.web evaluateJavaScript:@"window.irisFind&&irisFind()" completionHandler:nil]; return;
    }
    self.findBar.hidden = NO;
    [self.content addSubview:self.findBar];
    [self.window makeFirstResponder:self.findBar.field];
    [self.findBar.field.currentEditor selectAll:nil];
}
- (void)closeFind:(id)s {
    self.findBar.hidden = YES; [self.findBar removeFromSuperview];
    [self.current.web stopFind];
    if (self.current.web) [self.current.web focus];
}
- (void)find:(BOOL)backwards restart:(BOOL)restart {
    VPage *w = self.current.web; NSString *q = self.findBar.field.stringValue;
    if (!w || !q.length) { [w stopFind]; self.findBar.result.stringValue = @""; return; }
    [w find:q forward:!backwards next:!restart];
}
- (void)findCount:(int)count active:(int)active {
    if (self.findBar.hidden) return;
    self.findBar.result.stringValue = count <= 0 ? @"No matches" : active < 0 ? [NSString stringWithFormat:@"%d match%@", count, count == 1 ? @"" : @"es"] : [NSString stringWithFormat:@"%d of %d", active, count];
    self.findBar.result.textColor = count > 0 ? vFaint : HexA(0xe57373, 1);
}

#pragma mark Toast

- (void)showToast:(NSString *)s {
    VToast *t = (VToast *)self.toast;
    [t setMessage:s];
    NSSize sz = t.fittingSize;
    NSRect cb = self.content.bounds;
    sz.width = MIN(sz.width, NSWidth(cb) - 40);
    CGFloat y = self.content.isFlipped ? 14 : NSHeight(cb) - sz.height - 14;
    t.frame = NSMakeRect(round((NSWidth(cb) - sz.width) / 2), y, sz.width, sz.height);
    BOOL shown = t.superview == self.content && t.alphaValue > 0.5;
    if (t.superview != self.content) [self.content addSubview:t positioned:NSWindowAbove relativeTo:nil];
    if (!shown) [t appear];
    [NSObject cancelPreviousPerformRequestsWithTarget:self selector:@selector(hideToast) object:nil];
    [self performSelector:@selector(hideToast) withObject:nil afterDelay:MIN(5, 1.9 + s.length * 0.03)];   // longer messages stay a little longer
}
- (void)hideToast { [(VToast *)self.toast vanish]; }

@end

#pragma mark - Page tools: reader, PDF, web archive, share, open file, inspector

// Pulls the main article out of a page (a small Readability-style pass), run in Iris's own world so
// the page can't interfere. Returns {title, byline, site, lang, dir, html, words}.
static NSString *ReaderExtractJS(void) {
    return @"const doc=document;const W=s=>(s||'').replace(/\\s+/g,' ').trim();"
    "const meta=n=>{const m=doc.querySelector('meta[property=\"'+n+'\"],meta[name=\"'+n+'\"]');return m?W(m.content):''};"
    "const junk=/(comment|share|social|related|promo|advert|^ad-|-ad$|\\bads?\\b|sponsor|newsletter|subscribe|signup|cookie|popup|modal|banner|breadcrumb|pagination|toolbar|sidebar|footer|masthead|byline-share|outbrain|taboola|recirc|more-from|read-next|paywall)/i;"
    "const textLen=e=>W(e.textContent).length;const linkLen=e=>{let n=0;for(const a of e.querySelectorAll('a'))n+=W(a.textContent).length;return n};"
    "let best=null,bestScore=0;const scores=new Map();"
    "for(const p of doc.querySelectorAll('p,pre,blockquote,td')){const t=W(p.textContent);if(t.length<40)continue;"
    "const s=1+t.split(',').length+Math.min(3,Math.floor(t.length/100));let e=p.parentElement,f=1;"
    "for(let i=0;e&&i<3;i++,e=e.parentElement,f/=2){scores.set(e,(scores.get(e)||0)+s*f)}}"
    "for(const [e,s0] of scores){const tl=textLen(e)||1;let s=s0*(1-linkLen(e)/tl);const idc=(e.id+' '+e.className);"
    "if(/article|content|post|story|entry|main|body|text/i.test(idc))s*=1.25;if(junk.test(idc))s*=.3;if(e.tagName==='ARTICLE'||e.tagName==='MAIN')s*=1.3;"
    "if(s>bestScore){bestScore=s;best=e}}"
    "const arts=[...doc.querySelectorAll('article')].filter(a=>textLen(a)>600).sort((a,b)=>textLen(b)-textLen(a));"
    "if(arts[0]&&(!best||arts[0].contains(best)||textLen(arts[0])>textLen(best)*.9))best=arts[0];"
    "if(!best||textLen(best)<250)return {error:'Iris couldn\\'t find an article on this page.'};"
    "const root=best.cloneNode(true);"
    "for(const img of root.querySelectorAll('img')){const real=img.getAttribute('data-src')||img.getAttribute('data-lazy-src')||img.getAttribute('data-original');if(real)img.setAttribute('src',real)}"
    "const live=best.querySelectorAll('img'),copy=root.querySelectorAll('img');copy.forEach((c,i)=>{const l=live[i];if(l&&l.currentSrc&&!/^data:/.test(l.currentSrc))c.setAttribute('src',l.currentSrc);"
    "try{c.setAttribute('src',new URL(c.getAttribute('src')||'',doc.baseURI).href)}catch(e){};c.removeAttribute('srcset')});"
    "for(const a of root.querySelectorAll('a[href]')){try{a.setAttribute('href',new URL(a.getAttribute('href'),doc.baseURI).href)}catch(e){}}"
    "root.querySelectorAll('script,style,noscript,iframe,object,embed,form,button,input,select,textarea,nav,aside,footer,svg,canvas,dialog,[hidden],[aria-hidden=true],[role=navigation],[role=complementary],[role=dialog]').forEach(e=>e.remove());"
    "const clutter=/(^|\\s)(hatnote|ambox|mbox-[a-z]+|metadata|navbox|vertical-navbox|infobox|sidebar|mw-editsection|noprint|shortdescription|reflist|toc|sistersitebox|mw-jump-link|printfooter|catlinks|reference|mw-empty-elt|portal|authority-control)(\\s|$)/;"
    "root.querySelectorAll('[class]').forEach(e=>{if(e.isConnected&&typeof e.className==='string'&&clutter.test(e.className))e.remove()});"
    "for(const e of [...root.querySelectorAll('div,section,ul,header,figure,span')]){if(!e.isConnected)continue;const idc=(e.id+' '+(typeof e.className==='string'?e.className:''));"
    "const tl=textLen(e);if(junk.test(idc)&&tl<800){e.remove();continue}if(tl&&linkLen(e)/tl>.65&&tl<500&&!e.querySelector('img')){e.remove()}}"
    "const h1t=W((doc.querySelector('h1')||{}).textContent),og=meta('og:title');const title=(h1t&&(!og||og.startsWith(h1t)||h1t.length>10))?h1t:(og||h1t||doc.title);"
    "const h=root.querySelector('h1');if(h&&W(h.textContent)===title)h.remove();"
    "const words=W(root.textContent).split(' ').length;"
    "return {title,byline:meta('author')||meta('article:author')||W((doc.querySelector('[rel=author],.author,.byline,[itemprop=author]')||{}).textContent).slice(0,120),"
    "site:meta('og:site_name')||location.hostname.replace(/^www\\./,''),lang:doc.documentElement.lang||'',dir:doc.dir||'',html:root.innerHTML,words,url:location.href,"
    "published:meta('article:published_time')||((doc.querySelector('time[datetime]')||{}).getAttribute?doc.querySelector('time[datetime]').getAttribute('datetime'):'')}";
}

// Peek: a floating look at a link over the current page. Esc or a click outside closes it; "Open in Tab" keeps it.
@interface VPeek : NSView
@property (strong) FWebView *web;
@property (strong) NSView *card;
@property (strong) NSTextField *label;
@property (weak) VWindow *owner;
@property (strong) id monitor;
@end
@implementation VPeek
- (BOOL)isFlipped { return YES; }
- (void)drawRect:(NSRect)d { [[NSColor colorWithWhite:0 alpha:ThemeIsLight() ? 0.25 : 0.5] setFill]; NSRectFillUsingOperation(d, NSCompositingOperationSourceOver); }
- (void)mouseDown:(NSEvent *)e { if (!NSPointInRect([self convertPoint:e.locationInWindow fromView:nil], self.card.frame)) [self.owner closePeek:nil]; }
- (void)resizeSubviewsWithOldSize:(NSSize)o {
    NSRect b = self.bounds;
    CGFloat w = MIN(NSWidth(b) - 80, 1100), h = NSHeight(b) - 64;
    self.card.frame = NSMakeRect(round((NSWidth(b) - w) / 2), 32, w, h);
    self.label.frame = NSMakeRect(16, 10, w - 160, 18);
    for (NSView *v in self.card.subviews) if ([v isKindOfClass:VButton.class]) v.frame = NSMakeRect(v.tag == 1 ? w - 72 : w - 40, 4, 30, 28);
    self.web.frame = NSMakeRect(0, 36, w, h - 36);
}
@end

@implementation VWindow (Tools)
- (void)peekLink:(NSMenuItem *)m { NSURL *u = [NSURL URLWithString:m.representedObject ?: @""]; if (u) [self peekURL:u]; }
- (void)peekURL:(NSURL *)u {
    [self closePeek:nil];
    VPeek *pk = [[VPeek alloc] initWithFrame:self.content.bounds];
    pk.owner = self; pk.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable; pk.identifier = @"peek";
    NSView *card = [[NSView alloc] initWithFrame:NSZeroRect]; card.wantsLayer = YES;
    card.layer.backgroundColor = vContentBg.CGColor; card.layer.cornerRadius = 12; card.layer.masksToBounds = YES;
    card.layer.borderWidth = 1; card.layer.borderColor = vLine.CGColor;
    NSView *head = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 4000, 36)]; head.wantsLayer = YES; head.layer.backgroundColor = vCard.CGColor;
    [card addSubview:head];
    pk.label = [NSTextField labelWithString:HostOf(u) ?: u.absoluteString];
    pk.label.font = UIFont(12.5, NSFontWeightMedium); pk.label.textColor = vDim; pk.label.lineBreakMode = NSLineBreakByTruncatingTail;
    [card addSubview:pk.label];
    VButton *open = [VButton symbol:@"arrow.up.forward.square" size:13 tip:@"Open in tab" target:self action:@selector(adoptPeek:)]; open.tag = 1;
    VButton *close = [VButton symbol:@"xmark" size:11 tip:@"Close (esc)" target:self action:@selector(closePeek:)]; close.tag = 2;
    [card addSubview:open]; [card addSubview:close];
    pk.web = [[FWebView alloc] initWithFrame:NSZeroRect configuration:[self pageConfig]];
    pk.web.allowsBackForwardNavigationGestures = YES;
    if (@available(macOS 12.0, *)) pk.web.underPageBackgroundColor = vContentBg;
    [card addSubview:pk.web];
    pk.card = card; [pk addSubview:card];
    [self.content addSubview:pk];
    [pk resizeSubviewsWithOldSize:pk.bounds.size];
    [pk.web loadRequest:[NSURLRequest requestWithURL:u]];
    [self.window makeFirstResponder:pk.web];
    __weak VWindow *ws = self;
    pk.monitor = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent *(NSEvent *e) {
        if (e.keyCode == 53 && e.window == ws.window) { [ws closePeek:nil]; return nil; }   // esc
        return e;
    }];
}
- (VPeek *)peekView { for (NSView *v in self.content.subviews) if ([v isKindOfClass:VPeek.class]) return (VPeek *)v; return nil; }
- (void)closePeek:(id)s {
    VPeek *pk = [self peekView]; if (!pk) return;
    if (pk.monitor) [NSEvent removeMonitor:pk.monitor];
    [pk.web stopLoading]; [pk removeFromSuperview];
    [self.current.web focus];
}
- (void)adoptPeek:(id)s {   // the peeked page becomes a real tab, history and all
    VPeek *pk = [self peekView]; if (!pk) return;
    FWebView *w = pk.web; NSURL *u = w.URL ?: [NSURL URLWithString:@"about:blank"];
    [w removeFromSuperview]; pk.web = nil;
    if (pk.monitor) [NSEvent removeMonitor:pk.monitor];
    [pk removeFromSuperview];
    VPage *p = [[VPage alloc] initWithFrame:self.content.bounds web:w];
    [self newTabWithPage:p url:u select:YES];
}

- (void)toggleReader:(id)s {
    VPage *p = self.current.web; if (!p) return;
    NSURL *u = p.web.URL;
    if ([u.scheme isEqualToString:@"iris"] && [u.host isEqualToString:@"reader"]) {   // already reading: back to the page
        if (p.web.canGoBack) [p.web goBack];
        else { NSString *orig = nil; for (NSURLQueryItem *q in [NSURLComponents componentsWithURL:u resolvingAgainstBaseURL:NO].queryItems) if ([q.name isEqualToString:@"u"]) orig = q.value; if (orig) [self openURL:[NSURL URLWithString:orig] newTab:NO]; }
        return;
    }
    if (![u.scheme hasPrefix:@"http"]) { [self showToast:@"Reader works on web articles"]; return; }
    [p.web callAsyncJavaScript:ReaderExtractJS() arguments:@{} inFrame:nil inContentWorld:[WKContentWorld worldWithName:@"iris"] completionHandler:^(id r, NSError *e) {
        if (![r isKindOfClass:NSDictionary.class] || r[@"error"]) { [self showToast:[r isKindOfClass:NSDictionary.class] ? r[@"error"] : @"Couldn't open Reader on this page"]; return; }
        if (!gReader) gReader = [NSMutableDictionary dictionary];
        if (gReader.count > 30) [gReader removeAllObjects];
        NSString *token = [NSUUID UUID].UUIDString;
        gReader[token] = r;
        NSURLComponents *c = [NSURLComponents componentsWithString:@"iris://reader/"];
        c.queryItems = @[[NSURLQueryItem queryItemWithName:@"id" value:token], [NSURLQueryItem queryItemWithName:@"u" value:u.absoluteString]];
        [p.web loadRequest:[NSURLRequest requestWithURL:c.URL]];
    }];
}

- (void)exportPDF:(id)s {
    VPage *p = self.current.web; if (!p) return;
    NSString *title = [[self.current.title ?: @"Page" componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"/:\\?%*|\"<>"]] componentsJoinedByString:@"-"];
    [p.web createPDFWithConfiguration:nil completionHandler:^(NSData *d, NSError *e) {
        if (d.length) [self saveData:d name:[title stringByAppendingPathExtension:@"pdf"]]; else [self showToast:@"Couldn't make a PDF"];
    }];
}
- (void)saveWebArchive:(id)s {
    VPage *p = self.current.web; if (!p) return;
    NSString *title = [[self.current.title ?: @"Page" componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"/:\\?%*|\"<>"]] componentsJoinedByString:@"-"];
    [p.web createWebArchiveDataWithCompletionHandler:^(NSData *d, NSError *e) {
        if (d.length) [self saveData:d name:[title stringByAppendingPathExtension:@"webarchive"]]; else [self showToast:@"Couldn't save the page"];
    }];
}

- (void)sharePage:(id)s {
    NSURL *u = [NSURL URLWithString:self.current.url ?: @""]; if (!u) return;
    NSSharingServicePicker *pk = [[NSSharingServicePicker alloc] initWithItems:@[u]];
    NSView *anchor = self.toolbar.menuBtn ?: self.toolbar;
    [pk showRelativeToRect:anchor.bounds ofView:anchor preferredEdge:NSRectEdgeMinY];
}
- (void)emailLink:(id)s {
    NSURL *u = [NSURL URLWithString:self.current.url ?: @""]; if (!u) return;
    NSSharingService *m = [NSSharingService sharingServiceNamed:NSSharingServiceNameComposeEmail];
    m.subject = self.current.title ?: u.host;
    if ([m canPerformWithItems:@[u]]) [m performWithItems:@[u]]; else [self showToast:@"No mail app is set up"];
}

- (void)openFile:(id)s {
    NSOpenPanel *o = [NSOpenPanel openPanel];
    o.allowedContentTypes = @[UTTypeHTML, UTTypePDF, UTTypeImage, UTTypePlainText, UTTypeSVG, [UTType typeWithFilenameExtension:@"webarchive"] ?: UTTypeData, UTTypeXML, UTTypeMovie, UTTypeAudio];
    o.allowsMultipleSelection = YES;
    [o beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r != NSModalResponseOK) return;
        BOOL first = YES;
        for (NSURL *u in o.URLs) { [self newTab:u select:first]; first = NO; }
    }];
}

- (void)findSelection:(id)s {
    VPage *p = self.current.web; if (!p) return;
    [p.web evaluateJavaScript:@"String(getSelection()||'').trim().slice(0,200)" completionHandler:^(id r, NSError *e) {
        NSString *sel = [r isKindOfClass:NSString.class] ? r : @"";
        if (!sel.length) { NSBeep(); return; }
        [self showFind:nil];
        self.findBar.field.stringValue = sel;
        [self find:NO restart:YES];
    }];
}

static id Inspector(VPage *p) { @try { return [p.web valueForKey:@"_inspector"]; } @catch (NSException *e) { return nil; } }
- (void)showInspector:(id)s {
    id i = Inspector(self.current.web);
    if (i && [i respondsToSelector:@selector(show)]) [i performSelector:@selector(show)]; else [self showToast:@"Web Inspector isn't available"];
}
- (void)showConsole:(id)s {
    id i = Inspector(self.current.web);
    if (i && [i respondsToSelector:NSSelectorFromString(@"showConsole")]) ((void (*)(id, SEL))objc_msgSend)(i, NSSelectorFromString(@"showConsole")); else [self showInspector:s];
}

- (void)closeOtherTabs:(id)s {
    VTab *keep = self.current; if (!keep) return;
    NSUInteger n = 0;
    for (VTab *t in self.tabs.copy) if (t != keep && !t.pinned) { [self closeTab:t]; n++; }
    [self selectTab:keep];
    if (n) [self showToast:[NSString stringWithFormat:@"Closed %lu tab%@ · ⇧⌘T reopens", (unsigned long)n, n == 1 ? @"" : @"s"]];
}
- (void)moveTabLeft:(id)s { VTab *t = self.current; NSUInteger i = [self.tabs indexOfObject:t]; if (t && i != NSNotFound && i > 0) [self moveTab:t to:(NSInteger)i - 1]; }
- (void)moveTabRight:(id)s { VTab *t = self.current; NSUInteger i = [self.tabs indexOfObject:t]; if (t && i != NSNotFound && i + 1 < self.tabs.count) [self moveTab:t to:(NSInteger)i + 1]; }

@end

#pragma mark - Now playing: a small player at the foot of the sidebar (YouTube Music, YouTube, any site with media)

static NSString *MediaQueryJS(void) {
    // the media you'd want controls for: something playing with sound, else something paused part-way with sound on.
    // Muted autoplay (feeds, previews) never counts; a site's media session counts only while it says it's playing.
    return @"(()=>{const ms=navigator.mediaSession,m=ms&&ms.metadata;const all=[...document.querySelectorAll('video,audio')].filter(x=>x.currentSrc&&x.duration>0&&!x.muted&&x.volume>0);"
            "const v=all.find(x=>!x.paused)||all.find(x=>x.currentTime>1)||null;"
            "if(!v&&!(m&&ms.playbackState==='playing'))return null;const art=m&&m.artwork&&m.artwork.length?m.artwork[m.artwork.length-1].src:'';"
            "const pip=!!document.pictureInPictureElement||[...document.querySelectorAll('video')].some(x=>x.webkitPresentationMode==='picture-in-picture');"
            "return{title:(m&&m.title)||document.title||'',artist:(m&&m.artist)||'',art:art,playing:v?!v.paused:(ms&&ms.playbackState==='playing'),pos:v?v.currentTime:0,dur:v&&isFinite(v.duration)?v.duration:0,ended:v?v.ended:false,pip:pip}})()";
}
// Video thumbnails often come letterboxed (black bands above and below, or at the sides); cut those off so the
// artwork fills its square with the picture itself.
static NSImage *TrimLetterbox(NSImage *im) {
    NSBitmapImageRep *rep = nil;
    for (NSImageRep *r in im.representations) if ([r isKindOfClass:NSBitmapImageRep.class]) { rep = (NSBitmapImageRep *)r; break; }
    if (!rep) { CGImageRef cg = [im CGImageForProposedRect:NULL context:nil hints:nil]; if (cg) rep = [[NSBitmapImageRep alloc] initWithCGImage:cg]; }
    NSInteger w = rep.pixelsWide, h = rep.pixelsHigh; if (w < 16 || h < 16) return im;
    BOOL (^dark)(NSInteger, NSInteger, BOOL) = ^BOOL(NSInteger i, NSInteger n, BOOL row) {   // every sampled pixel of row/column i is near black
        for (NSInteger k = 0; k < n; k += MAX(1, n / 48)) {
            NSColor *c = [[rep colorAtX:row ? k : i y:row ? i : k] colorUsingColorSpace:NSColorSpace.sRGBColorSpace];
            if (MAX(c.redComponent, MAX(c.greenComponent, c.blueComponent)) > 0.09) return NO;
        }
        return YES;
    };
    NSInteger top = 0, bot = 0, left = 0, right = 0;
    while (top < h / 3 && dark(top, w, YES)) top++;
    while (bot < h / 3 && dark(h - 1 - bot, w, YES)) bot++;
    while (left < w / 3 && dark(left, h, NO)) left++;
    while (right < w / 3 && dark(w - 1 - right, h, NO)) right++;
    if (top + bot < h * 0.04 && left + right < w * 0.04) return im;
    CGImageRef cg = [rep CGImage]; if (!cg) return im;
    CGImageRef cut = CGImageCreateWithImageInRect(cg, CGRectMake(left, top, w - left - right, h - top - bot)); if (!cut) return im;
    NSImage *out = [[NSImage alloc] initWithCGImage:cut size:NSMakeSize(w - left - right, h - top - bot)];
    CGImageRelease(cut);
    return out;
}
static NSString *MediaControlJS(void) {
    return @"const q=s=>document.querySelector(s),click=(...ss)=>{for(const s of ss){const b=q(s);if(b){b.click();return true}}return false};"
            "const ytm=location.hostname.includes('music.youtube');const v=[...document.querySelectorAll('video,audio')].find(x=>x.currentSrc)||null;"
            "if(a==='toggle'){if(ytm&&click('#play-pause-button'))return true;if(v){v.paused?v.play():v.pause();return true}return click('[aria-label=\"Play\" i]','[aria-label=\"Pause\" i]')}"
            "if(a==='next')return click('.next-button','.ytp-next-button','[aria-label=\"Next\" i]','[aria-label=\"Next track\" i]');"
            "if(a==='prev'){if(click('.previous-button','.ytp-prev-button','[aria-label=\"Previous\" i]','[aria-label=\"Previous track\" i]'))return true;if(v){v.currentTime=0;return true}}"
            "return false";
}

@interface VNowPlaying : NSView
@property (weak) VWindow *owner;
@property (copy) NSDictionary *info;
@property (strong) NSImage *art;
@property (copy) NSString *artURL;
@property (strong) VButton *prev, *play, *next;
@property BOOL floating;   // Monolith: a glass card over the bottom-left of the page
@end

// Where the player sits: the corner you last dropped it in (bottom-left to start), clear of the top band.
static NSRect NowPlayingFrame(NSRect root, NSSize sz) {
    NSInteger c = [Defaults() integerForKey:@"nowPlayingCorner"];
    BOOL right = c & 1, top = c & 2;
    CGFloat x = right ? NSWidth(root) - 10 - sz.width : 10;
    CGFloat y = top ? 36 + 10 : NSHeight(root) - 10 - sz.height;
    return NSMakeRect(x, y, sz.width, sz.height);
}
@implementation VNowPlaying
- (BOOL)isFlipped { return YES; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (instancetype)initWithFrame:(NSRect)r {
    if (!(self = [super initWithFrame:r])) return nil;
    self.prev = [VButton symbol:@"backward.fill" size:11 tip:@"Previous" target:self action:@selector(control:)]; self.prev.tag = 1;
    self.play = [VButton symbol:@"play.fill" size:14 tip:@"Play / pause" target:self action:@selector(control:)]; self.play.tag = 2;
    self.next = [VButton symbol:@"forward.fill" size:11 tip:@"Next" target:self action:@selector(control:)]; self.next.tag = 3;
    for (NSView *b in @[self.prev, self.play, self.next]) [self addSubview:b];
    return self;
}
- (BOOL)compact { return NSWidth(self.bounds) < 100; }
- (void)resizeSubviewsWithOldSize:(NSSize)o {
    CGFloat W = NSWidth(self.bounds);
    for (NSView *b in @[self.prev, self.next]) b.hidden = self.compact;
    if (self.compact) { self.play.frame = NSMakeRect(round((W - 40) / 2), 6, 40, 40); return; }   // narrow: just the artwork, which plays and pauses
    self.next.frame = NSMakeRect(W - 14 - 26, 18, 26, 28);
    self.play.frame = NSMakeRect(W - 14 - 26 - 28, 18, 28, 28);
    self.prev.frame = NSMakeRect(W - 14 - 26 - 28 - 26, 18, 26, 28);
}
- (void)drawRect:(NSRect)dirty {
    if (!self.floating) { [vBg setFill]; NSRectFill(NSIntersectionRect(dirty, self.bounds)); }
    if (self.compact) {
        NSRect artR = NSMakeRect(round((NSWidth(self.bounds) - 40) / 2), 6, 40, 40);
        NSBezierPath *clip = [NSBezierPath bezierPathWithRoundedRect:artR xRadius:8 yRadius:8];
        if (self.art) { [NSGraphicsContext saveGraphicsState]; [clip addClip]; DrawImageFill(self.art, artR); [[NSColor colorWithWhite:0 alpha:0.35] setFill]; NSRectFillUsingOperation(artR, NSCompositingOperationSourceOver); [NSGraphicsContext restoreGraphicsState]; }
        else RoundRect(artR, 8, vPill);
        return;   // the play/pause button sits on top of the artwork
    }
    NSRect card = self.floating ? NSInsetRect(self.bounds, 6, 4) : NSInsetRect(self.bounds, 8, 4);
    if (self.floating) { MShadowed(^{ RoundRect(card, 16, MPanel()); }); ShardStroke(card, 16, MGlassEdge(), 1); }
    else RoundRect(card, 10, vPill);
    NSRect artR = NSMakeRect(NSMinX(card) + 8, NSMinY(card) + 8, 40, 40);
    NSBezierPath *clip = [NSBezierPath bezierPathWithRoundedRect:artR xRadius:6 yRadius:6];
    if (self.art) { [NSGraphicsContext saveGraphicsState]; [clip addClip]; DrawImageFill(self.art, artR); [NSGraphicsContext restoreGraphicsState]; }
    else { RoundRect(artR, 6, vActive); NSImage *n = Tinted(Symbol(@"music.note", 14, NSFontWeightMedium), vFaint); DrawImage(n, CenterIn(n.size, artR)); }
    CGFloat tx = NSMaxX(artR) + 10, tw = NSMinX(self.prev.frame) - tx - 4;
    NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.lineBreakMode = NSLineBreakByTruncatingTail;
    [(self.info[@"title"] ?: @"") drawInRect:NSMakeRect(tx, NSMinY(card) + 10, tw, 17) withAttributes:@{NSFontAttributeName: UIFont(12.5, NSFontWeightMedium), NSForegroundColorAttributeName: vText, NSParagraphStyleAttributeName: ps}];
    NSString *artist = [self.info[@"artist"] length] ? self.info[@"artist"] : HostOf([NSURL URLWithString:self.owner.mediaTab.url ?: @""]);
    [artist drawInRect:NSMakeRect(tx, NSMinY(card) + 28, tw, 16) withAttributes:@{NSFontAttributeName: UIFont(11.5, NSFontWeightRegular), NSForegroundColorAttributeName: vDim, NSParagraphStyleAttributeName: ps}];
    double dur = [self.info[@"dur"] doubleValue], pos = [self.info[@"pos"] doubleValue];
    if (dur > 0) {   // a hairline of progress along the foot of the card
        NSRect track = NSMakeRect(NSMinX(card) + 10, NSMaxY(card) - 4, NSWidth(card) - 20, 2);
        RoundRect(track, 1, vActive);
        RoundRect(NSMakeRect(NSMinX(track), NSMinY(track), NSWidth(track) * MIN(1, pos / dur), 2), 1, vDim);
    }
}
- (void)setPlaceInCorner:(BOOL)on { if (on && self.superview) self.frame = NowPlayingFrame(self.superview.bounds, self.frame.size); }   // the window lays it out this way
// Click the card to go to the music; drag it and it settles in whichever corner of the page you drop it nearest.
- (void)mouseDown:(NSEvent *)e {
    NSView *root = self.superview;
    NSPoint start = [root convertPoint:e.locationInWindow fromView:nil];
    NSRect from = self.frame; BOOL dragged = NO;
    while (YES) {
        NSEvent *n = [self.window nextEventMatchingMask:NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp];
        NSPoint p = [root convertPoint:n.locationInWindow fromView:nil];
        if (n.type == NSEventTypeLeftMouseUp) break;
        if (!dragged && hypot(p.x - start.x, p.y - start.y) < 4) continue;
        dragged = YES;
        NSRect f = NSOffsetRect(from, p.x - start.x, p.y - start.y);
        f.origin.x = MAX(0, MIN(NSWidth(root.bounds) - NSWidth(f), NSMinX(f)));
        f.origin.y = MAX(0, MIN(NSHeight(root.bounds) - NSHeight(f), NSMinY(f)));
        self.frame = f;
    }
    if (!dragged) { VTab *t = self.owner.mediaTab; if (t) [self.owner selectTab:t]; return; }
    BOOL right = NSMidX(self.frame) > NSMidX(root.bounds), top = NSMidY(self.frame) < NSMidY(root.bounds);   // root is flipped
    [Defaults() setInteger:(right ? 1 : 0) + (top ? 2 : 0) forKey:@"nowPlayingCorner"];
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext *ctx) {
        ctx.duration = 0.2; ctx.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionEaseOut];
        self.animator.frame = NowPlayingFrame(root.bounds, self.frame.size);
    }];
}
- (void)control:(VButton *)b {
    VTab *t = self.owner.mediaTab; if (!t.web) return;
    NSString *a = b.tag == 1 ? @"prev" : b.tag == 2 ? @"toggle" : @"next";
    [t.web.web callAsyncJavaScript:MediaControlJS() arguments:@{@"a": a} inFrame:nil inContentWorld:[WKContentWorld worldWithName:@"iris"] completionHandler:^(id r, NSError *err) {
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 300 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ [self.owner updateNowPlaying]; });
    }];
}
@end

@implementation VWindow (Media)

// Leaving a tab whose video is playing floats it in picture in picture; coming back docks it again.
// Music sites are left alone (the sidebar player covers them), and so is a tab still visible in split view.
- (void)autoPiPLeaving:(VTab *)old entering:(VTab *)t {
    if (![Defaults() boolForKey:kAutoPiP]) return;
    if ([self.splitPair containsObject:old] && [self.splitPair containsObject:t]) return;
    NSString *host = old.web.web.URL.host ?: @"";
    if (old.web && old.audible && !old.muted && ![host hasPrefix:@"music."] && ![host containsString:@"spotify"] && ![host containsString:@"soundcloud"])
        [old.web.web callAsyncJavaScript:@"const v=[...document.querySelectorAll('video')].find(v=>!v.paused&&!v.muted&&v.readyState>2&&v.videoWidth>0&&v.getBoundingClientRect().width>=200);"
                                          "if(!v||document.pictureInPictureElement||v.disablePictureInPicture)return false;await v.requestPictureInPicture();window.__irisAutoPiP=true;return true;"
                                arguments:@{} inFrame:nil inContentWorld:WKContentWorld.pageWorld completionHandler:nil];
    if (t.web)
        [t.web.web callAsyncJavaScript:@"if(window.__irisAutoPiP&&document.pictureInPictureElement){window.__irisAutoPiP=false;await document.exitPictureInPicture()}"
                             arguments:@{} inFrame:nil inContentWorld:WKContentWorld.pageWorld completionHandler:nil];
}
// Polled about once a second while there is music to show; it stops when the tab goes away.
- (void)updateNowPlaying {
    VNowPlaying *np = (VNowPlaying *)self.nowPlaying;
    if (!np) {
        np = [[VNowPlaying alloc] initWithFrame:NSMakeRect(0, 0, 230, 64)]; np.owner = self; np.hidden = YES;
        self.nowPlaying = np; [self.window.contentView addSubview:np];
    }
    VTab *t = self.mediaTab;
    if (!t || !t.web || ![self.tabs containsObject:t] || t == self.current) {   // nothing playing, or you're looking at it already
        if (!np.hidden) { np.hidden = YES; [self layout]; }
        return;
    }
    [t.web.web evaluateJavaScript:MediaQueryJS() inFrame:nil inContentWorld:[WKContentWorld worldWithName:@"iris"] completionHandler:^(id r, NSError *e) {
        NSDictionary *info = [r isKindOfClass:NSDictionary.class] ? r : nil;
        BOOL pip = [info[@"pip"] boolValue];
        if (t.inPiP != pip) { t.inPiP = pip; [self refreshChrome]; }
        // The card is for media you're in the middle of: playing now, or paused part-way within the last 10 minutes.
        // Finished, never started with sound, or left long ago: no card, and the polling stops until sound plays again.
        BOOL playing = [info[@"playing"] boolValue];
        double pos = [info[@"pos"] doubleValue], dur = [info[@"dur"] doubleValue];
        BOOL resumable = info && !playing && ![info[@"ended"] boolValue] && pos > 1 && (dur <= 0 || dur - pos > 3)
                         && NSDate.date.timeIntervalSince1970 - t.heardAt < 600;
        BOOL show = info && [info[@"title"] length] && !pip && (playing || resumable);   // floating in Picture in Picture already: no second player on top
        if (np.hidden == show) { np.hidden = !show; [self layout]; }
        if (!show && !pip && !playing && self.mediaTab == t) self.mediaTab = nil;
        if (!show) {
            if (pip) {   // look again once it comes back from Picture in Picture
                [NSObject cancelPreviousPerformRequestsWithTarget:self selector:@selector(updateNowPlaying) object:nil];
                [self performSelector:@selector(updateNowPlaying) withObject:nil afterDelay:1.0];
            }
            return;
        }
        np.info = info;
        np.toolTip = [info[@"artist"] length] ? [NSString stringWithFormat:@"%@ — %@", info[@"title"], info[@"artist"]] : info[@"title"];
        np.play.symbolName = [info[@"playing"] boolValue] ? @"pause.fill" : @"play.fill"; np.play.needsDisplay = YES;
        NSString *art = [info[@"art"] isKindOfClass:NSString.class] ? info[@"art"] : @"";
        if (art.length && ![art isEqualToString:np.artURL] && [art hasPrefix:@"http"]) {
            np.artURL = art; np.art = nil;
            [[NSURLSession.sharedSession dataTaskWithURL:[NSURL URLWithString:art] completionHandler:^(NSData *d, NSURLResponse *resp, NSError *err) {
                NSImage *im = d ? [[NSImage alloc] initWithData:d] : nil; if (im) im = TrimLetterbox(im);
                dispatch_async(dispatch_get_main_queue(), ^{ if ([np.artURL isEqualToString:art]) { np.art = im; np.needsDisplay = YES; } });
            }] resume];
        } else if (!art.length) { np.artURL = nil; np.art = nil; }
        np.needsDisplay = YES;
        // keep the card current while something is loaded
        [NSObject cancelPreviousPerformRequestsWithTarget:self selector:@selector(updateNowPlaying) object:nil];
        [self performSelector:@selector(updateNowPlaying) withObject:nil afterDelay:[info[@"playing"] boolValue] ? 1.0 : 3.0];
    }];
}
@end

#pragma mark - Split view

// Two tabs share the page area side by side. Clicking a side makes it the current tab (the address bar
// follows it); the divider drags from 20% to 80%, and double-clicking it evens them out.
@interface VSplitDivider : NSView
@property (weak) VWindow *owner;
@end
@implementation VSplitDivider
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (void)resetCursorRects { [self addCursorRect:self.bounds cursor:NSCursor.resizeLeftRightCursor]; }
- (void)drawRect:(NSRect)dirty {
    [vBg setFill]; NSRectFill(self.bounds);
    RoundRect(NSMakeRect(NSMidX(self.bounds) - 1.5, NSMidY(self.bounds) - 18, 3, 36), 1.5, [vText colorWithAlphaComponent:0.22]);
}
- (void)mouseDown:(NSEvent *)e {
    if (e.clickCount == 2) { self.owner.splitRatio = 0.5; [self.owner placePages]; }
}
- (void)mouseDragged:(NSEvent *)e {
    NSView *c = self.superview;
    CGFloat x = [c convertPoint:e.locationInWindow fromView:nil].x;
    self.owner.splitRatio = MAX(0.2, MIN(0.8, x / MAX(1, NSWidth(c.bounds))));
    [self.owner placePages];
}
@end

// "Load the open tab when you click it": at launch the tab you were on shows this card until you click.
@interface VResumeCard : NSView
@property (weak) VTab *tab;
@end
@implementation VResumeCard
- (BOOL)isFlipped { return YES; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (void)drawRect:(NSRect)dirty {
    [vContentBg setFill]; NSRectFill(dirty);
    VTab *t = self.tab; if (!t) return;
    CGFloat W = NSWidth(self.bounds), cy = round(NSHeight(self.bounds) * 0.38);
    NSImage *ic = t.favicon ?: Tinted(Symbol(@"globe", 22, NSFontWeightRegular), vDim);
    DrawImage(ic, NSMakeRect(round(W / 2 - 16), cy - 52, 32, 32));
    NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.alignment = NSTextAlignmentCenter; ps.lineBreakMode = NSLineBreakByTruncatingTail;
    [(t.title.length ? t.title : t.url ?: @"") drawInRect:NSMakeRect(40, cy, W - 80, 24) withAttributes:@{NSFontAttributeName: TitleFont(17, YES), NSForegroundColorAttributeName: vText, NSParagraphStyleAttributeName: ps}];
    [@"Click to load this page" drawInRect:NSMakeRect(40, cy + 30, W - 80, 18) withAttributes:@{NSFontAttributeName: UIFont(12.5, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint, NSParagraphStyleAttributeName: ps}];
}
- (void)mouseDown:(NSEvent *)e { VTab *t = self.tab; t.deferred = NO; [t.owner placePages]; [t.owner refreshChrome]; }
@end

@implementation VWindow (Split)

- (NSView *)resumeCardFor:(VTab *)t {
    static char key;
    VResumeCard *c = objc_getAssociatedObject(self, &key);
    if (!c) { c = [[VResumeCard alloc] initWithFrame:NSZeroRect]; objc_setAssociatedObject(self, &key, c, OBJC_ASSOCIATION_RETAIN_NONATOMIC); }
    c.tab = t; c.needsDisplay = YES;
    return c;
}

- (NSView *)paneFor:(VTab *)t {
    if (t.isHome) return self.home;
    if (!t.web && t.deferred) return [self resumeCardFor:t];
    if (!t.web) { VPage *p = [self makePage:t]; id st = t.savedState; t.savedState = nil; [p restoreState:st url:t.url]; }
    return t.web;
}

// Puts the current tab's page (and, in split view, its partner's) into the page area; everything else leaves it.
- (void)placePages {
    if (!self.content) return;
    NSArray<VTab *> *pair = self.splitPair;
    if (pair && (![self.tabs containsObject:pair[0]] || ![self.tabs containsObject:pair[1]] || (pair[0].isHome && pair[1].isHome))) { [self endSplit]; pair = nil; }
    VTab *cur = self.current;
    BOOL split = pair && [pair containsObject:cur];
    NSMutableArray<NSView *> *views = [NSMutableArray array];
    for (VTab *t in (split ? pair : cur ? @[cur] : @[])) { NSView *v = [self paneFor:t]; if (v) [views addObject:v]; }
    if (split && views.count < 2) split = NO;
    for (NSView *v in self.content.subviews.copy)
        if (([v isKindOfClass:VPage.class] || v == self.home || [v isKindOfClass:VResumeCard.class]) && ![views containsObject:v]) [v removeFromSuperview];
    NSRect b = self.content.bounds;
    if (!split) {
        [self.splitDivider removeFromSuperview]; [self.splitMark removeFromSuperview];
        if (views.count) {
            NSView *v = views[0]; v.frame = b; v.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
            if (v.superview != self.content) [self.content addSubview:v positioned:NSWindowBelow relativeTo:nil];
        }
        return;
    }
    CGFloat gap = 6, r = self.splitRatio > 0.05 ? self.splitRatio : 0.5;
    CGFloat lw = round((NSWidth(b) - gap) * r);
    NSRect frames[2] = { NSMakeRect(0, 0, lw, NSHeight(b)), NSMakeRect(lw + gap, 0, NSWidth(b) - lw - gap, NSHeight(b)) };
    for (NSUInteger i = 0; i < 2; i++) {
        NSView *v = views[i]; v.frame = frames[i]; v.autoresizingMask = NSViewHeightSizable;
        if (v.superview != self.content) [self.content addSubview:v positioned:NSWindowBelow relativeTo:nil];
    }
    if (!self.splitDivider) { VSplitDivider *d = [[VSplitDivider alloc] initWithFrame:NSZeroRect]; d.owner = self; self.splitDivider = d; }
    self.splitDivider.frame = NSMakeRect(lw, 0, gap, NSHeight(b));
    if (self.splitDivider.superview != self.content) [self.content addSubview:self.splitDivider positioned:NSWindowAbove relativeTo:views.lastObject];
    self.splitDivider.needsDisplay = YES;
    [self.window invalidateCursorRectsForView:self.splitDivider];
    // a short bar at the top of the side the address bar is talking about
    if (!self.splitMark) {
        NSView *m = [[NSView alloc] initWithFrame:NSZeroRect]; m.wantsLayer = YES; m.layer.cornerRadius = 1.5;
        self.splitMark = m;
    }
    self.splitMark.layer.backgroundColor = [vText colorWithAlphaComponent:0.4].CGColor;
    NSRect act = frames[pair[0] == cur ? 0 : 1];
    CGFloat my = self.content.isFlipped ? 4 : NSHeight(b) - 7;
    self.splitMark.frame = NSMakeRect(round(NSMidX(act) - 18), my, 36, 3);
    if (self.splitMark.superview != self.content) [self.content addSubview:self.splitMark positioned:NSWindowAbove relativeTo:self.splitDivider];
}

- (void)endSplit {
    self.splitPair = nil;
    [self.splitDivider removeFromSuperview]; [self.splitMark removeFromSuperview];
    if (self.splitMonitor) { [NSEvent removeMonitor:self.splitMonitor]; self.splitMonitor = nil; }
}

- (void)splitWith:(VTab *)t {
    VTab *cur = self.current;
    if (!cur || !t || t == cur || ![self.tabs containsObject:t]) return;
    if (cur.isHome && t.isHome) { [self showToast:@"Open a page in one side first"]; return; }
    // the partner moves next to the current tab so the pair reads as one in the sidebar
    if (t.pinned == cur.pinned) {
        [self.tabs removeObject:t];
        [self.tabs insertObject:t atIndex:[self.tabs indexOfObject:cur] + 1];
    }
    self.splitPair = @[cur, t];
    if (self.splitRatio < 0.05) self.splitRatio = 0.5;
    if (!self.splitMonitor) {
        __weak VWindow *ws = self;
        self.splitMonitor = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskLeftMouseDown | NSEventMaskRightMouseDown | NSEventMaskOtherMouseDown handler:^NSEvent *(NSEvent *e) {
            VWindow *s = ws;
            if (!s || e.window != s.window || ![s.splitPair containsObject:s.current]) return e;
            NSPoint p = [s.content convertPoint:e.locationInWindow fromView:nil];
            if (!NSPointInRect(p, s.content.bounds)) return e;
            for (VTab *x in s.splitPair) {
                NSView *v = x.isHome ? s.home : x.web;
                if (x != s.current && v.superview == s.content && NSPointInRect(p, v.frame)) { [s selectTab:x]; break; }
            }
            return e;
        }];
    }
    [self placePages];
    [self refreshChrome]; [self.sidebar reload]; [self scheduleSave];
}

- (void)toggleSplit:(id)s {
    VTab *cur = self.current; if (!cur) return;
    if ([self.splitPair containsObject:cur]) { [self endSplit]; [self placePages]; [self.sidebar reload]; return; }
    // the partner: the tab you were on last, or a fresh one to type into
    VTab *best = nil;
    for (VTab *t in self.tabs) if (t != cur && !(t.isHome && cur.isHome) && (!best || t.hiddenAt > best.hiddenAt)) best = t;
    if (!best) {
        if (cur.isHome) { [self showToast:@"Open a page first, then split"]; return; }
        NSSet *before = [NSSet setWithArray:self.tabs];
        [self newTab:nil select:NO];
        for (VTab *t in self.tabs) if (![before containsObject:t]) best = t;
        if (!best) return;
        [self splitWith:best];
        [self selectTab:best];
        return;
    }
    [self splitWith:best];
}

- (void)menuSplit:(NSMenuItem *)m {
    VTab *t = m.representedObject;
    if ([self.splitPair containsObject:t]) { [self endSplit]; [self placePages]; [self.sidebar reload]; }
    else if (t == self.current) [self toggleSplit:nil];
    else [self splitWith:t];
}

- (void)swapSplit:(id)s {
    NSArray *p = self.splitPair; if (p.count != 2) return;
    self.splitPair = @[p[1], p[0]];
    self.splitRatio = 1 - (self.splitRatio > 0.05 ? self.splitRatio : 0.5);
    [self placePages];
}

// "Open Link in Split View": the link opens beside this page (replacing the other side if already split).
- (void)splitLink:(NSMenuItem *)m {
    NSURL *u = [NSURL URLWithString:m.representedObject]; if (!u) return;
    VTab *cur = self.current;
    if ([self.splitPair containsObject:cur]) [self endSplit];
    NSSet *before = [NSSet setWithArray:self.tabs];
    [self newTab:u select:NO];
    for (VTab *t in self.tabs.copy) if (![before containsObject:t]) { [self splitWith:t]; break; }
}
@end

#pragma mark - The CPU rule: background pages share a budget, what you're watching never waits

// One rule, always on: Iris plus every process it starts (page and extension engines, the network process)
// average at most a quarter of the Mac's processor over any 10 seconds on battery, 40% plugged in (see GovCap). Short bursts run at full speed (a page draws in a
// few seconds), because fans answer heat built up over time, not a moment of work. Measured every 100 ms;
// while the 10-second average is under the cap nothing is touched; over it, Iris's helper processes are paced the way the `cpulimit` tool does it: in each 100 ms they run for
// a share of the time and pause for the rest, and that share is steered by what they actually used (a page
// runs on several cores at once, so a fixed split can't hold a cap). The graphics process and any page that
// is playing sound are paced last, so video and music stay smooth. Everything is resumed if Iris quits or
// crashes.

static pid_t gGovPids[256];            // processes Iris may have paused (read by the crash handler)
static volatile sig_atomic_t gGovCount;
static void GovResumeAll(void) { for (int i = 0; i < gGovCount; i++) if (gGovPids[i] > 0) kill(gGovPids[i], SIGCONT); }
static void GovCrash(int sig) { GovResumeAll(); signal(sig, SIG_DFL); raise(sig); }

static pid_t WebPid(WKWebView *v) {
    SEL s = NSSelectorFromString(@"_webProcessIdentifier");
    return v && [v respondsToSelector:s] ? ((pid_t (*)(id, SEL))objc_msgSend)(v, s) : 0;
}

// Every process macOS counts as Iris's (WebKit's engine, network and graphics processes are launched on
// Iris's behalf, so the system records Iris as "responsible" for them, which is how Activity Monitor groups them).
static NSArray<NSNumber *> *IrisHelperPids(void) {
    static pid_t (*responsible)(pid_t); static BOOL tried;
    if (!tried) { tried = YES; responsible = (pid_t (*)(pid_t))dlsym(RTLD_DEFAULT, "responsibility_get_pid_responsible_for_pid"); }
    if (!responsible) return @[];
    pid_t me = getpid();
    int n = proc_listallpids(NULL, 0); if (n <= 0) return @[];
    pid_t *all = calloc((size_t)n + 64, sizeof(pid_t));
    n = proc_listallpids(all, (int)(((size_t)n + 64) * sizeof(pid_t)));
    NSMutableArray *out = [NSMutableArray array];
    for (int i = 0; i < n; i++) if (all[i] > 0 && all[i] != me && responsible(all[i]) == me) [out addObject:@(all[i])];
    free(all);
    return out;
}
static NSString *ProcName(pid_t p) { char b[PROC_PIDPATHINFO_MAXSIZE]; return proc_name(p, b, sizeof b) > 0 ? @(b) : @""; }
static double SelfCPUSeconds(void) {
    struct rusage r; getrusage(RUSAGE_SELF, &r);
    return r.ru_utime.tv_sec + r.ru_utime.tv_usec / 1e6 + r.ru_stime.tv_sec + r.ru_stime.tv_usec / 1e6;
}

// The budget scales with the Mac: a quarter of its processor on battery, 40% plugged in (counting threads, the way
// macOS does). A 2-core, 4-thread MacBook gets 1 core on battery and 1.6 plugged in; a bigger Mac gets more.
static double GovCap(void) {
    double threads = MAX(2, (double)NSProcessInfo.processInfo.activeProcessorCount);
    return MAX(1.0, threads * (OnBattery() ? 0.25 : 0.4));
}

@interface VGovernor : NSObject
+ (void)start;
+ (void)stop;
@end

@implementation VGovernor
static volatile BOOL gGovRunning;

// What may be paced: background page and extension engines only. Never the graphics or network process (they
// carry video and audio), and never a page that is:
//   · on screen: the current tab of any visible window (pausing it makes scrolling and video stutter)
//   · playing sound now, or in the last 90 seconds (the gap between two videos, an ad break, a pause and resume:
//     the next video's buffering and first frames must run free)
//   · floating in Picture in Picture
//   · the tab you clicked or typed in during the last 8 seconds
+ (NSDictionary *)snapshot {
    NSMutableSet *spare = [NSMutableSet set];
    NSTimeInterval now = NSDate.date.timeIntervalSince1970;
    static NSMapTable<VTab *, NSNumber *> *heard;   // when each tab last made sound
    if (!heard) heard = [NSMapTable weakToStrongObjectsMapTable];
    NSMutableSet *onScreen = [NSMutableSet set];
    for (VWindow *w in gWindows) if (w.window.isVisible && !w.window.isMiniaturized && w.window.occlusionState & NSWindowOcclusionStateVisible) {
        if (w.current) [onScreen addObject:w.current];
        for (VTab *t in w.splitPair) [onScreen addObject:t];
    }
    for (VTab *t in AllTabs(YES)) {
        if (t.audible) [heard setObject:@(now) forKey:t];
        BOOL recent = now - [[heard objectForKey:t] doubleValue] < 90;
        if (t.audible || recent || t.inPiP || [onScreen containsObject:t] || now - t.lastInput < 8) { pid_t p = WebPid(t.web.web); if (p > 0) [spare addObject:@(p)]; }
    }
    NSMutableArray *first = [NSMutableArray array];
    NSArray *pids = IrisHelperPids();   // one walk of the process list, used twice
    for (NSNumber *p in pids) {
        NSString *name = ProcName(p.intValue);
        if (![name hasPrefix:@"com.apple.WebKit.WebContent"]) continue;
        if (![spare containsObject:p]) [first addObject:p];
    }
    NSMutableArray *measured = [NSMutableArray array];
    for (NSNumber *p in pids) if ([ProcName(p.intValue) hasPrefix:@"com.apple.WebKit"] && ![first containsObject:p]) [measured addObject:p];
    return @{@"first": first, @"last": measured, @"cap": @(GovCap())};
}

+ (void)start {
    if (gGovRunning) return;
    gGovRunning = YES;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ atexit(GovResumeAll); });   // crashes and quit signals resume them too (v6c_crash)
    [NSThread detachNewThreadWithBlock:^{
        [NSThread currentThread].qualityOfService = NSQualityOfServiceUtility;
        const double period = 0.1; double cap = 1.5;   // the rule: GovCap(), averaged over 10 s
        double frac = 1.0, lastSelf = SelfCPUSeconds();
        double avg = 0;   // use over roughly the last 10 s (a moving average that works with any sampling interval)
        BOOL idle = NO;   // comfortably under the budget: look once a second instead of ten times
        NSMutableDictionary<NSNumber *, NSNumber *> *last = [NSMutableDictionary dictionary];
        NSArray *first = @[], *late = @[]; NSTimeInterval lastSnap = 0, lastT = NSDate.date.timeIntervalSince1970, lastLog = 0;
        while (gGovRunning) {
            NSTimeInterval now = NSDate.date.timeIntervalSince1970;
            if (now - lastSnap > (idle ? 2.0 : 0.5)) {
                __block NSDictionary *snap;
                dispatch_sync(dispatch_get_main_queue(), ^{ snap = [VGovernor snapshot]; });
                first = snap[@"first"]; late = snap[@"last"]; cap = [snap[@"cap"] doubleValue] ?: 1.5; lastSnap = now;
                int n = 0; for (NSNumber *p in [first arrayByAddingObjectsFromArray:late]) if (n < 256) gGovPids[n++] = p.intValue;
                gGovCount = n;
                NSSet *live = [NSSet setWithArray:[first arrayByAddingObjectsFromArray:late]];
                for (NSNumber *p in last.allKeys) if (![live containsObject:p]) [last removeObjectForKey:p];
            }
            // total use over the last period, Iris itself included
            double dt = MAX(0.02, now - lastT); lastT = now;
            double me = SelfCPUSeconds(), total = (me - lastSelf) / dt; lastSelf = me;
            for (NSNumber *p in [first arrayByAddingObjectsFromArray:late]) {
                double c = ProcessCPUSeconds(p.intValue);
                if (last[p]) total += MAX(0, c - last[p].doubleValue) / dt;
                last[p] = @(c);
            }
            avg += (total - avg) * (1 - exp(-dt / 10.0));
            // only when the 10-second average is over the cap: steer the helpers' share of time so use comes back
            // down to it; once the average is comfortably under, let them run free again
            // (never below a quarter of the time: when the load comes from what can't be paced, graphics, sound or
            //  the tab you're using, squeezing the rest harder only starves them without cooling anything)
            if (avg > cap && total > cap) frac = MAX(0.25, frac * pow(cap / total, 0.8));
            else if (avg < cap * 0.9) frac = MIN(1.0, frac * 1.25);
            if (now - lastLog > 10 && frac < 1) { lastLog = now; DLog(@"cpu rule: now %.2f cores, 10 s average %.2f, helpers running %.0f%% of the time", total, avg, frac * 100); }
            idle = frac >= 1 && avg < cap * 0.6 && total < cap;
            if (frac >= 1) { usleep((useconds_t)((idle ? 1.0 : period) * 1e6)); continue; }   // under the cap: nothing touched
            // plain pages and extensions take the pause; graphics and sound only when that isn't enough
            NSArray *pause = first;
            usleep((useconds_t)(period * frac * 1e6));
            for (NSNumber *p in pause) kill(p.intValue, SIGSTOP);
            usleep((useconds_t)(period * (1 - frac) * 1e6));
            for (NSNumber *p in pause) kill(p.intValue, SIGCONT);
        }
        GovResumeAll();
    }];
}
+ (void)stop { gGovRunning = NO; GovResumeAll(); }
@end
#pragma mark - Web apps (installed PWAs)

// A site installed as an app gets a real .app in ~/Applications/Iris Apps: its own name, icon, Dock tile and windows.
// The .app carries a copy of Iris itself plus an IrisWebApp entry in its Info.plist; started that way, Iris runs as the
// app (gWebApp is set) with a slim bar of the site's colour instead of the browser's controls. Pages outside the app's
// site open in Iris. The app keeps its own website data, so your sign-in is carried over once, at install.

static NSString *WebAppsDir(void) {   // a profile's sites sit in a folder of their own, so two people can each install the same site
    if (IrisIsDev()) return [NSHomeDirectory() stringByAppendingPathComponent:@"Applications/Iris Dev Apps"];
    NSString *d = [NSHomeDirectory() stringByAppendingPathComponent:@"Applications/Iris Apps"];
    return gProfileApp ? [d stringByAppendingPathComponent:[[gProfileApp[@"name"] ?: @"Profile" stringByReplacingOccurrencesOfString:@"/" withString:@"-"] stringByReplacingOccurrencesOfString:@":" withString:@"-"]] : d;
}
static NSString *WebAppDataDir(NSString *ident) {
    NSString *d = SupportFile([@"WebApps" stringByAppendingPathComponent:ident ?: @"_"]);
    [NSFileManager.defaultManager createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil];
    return d;
}
static NSMutableArray<NSDictionary *> *WebAppRegistry(void) {
    NSData *d = [NSData dataWithContentsOfFile:SupportFile(@"webapps.json")];
    NSArray *a = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : nil;
    NSMutableArray *out = [NSMutableArray array];
    for (id x in [a isKindOfClass:NSArray.class] ? a : @[]) if ([x isKindOfClass:NSDictionary.class] && [x[@"id"] isKindOfClass:NSString.class]) [out addObject:x];
    return out;
}
static void WebAppSaveRegistry(NSArray *a) {
    NSData *d = [NSJSONSerialization dataWithJSONObject:a ?: @[] options:NSJSONWritingPrettyPrinted error:nil];
    [d writeToFile:SupportFile(@"webapps.json") atomically:YES];
}
static NSString *OriginOf(NSURL *u) {
    if (!u.host) return @"";
    return [NSString stringWithFormat:@"%@://%@%@", u.scheme.lowercaseString, u.host.lowercaseString, u.port ? [NSString stringWithFormat:@":%@", u.port] : @""];
}
// The installed app for a page (same site as its scope), if its .app is still there.
static NSDictionary *WebAppFor(NSURL *u) {
    if (gWebApp || ![u.scheme hasPrefix:@"http"]) return nil;
    static NSArray *cache; static NSTimeInterval at;
    NSTimeInterval now = NSDate.date.timeIntervalSince1970;
    if (!cache || now - at > 5) { cache = WebAppRegistry(); at = now; }
    NSString *o = OriginOf(u);
    for (NSDictionary *a in cache) if ([OriginOf([NSURL URLWithString:a[@"scope"] ?: a[@"start"] ?: @""]) isEqualToString:o] && [NSFileManager.defaultManager fileExistsAtPath:a[@"path"] ?: @""]) return a;
    return nil;
}
static void WebAppRegistryChanged(void) {   // the cache above, and every window's install button
    for (VWindow *w in gWindows) { [w.toolbar layoutBar]; [w refreshChrome]; }
}

#pragma mark Icons

// PNG bytes of an image drawn at exactly `px` pixels square.
static NSData *PNGAt(NSImage *im, NSInteger px) {
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:px pixelsHigh:px bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO
                                                                 colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
    rep.size = NSMakeSize(px, px);
    [NSGraphicsContext saveGraphicsState];
    NSGraphicsContext *g = [NSGraphicsContext graphicsContextWithBitmapImageRep:rep];
    g.imageInterpolation = NSImageInterpolationHigh;
    NSGraphicsContext.currentContext = g;
    [im drawInRect:NSMakeRect(0, 0, px, px) fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1];
    [NSGraphicsContext restoreGraphicsState];
    return [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
}
// An .icns written by hand (PNG entries), so no extra framework is needed.
static BOOL WriteICNS(NSImage *im, NSString *path) {
    NSArray *entries = @[@[@"icp4", @16], @[@"icp5", @32], @[@"icp6", @64], @[@"ic07", @128], @[@"ic08", @256], @[@"ic09", @512], @[@"ic10", @1024],
                         @[@"ic11", @32], @[@"ic12", @64], @[@"ic13", @256], @[@"ic14", @512]];
    NSMutableData *body = [NSMutableData data];
    for (NSArray *e in entries) {
        NSData *png = PNGAt(im, [e[1] integerValue]); if (!png) continue;
        uint32_t len = CFSwapInt32HostToBig((uint32_t)png.length + 8);
        [body appendData:[e[0] dataUsingEncoding:NSASCIIStringEncoding]]; [body appendBytes:&len length:4]; [body appendData:png];
    }
    NSMutableData *file = [NSMutableData dataWithData:[@"icns" dataUsingEncoding:NSASCIIStringEncoding]];
    uint32_t total = CFSwapInt32HostToBig((uint32_t)body.length + 8);
    [file appendBytes:&total length:4]; [file appendData:body];
    return [file writeToFile:path atomically:YES];
}
static BOOL ImageHasClearCorners(NSImage *im) {
    NSData *png = PNGAt(im, 64);
    NSBitmapImageRep *r = png ? [[NSBitmapImageRep alloc] initWithData:png] : nil;
    if (!r) return NO;
    NSInteger clear = 0;
    for (NSArray *p in @[@[@1, @1], @[@62, @1], @[@1, @62], @[@62, @62]]) if ([r colorAtX:[p[0] integerValue] y:[p[1] integerValue]].alphaComponent < 0.6) clear++;
    return clear >= 2;
}
static NSColor *ColorFromCSS(NSString *s) {
    s = [Trim(s ?: @"") lowercaseString];
    if ([s hasPrefix:@"#"]) {
        NSString *h = [s substringFromIndex:1];
        if (h.length == 3) h = [NSString stringWithFormat:@"%C%C%C%C%C%C", [h characterAtIndex:0], [h characterAtIndex:0], [h characterAtIndex:1], [h characterAtIndex:1], [h characterAtIndex:2], [h characterAtIndex:2]];
        if (h.length >= 6) { unsigned v = 0; [[NSScanner scannerWithString:[h substringToIndex:6]] scanHexInt:&v]; return Hex(v); }
    }
    if ([s hasPrefix:@"rgb"]) {
        NSArray *n = [[[s componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"rgba() "]] componentsJoinedByString:@""] componentsSeparatedByString:@","];
        if (n.count >= 3) return [NSColor colorWithSRGBRed:[n[0] doubleValue] / 255 green:[n[1] doubleValue] / 255 blue:[n[2] doubleValue] / 255 alpha:1];
    }
    NSDictionary *named = @{@"white": @0xffffff, @"black": @0x000000};
    if (named[s]) return Hex([named[s] unsignedIntValue]);
    return nil;
}
static BOOL ColorIsLight(NSColor *c) {
    NSColor *s = [c colorUsingColorSpace:NSColorSpace.sRGBColorSpace];
    return s && (0.299 * s.redComponent + 0.587 * s.greenComponent + 0.114 * s.blueComponent) > 0.6;
}
// The app's Dock icon, shaped like a Mac app: a full-bleed icon fills the rounded square; one with clear corners
// (most "any" icons and favicons) sits in the middle of a tile in the site's background colour.
static NSImage *WebAppIcon(NSImage *src, BOOL maskable, NSColor *bg) {
    BOOL fill = src && (maskable || !ImageHasClearCorners(src));
    NSColor *tile = bg ?: NSColor.whiteColor;
    return [NSImage imageWithSize:NSMakeSize(1024, 1024) flipped:NO drawingHandler:^BOOL(NSRect r) {
        NSRect sq = NSMakeRect(100, 100, 824, 824);
        NSBezierPath *p = [NSBezierPath bezierPathWithRoundedRect:sq xRadius:185 yRadius:185];
        [NSGraphicsContext saveGraphicsState];
        NSShadow *sh = [NSShadow new]; sh.shadowBlurRadius = 24; sh.shadowOffset = NSMakeSize(0, -10); sh.shadowColor = [NSColor colorWithWhite:0 alpha:0.28]; [sh set];
        [tile setFill]; [p fill];
        [NSGraphicsContext restoreGraphicsState];
        [NSGraphicsContext saveGraphicsState];
        [p addClip];
        if (fill) {
            NSSize s = src.size; CGFloat k = MAX(824 / MAX(1, s.width), 824 / MAX(1, s.height)) * (maskable ? 1.0 : 1.0);
            NSRect d = NSMakeRect(512 - s.width * k / 2, 512 - s.height * k / 2, s.width * k, s.height * k);
            [src drawInRect:d fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1];
        } else if (src) {
            NSSize s = src.size; CGFloat side = MAX(s.width, s.height) >= 128 ? 560 : 420, k = side / MAX(1, MAX(s.width, s.height));
            [src drawInRect:NSMakeRect(512 - s.width * k / 2, 512 - s.height * k / 2, s.width * k, s.height * k) fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1];
        }
        [NSGraphicsContext restoreGraphicsState];
        NSBezierPath *edge = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(sq, 0.75, 0.75) xRadius:184 yRadius:184]; edge.lineWidth = 1.5;
        [[NSColor colorWithWhite:0 alpha:ColorIsLight(tile) || fill ? 0.10 : 0.0] setStroke]; [edge stroke];
        return YES;
    }];
}
static NSString *ImageDataURLOf(NSImage *im, NSInteger px) {
    NSData *png = PNGAt(im, px);
    return png ? [@"data:image/png;base64," stringByAppendingString:[png base64EncodedStringWithOptions:0]] : @"";
}

#pragma mark Reading the site

static char kPendingInstallKey;
// Everything the page says about itself as an app: its manifest, its icons, its colour.
static NSString *const kManifestJS =
    @"const abs=h=>{try{return new URL(h,document.baseURI).href}catch(e){return null}};"
    "const ml=document.querySelector('link[rel~=\"manifest\"]');let m=null,mu=null;"
    "if(ml){mu=abs(ml.getAttribute('href'));try{const r=await fetch(mu,{credentials:ml.crossOrigin==='use-credentials'?'include':'same-origin'});m=await r.json()}catch(e){}}"
    "const icons=[...document.querySelectorAll('link[rel~=\"icon\"],link[rel=\"apple-touch-icon\"],link[rel=\"apple-touch-icon-precomposed\"],link[rel=\"mask-icon\"]')]"
    ".map(l=>({src:abs(l.getAttribute('href')),sizes:l.getAttribute('sizes')||'',rel:l.rel,type:l.type||''}));"
    "const meta=n=>{const e=document.querySelector('meta[name=\"'+n+'\"]');return e?e.content:''};"
    "return JSON.stringify({m,mu,title:document.title,appName:meta('application-name'),apple:meta('apple-mobile-web-app-title'),theme:meta('theme-color'),icons,url:location.href})";

static CGFloat IconSizeOf(NSString *sizes) {
    CGFloat best = 0;
    for (NSString *s in [sizes.lowercaseString componentsSeparatedByString:@" "]) {
        if ([s isEqualToString:@"any"]) best = MAX(best, 1024);
        NSArray *p = [s componentsSeparatedByString:@"x"]; if (p.count == 2) best = MAX(best, MIN([p[0] doubleValue], [p[1] doubleValue]));
    }
    return best;
}
// What would be installed: name, start page, scope, colours, and the icon candidates best first.
static NSDictionary *WebAppDescribe(NSDictionary *j) {
    NSURL *page = [NSURL URLWithString:j[@"url"] ?: @""];
    NSDictionary *m = [j[@"m"] isKindOfClass:NSDictionary.class] ? j[@"m"] : nil;
    NSURL *mu = [j[@"mu"] isKindOfClass:NSString.class] ? [NSURL URLWithString:j[@"mu"]] : page;
    NSURL *(^rel)(id) = ^NSURL *(id s) { return [s isKindOfClass:NSString.class] && [s length] ? [NSURL URLWithString:s relativeToURL:mu].absoluteURL : nil; };
    NSString *(^str)(id) = ^NSString *(id s) { return [s isKindOfClass:NSString.class] ? Trim(s) : @""; };
    NSString *name = str(m[@"name"]), *shortName = str(m[@"short_name"]);
    if (shortName.length && (name.length > 24 || !name.length)) name = shortName;
    for (NSString *alt in @[str(j[@"apple"]), str(j[@"appName"]), str(j[@"title"]), HostOf(page) ?: @"App"]) if (!name.length) name = alt;
    name = [[name componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"/:\\\n\r\t"]] componentsJoinedByString:@" "];
    if (name.length > 40) name = [name substringToIndex:40];
    NSURL *start = rel(m[@"start_url"]);
    if (!start || ![OriginOf(start) isEqualToString:OriginOf(page)]) start = m ? [NSURL URLWithString:@"/" relativeToURL:page].absoluteURL : page;
    NSURL *scope = rel(m[@"scope"]);
    if (!scope || ![OriginOf(scope) isEqualToString:OriginOf(start)]) scope = [NSURL URLWithString:@"/" relativeToURL:start].absoluteURL;
    NSMutableArray *cands = [NSMutableArray array];
    for (NSDictionary *i in [m[@"icons"] isKindOfClass:NSArray.class] ? m[@"icons"] : @[]) {
        if (![i isKindOfClass:NSDictionary.class]) continue;
        NSURL *u = rel(i[@"src"]); if (!u) continue;
        NSString *purpose = str(i[@"purpose"]).lowercaseString, *type = str(i[@"type"]).lowercaseString;
        BOOL svg = [type containsString:@"svg"] || [u.path.lowercaseString hasSuffix:@".svg"];
        BOOL maskable = [purpose containsString:@"maskable"], any = !purpose.length || [purpose containsString:@"any"];
        CGFloat size = IconSizeOf(str(i[@"sizes"]));
        CGFloat score = MIN(size, 1024) + (any ? 300 : 0) + (maskable && !any ? 120 : 0) - (svg ? 2000 : 0) - ([purpose containsString:@"monochrome"] ? 3000 : 0);
        [cands addObject:@{@"url": u.absoluteString, @"score": @(score), @"maskable": @(maskable && !any)}];
    }
    for (NSDictionary *i in [j[@"icons"] isKindOfClass:NSArray.class] ? j[@"icons"] : @[]) {
        NSString *src = str(i[@"src"]); if (!src.length) continue;
        NSString *relName = str(i[@"rel"]).lowercaseString;
        BOOL apple = [relName containsString:@"apple-touch"]; BOOL svg = [str(i[@"type"]) containsString:@"svg"] || [src.lowercaseString hasSuffix:@".svg"] || [relName containsString:@"mask-icon"];
        CGFloat size = IconSizeOf(str(i[@"sizes"])); if (!size) size = apple ? 180 : 32;
        [cands addObject:@{@"url": src, @"score": @(size + (apple ? 100 : 0) - (svg ? 2000 : 0) - 400), @"maskable": @NO}];
    }
    if (page.host) [cands addObject:@{@"url": [NSURL URLWithString:@"/favicon.ico" relativeToURL:page].absoluteURL.absoluteString, @"score": @(-1000), @"maskable": @NO}];
    [cands sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) { return [b[@"score"] compare:a[@"score"]]; }];
    NSMutableDictionary *d = [@{@"name": name, @"start": start.absoluteString ?: page.absoluteString, @"scope": scope.absoluteString ?: @"", @"host": HostOf(start) ?: @"",
                                @"icons": cands, @"manifest": @(m != nil)} mutableCopy];
    NSString *theme = str(m[@"theme_color"]); if (!theme.length) theme = str(j[@"theme"]);
    if (ColorFromCSS(theme)) d[@"theme"] = theme;
    if (ColorFromCSS(str(m[@"background_color"]))) d[@"bg"] = str(m[@"background_color"]);
    return d;
}
// Fetch icon candidates in order until one is a real image of a useful size.
static void WebAppFetchIcon(NSArray *cands, NSUInteger i, NSImage *fallback, void (^done)(NSImage *, BOOL maskable)) {
    if (i >= cands.count || i >= 6) { done(fallback, NO); return; }
    NSDictionary *c = cands[i];
    NSURL *u = [NSURL URLWithString:c[@"url"]];
    if (!u) { WebAppFetchIcon(cands, i + 1, fallback, done); return; }
    NSMutableURLRequest *rq = [NSMutableURLRequest requestWithURL:u cachePolicy:NSURLRequestReturnCacheDataElseLoad timeoutInterval:12];
    [[NSURLSession.sharedSession dataTaskWithRequest:rq completionHandler:^(NSData *data, NSURLResponse *r, NSError *e) {
        NSImage *im = data.length ? [[NSImage alloc] initWithData:data] : nil;
        CGFloat px = 0; for (NSImageRep *rep in im.representations) px = MAX(px, MIN(rep.pixelsWide, rep.pixelsHigh));
        if (!px && im) px = MIN(im.size.width, im.size.height);
        dispatch_async(dispatch_get_main_queue(), ^{
            if (im && px >= 48) { im.size = NSMakeSize(px, px); done(im, [c[@"maskable"] boolValue]); }
            else WebAppFetchIcon(cands, i + 1, (!fallback && im && px >= 16) ? im : fallback, done);
        });
    }] resume];
}

#pragma mark Making the app

static NSString *WebAppIdentFor(NSString *scope) {   // stable for a site, so installing again replaces the same app
    for (NSDictionary *a in WebAppRegistry()) if ([OriginOf([NSURL URLWithString:a[@"scope"] ?: @""]) isEqualToString:OriginOf([NSURL URLWithString:scope])]) return a[@"id"];
    return [[NSUUID.UUID.UUIDString stringByReplacingOccurrencesOfString:@"-" withString:@""] substringToIndex:12].lowercaseString;
}
static BOOL RunTool(NSString *path, NSArray *args) {
    NSTask *t = [NSTask new]; t.executableURL = [NSURL fileURLWithPath:path]; t.arguments = args;
    t.standardOutput = NSFileHandle.fileHandleWithNullDevice; t.standardError = NSFileHandle.fileHandleWithNullDevice;
    if (![t launchAndReturnError:nil]) return NO;
    [t waitUntilExit];
    return t.terminationStatus == 0;
}
static void SignApp(NSString *app) {   // the local identity when there is one (macOS then keeps camera/microphone answers), else ad hoc
    if (!RunTool(@"/usr/bin/codesign", @[@"--force", @"--sign", @"Iris Local Signing", app])) RunTool(@"/usr/bin/codesign", @[@"--force", @"--sign", @"-", app]);
}
static NSDictionary *WebAppInfoPlist(NSDictionary *app) {
    NSDictionary *mainInfo = NSBundle.mainBundle.infoDictionary;
    NSMutableDictionary *p = [@{
        @"CFBundleName": app[@"name"], @"CFBundleDisplayName": app[@"name"],
        @"CFBundleIdentifier": [@"com.y.iris.app." stringByAppendingString:app[@"id"]],
        @"CFBundleExecutable": @"IrisApp", @"CFBundlePackageType": @"APPL", @"CFBundleIconFile": @"app",
        @"CFBundleShortVersionString": @"1.0", @"CFBundleVersion": @"1", @"LSMinimumSystemVersion": @"12.3",
        @"NSHighResolutionCapable": @YES, @"NSSupportsAutomaticGraphicsSwitching": @YES,
        @"LSApplicationCategoryType": @"public.app-category.productivity",
        @"IrisWebApp": @{@"id": app[@"id"], @"name": app[@"name"], @"start": app[@"start"], @"scope": app[@"scope"], @"host": app[@"host"] ?: @"",
                         @"theme": app[@"theme"] ?: @"", @"mainApp": NSBundle.mainBundle.bundlePath,
                         @"root": SupportDir(), @"prefs": NSBundle.mainBundle.bundleIdentifier ?: @"com.y.iris"}} mutableCopy];   // whoever installed it: their extensions, lists and settings
    for (NSString *k in @[@"NSCameraUsageDescription", @"NSMicrophoneUsageDescription", @"NSLocationUsageDescription", @"NSLocationWhenInUseUsageDescription", @"NSAppTransportSecurity"])
        if (mainInfo[k]) p[k] = mainInfo[k];
    return p;
}
// Puts the .app together next to its final place, then swaps it in. Runs off the main thread.
static NSString *WebAppWriteBundle(NSDictionary *app, NSImage *icon) {
    NSFileManager *fm = NSFileManager.defaultManager;
    [fm createDirectoryAtPath:WebAppsDir() withIntermediateDirectories:YES attributes:nil error:nil];
    NSString *dest = app[@"path"];
    NSString *tmp = [WebAppsDir() stringByAppendingPathComponent:[NSString stringWithFormat:@".%@.building.app", app[@"id"]]];
    [fm removeItemAtPath:tmp error:nil];
    NSString *contents = [tmp stringByAppendingPathComponent:@"Contents"];
    NSString *macos = [contents stringByAppendingPathComponent:@"MacOS"], *res = [contents stringByAppendingPathComponent:@"Resources"];
    for (NSString *d in @[macos, res]) if (![fm createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil]) return @"Couldn't create the app's folder";
    NSError *err = nil;
    if (![fm copyItemAtPath:NSBundle.mainBundle.executablePath toPath:[macos stringByAppendingPathComponent:@"IrisApp"] error:&err]) return err.localizedDescription ?: @"Couldn't copy Iris into the app";
    if (![WebAppInfoPlist(app) writeToURL:[NSURL fileURLWithPath:[contents stringByAppendingPathComponent:@"Info.plist"]] error:&err]) return err.localizedDescription ?: @"Couldn't write the app's description";
    [@"APPL????" writeToFile:[contents stringByAppendingPathComponent:@"PkgInfo"] atomically:YES encoding:NSASCIIStringEncoding error:nil];
    if (!WriteICNS(icon, [res stringByAppendingPathComponent:@"app.icns"])) return @"Couldn't write the icon";
    NSString *mainRes = NSBundle.mainBundle.resourcePath;   // the built-in pages and the extension layer stay Iris's own, always current
    for (NSString *f in @[@"pages", @"ext-shim.js"]) [fm createSymbolicLinkAtPath:[res stringByAppendingPathComponent:f] withDestinationPath:[mainRes stringByAppendingPathComponent:f] error:nil];
    SignApp(tmp);
    if ([fm fileExistsAtPath:dest]) {
        NSURL *out = nil;
        if (![fm replaceItemAtURL:[NSURL fileURLWithPath:dest] withItemAtURL:[NSURL fileURLWithPath:tmp] backupItemName:nil options:0 resultingItemURL:&out error:&err]) { [fm removeItemAtPath:tmp error:nil]; return err.localizedDescription ?: @"Couldn't replace the old app"; }
    } else if (![fm moveItemAtPath:tmp toPath:dest error:&err]) { [fm removeItemAtPath:tmp error:nil]; return err.localizedDescription ?: @"Couldn't put the app in place"; }
    LSRegisterURL((__bridge CFURLRef)[NSURL fileURLWithPath:dest], true);
    return nil;
}
// Your sign-in for the site, handed to the app once (it keeps its own website data from then on).
static void WebAppExportCookies(VWindow *win, NSString *host, NSString *ident, void (^done)(NSUInteger)) {
    WKHTTPCookieStore *store = win.pageConfig.websiteDataStore.httpCookieStore;
    NSArray *parts = [host.lowercaseString componentsSeparatedByString:@"."];
    NSString *site = parts.count >= 2 ? [[parts subarrayWithRange:NSMakeRange(parts.count - 2, 2)] componentsJoinedByString:@"."] : host;
    if (parts.count >= 3 && [parts[parts.count - 2] length] <= 3) site = [[parts subarrayWithRange:NSMakeRange(parts.count - 3, 3)] componentsJoinedByString:@"."];   // co.uk, com.au
    [store getAllCookies:^(NSArray<NSHTTPCookie *> *all) {
        NSMutableArray *keep = [NSMutableArray array];
        for (NSHTTPCookie *c in all) {
            NSString *d = [c.domain.lowercaseString hasPrefix:@"."] ? [c.domain.lowercaseString substringFromIndex:1] : c.domain.lowercaseString;
            if (![d isEqualToString:site] && ![d hasSuffix:[@"." stringByAppendingString:site]]) continue;
            NSMutableDictionary *p = [NSMutableDictionary dictionary];
            [c.properties enumerateKeysAndObjectsUsingBlock:^(id k, id v, BOOL *stop) { if ([v isKindOfClass:NSString.class] || [v isKindOfClass:NSDate.class] || [v isKindOfClass:NSNumber.class]) p[k] = v; }];
            [keep addObject:p];
        }
        NSString *file = [WebAppDataDir(ident) stringByAppendingPathComponent:@"cookies.plist"];
        NSData *d = keep.count ? [NSPropertyListSerialization dataWithPropertyList:keep format:NSPropertyListBinaryFormat_v1_0 options:0 error:nil] : nil;
        if (d) { [d writeToFile:file atomically:YES]; chmod(file.fileSystemRepresentation, 0600); }
        done(keep.count);
    }];
}
// After Iris itself changes (a new build), every installed app gets the new Iris inside it.
static void WebAppRefreshShims(void) {
    if (IrisIsDev()) return;   // apps belong to the Iris you browse with
    NSString *me = NSBundle.mainBundle.executablePath;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 8 * NSEC_PER_SEC), dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        NSFileManager *fm = NSFileManager.defaultManager;
        for (NSDictionary *a in WebAppRegistry()) {
            if ([NSRunningApplication runningApplicationsWithBundleIdentifier:[@"com.y.iris.app." stringByAppendingString:a[@"id"]]].count) continue;   // next time, when it isn't open
            NSString *old = [a[@"path"] stringByAppendingPathComponent:@"Contents/MacOS/Iris"], *exe = [a[@"path"] stringByAppendingPathComponent:@"Contents/MacOS/IrisApp"];
            if ([fm fileExistsAtPath:old] && ![fm fileExistsAtPath:exe]) [fm moveItemAtPath:old toPath:exe error:nil];   // apps made before the executable had its own name
            if (![fm fileExistsAtPath:exe] || [fm contentsEqualAtPath:exe andPath:me]) {
                NSDictionary *info = [NSDictionary dictionaryWithContentsOfFile:[a[@"path"] stringByAppendingPathComponent:@"Contents/Info.plist"]];
                if (![info[@"CFBundleExecutable"] isEqual:@"IrisApp"] && [fm fileExistsAtPath:exe]) { NSMutableDictionary *m = [info mutableCopy]; m[@"CFBundleExecutable"] = @"IrisApp"; [m writeToFile:[a[@"path"] stringByAppendingPathComponent:@"Contents/Info.plist"] atomically:YES]; SignApp(a[@"path"]); }
                continue;
            }
            NSString *next = [exe stringByAppendingString:@".new"];
            [fm removeItemAtPath:next error:nil];
            if (![fm copyItemAtPath:me toPath:next error:nil]) continue;
            rename(next.fileSystemRepresentation, exe.fileSystemRepresentation);   // a running app keeps the copy it started with
            NSMutableDictionary *info = [NSMutableDictionary dictionaryWithContentsOfFile:[a[@"path"] stringByAppendingPathComponent:@"Contents/Info.plist"]];
            if (info) { NSMutableDictionary *w = [info[@"IrisWebApp"] mutableCopy]; w[@"mainApp"] = NSBundle.mainBundle.bundlePath; info[@"IrisWebApp"] = w; info[@"CFBundleExecutable"] = @"IrisApp";
                        [info writeToFile:[a[@"path"] stringByAppendingPathComponent:@"Contents/Info.plist"] atomically:YES]; }
            SignApp(a[@"path"]);
            DLog(@"apps: %@ now runs this build of Iris", a[@"name"]);
        }
    });
}

#pragma mark The Install page (iris://install) and Settings

static void WebAppOp(NSString *op, NSDictionary *b, VWindow *win, void (^reply)(id, NSString *)) {
    NSMutableDictionary *pending = objc_getAssociatedObject(win, &kPendingInstallKey);
    if ([op isEqualToString:@"install.get"]) {
        if (!pending) { reply(@{@"error": @"Nothing to install"}, nil); return; }
        NSDictionary *existing = nil; for (NSDictionary *a in WebAppRegistry()) if ([a[@"id"] isEqualToString:pending[@"id"]]) existing = a;
        reply(@{@"name": pending[@"name"], @"host": pending[@"host"] ?: @"", @"start": pending[@"start"], @"icon": pending[@"iconURL"] ?: @"",
                @"manifest": pending[@"manifest"] ?: @NO, @"theme": pending[@"theme"] ?: @"", @"again": @(existing != nil), @"cookies": pending[@"cookieCount"] ?: @0}, nil);
        return;
    }
    if ([op isEqualToString:@"install.go"]) {
        if (!pending || !pending[@"icon"]) { reply(@{@"error": @"Nothing to install"}, nil); return; }
        NSString *name = [b[@"name"] isKindOfClass:NSString.class] ? Trim(b[@"name"]) : @"";
        name = [[name componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"/:\\\n\r\t"]] componentsJoinedByString:@" "];
        if (!name.length) name = pending[@"name"];
        BOOL cookies = [b[@"cookies"] boolValue];
        NSMutableDictionary *app = [pending mutableCopy]; app[@"name"] = name;
        [app removeObjectsForKeys:@[@"icon", @"iconURL", @"icons", @"cookieCount"]];
        NSString *path = nil;   // the same app reinstalled keeps its place; a new one gets a name not already taken
        for (NSDictionary *a in WebAppRegistry()) if ([a[@"id"] isEqualToString:app[@"id"]] && [a[@"path"] length]) path = a[@"path"];
        if (path && ![path.lastPathComponent.stringByDeletingPathExtension isEqualToString:name]) { [NSWorkspace.sharedWorkspace recycleURLs:@[[NSURL fileURLWithPath:path]] completionHandler:nil]; path = nil; }
        if (!path) {
            path = [WebAppsDir() stringByAppendingPathComponent:[name stringByAppendingPathExtension:@"app"]];
            for (NSInteger n = 2; [NSFileManager.defaultManager fileExistsAtPath:path]; n++) path = [WebAppsDir() stringByAppendingPathComponent:[NSString stringWithFormat:@"%@ %ld.app", name, (long)n]];
        }
        app[@"path"] = path; app[@"installed"] = @(NSDate.date.timeIntervalSince1970);
        NSImage *icon = pending[@"icon"];
        void (^build)(void) = ^{
            dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
                NSString *fail = WebAppWriteBundle(app, icon);
                dispatch_async(dispatch_get_main_queue(), ^{
                    if (fail) { DLog(@"apps: install of %@ failed: %@", name, fail); reply(@{@"error": fail}, nil); return; }
                    NSMutableArray *reg = WebAppRegistry();
                    for (NSDictionary *a in reg.copy) if ([a[@"id"] isEqualToString:app[@"id"]]) [reg removeObject:a];
                    [reg addObject:app]; WebAppSaveRegistry(reg); WebAppRegistryChanged();
                    DLog(@"apps: installed %@ at %@", name, path);
                    reply(@{@"ok": @YES, @"path": path, @"name": name}, nil);
                });
            });
        };
        if (cookies) WebAppExportCookies(win, app[@"host"], app[@"id"], ^(NSUInteger n) { dispatch_async(dispatch_get_main_queue(), build); });
        else build();
        return;
    }
    if ([op isEqualToString:@"install.open"]) {
        NSString *path = [b[@"path"] isKindOfClass:NSString.class] ? b[@"path"] : nil;
        if (path) [NSWorkspace.sharedWorkspace openApplicationAtURL:[NSURL fileURLWithPath:path] configuration:[NSWorkspaceOpenConfiguration configuration] completionHandler:nil];
        [win closeToolbarCustomiser];
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"install.reveal"]) {
        NSString *path = [b[@"path"] isKindOfClass:NSString.class] ? b[@"path"] : nil;
        if (path) [NSWorkspace.sharedWorkspace activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:path]]];
        reply(@YES, nil); return;
    }
    if ([op isEqualToString:@"install.done"]) { objc_setAssociatedObject(win, &kPendingInstallKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC); [win closeToolbarCustomiser]; reply(@YES, nil); return; }
    reply(nil, @"unknown op");
}
static void WebAppOpen(NSDictionary *a) {
    if ([NSFileManager.defaultManager fileExistsAtPath:a[@"path"] ?: @""])
        [NSWorkspace.sharedWorkspace openApplicationAtURL:[NSURL fileURLWithPath:a[@"path"]] configuration:[NSWorkspaceOpenConfiguration configuration] completionHandler:nil];
}
static void WebAppUninstall(NSDictionary *a) {
    NSMutableArray *reg = WebAppRegistry();
    for (NSDictionary *x in reg.copy) if ([x[@"id"] isEqualToString:a[@"id"]]) [reg removeObject:x];
    WebAppSaveRegistry(reg);
    for (NSRunningApplication *r in [NSRunningApplication runningApplicationsWithBundleIdentifier:[@"com.y.iris.app." stringByAppendingString:a[@"id"]]]) [r terminate];
    if ([a[@"path"] length]) [NSWorkspace.sharedWorkspace recycleURLs:@[[NSURL fileURLWithPath:a[@"path"]]] completionHandler:nil];
    [NSFileManager.defaultManager removeItemAtPath:WebAppDataDir(a[@"id"]) error:nil];
    WebAppRegistryChanged();
}

#pragma mark The app's own bar

static char kAppBarKey;
@interface VAppBar : NSView
@property (weak) VWindow *owner;
@property (strong) VButton *back, *fwd, *reload, *openIn, *more, *exts;
@end
@implementation VAppBar
- (BOOL)isFlipped { return YES; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (instancetype)initWithOwner:(VWindow *)w {
    if (!(self = [super initWithFrame:NSZeroRect])) return nil;
    self.owner = w;
    self.back = [VButton symbol:@"chevron.left" size:12.5 tip:@"Back (⌘[)" target:w action:@selector(goBack:)];
    self.fwd = [VButton symbol:@"chevron.right" size:12.5 tip:@"Forward (⌘])" target:w action:@selector(goForward:)];
    self.reload = [VButton symbol:@"arrow.clockwise" size:12 tip:@"Reload (⌘R)" target:w action:@selector(reloadOrStop:)];
    self.openIn = [VButton symbol:@"safari" size:13 tip:@"Open this page in Iris" target:self action:@selector(openInIris:)];
    self.more = [VButton symbol:@"ellipsis" size:13 tip:@"More" target:self action:@selector(showMore:)];
    self.exts = [VButton symbol:@"puzzlepiece.extension" size:12.5 tip:@"Extensions" target:self action:@selector(showExtensions:)];
    for (VButton *b in @[self.back, self.fwd, self.reload, self.openIn, self.more, self.exts]) { b.round = YES; [self addSubview:b]; }
    return self;
}
- (NSColor *)tint { return ColorFromCSS(gWebApp[@"theme"]); }
- (BOOL)lightText { NSColor *t = self.tint; return t ? !ColorIsLight(t) : !ThemeIsLight(); }
- (void)resizeSubviewsWithOldSize:(NSSize)s { [self place]; }
- (void)place {
    CGFloat W = NSWidth(self.bounds), y = 4;
    BOOL fs = (self.window.styleMask & NSWindowStyleMaskFullScreen) != 0;
    CGFloat x = fs ? 10 : 84;
    for (VButton *b in @[self.back, self.fwd, self.reload]) { b.frame = NSMakeRect(x, y, 29, 28); x += 29; }
    self.more.frame = NSMakeRect(W - 12 - 28, y, 28, 28);
    self.openIn.frame = NSMakeRect(W - 12 - 28 - 32, y, 28, 28);
    self.exts.hidden = !FExtHost.shared.extensions.count;
    self.exts.frame = NSMakeRect(W - 12 - 28 - 64, y, 28, 28);
}
// Your extensions, as in Iris: pick one to open it (a password manager's popup, say).
- (void)showExtensions:(VButton *)s {
    NSMenu *m = [[NSMenu alloc] initWithTitle:@""];
    for (id e in FExtHost.shared.extensions) {
        NSString *name = [e valueForKey:@"name"] ?: @"Extension";
        NSRange cut = [name rangeOfString:@" - "]; if (cut.location == NSNotFound) cut = [name rangeOfString:@": "];
        NSMenuItem *i = [m addItemWithTitle:cut.location != NSNotFound ? [name substringToIndex:cut.location] : name action:@selector(openExtension:) keyEquivalent:@""];
        i.target = self; i.representedObject = e;
        NSImage *ic = [FExtHost.shared iconFor:e]; if (ic) { ic = [ic copy]; ic.size = NSMakeSize(16, 16); i.image = ic; }
    }
    if (!m.numberOfItems) { NSMenuItem *n = [m addItemWithTitle:@"No extensions" action:nil keyEquivalent:@""]; n.enabled = NO; }
    PopMenu(m, NSMakePoint(NSMinX(s.frame), NSMaxY(s.frame) + 4), self);
}
- (void)openExtension:(NSMenuItem *)i { [FExtHost.shared openPopup:i.representedObject from:self.exts]; }
- (void)drawRect:(NSRect)dirty {
    NSColor *tint = self.tint;
    [(tint ?: vBg) setFill]; NSRectFill(self.bounds);
    BOOL light = self.lightText;
    NSColor *ink = light ? [NSColor colorWithWhite:1 alpha:0.92] : [NSColor colorWithWhite:0 alpha:0.85];
    VTab *t = self.owner.current;
    NSURL *u = [NSURL URLWithString:t.url ?: @""];
    BOOL away = u.host && !WebAppInScope(u);
    NSString *title = t.title.length ? t.title : gWebApp[@"name"];
    NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.alignment = NSTextAlignmentCenter; ps.lineBreakMode = NSLineBreakByTruncatingTail;
    CGFloat left = 84 + 3 * 29 + 12, right = NSWidth(self.bounds) - 12 - 92 - 12;
    if (away) {   // somewhere outside the app (a sign-in page, say): say where, plainly
        NSString *host = u.host ?: @"";
        NSDictionary *ha = @{NSFontAttributeName: UIFont(12, NSFontWeightMedium), NSForegroundColorAttributeName: ink};
        CGFloat hw = MIN(260, ceil([host sizeWithAttributes:ha].width)) + 34;
        NSRect pill = NSMakeRect(round(NSMidX(self.bounds) - hw / 2), 6, hw, 24);
        RoundRect(pill, 12, [ink colorWithAlphaComponent:0.10]);
        NSImage *lock = Tinted(Symbol([u.scheme isEqualToString:@"https"] ? @"lock.fill" : @"exclamationmark.triangle", 10, NSFontWeightSemibold), [ink colorWithAlphaComponent:0.75]);
        DrawImage(lock, NSMakeRect(NSMinX(pill) + 11, NSMidY(pill) - 6, 12, 12));
        [host drawInRect:NSMakeRect(NSMinX(pill) + 26, NSMidY(pill) - 8, hw - 34, 16) withAttributes:@{NSFontAttributeName: UIFont(12, NSFontWeightMedium), NSForegroundColorAttributeName: ink, NSParagraphStyleAttributeName: ps}];
    } else {
        [title drawInRect:NSMakeRect(left, 10, MAX(40, right - left), 17)
           withAttributes:@{NSFontAttributeName: UIFont(12.5, NSFontWeightSemibold), NSForegroundColorAttributeName: ink, NSParagraphStyleAttributeName: ps}];
    }
}
- (void)openInIris:(id)s { NSURL *u = [NSURL URLWithString:self.owner.current.url ?: @""]; OpenInIris(u ?: [NSURL URLWithString:gWebApp[@"start"]]); }
- (void)showMore:(VButton *)s {
    VWindow *w = self.owner;
    NSMenu *m = [[NSMenu alloc] initWithTitle:@""];
    NSMenuItem *(^add)(NSString *, SEL, id, NSString *) = ^NSMenuItem *(NSString *t, SEL a, id target, NSString *sym) {
        NSMenuItem *i = [m addItemWithTitle:t action:a keyEquivalent:@""]; i.target = target; if (sym) i.image = Tinted(Symbol(sym, 13, NSFontWeightMedium), vText); return i;
    };
    add(@"Open in Iris", @selector(openInIris:), self, @"safari");
    add(@"Copy Link", @selector(copyLink:), self, @"link");
    [m addItem:NSMenuItem.separatorItem];
    add(@"Find…", @selector(showFind:), w, @"magnifyingglass");
    add(@"Zoom In", @selector(zoomIn:), w, @"plus.magnifyingglass");
    add(@"Zoom Out", @selector(zoomOut:), w, @"minus.magnifyingglass");
    add(@"Actual Size", @selector(zoomReset:), w, nil);
    add(@"Print…", @selector(printPage:), w, @"printer");
    [m addItem:NSMenuItem.separatorItem];
    add(@"Go to the App's Start", @selector(goStart:), self, @"house");
    add([NSString stringWithFormat:@"Uninstall %@…", gWebApp[@"name"]], @selector(uninstallSelf:), self, @"trash");
    PopMenu(m, NSMakePoint(NSMaxX(s.frame) - 220, NSMaxY(s.frame) + 4), self);
}
- (void)copyLink:(id)s { NSString *u = self.owner.current.url; if (!u) return; [NSPasteboard.generalPasteboard clearContents]; [NSPasteboard.generalPasteboard setString:u forType:NSPasteboardTypeString]; [self.owner showToast:@"Link copied"]; }
- (void)goStart:(id)s { [self.owner openURL:[NSURL URLWithString:gWebApp[@"start"]] newTab:NO]; }
- (void)uninstallSelf:(id)s {
    NSAlert *a = [NSAlert new]; a.messageText = [NSString stringWithFormat:@"Uninstall %@?", gWebApp[@"name"]];
    a.informativeText = @"The app moves to the Bin and its sign-in and website data on this Mac are removed. The site itself stays in Iris.";
    [a addButtonWithTitle:@"Uninstall"]; [a addButtonWithTitle:@"Cancel"];
    [a beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r != NSAlertFirstButtonReturn) return;
        NSDictionary *me = @{@"id": gWebApp[@"id"] ?: @"", @"path": NSBundle.mainBundle.bundlePath};
        [WKWebsiteDataStore.defaultDataStore removeDataOfTypes:WKWebsiteDataStore.allWebsiteDataTypes modifiedSince:NSDate.distantPast completionHandler:^{
            NSMutableArray *reg = WebAppRegistry();
            for (NSDictionary *x in reg.copy) if ([x[@"id"] isEqualToString:me[@"id"]]) [reg removeObject:x];
            WebAppSaveRegistry(reg);
            [NSWorkspace.sharedWorkspace recycleURLs:@[[NSURL fileURLWithPath:me[@"path"]]] completionHandler:^(NSDictionary *n, NSError *e) { dispatch_async(dispatch_get_main_queue(), ^{ [NSApp terminate:nil]; }); }];
        }];
    }];
}
- (void)mouseDown:(NSEvent *)e { if (e.clickCount == 2) [self.window performZoom:nil]; else [self.window performWindowDragWithEvent:e]; }
- (void)refresh {
    VTab *t = self.owner.current; VPage *p = t.web;
    self.back.enabled = p.canGoBack; self.fwd.enabled = p.canGoForward;
    self.reload.symbolName = p.loading ? @"xmark" : @"arrow.clockwise";
    self.exts.hidden = !FExtHost.shared.extensions.count;
    for (VButton *b in @[self.back, self.fwd, self.reload, self.openIn, self.more, self.exts]) b.needsDisplay = YES;
    self.needsDisplay = YES;
}
@end

#pragma mark Running as the app

// The app sees your Iris settings (theme, blocking, codecs…) as its starting point, but keeps its own state.
static void WebAppAdoptSettings(void) {
    NSString *from = [gWebApp[@"prefs"] isKindOfClass:NSString.class] ? gWebApp[@"prefs"] : @"com.y.iris";   // the Iris or profile that installed it
    NSDictionary *main = [Defaults() persistentDomainForName:from];
    if (![main isKindOfClass:NSDictionary.class]) return;
    NSMutableDictionary *d = [main mutableCopy];
    for (NSString *k in main) if ([k hasPrefix:@"NSWindow Frame"] || [k hasPrefix:@"rule"] || [k hasPrefix:@"NSNavPanel"]) [d removeObjectForKey:k];
    for (NSString *k in @[kTabsState, kToolbarLayout]) [d removeObjectForKey:k];
    [Defaults() registerDefaults:d];
}
// The sign-in Iris handed over at install: set once into the app's own website data, then the file goes.
static void WebAppImportCookies(void (^done)(void)) {
    NSString *file = [WebAppDataDir(gWebApp[@"id"]) stringByAppendingPathComponent:@"cookies.plist"];
    NSData *d = [NSData dataWithContentsOfFile:file];
    NSArray *props = d ? [NSPropertyListSerialization propertyListWithData:d options:0 format:NULL error:nil] : nil;
    if (![props isKindOfClass:NSArray.class] || !props.count) { done(); return; }
    WKHTTPCookieStore *store = WKWebsiteDataStore.defaultDataStore.httpCookieStore;
    dispatch_group_t g = dispatch_group_create();
    NSUInteger n = 0;
    for (NSDictionary *p in props) {
        NSHTTPCookie *c = [p isKindOfClass:NSDictionary.class] ? [NSHTTPCookie cookieWithProperties:p] : nil;
        if (!c) continue;
        dispatch_group_enter(g); n++;
        [store setCookie:c completionHandler:^{ dispatch_group_leave(g); }];
    }
    DLog(@"app: %lu cookies from Iris", (unsigned long)n);
    dispatch_group_notify(g, dispatch_get_main_queue(), ^{ [NSFileManager.defaultManager removeItemAtPath:file error:nil]; done(); });
}
static VWindow *WebAppOpenWindow(NSURL *u) {
    VWindow *w = [[VWindow alloc] initPrivate:NO state:@{@"empty": @YES}];
    w.window.title = gWebApp[@"name"] ?: @"App";
    if (gWindows.count > 1) {
        VWindow *prev = gWindows[gWindows.count - 2];
        NSRect f = prev.window.frame; [w.window setFrame:f display:NO];
        [w.window cascadeTopLeftFromPoint:NSMakePoint(NSMinX(f) + 26, NSMaxY(f) - 26)];
    }
    [w newTab:u ?: [NSURL URLWithString:gWebApp[@"start"]] select:YES];
    [w showWindow:nil]; [w windowDidResize:nil];
    [w.window makeKeyAndOrderFront:nil];
    return w;
}

@implementation VWindow (WebApp)
- (VAppBar *)appBar {
    VAppBar *b = objc_getAssociatedObject(self, &kAppBarKey);
    if (!b) { b = [[VAppBar alloc] initWithOwner:self]; objc_setAssociatedObject(self, &kAppBarKey, b, OBJC_ASSOCIATION_RETAIN_NONATOMIC); }
    return b;
}
// The app's window: its own bar of the site's colour (back, forward, reload, the page's title), and the page below.
- (void)layoutWebApp {
    NSView *root = self.window.contentView;
    CGFloat W = NSWidth(root.bounds), H = NSHeight(root.bounds), top = 36;
    BOOL fs = (self.window.styleMask & NSWindowStyleMaskFullScreen) != 0;
    VAppBar *bar = (VAppBar *)[self appBar];
    if (bar.superview != root) [root addSubview:bar positioned:NSWindowAbove relativeTo:self.content];
    self.toolbar.hidden = YES; self.shelfHandle.hidden = YES; self.shelf.hidden = YES;
    bar.frame = NSMakeRect(0, 0, W, top); [bar place];
    self.lights.hidden = fs; self.lights.frame = NSMakeRect(12, 7, 62, 22);
    [root addSubview:self.lights positioned:NSWindowAbove relativeTo:bar];
    self.content.frame = NSMakeRect(0, top, W, H - top);
    self.loadLine.hidden = NO; self.loadLine.frame = NSMakeRect(0, top - 2, W, 2);
    [root addSubview:self.loadLine positioned:NSWindowAbove relativeTo:bar];
    NSColor *tint = ColorFromCSS(gWebApp[@"theme"]);
    if (tint) self.window.backgroundColor = tint;
    self.findBar.frame = NSMakeRect(NSWidth(self.content.bounds) - 344, NSHeight(self.content.bounds) - 36 - 10, 330, 36);
    [self frameContent];
    [self placePages];
    [self updateEmber];
    [bar refresh];
}
- (void)refreshWebAppBar {
    VTab *t = self.current;
    self.window.title = t.title.length ? t.title : gWebApp[@"name"] ?: @"App";
    [(VAppBar *)[self appBar] refresh];
}

// Install: read what the page says about itself, make the icon, and show the Install page over the window.
- (void)installWebApp:(id)s {
    VTab *t = self.current;
    if (gWebApp || !t.web || ![t.url hasPrefix:@"http"]) { [self showToast:@"Open the site you want as an app first"]; return; }
    if (self.isPrivate) { [self showToast:@"Apps can't be installed from a private window"]; return; }
    NSDictionary *installed = WebAppFor([NSURL URLWithString:t.url]);
    if (installed && [s isKindOfClass:VButton.class]) { WebAppOpen(installed); return; }   // the address bar's button: already an app, so open it
    __weak VWindow *ws = self;
    [t.web.web callAsyncJavaScript:kManifestJS arguments:@{} inFrame:nil inContentWorld:WKContentWorld.defaultClientWorld completionHandler:^(id r, NSError *e) {
        NSDictionary *j = [r isKindOfClass:NSString.class] ? [NSJSONSerialization JSONObjectWithData:[r dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil] : nil;
        if (![j isKindOfClass:NSDictionary.class]) j = @{@"url": t.url ?: @"", @"title": t.title ?: @""};
        NSMutableDictionary *d = [WebAppDescribe(j) mutableCopy];
        d[@"id"] = WebAppIdentFor(d[@"scope"]);
        NSImage *fallback = t.favicon;
        WebAppFetchIcon(d[@"icons"], 0, nil, ^(NSImage *im, BOOL maskable) {
            VWindow *w = ws; if (!w) return;
            NSImage *icon = WebAppIcon(im ?: fallback, maskable, ColorFromCSS(d[@"bg"]) ?: (im ? nil : ColorFromCSS(d[@"theme"])));
            d[@"icon"] = icon; d[@"iconURL"] = ImageDataURLOf(icon, 256);
            [d removeObjectForKey:@"icons"];
            objc_setAssociatedObject(w, &kPendingInstallKey, d, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            [w showOverlay:@"install" size:NSMakeSize(520, 470)];
        });
    }];
}
- (void)openInstalledApp:(id)s { NSDictionary *a = WebAppFor([NSURL URLWithString:self.current.url ?: @""]); if (a) WebAppOpen(a); }
@end
#pragma mark - Profiles as separate apps

// A profile is a different person. Each one besides the first runs as its own app, "Iris <Name>" in
// ~/Applications/Iris Profiles: its own Dock icon, and its own everything (extensions and their data, bookmarks,
// downloads, settings, history, tabs, sign-ins), kept apart by macOS itself. The app carries this same Iris, with an
// IrisProfile entry in its Info.plist; started that way, gProfileApp is set and Iris keeps that profile's data in
// Application Support/Iris/Profiles/<id>.

static NSString *ProfileAppsDir(void) { return [NSHomeDirectory() stringByAppendingPathComponent:@"Applications/Iris Profiles"]; }
static NSString *ProfileDataDir(NSString *pid) {
    NSString *d = [[[NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory, NSUserDomainMask, YES).firstObject
                     stringByAppendingPathComponent:@"Iris"] stringByAppendingPathComponent:@"Profiles"] stringByAppendingPathComponent:pid ?: @"_"];
    [NSFileManager.defaultManager createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil];
    return d;
}
static NSString *ProfileBundleID(NSString *pid) { return [@"com.y.iris.profile." stringByAppendingString:[[pid stringByReplacingOccurrencesOfString:@"-" withString:@""] lowercaseString]]; }
static NSString *MainIrisPath(void) {   // the Iris you browse with, from wherever this code is running
    if (gProfileApp[@"mainApp"]) return gProfileApp[@"mainApp"];
    return NSBundle.mainBundle.bundlePath;
}
// The profile's app on disk, if it has been made.
static NSString *ProfileAppFind(NSString *pid) {
    NSFileManager *fm = NSFileManager.defaultManager;
    for (NSString *f in [fm contentsOfDirectoryAtPath:ProfileAppsDir() error:nil]) {
        if (![f hasSuffix:@".app"]) continue;
        NSString *p = [ProfileAppsDir() stringByAppendingPathComponent:f];
        NSDictionary *info = [NSDictionary dictionaryWithContentsOfFile:[p stringByAppendingPathComponent:@"Contents/Info.plist"]];
        if ([info[@"IrisProfile"][@"id"] isEqualToString:pid]) return p;
    }
    return nil;
}
static NSDictionary *ProfileEntry(NSString *pid) {
    for (NSDictionary *p in ProfilesStored()) if ([p[@"id"] isEqualToString:pid]) return p;
    return nil;
}
// The Iris binary a profile's app carries: the one in Iris itself, so an app made from another profile's app is never older.
static NSString *IrisBinary(void) {
    NSString *b = [MainIrisPath() stringByAppendingPathComponent:@"Contents/MacOS/Iris"];
    return [NSFileManager.defaultManager isExecutableFileAtPath:b] ? b : NSBundle.mainBundle.executablePath;
}
// Its Dock icon: Iris's, with the profile's initial on its colour in the corner.
static NSImage *ProfileAppIcon(NSString *pid, NSString *name, NSInteger colorIndex) {
    NSImage *base = [[NSImage alloc] initWithContentsOfFile:[MainIrisPath() stringByAppendingPathComponent:@"Contents/Resources/Iris.icns"]] ?: NSApp.applicationIconImage;
    NSArray *cols = ProfileColors();
    NSColor *c = Hex((uint32_t)[cols[(NSUInteger)MAX(0, MIN((NSInteger)cols.count - 1, colorIndex))][1] unsignedIntValue]);
    NSString *initial = name.length ? [[name substringToIndex:[name rangeOfComposedCharacterSequenceAtIndex:0].length] uppercaseString] : @"•";
    return [NSImage imageWithSize:NSMakeSize(1024, 1024) flipped:NO drawingHandler:^BOOL(NSRect r) {
        [base drawInRect:r fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1];
        NSRect dot = NSMakeRect(600, 110, 330, 330);
        [NSGraphicsContext saveGraphicsState];
        NSShadow *sh = [NSShadow new]; sh.shadowBlurRadius = 22; sh.shadowOffset = NSMakeSize(0, -8); sh.shadowColor = [NSColor colorWithWhite:0 alpha:0.4]; [sh set];
        [c setFill]; [[NSBezierPath bezierPathWithOvalInRect:dot] fill];
        [NSGraphicsContext restoreGraphicsState];
        NSBezierPath *ring = [NSBezierPath bezierPathWithOvalInRect:NSInsetRect(dot, 5, 5)]; ring.lineWidth = 10; [[NSColor colorWithWhite:1 alpha:0.9] setStroke]; [ring stroke];
        NSDictionary *a = @{NSFontAttributeName: [NSFont systemFontOfSize:190 weight:NSFontWeightBold], NSForegroundColorAttributeName: NSColor.whiteColor};
        NSSize s = [initial sizeWithAttributes:a];
        [initial drawAtPoint:NSMakePoint(NSMidX(dot) - s.width / 2, NSMidY(dot) - s.height / 2 + 6) withAttributes:a];
        return YES;
    }];
}
// Puts a small app together (Iris inside, its own Info.plist and icon) and swaps it into place. Off the main thread.
static NSString *WriteShimApp(NSString *dest, NSDictionary *info, NSString *exe, NSImage *icon) {
    NSFileManager *fm = NSFileManager.defaultManager;
    [fm createDirectoryAtPath:dest.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil];
    NSString *tmp = [dest.stringByDeletingLastPathComponent stringByAppendingPathComponent:[NSString stringWithFormat:@".%@.building.app", NSUUID.UUID.UUIDString]];
    NSString *contents = [tmp stringByAppendingPathComponent:@"Contents"];
    NSString *macos = [contents stringByAppendingPathComponent:@"MacOS"], *res = [contents stringByAppendingPathComponent:@"Resources"];
    for (NSString *d in @[macos, res]) if (![fm createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil]) return @"Couldn't create the app's folder";
    NSError *err = nil;
    if (![fm copyItemAtPath:IrisBinary() toPath:[macos stringByAppendingPathComponent:exe] error:&err]) { [fm removeItemAtPath:tmp error:nil]; return err.localizedDescription ?: @"Couldn't copy Iris into the app"; }
    if (![info writeToURL:[NSURL fileURLWithPath:[contents stringByAppendingPathComponent:@"Info.plist"]] error:&err]) { [fm removeItemAtPath:tmp error:nil]; return err.localizedDescription ?: @"Couldn't write the app's description"; }
    [@"APPL????" writeToFile:[contents stringByAppendingPathComponent:@"PkgInfo"] atomically:YES encoding:NSASCIIStringEncoding error:nil];
    if (!WriteICNS(icon, [res stringByAppendingPathComponent:@"app.icns"])) { [fm removeItemAtPath:tmp error:nil]; return @"Couldn't write the icon"; }
    NSString *mainRes = [MainIrisPath() stringByAppendingPathComponent:@"Contents/Resources"];   // built-in pages, icons and the extension layer stay Iris's own, always current
    for (NSString *f in @[@"pages", @"ext-shim.js", @"Iris.icns"]) [fm createSymbolicLinkAtPath:[res stringByAppendingPathComponent:f] withDestinationPath:[mainRes stringByAppendingPathComponent:f] error:nil];
    SignApp(tmp);
    if ([fm fileExistsAtPath:dest]) {
        if (![fm replaceItemAtURL:[NSURL fileURLWithPath:dest] withItemAtURL:[NSURL fileURLWithPath:tmp] backupItemName:nil options:0 resultingItemURL:nil error:&err]) { [fm removeItemAtPath:tmp error:nil]; return err.localizedDescription ?: @"Couldn't replace the old app"; }
    } else if (![fm moveItemAtPath:tmp toPath:dest error:&err]) { [fm removeItemAtPath:tmp error:nil]; return err.localizedDescription ?: @"Couldn't put the app in place"; }
    LSRegisterURL((__bridge CFURLRef)[NSURL fileURLWithPath:dest], true);
    return nil;
}
static NSDictionary *ProfileInfoPlist(NSString *pid, NSString *name, NSInteger color) {
    NSDictionary *mainInfo = [NSDictionary dictionaryWithContentsOfFile:[MainIrisPath() stringByAppendingPathComponent:@"Contents/Info.plist"]] ?: NSBundle.mainBundle.infoDictionary;
    NSMutableDictionary *p = [@{
        @"CFBundleName": [@"Iris " stringByAppendingString:name], @"CFBundleDisplayName": [@"Iris " stringByAppendingString:name],
        @"CFBundleIdentifier": ProfileBundleID(pid), @"CFBundleExecutable": @"IrisProfile", @"CFBundlePackageType": @"APPL", @"CFBundleIconFile": @"app",
        @"CFBundleShortVersionString": @"1.0", @"CFBundleVersion": @"1", @"LSMinimumSystemVersion": @"12.3", @"NSHighResolutionCapable": @YES,
        @"LSApplicationCategoryType": @"public.app-category.productivity",
        @"IrisProfile": @{@"id": pid, @"name": name, @"color": @(color), @"mainApp": MainIrisPath()}} mutableCopy];
    for (NSString *k in @[@"NSCameraUsageDescription", @"NSMicrophoneUsageDescription", @"NSLocationUsageDescription", @"NSLocationWhenInUseUsageDescription", @"NSAppTransportSecurity"])
        if (mainInfo[k]) p[k] = mainInfo[k];
    return p;
}
static BOOL ProfileAppRunning(NSString *pid) { return [NSRunningApplication runningApplicationsWithBundleIdentifier:ProfileBundleID(pid)].count > 0; }
// The profile's app, made (or brought up to date: this build, its current name and colour) when it isn't open.
static NSString *ProfileAppEnsure(NSString *pid) {
    NSDictionary *e = ProfileEntry(pid);
    NSString *name = e[@"name"] ?: @"Profile"; NSInteger color = ProfileColorIndex(pid);
    NSString *path = ProfileAppFind(pid), *want = [ProfileAppsDir() stringByAppendingPathComponent:[NSString stringWithFormat:@"Iris %@.app", name]];
    if (path && ProfileAppRunning(pid)) return path;
    BOOL stale = YES;
    if (path) {
        NSDictionary *info = [NSDictionary dictionaryWithContentsOfFile:[path stringByAppendingPathComponent:@"Contents/Info.plist"]];
        stale = ![info[@"IrisProfile"][@"name"] isEqual:name] || ![info[@"IrisProfile"][@"color"] isEqual:@(color)] || ![path isEqualToString:want]
             || ![NSFileManager.defaultManager contentsEqualAtPath:[path stringByAppendingPathComponent:@"Contents/MacOS/IrisProfile"] andPath:IrisBinary()];
    }
    if (!stale) return path;
    if (path && ![path isEqualToString:want]) [NSFileManager.defaultManager removeItemAtPath:path error:nil];
    NSString *fail = WriteShimApp(want, ProfileInfoPlist(pid, name, color), @"IrisProfile", ProfileAppIcon(pid, name, color));
    if (fail) { DLog(@"profiles: couldn't make the app for %@: %@", name, fail); return path && [NSFileManager.defaultManager fileExistsAtPath:path] ? path : nil; }
    DLog(@"profiles: %@ is ready at %@", name, want);
    return want;
}

// The first time a profile opens as its own app, what Iris kept for it comes along: its sign-ins (cookies),
// history, and any of its windows that were open, with their tabs.
static NSString *const kProfileMoved = @"movedToApp";
static void ProfileHandOver(NSString *pid, NSArray *windows, void (^done)(void)) {
    if (gProfileApp || IrisIsDev() || gWebApp) { done(); return; }
    NSString *dir = ProfileDataDir(pid);
    NSFileManager *fm = NSFileManager.defaultManager;
    if (windows.count) {
        NSMutableArray *ws = [NSMutableArray array];
        for (NSDictionary *w in windows) { NSMutableDictionary *m = [w mutableCopy]; m[@"profile"] = @""; [ws addObject:m]; }
        NSString *f = [dir stringByAppendingPathComponent:@"seed-session.plist"];
        NSArray *old = [NSArray arrayWithContentsOfFile:f] ?: @[];
        [[old arrayByAddingObjectsFromArray:ws] writeToFile:f atomically:YES];
    }
    NSDictionary *e = ProfileEntry(pid);
    if ([e[kProfileMoved] boolValue]) { done(); return; }
    NSString *hist = SupportFile([NSString stringWithFormat:@"history-%@.json", pid]);
    if ([fm fileExistsAtPath:hist] && ![fm fileExistsAtPath:[dir stringByAppendingPathComponent:@"history.json"]]) [fm copyItemAtPath:hist toPath:[dir stringByAppendingPathComponent:@"history.json"] error:nil];
    void (^mark)(void) = ^{
        NSMutableArray *profiles = [NSMutableArray array];
        for (NSDictionary *x in ProfilesStored()) { NSMutableDictionary *m = [x mutableCopy]; if ([x[@"id"] isEqualToString:pid]) m[kProfileMoved] = @YES; [profiles addObject:m]; }
        ProfilesStore(profiles);
    };
    WKWebsiteDataStore *store = ProfileStore(pid);
    if (store == WKWebsiteDataStore.defaultDataStore) { mark(); done(); return; }   // before macOS 14 profiles had no sign-ins of their own to bring
    [store.httpCookieStore getAllCookies:^(NSArray<NSHTTPCookie *> *all) {
        NSMutableArray *keep = [NSMutableArray array];
        for (NSHTTPCookie *c in all) {
            NSMutableDictionary *p = [NSMutableDictionary dictionary];
            [c.properties enumerateKeysAndObjectsUsingBlock:^(id k, id v, BOOL *stop) { if ([v isKindOfClass:NSString.class] || [v isKindOfClass:NSDate.class] || [v isKindOfClass:NSNumber.class]) p[k] = v; }];
            [keep addObject:p];
        }
        NSData *d = keep.count ? [NSPropertyListSerialization dataWithPropertyList:keep format:NSPropertyListBinaryFormat_v1_0 options:0 error:nil] : nil;
        NSString *f = [dir stringByAppendingPathComponent:@"cookies.plist"];
        if (d) { [d writeToFile:f atomically:YES]; chmod(f.fileSystemRepresentation, 0600); }
        mark();
        DLog(@"profiles: handed %lu sign-in cookies and its history to the app", (unsigned long)keep.count);
        dispatch_async(dispatch_get_main_queue(), done);
    }];
}
// Open a profile: its app, made if needed, with these pages if any.
static void ProfileAppOpen(NSString *pid, NSArray<NSURL *> *urls) {
    if (!pid.length) return;
    if ([pid isEqualToString:@"@main"]) {   // from a profile's app: the first profile is Iris itself
        NSURL *app = [NSURL fileURLWithPath:MainIrisPath()];
        if (urls.count) [NSWorkspace.sharedWorkspace openURLs:urls withApplicationAtURL:app configuration:[NSWorkspaceOpenConfiguration configuration] completionHandler:nil];
        else [NSWorkspace.sharedWorkspace openApplicationAtURL:app configuration:[NSWorkspaceOpenConfiguration configuration] completionHandler:nil];
        return;
    }
    ProfileHandOver(pid, nil, ^{
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            NSString *path = ProfileAppEnsure(pid);
            dispatch_async(dispatch_get_main_queue(), ^{
                if (!path) { [gWin showToast:@"Couldn't open that profile's app"]; return; }
                NSURL *app = [NSURL fileURLWithPath:path];
                NSWorkspaceOpenConfiguration *cfg = [NSWorkspaceOpenConfiguration configuration]; cfg.activates = YES;
                if (urls.count) [NSWorkspace.sharedWorkspace openURLs:urls withApplicationAtURL:app configuration:cfg completionHandler:nil];
                else [NSWorkspace.sharedWorkspace openApplicationAtURL:app configuration:cfg completionHandler:nil];
            });
        });
    });
}
// At launch, Iris itself: windows of other profiles saved last time go to those profiles' apps.
static void ProfilesMoveWindowsOut(void) {
    if (gProfileApp || IrisIsDev() || gWebApp) return;
    NSDictionary *st = [Defaults() dictionaryForKey:kTabsState];
    if (![st isKindOfClass:NSDictionary.class]) return;
    NSMutableArray *all = [NSMutableArray array];
    NSMutableDictionary *first = [st mutableCopy]; [first removeObjectForKey:@"windows"];
    [all addObject:first];
    for (NSDictionary *w in [st[@"windows"] isKindOfClass:NSArray.class] ? st[@"windows"] : @[]) if ([w isKindOfClass:NSDictionary.class]) [all addObject:w];
    NSMutableArray *mine = [NSMutableArray array]; NSMutableDictionary *theirs = [NSMutableDictionary dictionary];
    for (NSDictionary *w in all) {
        NSString *pid = [w[@"profile"] isKindOfClass:NSString.class] ? w[@"profile"] : @"";
        if (!pid.length || !ProfileEntry(pid)) [mine addObject:w];
        else { if (!theirs[pid]) theirs[pid] = [NSMutableArray array]; [theirs[pid] addObject:w]; }
    }
    if (!theirs.count) return;
    NSMutableDictionary *next = mine.count ? [mine[0] mutableCopy] : [@{@"tabs": @[], @"current": @0} mutableCopy];
    if (mine.count > 1) next[@"windows"] = [mine subarrayWithRange:NSMakeRange(1, mine.count - 1)];
    [Defaults() setObject:next forKey:kTabsState];
    for (NSString *pid in theirs) {
        DLog(@"profiles: %lu window(s) of %@ move to its app", (unsigned long)[theirs[pid] count], ProfileName(pid));
        ProfileHandOver(pid, theirs[pid], ^{ ProfileAppOpen(pid, nil); });
    }
}

// In a profile's app, at its first start: Iris's look and the public filter lists, then what Iris handed over.
static void ProfileAppFirstLaunch(void) {
    if (!gProfileApp) return;
    NSFileManager *fm = NSFileManager.defaultManager;
    NSString *dir = SupportDir();
    if (![fm fileExistsAtPath:[dir stringByAppendingPathComponent:@".seeded"]]) {
        NSDictionary *main = [NSUserDefaults.standardUserDefaults persistentDomainForName:@"com.y.iris"];
        for (NSString *k in @[kTheme, kAccent, kDensity, kAddrWidth, kToolbarLayout, kShelfSide, kBlock, kStrip, kCookieReject, kGPC, kCodec, kThrottleOn, kBgThrottle, kSearch])
            if (main[k] && ![Defaults() objectForKey:k]) [Defaults() setObject:main[k] forKey:k];
        [@"[]" writeToFile:SupportFile(@"bookmarks.json") atomically:YES encoding:NSUTF8StringEncoding error:nil];
        [@"" writeToFile:[dir stringByAppendingPathComponent:@".seeded"] atomically:YES encoding:NSUTF8StringEncoding error:nil];
    }
    // windows Iris handed over: they become this app's saved session
    NSString *seed = [dir stringByAppendingPathComponent:@"seed-session.plist"];
    NSArray *ws = [NSArray arrayWithContentsOfFile:seed];
    if (ws.count) {
        NSMutableArray *windows = [ws mutableCopy];
        NSDictionary *cur = [Defaults() dictionaryForKey:kTabsState];
        if ([cur[@"tabs"] count]) { NSMutableDictionary *c = [cur mutableCopy]; [c removeObjectForKey:@"windows"]; [windows insertObject:c atIndex:0];
                                    for (id w in cur[@"windows"] ?: @[]) [windows addObject:w]; }
        NSMutableDictionary *st = [windows[0] mutableCopy];
        if (windows.count > 1) st[@"windows"] = [windows subarrayWithRange:NSMakeRange(1, windows.count - 1)];
        [Defaults() setObject:st forKey:kTabsState];
    }
    [fm removeItemAtPath:seed error:nil];
}
// Its sign-ins from Iris, set before any page loads (the first start only).
static void ProfileAppImportCookies(void) {
    if (!gProfileApp) return;
    NSFileManager *fm = NSFileManager.defaultManager;
    NSString *file = [SupportDir() stringByAppendingPathComponent:@"cookies.plist"];
    NSData *d = [NSData dataWithContentsOfFile:file];
    NSArray *props = d ? [NSPropertyListSerialization propertyListWithData:d options:0 format:NULL error:nil] : nil;
    if ([props isKindOfClass:NSArray.class] && props.count) {
        __block NSInteger left = 0;
        WKHTTPCookieStore *store = WKWebsiteDataStore.defaultDataStore.httpCookieStore;
        for (NSDictionary *p in props) {
            NSHTTPCookie *c = [p isKindOfClass:NSDictionary.class] ? [NSHTTPCookie cookieWithProperties:p] : nil;
            if (!c) continue;
            left++; [store setCookie:c completionHandler:^{ left--; }];
        }
        NSDate *limit = [NSDate dateWithTimeIntervalSinceNow:8];
        while (left > 0 && limit.timeIntervalSinceNow > 0) [NSRunLoop.currentRunLoop runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:0.05]];
        DLog(@"profile: %lu sign-in cookies from Iris", (unsigned long)props.count);
    }
    [fm removeItemAtPath:file error:nil];
}
static void ProfileAppUninstall(NSString *pid) {
    NSArray *running = [NSRunningApplication runningApplicationsWithBundleIdentifier:ProfileBundleID(pid)];
    for (NSRunningApplication *r in running) [r terminate];
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)((running.count ? 4 : 0) * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{   // once it has closed
        for (NSRunningApplication *r in running) if (!r.terminated) [r forceTerminate];
        NSString *path = ProfileAppFind(pid);
        if (path) [NSWorkspace.sharedWorkspace recycleURLs:@[[NSURL fileURLWithPath:path]] completionHandler:nil];
        // everything that person had: Iris's folder for them, WebKit's website data and caches, their settings
        NSFileManager *fm = NSFileManager.defaultManager;
        [fm removeItemAtPath:ProfileDataDir(pid) error:nil];
        NSString *bid = ProfileBundleID(pid), *lib = [NSHomeDirectory() stringByAppendingPathComponent:@"Library"];
        for (NSString *d in @[@"WebKit", @"HTTPStorages", @"Caches", @"Saved Application State"])
            [fm removeItemAtPath:[[lib stringByAppendingPathComponent:d] stringByAppendingPathComponent:[d isEqualToString:@"Saved Application State"] ? [bid stringByAppendingString:@".savedState"] : bid] error:nil];
        [NSUserDefaults.standardUserDefaults removePersistentDomainForName:bid];
        [fm removeItemAtPath:[lib stringByAppendingPathComponent:[NSString stringWithFormat:@"Preferences/%@.plist", bid]] error:nil];
        DLog(@"profiles: removed the app and data of %@", pid);
    });
}
// Iris, after a new build: every profile app that isn't open gets it (and its current name and colour).
static void ProfileAppsRefresh(void) {
    if (gProfileApp || IrisIsDev() || gWebApp) return;
    NSArray *ids = [ProfilesStored() valueForKey:@"id"];
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 10 * NSEC_PER_SEC), dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        for (NSString *pid in ids) if (ProfileAppFind(pid) && !ProfileAppRunning(pid)) ProfileAppEnsure(pid);
    });
}
#pragma mark - Private windows: locking, and nothing left behind

// Private windows lock when your Mac locks or sleeps and, if you like, after a while away from Iris. A locked window
// shows nothing of its pages (they're hidden, not blurred, and paused) until Touch ID or your password opens it. All
// private windows lock and unlock together. When the last one closes, every decision made in them goes too.

static BOOL gPrivLocked;
static NSTimer *gPrivAwayTimer;
static void PrivateUnlockAll(void);

static NSArray<VWindow *> *PrivateWindows(void) {
    NSMutableArray *a = [NSMutableArray array];
    for (VWindow *w in gWindows) if (w.isPrivate) [a addObject:w];
    return a;
}

@interface VPrivateLock : NSView
@property (weak) VWindow *owner;
@property BOOL hoverBtn, pressing;
@property (strong) NSString *problem;
- (NSRect)buttonRect;
@end
@implementation VPrivateLock
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstResponder { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (BOOL)mouseDownCanMoveWindow { return NO; }
- (NSView *)hitTest:(NSPoint)p { NSView *h = [super hitTest:p]; return h ? self : nil; }   // nothing under it can be reached
- (void)resetCursorRects { [self addCursorRect:self.bounds cursor:NSCursor.arrowCursor]; }
- (NSRect)buttonRect { CGFloat w = 168, h = 36; return NSMakeRect(round(NSMidX(self.bounds) - w / 2), round(NSMidY(self.bounds) + 46), w, h); }
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    for (NSTrackingArea *t in self.trackingAreas.copy) [self removeTrackingArea:t];
    [self addTrackingArea:[[NSTrackingArea alloc] initWithRect:NSZeroRect options:NSTrackingMouseMoved | NSTrackingMouseEnteredAndExited | NSTrackingActiveAlways | NSTrackingInVisibleRect owner:self userInfo:nil]];
}
- (void)mouseMoved:(NSEvent *)e { BOOL h = NSPointInRect([self convertPoint:e.locationInWindow fromView:nil], self.buttonRect); if (h != self.hoverBtn) { self.hoverBtn = h; self.needsDisplay = YES; } }
- (void)mouseExited:(NSEvent *)e { self.hoverBtn = NO; self.needsDisplay = YES; }
- (void)mouseDown:(NSEvent *)e {
    if (NSPointInRect([self convertPoint:e.locationInWindow fromView:nil], self.buttonRect)) { self.pressing = YES; self.needsDisplay = YES; }
    else if (e.clickCount == 2) [self.window performZoom:nil];
    else [self.window performWindowDragWithEvent:e];
}
- (void)mouseUp:(NSEvent *)e {
    BOOL was = self.pressing; self.pressing = NO; self.needsDisplay = YES;
    if (was && NSPointInRect([self convertPoint:e.locationInWindow fromView:nil], self.buttonRect)) PrivateUnlockAll();
}
- (void)rightMouseDown:(NSEvent *)e {}
- (void)scrollWheel:(NSEvent *)e {}
- (void)keyDown:(NSEvent *)e {
    if (e.keyCode == 36 || e.keyCode == 76 || e.keyCode == 49) { PrivateUnlockAll(); return; }   // Return, Enter, Space
    if (e.modifierFlags & NSEventModifierFlagCommand) { [super keyDown:e]; return; }          // ⌘W, ⌘Q and the rest still work
}
- (void)drawRect:(NSRect)r {
    BOOL light = ThemeIsLight();
    [vContentBg setFill]; NSRectFill(self.bounds);
    CGFloat W = NSWidth(self.bounds), cy = NSMidY(self.bounds);
    NSPoint c = NSMakePoint(W / 2, cy - 40);
    NSColor *v = light ? Hex(0x6b5bd6) : Hex(0x7a68e8);
    NSGradient *glow = [[NSGradient alloc] initWithColors:@[[v colorWithAlphaComponent:light ? 0.10 : 0.18], [v colorWithAlphaComponent:0]]];
    [glow drawFromCenter:c radius:0 toCenter:c radius:220 options:0];
    // the lock, in a ring of the private window's violet
    NSRect ring = NSMakeRect(c.x - 34, c.y - 58, 68, 68);
    RoundRect(ring, 34, [v colorWithAlphaComponent:light ? 0.12 : 0.18]);
    NSBezierPath *edge = [NSBezierPath bezierPathWithOvalInRect:NSInsetRect(ring, 0.75, 0.75)]; edge.lineWidth = 1.5; [[v colorWithAlphaComponent:0.55] setStroke]; [edge stroke];
    NSImage *lk = Tinted(Symbol(@"lock.fill", 24, NSFontWeightSemibold), light ? Hex(0x4b3db8) : Hex(0xd6cffb));
    DrawImage(lk, CenterIn(lk.size, ring));
    NSMutableParagraphStyle *ps = [NSMutableParagraphStyle new]; ps.alignment = NSTextAlignmentCenter;
    NSUInteger n = PrivateWindows().count;
    [@"Private browsing is locked" drawInRect:NSMakeRect(0, cy - 22 + 10, W, 26)
       withAttributes:@{NSFontAttributeName: TitleFont(20, YES), NSForegroundColorAttributeName: vText, NSParagraphStyleAttributeName: ps}];
    NSString *sub = self.problem ?: [NSString stringWithFormat:@"%lu private window%@ · its pages are hidden and paused", (unsigned long)n, n == 1 ? @"" : @"s"];
    [sub drawInRect:NSMakeRect(0, cy + 14, W, 18) withAttributes:@{NSFontAttributeName: UIFont(12.5, NSFontWeightRegular), NSForegroundColorAttributeName: self.problem ? Hex(0xf08a8a) : vDim, NSParagraphStyleAttributeName: ps}];
    NSRect b = self.buttonRect;
    [NSGraphicsContext saveGraphicsState];
    NSShadow *sh = [NSShadow new]; sh.shadowBlurRadius = 16; sh.shadowOffset = NSZeroSize; sh.shadowColor = [v colorWithAlphaComponent:self.hoverBtn ? 0.55 : 0.35]; [sh set];
    RoundRect(b, NSHeight(b) / 2, self.pressing ? [v blendedColorWithFraction:0.2 ofColor:NSColor.blackColor] : self.hoverBtn ? [v blendedColorWithFraction:0.12 ofColor:NSColor.whiteColor] : v);
    [NSGraphicsContext restoreGraphicsState];
    NSImage *tid = Tinted(Symbol(@"touchid", 14, NSFontWeightMedium), NSColor.whiteColor);
    NSString *label = @"Unlock";
    NSDictionary *la = @{NSFontAttributeName: UIFont(13, NSFontWeightSemibold), NSForegroundColorAttributeName: NSColor.whiteColor};
    NSSize ls = [label sizeWithAttributes:la];
    CGFloat total = (tid ? tid.size.width + 8 : 0) + ls.width, x = NSMidX(b) - total / 2;
    if (tid) { DrawImage(tid, NSMakeRect(x, NSMidY(b) - tid.size.height / 2, tid.size.width, tid.size.height)); x += tid.size.width + 8; }
    [label drawAtPoint:NSMakePoint(x, NSMidY(b) - ls.height / 2) withAttributes:la];
    [@"Return also unlocks" drawInRect:NSMakeRect(0, NSMaxY(b) + 12, W, 16) withAttributes:@{NSFontAttributeName: UIFont(11, NSFontWeightRegular), NSForegroundColorAttributeName: vFaint, NSParagraphStyleAttributeName: ps}];
}
@end

static char kPrivLockViewKey;
// A locked window: its pages hidden (not just covered), playback paused, the cover on top of everything, the tabs closed.
static void PrivateLockWindow(VWindow *w) {
    if (!w.isPrivate || objc_getAssociatedObject(w, &kPrivLockViewKey)) return;
    [w closePanels]; [w showShelf:NO]; [w.suggest dismiss];
    for (VTab *t in w.tabs) if (t.web.web) {
        [t.web.web evaluateJavaScript:@"document.querySelectorAll('video,audio').forEach(m=>{try{m.pause()}catch(e){}})" completionHandler:nil];
        if ([t.web.web respondsToSelector:@selector(pauseAllMediaPlaybackWithCompletionHandler:)]) [t.web.web pauseAllMediaPlaybackWithCompletionHandler:^{}];
    }
    [w.current.web.web closeAllMediaPresentationsWithCompletionHandler:^{}];   // picture in picture and full-screen video too
    w.content.hidden = YES;
    NSView *root = w.window.contentView;
    VPrivateLock *lock = [[VPrivateLock alloc] initWithFrame:root.bounds];
    lock.owner = w; lock.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    [root addSubview:lock positioned:NSWindowAbove relativeTo:nil];
    if (w.lights.superview == root) [root addSubview:w.lights positioned:NSWindowAbove relativeTo:lock];   // close, minimise and zoom stay usable
    objc_setAssociatedObject(w, &kPrivLockViewKey, lock, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    PageHearsMouse(w, NO);
    if (w.window.isKeyWindow) [w.window makeFirstResponder:lock];
}
static void PrivateUnlockWindow(VWindow *w) {
    VPrivateLock *lock = objc_getAssociatedObject(w, &kPrivLockViewKey);
    if (!lock) return;
    [lock removeFromSuperview];
    objc_setAssociatedObject(w, &kPrivLockViewKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    w.content.hidden = NO;
    PageHearsMouse(w, YES);
    [w.window makeFirstResponder:w.current.web.web];
    [w layout];
}
static BOOL PrivateWindowLocked(VWindow *w) { return objc_getAssociatedObject(w, &kPrivLockViewKey) != nil; }

static void PrivateLockAll(NSString *why) {
    NSArray *ws = PrivateWindows();
    if (!ws.count || gPrivLocked) return;
    gPrivLocked = YES;
    for (VWindow *w in ws) PrivateLockWindow(w);
    DLog(@"private: locked (%@)", why);
}
// Touch ID, or your Mac's password when there's no Touch ID; the framework is loaded only when it's needed.
static void PrivateUnlockAll(void) {
    if (!gPrivLocked) return;
    static BOOL asking; if (asking) return;
    void (^open)(void) = ^{ gPrivLocked = NO; for (VWindow *w in PrivateWindows()) PrivateUnlockWindow(w); DLog(@"private: unlocked"); };
    void (^problem)(NSString *) = ^(NSString *s) { for (VWindow *w in PrivateWindows()) { VPrivateLock *l = objc_getAssociatedObject(w, &kPrivLockViewKey); l.problem = s; l.needsDisplay = YES; } };
    dlopen("/System/Library/Frameworks/LocalAuthentication.framework/LocalAuthentication", RTLD_LAZY);
    Class LA = NSClassFromString(@"LAContext");
    id ctx = [LA new];
    const NSInteger kOwnerAuth = 2;   // LAPolicyDeviceOwnerAuthentication: Touch ID, Apple Watch or the password
    NSError *err = nil;
    BOOL can = ctx && ((BOOL (*)(id, SEL, NSInteger, NSError **))objc_msgSend)(ctx, NSSelectorFromString(@"canEvaluatePolicy:error:"), kOwnerAuth, &err);
    if (!can) { DLog(@"private: no way to ask who you are (%@), opening", err.localizedDescription); open(); return; }   // a Mac with no password set
    asking = YES;
    ((void (*)(id, SEL, NSInteger, NSString *, void (^)(BOOL, NSError *)))objc_msgSend)(ctx, NSSelectorFromString(@"evaluatePolicy:localizedReason:reply:"), kOwnerAuth,
        @"show your private windows", ^(BOOL ok, NSError *e) {
            dispatch_async(dispatch_get_main_queue(), ^{
                asking = NO;
                if (ok) open();
                else if (e.code != -2 && e.code != -4) problem(@"That didn't match. Try again.");   // -2 you cancelled, -4 the system did
            });
        });
}

// Locking when the Mac locks or sleeps, and after the time away you chose
static void PrivateAwayChanged(BOOL away) {
    [gPrivAwayTimer invalidate]; gPrivAwayTimer = nil;
    NSInteger mode = [Defaults() integerForKey:kPrivLock];
    if (!away || mode < 2 || !PrivateWindows().count) return;
    NSTimeInterval after = mode == 2 ? 60 : mode == 3 ? 300 : 900;
    gPrivAwayTimer = [NSTimer scheduledTimerWithTimeInterval:after repeats:NO block:^(NSTimer *t) { gPrivAwayTimer = nil; if (!NSApp.isActive) PrivateLockAll(@"away"); }];
}
static void PrivateWatch(void) {
    static BOOL on; if (on) return; on = YES;
    void (^mac)(NSNotification *) = ^(NSNotification *n) { if ([Defaults() integerForKey:kPrivLock] > 0) PrivateLockAll(@"Mac locked or asleep"); };
    [NSDistributedNotificationCenter.defaultCenter addObserverForName:@"com.apple.screenIsLocked" object:nil queue:NSOperationQueue.mainQueue usingBlock:mac];
    [NSWorkspace.sharedWorkspace.notificationCenter addObserverForName:NSWorkspaceScreensDidSleepNotification object:nil queue:NSOperationQueue.mainQueue usingBlock:mac];
    [NSWorkspace.sharedWorkspace.notificationCenter addObserverForName:NSWorkspaceWillSleepNotification object:nil queue:NSOperationQueue.mainQueue usingBlock:mac];
    [NSWorkspace.sharedWorkspace.notificationCenter addObserverForName:NSWorkspaceSessionDidResignActiveNotification object:nil queue:NSOperationQueue.mainQueue usingBlock:mac];   // switched to another user
    [NSNotificationCenter.defaultCenter addObserverForName:NSApplicationDidResignActiveNotification object:nil queue:NSOperationQueue.mainQueue usingBlock:^(NSNotification *n) { PrivateAwayChanged(YES); }];
    [NSNotificationCenter.defaultCenter addObserverForName:NSApplicationDidBecomeActiveNotification object:nil queue:NSOperationQueue.mainQueue usingBlock:^(NSNotification *n) { PrivateAwayChanged(NO); }];
}

// A private window opening: nothing of it goes into macOS's own window restoration, it can be left out of screenshots,
// and if the others are locked it starts locked too.
static void PrivateWindowOpened(VWindow *w) {
    if (!w.isPrivate) return;
    PrivateWatch();
    w.window.restorable = NO;
    if ([Defaults() boolForKey:kPrivHide]) w.window.sharingType = NSWindowSharingNone;
    if (gPrivLocked) PrivateLockWindow(w);
}
// The last private window closing: what was decided in them goes, the lock resets.
static void PrivateWindowClosed(VWindow *w) {
    if (!w.isPrivate) return;
    for (VWindow *x in gWindows) if (x != w && x.isPrivate) return;
    gPrivSite = nil;
    gPrivLocked = NO;
    [gPrivAwayTimer invalidate]; gPrivAwayTimer = nil;
    DLog(@"private: last window closed, nothing kept");
}
static void PrivateApplyCaptureSetting(void) {
    for (VWindow *w in PrivateWindows()) w.window.sharingType = [Defaults() boolForKey:kPrivHide] ? NSWindowSharingNone : NSWindowSharingReadOnly;
}

@implementation VWindow (Private)
- (void)lockPrivateWindows:(id)s {
    if (!PrivateWindows().count) { [self showToast:@"No private windows are open"]; return; }
    PrivateLockAll(@"you asked");
}
@end
#pragma mark - Test harness: commands from control.txt, screenshots into shots/

// Development aid. Write lines to control.txt beside Iris.app; each runs once, in order:
//   open URL | tab URL | select N | close | back | forward | reload | scroll DY | top | find TEXT
//   zoom Z | block on|off | wait SECONDS | shot NAME | source NAME | js EXPR | status | size W H
//   window (a fresh window runs the rest) | win N | closewindow | bookmarksbar on|off | sidebar WIDTH
// Results and status lines are appended to control.out.

@interface VWindow (Control)
- (void)startControl;
@end

@implementation VWindow (Control)

static NSString *CtlDir(void) { return NSBundle.mainBundle.bundlePath.stringByDeletingLastPathComponent; }

static void CtlOut(NSString *s) {
    if (!s) return;
    NSString *p = [CtlDir() stringByAppendingPathComponent:@"control.out"];
    NSString *line = [s stringByAppendingString:@"\n"];
    dispatch_async(DevQueue(), ^{   // off the main thread: a macOS folder-access prompt must never freeze the browser
        NSFileHandle *h = [NSFileHandle fileHandleForWritingAtPath:p];
        if (!h) { [line writeToFile:p atomically:NO encoding:NSUTF8StringEncoding error:nil]; return; }
        [h seekToEndOfFile]; [h writeData:[line dataUsingEncoding:NSUTF8StringEncoding]]; [h closeFile];
    });
}

- (void)startControl {
    // with Iris Dev beside it, only Iris Dev answers control.txt: tests never touch the Iris you browse with
    if (!IrisIsDev() && [NSFileManager.defaultManager fileExistsAtPath:[CtlDir() stringByAppendingPathComponent:@"Iris Dev.app"]]) return;
    static NSDate *seen;
    NSString *p = [CtlDir() stringByAppendingPathComponent:@"control.txt"];
    static BOOL busy;
    [NSTimer scheduledTimerWithTimeInterval:1.5 repeats:YES block:^(NSTimer *t) {
        if (busy) return;
        busy = YES;
        dispatch_async(DevQueue(), ^{   // the file is read in the background; commands run on the main thread
            NSDate *m = [[NSFileManager.defaultManager attributesOfItemAtPath:p error:nil] fileModificationDate];
            NSString *text = nil; BOOL run = NO;
            if (m && ![m isEqualToDate:seen]) {
                BOOL first = seen == nil; seen = m;
                run = !(first && -[m timeIntervalSinceNow] > 5);   // stale file from an earlier run
                if (run) text = [NSString stringWithContentsOfFile:p encoding:NSUTF8StringEncoding error:nil];
            }
            dispatch_async(dispatch_get_main_queue(), ^{
                busy = NO;
                if (!run) return;
                NSMutableArray *lines = [NSMutableArray array];
                for (NSString *l in [text componentsSeparatedByString:@"\n"]) { NSString *x = [l stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet]; if (x.length) [lines addObject:x]; }
                [self runControl:lines];
            });
        });
    }];
}

- (void)runControl:(NSMutableArray *)lines {
    while (lines.count) {
        NSString *l = lines.firstObject; [lines removeObjectAtIndex:0];
        NSRange sp = [l rangeOfString:@" "];
        NSString *cmd = sp.location == NSNotFound ? l : [l substringToIndex:sp.location];
        NSString *arg = sp.location == NSNotFound ? @"" : [l substringFromIndex:sp.location + 1];
        VPage *w = self.current.web;
        if ([cmd isEqualToString:@"wait"]) {
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(arg.doubleValue * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{ [self runControl:lines]; });
            return;
        }
        else if ([cmd isEqualToString:@"open"]) [self go:arg];
        else if ([cmd isEqualToString:@"tab"]) [self newTab:URLFromInput(arg) select:YES];
        else if ([cmd isEqualToString:@"select"]) { NSInteger i = arg.integerValue; if (i >= 0 && i < (NSInteger)self.tabs.count) [self selectTab:self.tabs[i]]; }
        else if ([cmd isEqualToString:@"close"]) { if (self.current) [self closeTab:self.current]; }
        else if ([cmd isEqualToString:@"back"]) [w goBack];
        else if ([cmd isEqualToString:@"forward"]) [w goForward];
        else if ([cmd isEqualToString:@"reload"]) [w reload];
        else if ([cmd isEqualToString:@"scroll"]) [w runJS:[NSString stringWithFormat:@"window.scrollBy(0,%f)", arg.doubleValue]];
        else if ([cmd isEqualToString:@"top"]) [w runJS:@"window.scrollTo(0,0)"];
        else if ([cmd isEqualToString:@"act"] && [@[@"toggleSplit:", @"swapSplit:", @"toggleReader:", @"showFind:", @"closePeek:", @"toggleSidebar:", @"toggleLens:", @"toggleShieldPanel:", @"toggleSitePanel:", @"closePanels", @"showToolbarCustomiser:", @"closeToolbarCustomiser", @"installWebApp:"] containsObject:arg]) {
            [NSApp sendAction:NSSelectorFromString(arg) to:self from:nil];
            CtlOut([NSString stringWithFormat:@"act %@ split=%lu", arg, (unsigned long)self.splitPair.count]);
        }
        else if ([cmd isEqualToString:@"privwindow"]) {   // dev: a fresh private window; the rest of the commands run in it
            VWindow *nw = [[VWindow alloc] initPrivate:YES state:@{}]; [nw showWindow:nil]; [nw windowDidResize:nil];
            [nw.window makeKeyAndOrderFront:nil];
            CtlOut(@"private window opened");
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 600 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ [nw runControl:lines]; });
            return;
        }
        else if ([cmd isEqualToString:@"privlock"]) PrivateLockAll(@"test");
        else if ([cmd isEqualToString:@"privstate"]) CtlOut([NSString stringWithFormat:@"privstate locked=%d thisLocked=%d private=%d remembered=%@ restorable=%d sharing=%ld", gPrivLocked, PrivateWindowLocked(self), self.isPrivate, [gPrivSite.allKeys componentsJoinedByString:@","] ?: @"-", self.window.restorable, (long)self.window.sharingType]);
        else if ([cmd isEqualToString:@"window"]) {   // a fresh window; the rest of the commands run in it
            VWindow *nw = [[VWindow alloc] initPrivate:NO state:@{}]; [nw showWindow:nil]; [nw windowDidResize:nil];
            [nw.window makeKeyAndOrderFront:nil];
            CtlOut(@"window opened");
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 600 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ [nw runControl:lines]; });
            return;
        }
        else if ([cmd isEqualToString:@"size"]) {   // dev: "size 1440 900" for screenshots of a known size
            NSArray *wh = [arg componentsSeparatedByString:@" "];
            if (wh.count == 2) { NSRect f = self.window.frame; CGFloat h = [wh[1] doubleValue]; [self.window setFrame:NSMakeRect(NSMinX(f), NSMaxY(f) - h, [wh[0] doubleValue], h) display:YES]; }
            CtlOut([NSString stringWithFormat:@"size %@", NSStringFromSize(self.window.frame.size)]);
        }
        else if ([cmd isEqualToString:@"closewindow"]) { if (gWindows.count > 1) { CtlOut(@"window closed"); [self.window performClose:nil]; CtlOut(@"done"); return; } }
        else if ([cmd isEqualToString:@"win"]) {   // the rest of the commands run in window N (oldest first)
            NSInteger i = arg.integerValue;
            if (i >= 0 && i < (NSInteger)gWindows.count) { VWindow *x = gWindows[i]; CtlOut([NSString stringWithFormat:@"win %ld of %lu", (long)i, (unsigned long)gWindows.count]); [x runControl:lines]; return; }
        }
        else if ([cmd isEqualToString:@"sidebar"]) { CGFloat wdt = arg.doubleValue; if (wdt >= 40 && wdt <= 420) { [Defaults() setDouble:wdt forKey:kSidebarW]; RelayoutAll(); } CtlOut([NSString stringWithFormat:@"sidebar %.0f", SidebarWidth()]); }
        else if ([cmd isEqualToString:@"bookmarksbar"]) { [Defaults() setBool:[arg isEqualToString:@"on"] forKey:kShowBookmarks]; RelayoutAll(); }
        else if ([cmd isEqualToString:@"extinstall"]) {   // a Chrome Web Store link or extension id (takes effect at the next launch)
            [FExtHost.shared installFromWebStore:arg done:^(NSString *name, NSString *err) { CtlOut([NSString stringWithFormat:@"extinstall %@ %@", name ?: @"-", err ?: @"ok"]); }];
        }
        else if ([cmd isEqualToString:@"rules"]) {
            for (NSString *k in gExtRuleLists) CtlOut([NSString stringWithFormat:@"rules %@: %lu lists", k, (unsigned long)gExtRuleLists[k].count]);
            CtlOut([NSString stringWithFormat:@"rules gUCC total lists attached: (blocker %lu)", (unsigned long)gRules.count]);
        }
        else if ([cmd isEqualToString:@"media"]) {
            for (VTab *t in self.tabs) CtlOut([NSString stringWithFormat:@"media tab=%@ key=%@ time=%.0f saved=%.0f resume=%.0f web=%d", t.url ?: @"-", t.mediaKey ?: @"-", t.mediaTime, t.savedMedia, t.resumeAt, t.web != nil]);
            for (NSDictionary *d in [Defaults() dictionaryForKey:kTabsState][@"tabs"]) CtlOut([NSString stringWithFormat:@"media saved url=%@ key=%@ time=%@", d[@"url"], d[@"mediaKey"] ?: @"-", d[@"mediaTime"] ?: @"-"]);
        }
        else if ([cmd isEqualToString:@"find"]) [w find:arg forward:YES next:NO];
        else if ([cmd isEqualToString:@"shelf"]) {   // dev: tabs out (and held) or away, for screenshots
            if ([arg isEqualToString:@"on"]) { [self showShelf:YES]; ((VTabShelf *)self.shelf).sticky = YES; } else [self showShelf:NO];
        }
        else if ([cmd isEqualToString:@"side"]) {   // dev: where the tabs live, 0 bottom, 1 left, 2 right
            [Defaults() setInteger:MAX(0, MIN(2, arg.integerValue)) forKey:kShelfSide];
            for (VWindow *x in gWindows) { [x showShelf:NO]; [(VTabShelf *)x.shelf reload]; [x layout]; x.shelfHandle.needsDisplay = YES; [x.shelfHandle updateTrackingAreas]; }
        }
        else if ([cmd isEqualToString:@"ringshot"]) {   // dev: the downloads ring at a value, drawn large to shots/ring.png
            VRing *r = [[VRing alloc] initWithFrame:NSMakeRect(0, 0, 30, 28)]; r.value = arg.doubleValue;
            NSImage *im = [NSImage imageWithSize:NSMakeSize(120, 112) flipped:NO drawingHandler:^BOOL(NSRect rr) {
                [vBg setFill]; NSRectFill(rr);
                NSAffineTransform *t = [NSAffineTransform transform]; [t scaleBy:4]; [t concat]; [r drawRect:r.bounds]; return YES; }];
            NSString *dir = [CtlDir() stringByAppendingPathComponent:@"shots"];
            [NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];
            NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithData:im.TIFFRepresentation];
            [[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}] writeToFile:[dir stringByAppendingPathComponent:@"ring.png"] atomically:YES];
            CtlOut(@"ringshot");
        }
        else if ([cmd isEqualToString:@"czdrag"] || [cmd isEqualToString:@"czclick"]) {   // dev: real mouse events into Customise Toolbar, "czdrag SRC|DST" by CSS selector
            NSView *dim = objc_getAssociatedObject(self, &kCustomiserKey);
            WKWebView *v = (WKWebView *)[[dim.subviews.firstObject subviews] firstObject];
            NSArray *sel = [arg componentsSeparatedByString:@"|"];
            NSString *(^JSONString)(NSString *) = ^NSString *(NSString *x) { NSString *j = [[NSString alloc] initWithData:[NSJSONSerialization dataWithJSONObject:@[x] options:0 error:nil] encoding:NSUTF8StringEncoding]; return [j substringWithRange:NSMakeRange(1, j.length - 2)]; };
            NSString *js = [NSString stringWithFormat:@"(()=>{const r=s=>{const e=document.querySelector(s);if(!e)return null;const b=e.getBoundingClientRect();return [b.left+b.width/2,b.top+b.height/2]};return JSON.stringify([r(%@),r(%@)])})()",
                            JSONString(sel.firstObject ?: @""), JSONString(sel.lastObject ?: @"")];
            BOOL click = [cmd isEqualToString:@"czclick"];
            [v evaluateJavaScript:js completionHandler:^(id res, NSError *err) {
                NSArray *pts = [res isKindOfClass:NSString.class] ? [NSJSONSerialization JSONObjectWithData:[res dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil] : nil;
                if (pts.count != 2 || [pts[0] isKindOfClass:NSNull.class] || [pts[1] isKindOfClass:NSNull.class]) { CtlOut([NSString stringWithFormat:@"%@ missing %@", cmd, res]); return; }
                NSPoint (^win)(NSArray *) = ^NSPoint(NSArray *q) { return [v convertPoint:NSMakePoint([q[0] doubleValue], [q[1] doubleValue]) toView:nil]; };
                NSPoint a = win(pts[0]), b = win(pts[1]); NSInteger wn = self.window.windowNumber;
                NSEvent *(^ev)(NSEventType, NSPoint) = ^NSEvent *(NSEventType t, NSPoint p) {
                    return [NSEvent mouseEventWithType:t location:p modifierFlags:0 timestamp:NSProcessInfo.processInfo.systemUptime windowNumber:wn context:nil eventNumber:0 clickCount:1 pressure:t == NSEventTypeLeftMouseUp ? 0 : 1];
                };
                [self.window sendEvent:ev(NSEventTypeLeftMouseDown, a)];
                __block int i = 0; int steps = click ? 0 : 12;
                __block void (^step)(void);
                step = ^{
                    if (i < steps) { i++; CGFloat f = (CGFloat)i / steps; [self.window sendEvent:ev(NSEventTypeLeftMouseDragged, NSMakePoint(a.x + (b.x - a.x) * f, a.y + (b.y - a.y) * f))];
                        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 30 * NSEC_PER_MSEC), dispatch_get_main_queue(), step); return; }
                    [self.window sendEvent:ev(NSEventTypeLeftMouseUp, click ? a : b)];
                    CtlOut([NSString stringWithFormat:@"%@ %@ -> %@", cmd, NSStringFromPoint(a), NSStringFromPoint(b)]);
                    step = nil;
                };
                dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 40 * NSEC_PER_MSEC), dispatch_get_main_queue(), step);
            }];
        }
        else if ([cmd isEqualToString:@"czjs"]) {   // dev: run script in the Customise Toolbar page
            NSView *dim = objc_getAssociatedObject(self, &kCustomiserKey);
            WKWebView *v = (WKWebView *)[[dim.subviews.firstObject subviews] firstObject];
            if ([v isKindOfClass:WKWebView.class]) [v evaluateJavaScript:arg completionHandler:^(id r, NSError *e) { CtlOut([NSString stringWithFormat:@"czjs %@", e ? e.localizedDescription : r]); }];
            else CtlOut(@"czjs no customiser");
        }
        else if ([cmd isEqualToString:@"tbstate"]) {   // dev: the toolbar's arrangement and what shows now
            NSMutableArray *live = [NSMutableArray array];
            for (NSString *k in self.toolbar.keyed) { VButton *b = self.toolbar.keyed[k]; if (!b.hidden) [live addObject:[NSString stringWithFormat:@"%@%@", k, b.symbolName && !Symbol(b.symbolName, 13, NSFontWeightMedium) ? @"(no symbol)" : @""]]; }
            CtlOut([NSString stringWithFormat:@"tbstate layout=%@ installable=%d shown=%@", [IrisJSON(ToolbarLayout()) stringByReplacingOccurrencesOfString:@"\n" withString:@""], self.current.installable, [live componentsJoinedByString:@","]]);
        }
        else if ([cmd isEqualToString:@"mouse"]) {   // dev: who has the pointer: muting, panels, and the view under it in every window
            NSMutableArray *o = [NSMutableArray array];
            SEL g = NSSelectorFromString(@"_ignoresMouseMoveEvents"), g2 = NSSelectorFromString(@"_ignoresNonWheelEvents");
            for (VWindow *w in gWindows) {
                NSView *root = w.window.contentView;
                NSPoint p = [root.superview ?: root convertPoint:[w.window convertPointFromScreen:NSEvent.mouseLocation] fromView:nil];
                NSView *hv = [root hitTest:p];
                NSMutableArray *ig = [NSMutableArray array];
                for (VTab *t in w.tabs) if (t.web.web) { WKWebView *v = t.web.web;
                    BOOL a = [v respondsToSelector:g] ? ((BOOL (*)(id, SEL))objc_msgSend)(v, g) : 0, b = [v respondsToSelector:g2] ? ((BOOL (*)(id, SEL))objc_msgSend)(v, g2) : 0;
                    if (a || b) [ig addObject:[NSString stringWithFormat:@"%@%@%@", t == w.current ? @"*" : @"", a ? @"M" : @"", b ? @"N" : @""]]; }
                [o addObject:[NSString stringWithFormat:@"[%@ key=%d muted=%d panel=%d cz=%d under=%@ ignoring=%@]", NSStringFromRect(w.window.frame), w.window.isKeyWindow, gMuted == w, [w panelOpen], objc_getAssociatedObject(w, &kCustomiserKey) != nil, NSStringFromClass(hv.class), ig]];
            }
            NSCursor *c = NSCursor.currentCursor;
            NSString *cn = c == NSCursor.arrowCursor ? @"arrow" : c == NSCursor.pointingHandCursor ? @"hand" : c == NSCursor.IBeamCursor ? @"ibeam" : c ? [NSString stringWithFormat:@"other(%@)", NSStringFromPoint(c.hotSpot)] : @"nil";
            CtlOut([NSString stringWithFormat:@"mouse at %@ active=%d cursor=%@ appkitHook=%d %@", NSStringFromPoint(NSEvent.mouseLocation), NSApp.isActive, cn, [NSWindow instancesRespondToSelector:NSSelectorFromString(@"_setCursorForMouseLocation:")], [o componentsJoinedByString:@" "]]);
        }
        else if ([cmd isEqualToString:@"profiletest"]) {   // dev: make, open or remove a throwaway profile app ("Iris Test")
            NSString *pid = @"0000test-dev0-0000-0000-000000000000";
            if ([arg isEqualToString:@"remove"]) { ProfileAppUninstall(pid); CtlOut(@"profiletest removing"); }
            else {
                NSString *dest = [ProfileAppsDir() stringByAppendingPathComponent:@"Iris Test.app"];
                NSString *fail = WriteShimApp(dest, ProfileInfoPlist(pid, @"Test", 3), @"IrisProfile", ProfileAppIcon(pid, @"Test", 3));
                NSDictionary *info = [NSDictionary dictionaryWithContentsOfFile:[dest stringByAppendingPathComponent:@"Contents/Info.plist"]];
                CtlOut([NSString stringWithFormat:@"profiletest made=%@ id=%@ exe=%d", fail ?: @"ok", info[@"CFBundleIdentifier"], [NSFileManager.defaultManager isExecutableFileAtPath:[dest stringByAppendingPathComponent:@"Contents/MacOS/IrisProfile"]]]);
                if (!fail) [NSWorkspace.sharedWorkspace openApplicationAtURL:[NSURL fileURLWithPath:dest] configuration:[NSWorkspaceOpenConfiguration configuration] completionHandler:nil];
            }
        }
        else if ([cmd isEqualToString:@"toast"]) [self showToast:arg];   // dev: "toast Filter lists updated"
        else if ([cmd isEqualToString:@"cursorguard"]) gCursorGuardOff = !arg.boolValue;
        else if ([cmd isEqualToString:@"linkflash"]) { for (int i = 0; i < 3; i++) { [self showLink:@"https://example.com/flash"]; [self showLink:@""]; } [self showLink:@"https://example.com/flash"]; }
        else if ([cmd isEqualToString:@"slowmo"])gSlowMo = MAX(1, MIN(20, arg.doubleValue));   // dev: "slowmo 8" stretches panel animations, "slowmo 1" back
        else if ([cmd isEqualToString:@"hover"]) { VButton *b = self.toolbar.menuBtn; b.hovered = [arg isEqualToString:@"lens"]; b.needsDisplay = YES; }   // dev: Lens as if under the pointer
        else if ([cmd isEqualToString:@"loadline"]) {   // dev: hold the loading line at a point ("loadline 0.55"), or "loadline off"
            VLoadLine *ll = (VLoadLine *)self.loadLine;
            if ([arg isEqualToString:@"off"]) [ll loading:NO progress:1]; else [ll loading:YES progress:arg.doubleValue];
        }
        else if ([cmd isEqualToString:@"zoom"]) [w setZoomLevel:arg.doubleValue];
        else if ([cmd isEqualToString:@"block"]) { BOOL on = [arg isEqualToString:@"on"]; if (on != [Defaults() boolForKey:kBlock]) [self performSelector:@selector(toggleBlockingGlobal:) withObject:nil]; }
        else if ([cmd isEqualToString:@"size"]) { NSArray *a = [arg componentsSeparatedByString:@" "]; if (a.count == 2) { NSRect f = self.window.frame; f.size = NSMakeSize([a[0] doubleValue], [a[1] doubleValue]); [self.window setFrame:f display:YES]; } }
        else if ([cmd isEqualToString:@"procs"]) {   // engine process per tab / extension background, to match CPU samples
            SEL pidSel = NSSelectorFromString(@"_webProcessIdentifier");
            pid_t (^pidOf)(WKWebView *) = ^pid_t(WKWebView *v) { return v && [v respondsToSelector:pidSel] ? ((pid_t (*)(id, SEL))objc_msgSend)(v, pidSel) : 0; };
            NSMutableString *o = [NSMutableString stringWithFormat:@"procs iris=%d throttleHard=%d battery=%d\n", getpid(), ThrottleHard(), OnBattery()];
            for (VTab *t in AllTabs(YES)) if (t.web) [o appendFormat:@"  tab pid=%d %@\n", pidOf(t.web.web), HostOf([NSURL URLWithString:t.url ?: @""])];
            for (FExt *e in FExtHost.shared.extensions) if ([e isKindOfClass:FExt.class] && e.background) [o appendFormat:@"  ext pid=%d %@\n", pidOf(e.background), e.name];
            CtlOut(o);
        }
        else if ([cmd isEqualToString:@"status"]) {
            CtlOut([NSString stringWithFormat:@"status tabs=%lu cur=%lu url=%@ title=%@ loading=%d progress=%.2f blocked=%ld rules=%lu extensions=%d side=%.0f split=%lu",
                    (unsigned long)self.tabs.count, (unsigned long)[self.tabs indexOfObject:self.current], w.url, w.title, w.loading, w.progress, (long)w.blocked,
                    (unsigned long)gRuleCount, (int)FExtHost.shared.extensions.count, NSWidth(self.sideScroll.frame), (unsigned long)self.splitPair.count]);
            NSView *hd = [self valueForKey:@"sideHandle"]; NSRect hr = [self.window convertRectToScreen:[hd convertRect:hd.bounds toView:nil]];
            CtlOut([NSString stringWithFormat:@"handle screen x=%.0f..%.0f y=%.0f..%.0f (top-left origin, screen h=%.0f) superview=%@ hidden=%d", NSMinX(hr), NSMaxX(hr), NSScreen.mainScreen.frame.size.height - NSMaxY(hr), NSScreen.mainScreen.frame.size.height - NSMinY(hr), NSScreen.mainScreen.frame.size.height, NSStringFromClass(hd.superview.class), hd.hidden]);
        }
        else if ([cmd isEqualToString:@"js"]) [w runJS:arg];
        else if ([cmd isEqualToString:@"geo"]) {   // dev: ask the page for a position and report what happens
            Class cl = NSClassFromString(@"CLLocationManager");
            int st = cl && [cl respondsToSelector:@selector(authorizationStatus)] ? ((int (*)(id, SEL))objc_msgSend)(cl, @selector(authorizationStatus)) : -1;
            BOOL on = cl && [cl respondsToSelector:@selector(locationServicesEnabled)] ? ((BOOL (*)(id, SEL))objc_msgSend)(cl, @selector(locationServicesEnabled)) : NO;
            CtlOut([NSString stringWithFormat:@"geo macOS status=%d services=%d", st, on]);
            [w.web callAsyncJavaScript:@"return await new Promise(r=>{if(!navigator.geolocation)return r('no api');navigator.geolocation.getCurrentPosition(p=>r('ok '+p.coords.latitude.toFixed(2)+','+p.coords.longitude.toFixed(2)),e=>r('error '+e.code+' '+e.message),{timeout:15000})})"
                             arguments:@{} inFrame:nil inContentWorld:WKContentWorld.pageWorld completionHandler:^(id r, NSError *e) { CtlOut([NSString stringWithFormat:@"geo page: %@ %@", r ?: @"-", e.localizedDescription ?: @""]); }];
        }
        else if ([cmd isEqualToString:@"extcopy"] && arg.length && ![arg containsString:@"/"] && ![arg hasPrefix:@"."]) {   // dev: copy an installed extension out for inspection
            NSString *src = [ExtRoot() stringByAppendingPathComponent:arg], *dst = [[CtlDir() stringByAppendingPathComponent:@"ext-debug"] stringByAppendingPathComponent:arg];
            [NSFileManager.defaultManager createDirectoryAtPath:dst.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil];
            [NSFileManager.defaultManager removeItemAtPath:dst error:nil];
            NSError *err = nil; [NSFileManager.defaultManager copyItemAtPath:src toPath:dst error:&err];
            CtlOut([NSString stringWithFormat:@"extcopy %@ %@", arg, err ? err.localizedDescription : @"ok"]);
        }
        else if ([cmd isEqualToString:@"extlist"]) CtlOut([@"extlist " stringByAppendingString:[[NSFileManager.defaultManager contentsOfDirectoryAtPath:ExtRoot() error:nil] componentsJoinedByString:@" "]]);
        else if ([cmd isEqualToString:@"popup"]) [FExtHost.shared openPopup:nil from:nil];
        else if ([cmd isEqualToString:@"isojs"]) {   // the first extension's content-script world, in this tab
            FExt *e = FExtHost.shared.extensions.firstObject;
            [w.web callAsyncJavaScript:[NSString stringWithFormat:@"const r = await (%@); return typeof r === 'object' ? JSON.stringify(r) : String(r);", arg] arguments:@{} inFrame:nil inContentWorld:e.world
                     completionHandler:^(id r, NSError *err) { CtlOut([NSString stringWithFormat:@"isojs %@", err ? (err.userInfo[@"WKJavaScriptExceptionMessage"] ?: err.localizedDescription) : r]); }];
        }
        else if ([cmd isEqualToString:@"popupjs"] || [cmd isEqualToString:@"bgjs"]) [FExtHost.shared evalIn:[cmd substringToIndex:cmd.length - 2] code:arg];
        else if ([cmd isEqualToString:@"source"]) {
            NSString *name = arg.length ? arg : @"source.html";
            [w source:^(NSString *d) {
                NSString *dir = [CtlDir() stringByAppendingPathComponent:@"shots"];
                [NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];
                [d writeToFile:[dir stringByAppendingPathComponent:name] atomically:YES encoding:NSUTF8StringEncoding error:nil];
                CtlOut([NSString stringWithFormat:@"source %@ (%lu chars)", name, (unsigned long)d.length]);
            }];
        }
        else if ([cmd isEqualToString:@"shot"]) {
            // the whole window as the screen shows it, Chromium's layers included
            typedef CGImageRef (*Grab)(CGRect, uint32_t, uint32_t, uint32_t);
            Grab grab = (Grab)dlsym(RTLD_DEFAULT, "CGWindowListCreateImage");
            NSBitmapImageRep *rep = nil;
            if (grab) { CGImageRef img = grab(CGRectNull, 8 /* including window */, (uint32_t)self.window.windowNumber, 1 /* ignore framing */); if (img) { rep = [[NSBitmapImageRep alloc] initWithCGImage:img]; CGImageRelease(img); } }
            if (!rep) {
                NSView *v = self.window.contentView.superview ?: self.window.contentView;
                rep = [v bitmapImageRepForCachingDisplayInRect:v.bounds];
                [v cacheDisplayInRect:v.bounds toBitmapImageRep:rep];
            }
            NSString *dir = [CtlDir() stringByAppendingPathComponent:@"shots"];
            [NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];
            NSString *f = [dir stringByAppendingPathComponent:[(arg.length ? arg : @"shot") stringByAppendingPathExtension:@"png"]];
            [[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}] writeToFile:f atomically:YES];
            CtlOut([NSString stringWithFormat:@"shot %@", f.lastPathComponent]);
        }
        else CtlOut([@"unknown " stringByAppendingString:l]);
    }
    CtlOut(@"done");
}

@end

#pragma mark - Crash and trouble reports: Iris's own, never Apple's crash reporter

// When Iris crashes it writes its own report and exits quietly, so macOS's crash reporter never sees it (no dialog,
// nothing sent to Apple). Reports go to crashes/ beside Iris.app while developing (where they can be read and
// worked on), otherwise to ~/Library/Logs/Iris. Each one says what failed and where (signal or exception, the
// call stack), what Iris was doing (tabs, what was playing, Picture in Picture, memory in use), and, added on the
// next launch, the last lines of the debug log. Non-fatal trouble goes to the same folder's events.log: a page's
// engine dying, macOS warning about memory, and what Iris did about it.
//
// A crashing process can't safely allocate or call Objective-C, so everything the signal handler writes is
// prepared in fixed buffers beforehand and refreshed every few seconds.

#include <execinfo.h>
#include <mach/mach.h>
#include <sys/stat.h>

static char gCrashDir[1024];         // where reports go
static char gCrashCtx[4096];         // "what Iris was doing", refreshed every 5 seconds
static volatile sig_atomic_t gCrashing;
static NSTimeInterval gLaunchedAt;

static NSString *CrashDir(void) {
    static NSString *d;
    if (d) return d;
    NSString *dev = [NSBundle.mainBundle.bundlePath.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"crashes"];
    BOOL devFolder = [NSFileManager.defaultManager fileExistsAtPath:[NSBundle.mainBundle.bundlePath.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"Iris.m"]];
    d = devFolder ? dev : [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Logs/Iris"];
    [NSFileManager.defaultManager createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil];
    return d;
}
static double FootprintMB(void) {
    task_vm_info_data_t info; mach_msg_type_number_t n = TASK_VM_INFO_COUNT;
    return task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&info, &n) == KERN_SUCCESS ? info.phys_footprint / 1048576.0 : 0;
}
static NSString *CrashContext(void) {
    NSMutableString *s = [NSMutableString string];
    NSDictionary *b = NSBundle.mainBundle.infoDictionary;
    NSDictionary *exe = [NSFileManager.defaultManager attributesOfItemAtPath:NSBundle.mainBundle.executablePath error:nil];
    [s appendFormat:@"Iris %@ (%@), built %@\n", b[@"CFBundleShortVersionString"] ?: @"?", b[@"CFBundleVersion"] ?: @"?", exe.fileModificationDate ?: @"?"];
    [s appendFormat:@"macOS %@ · %ld threads of %ld cores · %.0f GB memory\n", NSProcessInfo.processInfo.operatingSystemVersionString,
        (long)NSProcessInfo.processInfo.activeProcessorCount, (long)NSProcessInfo.processInfo.processorCount, NSProcessInfo.processInfo.physicalMemory / 1073741824.0];
    [s appendFormat:@"Iris's own memory: %.0f MB · up %.0f min · theme %ld · blocking %@ · holding back background tabs %@\n", FootprintMB(),
        (NSDate.date.timeIntervalSince1970 - gLaunchedAt) / 60,
        (long)[Defaults() integerForKey:kTheme], [Defaults() boolForKey:kBlock] ? @"on" : @"off", [Defaults() boolForKey:kThrottleOn] ? @"on" : @"off"];
    NSUInteger tabs = 0, awake = 0; NSMutableArray *notes = [NSMutableArray array];
    for (VWindow *w in gWindows) for (VTab *t in w.tabs) {
        tabs++; if (t.web) awake++;
        NSString *h = HostOf([NSURL URLWithString:t.url ?: @""]);
        NSMutableArray *f = [NSMutableArray array];
        if (t == w.current) [f addObject:@"current"];
        if (t.audible) [f addObject:@"playing"];
        if (t.inPiP) [f addObject:@"picture-in-picture"];
        if (t.loading) [f addObject:@"loading"];
        if (f.count) [notes addObject:[NSString stringWithFormat:@"%@ (%@)", h.length ? h : @"new tab", [f componentsJoinedByString:@", "]]];
    }
    [s appendFormat:@"%lu windows · %lu tabs, %lu awake%@%@\n", (unsigned long)gWindows.count, (unsigned long)tabs, (unsigned long)awake,
        notes.count ? @" · " : @"", [notes componentsJoinedByString:@" · "]];
    return s;
}
static void CrashRefreshContext(void) {
    NSString *c = CrashContext();
    strlcpy(gCrashCtx, c.UTF8String ?: "", sizeof gCrashCtx);
}

// async-signal-safe little helpers
static void CW(int fd, const char *s) { if (s) write(fd, s, strlen(s)); }
static void CWNum(int fd, long v) {
    char b[24]; int i = 23; b[i] = 0; BOOL neg = v < 0; unsigned long u = neg ? -(unsigned long)v : (unsigned long)v;
    do { b[--i] = '0' + u % 10; u /= 10; } while (u && i > 0);
    if (neg && i > 0) b[--i] = '-';
    CW(fd, b + i);
}
static int CrashOpen(char *path, size_t cap) {
    // crashes/crash-<unix time>.txt, and a "pending" marker so the next launch can add the log and say so
    strlcpy(path, gCrashDir, cap); strlcat(path, "/crash-", cap);
    char t[24]; int i = 23; t[i] = 0; unsigned long u = (unsigned long)time(NULL); do { t[--i] = '0' + u % 10; u /= 10; } while (u && i > 0);
    strlcat(path, t + i, cap); strlcat(path, ".txt", cap);
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    char marker[1100]; strlcpy(marker, gCrashDir, sizeof marker); strlcat(marker, "/pending", sizeof marker);
    int m = open(marker, O_WRONLY | O_CREAT | O_TRUNC, 0644); if (m >= 0) { CW(m, path); close(m); }
    return fd;
}

static void CrashSignal(int sig, siginfo_t *info, void *uctx) {
    if (gCrashing) _exit(128 + sig);   // crashed while reporting: just go
    gCrashing = 1;
    GovResumeAll();   // never leave a page's engine paused behind us
    char path[1100]; int fd = CrashOpen(path, sizeof path);
    if (fd >= 0) {
        const char *name = sig == SIGSEGV ? "SIGSEGV (bad memory access)" : sig == SIGBUS ? "SIGBUS (bad memory access)" : sig == SIGILL ? "SIGILL (trap: usually a failed check)"
                         : sig == SIGABRT ? "SIGABRT (aborted)" : sig == SIGFPE ? "SIGFPE (arithmetic)" : sig == SIGTRAP ? "SIGTRAP (trap)" : "signal";
        CW(fd, "Iris crash report\n=================\nWhat: "); CW(fd, name); CW(fd, " · signal "); CWNum(fd, sig);
        CW(fd, " · at address 0x"); { char h[20]; unsigned long a = (unsigned long)(info ? info->si_addr : 0); int i = 19; h[i] = 0; do { h[--i] = "0123456789abcdef"[a & 15]; a >>= 4; } while (a && i > 0); CW(fd, h + i); }
        CW(fd, "\nWhen: unix "); CWNum(fd, (long)time(NULL)); CW(fd, "\n\nWhat Iris was doing (a few seconds before):\n"); CW(fd, gCrashCtx);
        CW(fd, "\nCall stack (crashed thread):\n");
        void *frames[128]; int n = backtrace(frames, 128); backtrace_symbols_fd(frames, n, fd);
        close(fd);
    }
    _exit(128 + sig);   // exiting ourselves: macOS's crash reporter never gets it
}
static void CrashTerm(int sig) { GovResumeAll(); signal(sig, SIG_DFL); raise(sig); }   // a normal quit request (updates use it): no report

static void CrashWriteException(NSException *e, NSString *where) {
    if (gCrashing) return;
    gCrashing = 1;
    GovResumeAll();
    char path[1100]; int fd = CrashOpen(path, sizeof path);
    if (fd < 0) return;
    NSMutableString *s = [NSMutableString stringWithFormat:@"Iris crash report\n=================\nWhat: uncaught exception %@ (%@)\nReason: %@\nWhen: %@\n\nWhat Iris was doing:\n%@\nCall stack (where it was thrown):\n%@\n",
        e.name, where, e.reason, NSDate.date, CrashContext(), [e.callStackSymbols componentsJoinedByString:@"\n"]];
    if (e.userInfo.count) [s appendFormat:@"\nDetails: %@\n", e.userInfo];
    NSData *d = [s dataUsingEncoding:NSUTF8StringEncoding]; write(fd, d.bytes, d.length); close(fd);
}
static void CrashOnUncaught(NSException *e) {
    DLog(@"EXCEPTION %@ %@\n%@", e.name, e.reason, e.callStackSymbols);
    CrashWriteException(e, @"uncaught");
    _exit(70);
}
// AppKit stops the app itself when an exception escapes a run-loop turn (NSApplicationCrashOnExceptions):
// take that over so the report is ours and the exit is quiet.
static void (*gOrigCrashOnException)(id, SEL, NSException *);
static void IrisCrashOnException(id app, SEL sel, NSException *e) {
    DLog(@"EXCEPTION %@ %@\n%@", e.name, e.reason, e.callStackSymbols);
    CrashWriteException(e, @"in AppKit's run loop");
    _exit(70);
}

// Non-fatal trouble, one line each, in events.log next to the reports.
static void IrisEventLog(NSString *kind, NSString *detail) {
    NSString *line = [NSString stringWithFormat:@"%@  %@ · %@ · Iris %.0f MB\n", [NSISO8601DateFormatter stringFromDate:NSDate.date timeZone:NSTimeZone.localTimeZone formatOptions:NSISO8601DateFormatWithInternetDateTime],
                      kind, detail ?: @"", FootprintMB()];
    NSString *p = [CrashDir() stringByAppendingPathComponent:@"events.log"];
    NSFileHandle *h = [NSFileHandle fileHandleForWritingAtPath:p];
    if (!h) { [line writeToFile:p atomically:YES encoding:NSUTF8StringEncoding error:nil]; return; }
    [h seekToEndOfFile]; [h writeData:[line dataUsingEncoding:NSUTF8StringEncoding]]; [h closeFile];
    DLog(@"%@: %@", kind, detail);
}

// When macOS says memory is short: Iris lets go of what it can rebuild, and on a critical warning puts tabs you
// aren't using to sleep (never the one on screen, anything playing, or Picture in Picture).
static void CrashMemoryPressure(unsigned long level) {
    BOOL critical = (level & DISPATCH_MEMORYPRESSURE_CRITICAL) != 0;
    NSUInteger slept = 0, thumbs = 0;
    for (VWindow *w in gWindows) for (VTab *t in w.tabs.copy) {
        if (t != w.current && t.thumb && !t.web) { t.thumb = nil; thumbs++; }
        if (critical && t.web && t != w.current && !t.audible && !t.inPiP && ![w.splitPair containsObject:t]) { [w sleep:t]; slept++; }
    }
    IrisEventLog(critical ? @"memory critical" : @"memory warning", [NSString stringWithFormat:@"put %lu background tabs to sleep, let go of %lu pictures", (unsigned long)slept, (unsigned long)thumbs]);
}

static void IrisCrashInstall(void) {
    gLaunchedAt = NSDate.date.timeIntervalSince1970;
    strlcpy(gCrashDir, CrashDir().fileSystemRepresentation, sizeof gCrashDir);
    // a stack of its own, so even running out of stack can be reported
    static char altstack[128 * 1024]; stack_t ss = {.ss_sp = altstack, .ss_size = sizeof altstack, .ss_flags = 0}; sigaltstack(&ss, NULL);
    struct sigaction sa; memset(&sa, 0, sizeof sa);
    sa.sa_sigaction = CrashSignal; sa.sa_flags = SA_SIGINFO | SA_ONSTACK; sigemptyset(&sa.sa_mask);
    int sigs[] = {SIGSEGV, SIGBUS, SIGILL, SIGABRT, SIGFPE, SIGTRAP};
    for (int i = 0; i < 6; i++) sigaction(sigs[i], &sa, NULL);
    signal(SIGTERM, CrashTerm);
    NSSetUncaughtExceptionHandler(&CrashOnUncaught);
    Method m = class_getInstanceMethod(NSApplication.class, NSSelectorFromString(@"_crashOnException:"));
    if (m) gOrigCrashOnException = (void (*)(id, SEL, NSException *))method_setImplementation(m, (IMP)IrisCrashOnException);
}
// After launch: keep the context fresh, watch memory, and finish off last time's report if there is one.
static void IrisCrashStarted(void) {
    CrashRefreshContext();
    [NSTimer scheduledTimerWithTimeInterval:5 repeats:YES block:^(NSTimer *t) { CrashRefreshContext(); }];
    static dispatch_source_t mem;
    mem = dispatch_source_create(DISPATCH_SOURCE_TYPE_MEMORYPRESSURE, 0, DISPATCH_MEMORYPRESSURE_WARN | DISPATCH_MEMORYPRESSURE_CRITICAL, dispatch_get_main_queue());
    dispatch_source_set_event_handler(mem, ^{ CrashMemoryPressure(dispatch_source_get_data(mem)); });
    dispatch_resume(mem);
    NSString *marker = [CrashDir() stringByAppendingPathComponent:@"pending"];
    NSString *report = [NSString stringWithContentsOfFile:marker encoding:NSUTF8StringEncoding error:nil];
    if (!report.length) return;
    [NSFileManager.defaultManager removeItemAtPath:marker error:nil];
    NSString *log = [NSString stringWithContentsOfFile:[NSHomeDirectory() stringByAppendingPathComponent:@"Documents/Iris/iris.log"] encoding:NSUTF8StringEncoding error:nil];
    if (log.length) {   // the last 80 lines Iris logged before it went
        NSArray *lines = [log componentsSeparatedByString:@"\n"];
        NSString *tail = [[lines subarrayWithRange:NSMakeRange(lines.count > 80 ? lines.count - 80 : 0, MIN(80, lines.count))] componentsJoinedByString:@"\n"];
        NSFileHandle *h = [NSFileHandle fileHandleForWritingAtPath:report];
        [h seekToEndOfFile]; [h writeData:[[@"\n\nThe debug log just before:\n" stringByAppendingString:tail] dataUsingEncoding:NSUTF8StringEncoding]]; [h closeFile];
    }
    IrisEventLog(@"crashed last time", report.lastPathComponent);
    // keep the 30 most recent reports
    NSArray *all = [[[NSFileManager.defaultManager contentsOfDirectoryAtPath:CrashDir() error:nil] filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"SELF BEGINSWITH 'crash-'"]] sortedArrayUsingSelector:@selector(compare:)];
    for (NSUInteger i = 0; i + 30 < all.count; i++) [NSFileManager.defaultManager removeItemAtPath:[CrashDir() stringByAppendingPathComponent:all[i]] error:nil];
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 2 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
        [gWin showToast:[CrashDir() hasSuffix:@"/crashes"] ? @"Iris closed unexpectedly last time · a report is in crashes/" : @"Iris closed unexpectedly last time · a report is in Library/Logs/Iris"];
    });
}
#pragma mark - Theme

static void IrisApplyTheme(void) {
    InitPalette();   // decides light or dark once; everything below follows that one answer
    NSApp.appearance = ThemeAppearance();   // even with Follow macOS: the app matches the palette exactly, never half one and half the other
    for (VWindow *bw in gWindows) [bw applyTheme];
    for (VTab *t in AllTabs(YES)) if ([t.url hasPrefix:@"iris://"] && t.web) [t.web reload];   // built-in pages carry the theme's colours
    for (NSWindow *w in NSApp.windows) if (![w.windowController isKindOfClass:VWindow.class]) { w.appearance = ThemeAppearance(); w.backgroundColor = vBg; if (w.contentView) RedrawTree(w.contentView); }
}

#pragma mark - App

// A menu target that is always "the browser window you're using", whichever one that is.
@interface VWinProxy : NSObject
+ (instancetype)shared;
@end
@implementation VWinProxy
+ (instancetype)shared { static VWinProxy *p; static dispatch_once_t once; dispatch_once(&once, ^{ p = [VWinProxy new]; }); return p; }
- (id)forwardingTargetForSelector:(SEL)s { return gWin; }
- (BOOL)respondsToSelector:(SEL)s { return [super respondsToSelector:s] || [gWin respondsToSelector:s]; }
@end

@implementation VApp

// Development builds wait in .staged/ next to Iris.app instead of restarting Iris mid-use. Iris shows
// an "Update" pill while one is waiting; clicking it asks the watcher to swap the app in and reopen it.
static NSString *StageDir(void) { return [NSBundle.mainBundle.bundlePath.stringByDeletingLastPathComponent stringByAppendingPathComponent:@".staged"]; }
static void RunBuildScript(NSString *stamp);
// Plugging in or unplugging changes how hard background tabs are throttled.
- (void)applyThrottleNow {
    BOOL hard = ThrottleHard();
    for (VTab *t in AllTabs(YES)) if (t.web) ApplyThrottle(t.web.web, hard);
}
- (void)checkPower {
    static int last = -1;
    int hard = ThrottleHard();
    if (hard != last) { last = hard; for (VTab *t in AllTabs(YES)) if (t.web) ApplyThrottle(t.web.web, hard); }
}
- (void)checkForStagedBuild {
    if (IrisIsDev()) return;   // Iris Dev is replaced by each build directly; the Update pill is Iris's
    dispatch_async(DevQueue(), ^{
        NSString *dir = StageDir();
        BOOL ready = [NSFileManager.defaultManager fileExistsAtPath:[dir stringByAppendingPathComponent:@"ready"]];
        NSString *notes = ready ? [NSString stringWithContentsOfFile:[dir stringByAppendingPathComponent:@"notes"] encoding:NSUTF8StringEncoding error:nil] : nil;
        dispatch_async(dispatch_get_main_queue(), ^{
            if (ready == gUpdateReady && (notes == gUpdateNotes || [notes isEqualToString:gUpdateNotes])) return;
            gUpdateReady = ready; gUpdateNotes = Trim(notes ?: @"");
            if (!ready) gUpdating = NO;
            for (VWindow *w in gWindows) [w.toolbar layoutBar];
        });
    });
}
- (void)installUpdate:(id)s {
    if (gUpdating) return;
    gUpdating = YES;
    for (VWindow *w in gWindows) [w.toolbar layoutBar];
    for (VWindow *w in gWindows) if (!w.isPrivate) { [w saveSession]; break; }
    [Defaults() synchronize];
    dispatch_async(DevQueue(), ^{
        [@"install" writeToFile:[StageDir() stringByAppendingPathComponent:@"install"] atomically:YES encoding:NSUTF8StringEncoding error:nil];
        RunBuildScript(nil);   // with an install request waiting, the script quits Iris, swaps the app in and reopens it
    });
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 25 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
        if (!gUpdating) return;
        gUpdating = NO;
        for (VWindow *w in gWindows) [w.toolbar layoutBar];
        [gWin showToast:@"The update didn't go through — see build.log in the Iris folder"];
    });
}

// Iris builds itself: while it's open it watches its own source next to the app, compiles changes in the
// background into .staged/, and the Update pill appears. No Terminal window needed.
static NSString *BuildStamp(void) {
    NSString *d = StageDir().stringByDeletingLastPathComponent; NSFileManager *fm = NSFileManager.defaultManager;
    NSMutableArray *files = [@[@"Iris.m", @"ext-shim.js", @"iris", @".rebuild", @"Iris.icns"] mutableCopy];
    for (NSString *f in [[fm contentsOfDirectoryAtPath:[d stringByAppendingPathComponent:@"pages"] error:nil] sortedArrayUsingSelector:@selector(compare:)]) [files addObject:[@"pages" stringByAppendingPathComponent:f]];
    NSMutableString *s = [NSMutableString string];
    for (NSString *f in files) {
        NSDictionary *a = [fm attributesOfItemAtPath:[d stringByAppendingPathComponent:f] error:nil];
        if (a) [s appendFormat:@"%@:%.3f:%llu;", f, a.fileModificationDate.timeIntervalSince1970, a.fileSize];
    }
    return s;
}
static BOOL gBuilding;
static NSString *gSeenStamp; static NSTimeInterval gSeenAt;
// Runs the build script (a fresh copy, so editing it mid-build is safe). Call on DevQueue.
static void RunBuildScriptWith(NSString *stamp, NSArray *args);
static void RunBuildScript(NSString *stamp) { RunBuildScriptWith(stamp, nil); }
static void RunBuildScriptWith(NSString *stamp, NSArray *args) {
    NSString *d = StageDir().stringByDeletingLastPathComponent, *script = [d stringByAppendingPathComponent:@"iris"], *copy = [d stringByAppendingPathComponent:@".iris-run"];
    if (![NSFileManager.defaultManager fileExistsAtPath:script]) return;
    [NSFileManager.defaultManager removeItemAtPath:copy error:nil];
    [NSFileManager.defaultManager copyItemAtPath:script toPath:copy error:nil];
    NSTask *t = [NSTask new];
    t.executableURL = [NSURL fileURLWithPath:@"/bin/bash"];
    t.arguments = args ? [@[copy] arrayByAddingObjectsFromArray:args] : stamp ? @[copy, @"build"] : @[copy];   // a source change always compiles (file times can't be trusted after copies)
    t.currentDirectoryURL = [NSURL fileURLWithPath:d];
    t.standardOutput = NSFileHandle.fileHandleWithNullDevice; t.standardError = NSFileHandle.fileHandleWithNullDevice;
    gBuilding = YES;
    t.terminationHandler = ^(NSTask *task) {
        int code = task.terminationStatus;
        dispatch_async(DevQueue(), ^{
            gBuilding = NO;
            if (code == 75 && [args containsObject:@"ship"]) [@"" writeToFile:[d stringByAppendingPathComponent:@".ship"] atomically:YES encoding:NSUTF8StringEncoding error:nil];   // a build was running: ship once it's done
            if (stamp && code != 75) [stamp writeToFile:[d stringByAppendingPathComponent:@".built-stamp"] atomically:YES encoding:NSUTF8StringEncoding error:nil];   // 75: another build was running; try again
            NSString *st = [NSString stringWithContentsOfFile:[d stringByAppendingPathComponent:@"watch.status"] encoding:NSUTF8StringEncoding error:nil];
            NSInteger n = [[st componentsSeparatedByString:@" "].firstObject integerValue] + 1;
            [[NSString stringWithFormat:@"%ld %@ %.0f\n", (long)n, code == 0 ? @"ok" : @"failed", NSDate.date.timeIntervalSince1970]
                writeToFile:[d stringByAppendingPathComponent:@"watch.status"] atomically:YES encoding:NSUTF8StringEncoding error:nil];
            dispatch_async(dispatch_get_main_queue(), ^{ [gApp checkForStagedBuild]; });
        });
    };
    NSError *e = nil;
    if (![t launchAndReturnError:&e]) gBuilding = NO;
}
- (void)watchOwnSource {
    dispatch_async(DevQueue(), ^{
        NSString *d = StageDir().stringByDeletingLastPathComponent;
        if (gBuilding || ![NSFileManager.defaultManager fileExistsAtPath:[d stringByAppendingPathComponent:@"iris"]]) return;
        NSString *ship = [d stringByAppendingPathComponent:@".ship"];   // a tested build is being sent from Iris Dev to Iris
        if ([NSFileManager.defaultManager fileExistsAtPath:ship]) { [NSFileManager.defaultManager removeItemAtPath:ship error:nil]; RunBuildScriptWith(nil, @[@"ship"]); return; }
        NSString *st = BuildStamp();
        NSString *built = [NSString stringWithContentsOfFile:[d stringByAppendingPathComponent:@".built-stamp"] encoding:NSUTF8StringEncoding error:nil] ?: @"";
        if ([st isEqualToString:built]) { gSeenStamp = nil; return; }
        NSTimeInterval now = NSDate.date.timeIntervalSince1970;
        if (![st isEqualToString:gSeenStamp]) { gSeenStamp = st; gSeenAt = now; return; }   // changing: wait until it settles
        if (now - gSeenAt < 3) return;
        gSeenStamp = nil;
        RunBuildScript(st);
    });
}

- (void)applicationDidFinishLaunching:(NSNotification *)n {
    [Defaults() registerDefaults:@{kDLAccel: @YES, kCodec: @(MacIsAppleSilicon() ? 0 : 2), kCodec30: @NO, kBgThrottle: @1, kSingleProcess: @NO, kRestorePaused: @YES, kResumeMedia: @YES, kLazyRestore: @NO, kBlock: @YES, kStrip: @YES, kCookieReject: @YES, kAutoPiP: @YES, kSleepMins: @10, kShowBookmarks: @YES, kSearch: @0, kStartup: @0, kPrivLock: @3, kPrivHide: @NO, kShieldGate: @YES, kScripts: @YES, kAskDownload: @NO,
                                   kThrottleOn: @YES, kTheme: @1, kAccent: @0, kDensity: @1, kHTTPSOnly: @NO, kGPC: @YES, kHomeTopSites: @YES, kConfirmQuit: @NO, kSuggestNet: @YES}];
    if (gWebApp) WebAppAdoptSettings();   // an installed app starts from your Iris settings
    if (!gWebApp && ![Defaults() boolForKey:@"toolbarInstallV1"]) {   // the install button joins the address bar (Oct 2026)
        id stored = [Defaults() objectForKey:kToolbarLayout];
        if (stored) { NSMutableDictionary *L = [ToolbarSanitize(stored) mutableCopy]; NSMutableArray *a = [L[@"address"] mutableCopy];
                      if (!ToolbarZoneOf(@"install")) { [a insertObject:@"install" atIndex:0]; L[@"address"] = a; [Defaults() setObject:L forKey:kToolbarLayout]; } }
        [Defaults() setBool:YES forKey:@"toolbarInstallV1"];
    }
    if (![Defaults() boolForKey:@"toolbarGroupsV2"]) {   // the bar regrouped (Oct 2026): home and new tab leave it, ⌘T and the tab strip cover them
        NSMutableArray *x = [[Defaults() arrayForKey:kShowExtra] ?: @[] mutableCopy];
        [x removeObject:@"home"]; [x removeObject:@"newtab"];
        [Defaults() setObject:x forKey:kShowExtra]; [Defaults() setBool:YES forKey:@"toolbarGroupsV2"];
    }
    InitPalette();
    NSApp.appearance = ThemeAppearance();   // the palette and the app agree from the first frame
    // the Dock keeps an old icon for ad-hoc builds; hand it the current one directly
    NSImage *icon = [[NSImage alloc] initWithContentsOfFile:[NSBundle.mainBundle pathForResource:gWebApp || gProfileApp ? @"app" : IrisIsDev() ? @"IrisDev" : @"Iris" ofType:@"icns"]];
    if (icon) NSApp.applicationIconImage = icon;
    // "Follow macOS": recolour when the system switches between light and dark
    [NSDistributedNotificationCenter.defaultCenter addObserverForName:@"AppleInterfaceThemeChangedNotification" object:nil queue:NSOperationQueue.mainQueue usingBlock:^(NSNotification *note) {
        if ([Defaults() integerForKey:kTheme] != 0) return;
        for (NSNumber *ms in @[@150, @900]) dispatch_after(dispatch_time(DISPATCH_TIME_NOW, ms.longLongValue * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{
            if ((ThemeIsLightNow() ? 1 : 0) != gThemeLight) IrisApplyTheme();   // the system really changed: recolour once
        });
    }];
    IrisSetBlocking([Defaults() boolForKey:kBlock]);
    IrisReloadBlocklists();
    if (gWebApp) {   // an installed app: its window, nothing of the browser around it
        [self buildMenu];
        DLog(@"app: %@ starting", gWebApp[@"name"]);
        WebAppImportCookies(^{
            self.win = WebAppOpenWindow(nil); gWin = self.win;
            [NSApp activateIgnoringOtherApps:YES];
        });
        [NSTimer scheduledTimerWithTimeInterval:30 repeats:YES block:^(NSTimer *t) { [gApp checkPower]; }];
        [NSTimer scheduledTimerWithTimeInterval:2.5 repeats:YES block:^(NSTimer *t) {
            for (VWindow *w in gWindows) if (w.window.isVisible) [w.current.web checkVideo]; }];
        [VBlocker.shared prepare:nil];
        [FExtHost.shared start];   // your extensions run in the app too (a password manager on the site, say)
        if ([Defaults() boolForKey:kThrottleOn]) [VGovernor start];
        IrisCrashStarted();
        return;
    }
    WebAppRefreshShims();   // installed apps pick up this build of Iris
    ProfileAppImportCookies();   // a profile's app, the first time: its sign-ins, before any page loads
    ProfilesMoveWindowsOut();    // Iris: windows of other profiles left from before go to those profiles' apps
    ProfileAppsRefresh();        // and closed profile apps pick up this build
    self.win = [VWindow new];
    [self buildMenu];
    [self.win showWindow:nil];
    [self.win windowDidResize:nil];
    // other windows from last time come back behind the main one
    NSArray *extra = [Defaults() dictionaryForKey:kTabsState][@"windows"];
    if ([Defaults() integerForKey:kStartup] == 0 && [extra isKindOfClass:NSArray.class])
        for (NSDictionary *d in extra) if ([d isKindOfClass:NSDictionary.class]) { VWindow *x = [[VWindow alloc] initPrivate:NO state:d]; [x.window orderWindow:NSWindowBelow relativeTo:self.win.window.windowNumber]; [x windowDidResize:nil]; }
    gWin = self.win; [self.win.window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    __weak VApp *ws = self;
    if (!gProfileApp) {   // building and updating belong to Iris itself; a profile's app gets the new build when it next opens
        [self checkForStagedBuild];
        [NSTimer scheduledTimerWithTimeInterval:4 repeats:YES block:^(NSTimer *t) { [ws checkForStagedBuild]; }];
        [NSTimer scheduledTimerWithTimeInterval:2 repeats:YES block:^(NSTimer *t) { [ws watchOwnSource]; }];
    }
    [NSTimer scheduledTimerWithTimeInterval:30 repeats:YES block:^(NSTimer *t) { [ws checkPower]; }];
    // pages that grow a video after loading (YouTube moving between videos): the PiP button follows
    [NSTimer scheduledTimerWithTimeInterval:2.5 repeats:YES block:^(NSTimer *t) {   // video bookkeeping: only where there is video to keep track of
        for (VWindow *w in gWindows) {
            BOOL seen = w.window.isVisible && !w.window.isMiniaturized && (w.window.occlusionState & NSWindowOcclusionStateVisible) && !NSApp.isHidden;
            if (seen) [w.current.web checkVideo];
            for (VTab *x in w.tabs) {
                if (x.web && x.resumeAt > 0 && !x.resuming && !x.web.web.isLoading) [x.web resumeMedia];
                if (x.web && (x.audible || ((x == w.current) && seen && (x.hasVideo || x.inPiP)))) [x.web noteMediaTime];
            }
        } }];
    [VBlocker.shared prepare:nil];
    if (!gProfileApp) [self.win startControl];
    [FExtHost.shared start];
    if ([Defaults() boolForKey:kThrottleOn]) [VGovernor start];
    IrisCrashStarted();   // the CPU rule: background pages share a quarter of the processor on battery, 40% plugged in; what you watch is never paced
    [self fillMissingIcons];
}

// Bookmarks and restored tabs that have never been visited in Iris still get their site icons.
- (void)fillMissingIcons {
    NSMutableOrderedSet<NSString *> *urls = [NSMutableOrderedSet orderedSet];
    for (VTab *t in gWin.tabs) if (!t.favicon && [t.url hasPrefix:@"http"]) [urls addObject:t.url];
    for (NSDictionary *b in VBookmarks.shared.allURLs) { NSString *u = b[@"url"]; if ([u hasPrefix:@"http"] && ![VFavicons.shared iconForURL:u]) [urls addObject:u]; }
    NSUInteger i = 0;
    for (NSString *u in urls) {
        NSURL *page = [NSURL URLWithString:u]; if (!page) continue;
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(i++ * 150 * NSEC_PER_MSEC)), dispatch_get_main_queue(), ^{
            [VFavicons.shared fetchFor:page href:nil done:^(NSImage *im) {
                for (VTab *t in gWin.tabs) if (!t.favicon && [HostOf([NSURL URLWithString:t.url ?: @""]) isEqualToString:HostOf(page)]) t.favicon = im;
                [gWin refreshChrome]; [gWin.bookmarksBar reload];
            }];
        });
    }
}

- (BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication *)a { return YES; }

- (NSApplicationTerminateReply)applicationShouldTerminate:(NSApplication *)app {
    NSUInteger open = 0; for (VTab *t in AllTabs(YES)) if (!t.isHome) open++;
    if ([Defaults() boolForKey:kConfirmQuit] && open > 1 && !self.quitConfirmed) {
        NSAlert *a = [NSAlert new]; a.messageText = [NSString stringWithFormat:@"Quit Iris with %lu tabs open?", (unsigned long)open];
        a.informativeText = @"They'll be restored next time if Iris is set to continue where you left off.";
        [a addButtonWithTitle:@"Quit"]; [a addButtonWithTitle:@"Cancel"];
        if ([a runModal] != NSAlertFirstButtonReturn) return NSTerminateCancel;
    }
    [self.win saveSession]; gQuitting = YES;   // saved before anything starts closing
    if (![Defaults() boolForKey:kClearOnQuit]) return NSTerminateNow;
    [WKWebsiteDataStore.defaultDataStore removeDataOfTypes:WKWebsiteDataStore.allWebsiteDataTypes modifiedSince:NSDate.distantPast completionHandler:^{
        [NSApp replyToApplicationShouldTerminate:YES];
    }];
    return NSTerminateLater;
}
- (void)applicationWillTerminate:(NSNotification *)n { [VGovernor stop]; if (!gQuitting) [self.win saveSession]; gQuitting = YES; [VHistory flushAll]; }

- (BOOL)application:(NSApplication *)a openFile:(NSString *)f { [gWin openURL:[NSURL fileURLWithPath:f] newTab:YES]; return YES; }
- (void)application:(NSApplication *)a openURLs:(NSArray<NSURL *> *)urls {
    if (gWebApp) { for (NSURL *u in urls) { if (WebAppInScope(u)) WebAppOpenWindow(u); else OpenInIris(u); } return; }
    for (NSURL *u in urls) [gWin openURL:u newTab:YES];
}

// Settings is a page, iris://settings, in the window you're using (a new window if none is open).
